--
-- Table structure for table `commands`
--

DROP TABLE IF EXISTS `commands`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `commands` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `d_b_credential_id` bigint(20) unsigned NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` text COLLATE utf8mb4_unicode_ci,
  `is_fixed` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `commands_d_b_credential_id_index` (`d_b_credential_id`),
  KEY `commands_title_index` (`title`),
  CONSTRAINT `commands_d_b_credential_id_foreign` FOREIGN KEY (`d_b_credential_id`) REFERENCES `d_b_credentials` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `commands`
--

LOCK TABLES `commands` WRITE;
/*!40000 ALTER TABLE `commands` DISABLE KEYS */;
INSERT INTO `commands` (`id`, `d_b_credential_id`, `title`, `content`, `is_fixed`, `created_at`, `updated_at`) VALUES (1,31,'All users','SELECT     users.id AS user_id,     users.name,     users.email,     users.phone,     users.username,     users.deleted_at,     users.deleted_by,     users.status AS user_status,     drivers.id AS driver_id,     drivers.deleted_at AS driver_deleted_at,     drivers.id AS driver_id,     merchants.deleted_at AS merchant_deleted_at,     merchants.id AS merchant_id FROM users LEFT JOIN drivers     ON drivers.user_id = users.id LEFT JOIN merchants     ON merchants.user_id = users.id;',0,'2026-03-04 16:26:07','2026-03-04 16:37:32'),(2,31,'All users transactions','SELECT      t.id,     t.advance_id,     t.amount,     t.created_at,     t.created_by,     t.description,     t.from_id,     t.from_type,     t.isPaid,     t.payout_id,     t.reference,     t.settled_at,     t.shipment_id,     t.to_id,     t.updated_at,     t.warehouse_id,     s.tracking_no AS shipment_tracking_no,     u.username AS to_username FROM transactions t LEFT JOIN shipments s ON t.shipment_id = s.id LEFT JOIN users u ON t.to_id = u.id ORDER BY t.id DESC LIMIT 50 ++  SELECT     dbt.id,     dbt.action,     dbt.active,     dbt.bonus_amount,     dbt.bonus_rate,     dbt.created_at,     dbt.created_by,     dbt.description,     dbt.driver_id,     u.username AS driver_username,     dbt.driver_runsheet_id,     dbt.isPaid,     dbt.pre_id,     dbt.reference,     dbt.shipment_id,     s.tracking_no AS shipment_tracking_no,     dbt.state_id,     dbt.status,     dbt.updated_at FROM driver_bonuses_transactions dbt LEFT JOIN users u ON dbt.driver_id = u.id LEFT JOIN shipments s ON dbt.shipment_id = s.id ORDER BY dbt.id DESC LIMIT 50 ++ SELECT * FROM pickuptask_transactions ORDER BY id DESC limit 50  ++ SELECT     mt.id,     mt.amount,     mt.base_amount,     mt.completed_at,     mt.country_id,     mt.created_at,     mt.created_by,     mt.currency,     mt.deleted_at,     mt.description,     mt.discount_amount,     mt.fee_payer,     mt.merchant_id,     u.username AS merchant_username,     mt.metadata,     mt.paid_at,     mt.paid_by_bank,     mt.paid_by_cash,     mt.pickup_task_id,     mt.receipt_path,     mt.received_by,     mt.reference,     mt.shipment_id,     s.tracking_no AS shipment_tracking_no,     mt.state_id,     mt.status,     mt.transactionable_id,     mt.transactionable_type,     mt.type,     mt.updated_at FROM merchant_transactions mt LEFT JOIN users u ON mt.merchant_id = u.id LEFT JOIN shipments s ON mt.shipment_id = s.id ORDER BY mt.id DESC LIMIT 50',0,'2026-03-04 16:55:57','2026-03-04 16:55:57'),(3,31,'Users Roles','SELECT      model_has_roles.role_id,     model_has_roles.model_type,     model_has_roles.model_id,     users.username AS username,     users.email,     roles.name AS role_name FROM model_has_roles LEFT JOIN roles      ON roles.id = model_has_roles.role_id LEFT JOIN users      ON users.id = model_has_roles.model_id WHERE model_has_roles.model_type = \'App\\\\Models\\\\User\';',0,'2026-03-04 16:57:19','2026-03-04 17:55:10'),(4,1,'Projects that has no tasks with remaining money','SELECT \n    p.id,\n    p.title,\n    p.cost,\n    IFNULL((SELECT SUM(amount) \n            FROM fees f \n            WHERE f.project_id = p.id),0) AS total_fees,\n    (p.cost - IFNULL((SELECT SUM(amount) \n                      FROM fees f \n                      WHERE f.project_id = p.id),0)) AS remaining\nFROM projects p\nWHERE NOT EXISTS (\n    SELECT 1 FROM tasks t WHERE t.project_id = p.id\n)\nHAVING remaining > 0;',0,'2026-03-05 06:29:23','2026-03-05 06:29:23'),(5,1,'Random Notes','SELECT title\nFROM notes\nWHERE isActive = 1\nORDER BY RAND()\nLIMIT 5;',0,'2026-03-05 06:32:21','2026-03-05 06:33:01'),(6,31,'get shipmen id by tracking','select id from shipments where tracking_no=\"\"',0,'2026-03-05 15:12:55','2026-03-05 15:12:55'),(7,31,'get shipment tracking by id','select tracking_no from shipments where id=',0,'2026-03-05 15:14:20','2026-03-05 15:14:20'),(8,31,'shipments with no delivery address','SELECT s.* FROM shipments s LEFT JOIN addresses a ON a.id = s.delivery_address_id WHERE a.id IS NULL ORDER BY s.id DESC LIMIT 20;',0,'2026-03-08 13:48:44','2026-03-08 13:48:44'),(9,31,'group shipments by status','SELECT      status,     COUNT(*) AS total_shipments FROM shipments GROUP BY status ORDER BY total_shipments DESC;',0,'2026-03-08 20:06:09','2026-03-08 20:06:09'),(10,31,'Shipment with status','SELECT * FROM shipments where status=\"\" ORDER BY id DESC LIMIT 20',0,'2026-03-09 14:05:44','2026-03-09 14:05:44'),(11,31,'Unassigned or Unregistered shipments','SELECT * FROM merchant_pickup_shipments where is_entry=1 and is_created=0 ORDER BY id DESC LIMIT 20',0,'2026-03-09 14:14:39','2026-03-09 14:14:39'),(12,31,'Unumbred shipments','SELECT * FROM merchant_pickup_shipments where is_entry=1 and is_numbred=0 ORDER BY id DESC LIMIT 20',0,'2026-03-09 14:16:13','2026-03-09 14:16:13'),(13,31,'Select zones without coordinates','SELECT      id,     name,     governorate_id,     state_id,     owner_id,     owner_type,     created_at,     updated_at FROM zones;',0,'2026-03-11 15:00:12','2026-03-11 15:00:12'),(14,31,'Select states without polygon','SELECT      id,     ar_name,     en_name,     country_id,     governorate_id,     lat,     lng,     created_at,     updated_at FROM states;',0,'2026-03-11 15:03:21','2026-03-11 15:03:21'),(15,31,'select governorates without polygon','SELECT      id,     ar_name,     en_name,     country_id,     lat,     lng,     created_at,     updated_at FROM governorates;',0,'2026-03-11 15:04:35','2026-03-11 15:04:35'),(16,32,'Product with no variations','SELECT *\nFROM products p\nWHERE NOT EXISTS (\n    SELECT 1\n    FROM productvariations pv\n    WHERE pv.product_id = p.id\n);',0,'2026-03-14 00:03:01','2026-03-14 00:03:01'),(17,35,'Total Scans','SELECT  p.id, p.title, COUNT(s.id) as total_scans FROM products p LEFT JOIN product_qr_codes q ON q.product_id = p.id LEFT JOIN product_qr_scans s ON s.product_qr_code_id = q.id GROUP BY p.id;',0,'2026-03-14 01:14:47','2026-03-14 01:46:59'),(18,32,'Products with variations and quantity 0','SELECT DISTINCT p.*\nFROM products p\nJOIN productvariations pv \nON pv.product_id = p.id\nWHERE pv.quantity = 0;',0,'2026-03-14 01:45:26','2026-03-14 01:45:26'),(19,31,'Role Permissions','SELECT      r.id AS role_id,     r.name AS role_name,     p.id AS permission_id,     p.name AS permission_name FROM role_has_permissions rp JOIN roles r ON r.id = rp.role_id JOIN permissions p ON p.id = rp.permission_id ORDER BY r.name;',0,'2026-03-15 13:50:16','2026-03-15 13:50:16'),(20,31,'update all user to be able to login','update users set password_changed_at=\"23-02-2026\" where id>0',0,'2026-03-15 15:00:53','2026-03-15 15:00:53'),(21,31,'Database Complete Schema for AI','SELECT      TABLE_NAME,     COLUMN_NAME,     COLUMN_TYPE,     IS_NULLABLE,     COLUMN_DEFAULT,     EXTRA FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() ORDER BY TABLE_NAME, ORDINAL_POSITION;',0,'2026-03-15 16:01:22','2026-03-15 16:01:22');
/*!40000 ALTER TABLE `commands` ENABLE KEYS */;
UNLOCK TABLES;

