-notice alert-light-success fade show mb-5\" role=\"alert\">\r\n            <div class=\"alert-icon\">\r\n                <i class=\"flaticon-like\"></i>\r\n            </div>\r\n            <div class=\"alert-text\">\r\n                {{ Session()->get(\'success\') }}\r\n            </div>\r\n            <div class=\"alert-close\">\r\n                <button type=\"button\" class=\"close\" data-dismiss=\"alert\" aria-label=\"Close\">\r\n                    <span aria-hidden=\"true\">\r\n                        <i class=\"ki ki-close\"></i>\r\n                    </span>\r\n                </button>\r\n            </div>\r\n        </div>\r\n    @endif\r\n    <div class=\"card card-custom\">\r\n        <div class=\"card-header flex-wrap py-5\">\r\n            <div class=\"card-title\">\r\n                <h3 class=\"card-label\">@lang(\'general.data\')</h3>\r\n            </div>\r\n            @if (Route::is(\'contact.index\'))\r\n                <div class=\"card-toolbar\"></div>\r\n            @else\r\n                <div class=\"card-toolbar\">\r\n                    <!--begin::Button-->\r\n                    <a href=\"@yield(\'create_route\')\" class=\"btn btn-primary font-weight-bolder\">\r\n                        <i class=\"la la-plus\"></i>@lang(\'general.add_new\')\r\n                    </a>\r\n                    <!--end::Button-->\r\n                </div>\r\n            @endif\r\n        </div>\r\n        <div class=\"card-body\">\r\n            <!--begin: Datatable-->\r\n            @yield(\'filters\')\r\n            <div class=\"table-responsive\">\r\n                @yield(\'page_content\')\r\n            </div>\r\n            <!--end: Datatable-->\r\n        </div>\r\n    </div>\r\n    <!--end::Card-->\r\n@endsection\r\n \r\n \r\nSlider.SliderController\r\n<?php\r\n \r\nnamespace App\\Http\\Controllers\\Admin;\r\n \r\nuse App\\Http\\Controllers\\Controller;\r\nuse App\\Http\\Requests\\GeneralRequest;\r\nuse App\\Models\\General;\r\nuse Illuminate\\Support\\Facades\\File;\r\nclass SliderController extends Controller\r\n{\r\n    /**\r\n     * Display a listing of the resource.\r\n     *\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function index()\r\n    {\r\n       $data = General::where(\'type\',\'slider\')->take(6)->skip(5)->get();\r\n\r\n        return view(\'admin.sliders.index\', compact(\'data\'));\r\n    }\r\n \r\n    /**\r\n     * Show the form for creating a new resource.\r\n     *\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function create()\r\n    {\r\n        return view(\'admin.sliders.create\');\r\n    }\r\n \r\n    /**\r\n     * Store a newly created resource in storage.\r\n     *\r\n     * @param  \\Illuminate\\Http\\Request  $request\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function store(GeneralRequest $request)\r\n    {\r\n        $data = $request->all();\r\n        if ($request->hasFile(\'image\')) {\r\n            $file = $request->file(\'image\');\r\n            $data[\'image\']  = upload_image($file, \'image_\');\r\n        } else {\r\n            $data[\'image\'] = \'\';\r\n        }\r\n        $data[\'type\'] = \'slider\';\r\n        $general = General::create($data);\r\n        return $general ? redirect(route(\'sliders.index\'))->with([\'success\' => trans(\'general.added_success\')]) : redirect()->back();\r\n    }\r\n \r\n    /**\r\n     * Display the specified resource.\r\n     *\r\n     * @param  int  $id\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function show($id)\r\n    {\r\n        $data = General::findorfail($id);\r\n \r\n        return view(\'admin.sliders.show\', compact(\'data\'));\r\n    }\r\n \r\n    /**\r\n     * Show the form for editing the specified resource.\r\n     *\r\n     * @param  int  $id\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function edit($id)\r\n    {\r\n        $data = General::findOrfail($id);\r\n        return view(\'admin.sliders.edit\', compact(\'data\'));\r\n    }\r\n \r\n    /**\r\n     * Update the specified resource in storage.\r\n     *\r\n     * @param  \\Illuminate\\Http\\Request  $request\r\n     * @param  int  $id\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function update(GeneralRequest $request, $id)\r\n    {\r\n        $data =  $request->all();\r\n        $general = General::findOrfail($id);\r\n        if ($request->hasFile(\'image\')) {\r\n            $file = $request->file(\'image\');\r\n            $data[\'image\']  = upload_image($file, \'image_\');\r\n            if(file_exists($general->image))\r\n            File::delete($general->image);\r\n        } else {\r\n            $data[\'image\'] =  $general->image;\r\n        }\r\n        $general->fill($data)->save();\r\n        return $general ? redirect(route(\'sliders.index\', $id))->with([\'success\' => trans(\'general.updated_success\')]) : redirect()->back();\r\n    }\r\n \r\n    /**\r\n     * Remove the specified resource from storage.\r\n     *\r\n     * @param  int  $id\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function destroy($id)\r\n    {\r\n        $general = General::findOrfail($id);\r\n        $general->translations()->delete();\r\n        $general->delete();\r\n        return redirect(route(\'sliders.index\'))->with([\'success\' => trans(\'general.deleted_success\')]);\r\n    }\r\n}\r\n \r\n \r\nSlider.Request\r\n<?php\r\n \r\nnamespace App\\Http\\Requests;\r\n \r\nuse Illuminate\\Foundation\\Http\\FormRequest;\r\n \r\nclass GeneralRequest extends FormRequest\r\n{\r\n    public function authorize()\r\n    {\r\n        return true;\r\n    }\r\n \r\n    public function rules()\r\n    {\r\n        //to add or remove input from request in validation class use $this->merge\r\n         $this->merge([\'user_id\' => auth(\'api\')->user()->id]);\r\n\r\n        $image = request()->isMethod(\'put\') ? \'nullable\' : \'required\';\r\n        $rules = [\r\n            \'image\' =>  $image ,\r\n        ];\r\n        foreach (config(\'translatable.locales\') as $locale) {\r\n            $rules += [$locale . \'.title\' => [\'required\', \'string\']];\r\n            $rules += [$locale . \'.description\' => [\'required\']];\r\n        }\r\n        return  $rules;\r\n    }\r\n    public function messages()\r\n    {\r\n        $messages = [\r\n            \'image.required\' => trans(\'requests.image_required\'),\r\n        ];\r\n        foreach (config(\'translatable.locales\') as $locale) {\r\n            $messages += [$locale . \'.title.required\' => trans(\'requests.title_required_\' . $locale)];\r\n            $messages += [$locale . \'.description.required\' => trans(\'requests.desc_required_\' . $locale)];\r\n        }\r\n        return $messages;\r\n    }\r\n \r\n}\r\n\r\nHome.Apicontroller\r\n<?php\r\n \r\nnamespace App\\Http\\Controllers\\Api;\r\n \r\nuse App\\Http\\Controllers\\Controller;\r\nuse App\\Http\\Resources\\GeneralResource;\r\nuse App\\Http\\Resources\\PageResource;\r\nuse App\\Http\\Resources\\PropertiesResource;\r\nuse App\\Http\\Resources\\TeamResource;\r\nuse App\\Http\\Resources\\ToothResource;\r\nuse App\\Http\\Resources\\SettingsResource;\r\nuse App\\Models\\Category;\r\nuse App\\Models\\General;\r\nuse App\\Models\\OurTeam;\r\nuse App\\Models\\Page;\r\nuse App\\Models\\Property;\r\nuse App\\Models\\PropertyTranslation;\r\nuse App\\Models\\Setting;\r\nuse GrahamCampbell\\ResultType\\Success;\r\nuse Illuminate\\Http\\Request;\r\n \r\nclass HomeController extends Controller\r\n{\r\n    public function home(Request $request)\r\n    {\r\n        $data[\'sliders\'] = GeneralResource::collection(General::where(\'type\',\'slider\')->get());\r\n        $data[\'services\'] = GeneralResource::collection(General::where(\'type\',\'service\')->get());\r\n        $data[\'appointment_page\'] = new PageResource(Page::where(\'identifier\',\'appointment\')->first());\r\n        $data[\'about_page\'] = new PageResource(Page::where(\'identifier\',\'about\')->first());\r\n        $data[\'testimonials\'] = GeneralResource::collection(General::where(\'type\',\'testimonial\')->get());\r\n        $data[\'our_team\'] = TeamResource::collection(OurTeam::get());\r\n        $data[\'tooth_page\'] = new ToothResource(Page::where(\'identifier\',\'tooth_cleaning\')->first());\r\n \r\n        return response()->json([\r\n            \'status\' => \'Success\',\r\n            \'data\'   => $data\r\n        ]);\r\n    }\r\n \r\n}\r\n \r\nGeneral.Resource\r\n<?php\r\n \r\nnamespace App\\Http\\Resources;\r\n \r\nuse Illuminate\\Http\\Resources\\Json\\JsonResource;\r\n \r\nclass GeneralResource extends JsonResource\r\n{\r\n    /**\r\n     * Transform the resource into an array.\r\n     *\r\n     * @param  \\Illuminate\\Http\\Request  $request\r\n     * @return array|\\Illuminate\\Contracts\\Support\\Arrayable|\\JsonSerializable\r\n     */\r\n    public function toArray($request)\r\n    {\r\n        return [\r\n            \'id\' => $this->id,\r\n            \'title\' => $this->translate($request->lang)->title,\r\n            \'description\' => $this->translate($request->lang)->description,\r\n            \'image\' =>$this->image ? asset($this->image) : asset(settings()->logo),\r\n        ];\r\n    }\r\n}\r\n\r\nGeneral.Model.php\r\n<?php\r\n \r\nnamespace App\\Models;\r\n \r\nuse Astrotomic\\Translatable\\Contracts\\Translatable as TranslatableContract;\r\nuse Illuminate\\Database\\Eloquent\\Model;\r\nuse Astrotomic\\Translatable\\Translatable;\r\n \r\nclass General extends Model implements TranslatableContract\r\n{\r\n    use Translatable;\r\n \r\n    public $translatedAttributes = [\r\n        \'title\',\r\n        \'description\'\r\n    ];\r\n \r\n    protected $fillable = [\'image\',\'type\'];\r\n}\r\n\r\nGeneralTranslation.Model.php\r\n<?php\r\n \r\nnamespace App\\Models;\r\n \r\nuse Illuminate\\Database\\Eloquent\\Factories\\HasFactory;\r\nuse Illuminate\\Database\\Eloquent\\Model;\r\n \r\nclass GeneralTranslation extends Model\r\n{\r\n    protected $fillable = [\r\n        \'title\',\r\n        \'description\',\r\n    ];\r\n}\r\n\r\nGeneral.migration\r\n<?php\r\n \r\nuse Illuminate\\Database\\Migrations\\Migration;\r\nuse Illuminate\\Database\\Schema\\Blueprint;\r\nuse Illuminate\\Support\\Facades\\Schema;\r\n \r\nclass CreateGeneralsTable extends Migration\r\n{\r\n    /**\r\n     * Run the migrations.\r\n     *\r\n     * @return void\r\n     */\r\n    public function up()\r\n    {\r\n        Schema::create(\'generals\', function (Blueprint $table) {\r\n            $table->bigIncrements(\'id\');\r\n            $table->string(\'image\')->nullable();\r\n            $table->string(\'type\');\r\n            $table->timestamps();\r\n        });\r\n    }\r\n \r\n    /**\r\n     * Reverse the migrations.\r\n     *\r\n     * @return void\r\n     */\r\n    public function down()\r\n    {\r\n        Schema::dropIfExists(\'generals\');\r\n    }\r\n}\r\n \r\nGeneralTranslation.migration\r\n<?php\r\n \r\nuse Illuminate\\Database\\Migrations\\Migration;\r\nuse Illuminate\\Database\\Schema\\Blueprint;\r\nuse Illuminate\\Support\\Facades\\Schema;\r\n \r\nclass CreateGeneralTranslationsTable extends Migration\r\n{\r\n    /**\r\n     * Run the migrations.\r\n     *\r\n     * @return void\r\n     */\r\n    public function up()\r\n    {\r\n        Schema::create(\'general_translations\', function (Blueprint $table) {\r\n            $table->bigIncrements(\'id\');\r\n            $table->string(\'title\')->nullable();\r\n            $table->string(\'description\')->nullable();\r\n            $table->unsignedBigInteger(\'general_id\');\r\n            $table->string(\'locale\')->index();\r\n            $table->unique([\'general_id\', \'locale\']);\r\n            $table->foreign(\'general_id\')->references(\'id\')->on(\'generals\')->delete(\'cascade\');\r\n            $table->timestamps();\r\n        });\r\n    }\r\n \r\n    /**\r\n     * Reverse the migrations.\r\n     *\r\n     * @return void\r\n     */\r\n    public function down()\r\n    {\r\n        Schema::dropIfExists(\'general_translations\');\r\n    }\r\n}\r\n\r\nAppointment and Contact Api routes\r\nRoute::post(\'contact\', \'App\\Http\\Controllers\\Api\\AboutController@contact\');\r\nRoute::post(\'appointment\', \'App\\Http\\Controllers\\Api\\AboutController@appointment\');\r\nRoute::post(\'question\', \'App\\Http\\Controllers\\Api\\AboutController@post_question\');\r\n\r\nAppointment and Contact Api controller\r\n<?php\r\nnamespace App\\Http\\Controllers\\Api;\r\nuse App\\Http\\Controllers\\Controller;\r\nuse App\\Http\\Requests\\Site\\ContactFormRequest;\r\nuse App\\Http\\Requests\\ContactRequest;\r\nuse App\\Models\\Contact;\r\nuse App\\Models\\Page;\r\nuse App\\Models\\Setting;\r\nuse Illuminate\\Http\\Request;\r\nuse Validator;\r\nuse App\\Http\\Controllers\\Api\\BaseController as BaseController;\r\nuse App\\Models\\Appointment;\r\nuse App\\Models\\Question;\r\n \r\nclass AboutController extends BaseController\r\n{\r\n \r\n    public function contact(Request $request) {\r\n        $validator = Validator::make($request->all(), [\r\n            \'name\' => \'required\',\r\n            \'phone\' => \'required\',\r\n            \'message\' => \'required\',\r\n        ]);\r\n        if ($validator->fails()) {\r\n            return $this->sendError(\'Validation Error.\', $validator->errors());\r\n        }\r\n        $data = $request->all();\r\n        $success = Contact::create($data);\r\n        return $this->sendResponse($success, \'تم ارسال الرسالة بنح\');\r\n    }\r\n    public function appointment(Request $request) {\r\n        $validator = Validator::make($request->all(), [\r\n            \'first_name\' => \'required\',\r\n            \'last_name\' => \'required\',\r\n            \'age\' => \'required\',\r\n            \'phone\' => \'required\',\r\n            \'service\' => \'required\',\r\n            \'date_time\' => \'required\',\r\n        ]);\r\n        if ($validator->fails()) {\r\n            return $this->sendError(\'Validation Error.\', $validator->errors());\r\n        }\r\n        $data = $request->all();\r\n        $success = Appointment::create($data);\r\n        return $this->sendResponse($success, \'تم حجز الموعد بنجاح\');\r\n    }\r\n \r\n    public function post_question(Request $request) {\r\n        $validator = Validator::make($request->all(), [\r\n            \'name\' => \'required\',\r\n            \'phone\' => \'required|numeric\',\r\n            \'message\' => \'required\',\r\n        ]);\r\n        if ($validator->fails()) {\r\n            return $this->sendError(\'Validation Error.\', $validator->errors());\r\n        }\r\n        $data = $request->all();\r\n        $success = Question::create($data);\r\n        return $this->sendResponse($success, \'تم ارسال السؤال بنجاح\');\r\n    }\r\n \r\n    public function setting(Request $request){\r\n        $data = Setting::first();\r\n        $data[\'logo\'] = asset($data->logo);\r\n        $data[\'breadcrumb\'] = asset($data->breadcrumb);\r\n        $data[\'website_title\'] = $data->translate($request->lang)->website_title;\r\n        $data[\'meta_title\'] = $data->translate($request->lang)->meta_title;\r\n        $data[\'meta_description\'] = $data->translate($request->lang)->meta_description;\r\n        $data[\'meta_keywords\'] = $data->translate($request->lang)->meta_keywords;\r\n        $data[\'address\'] = $data->translate($request->lang)->address;\r\n        $data[\'footer_description\'] = $data->translate($request->lang)->footer_description;\r\n        return response()->json([\r\n            \'status\' => \'true\',\r\n            \'data\'   => $data\r\n        ]);\r\n    }\r\n}\r\n\r\nNBE payment gate way\r\npublic function store(Request $request){\r\n$data=$request->all();\r\n$last_invoice = Invoice::create($data);\r\n// $last_invoice=Invoice::where(\'name\',$data[\'name\'])->first();\r\n$username=\'merchant.TESTEGPTEST\';\r\n$password=\'c622b7e9e550292df400be7d3e846476\';\r\n \r\n$url = \'https://test-\r\nnbe.gateway.mastercard.com/api/rest/version/65/merchant/TESTEGPTEST/session\';\r\n \r\n$data = array(\"apiOperation\" => \"INITIATE_CHECKOUT\",\r\n        \"interaction\" => array (\"operation\" => \"AUTHORIZE\" ,\"returnUrl\"\r\n        =>\"http://127.0.0.1:8000/success_invoice/\".$last_invoice->id,\"cancelUrl\" =>\r\n        \"http://127.0.0.1:8000/cancel_invoice/\".$last_invoice->id),\r\n        \"order\" => array (\"currency\" => \"EGP\" ,\"id\" =>\r\n \r\n        $last_invoice->id,\"amount\" => $last_invoice->price,\"description\"=>\'description\')\r\n \r\n);\r\n \r\n$postdata = json_encode($data);\r\n$ch = curl_init($url);\r\ncurl_setopt($ch, CURLOPT_POST, 1);\r\ncurl_setopt($ch, CURLOPT_POSTFIELDS, $postdata);\r\ncurl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);\r\ncurl_setopt($ch, CURLOPT_HTTPHEADER, array(\'Content-Type:\r\napplication/json\'));\r\ncurl_setopt($ch, CURLOPT_USERPWD, \"$username:$password\");\r\n$result = curl_exec($ch);\r\ncurl_close($ch);\r\n$seeion_id = json_decode($result)->session->id ;\r\n \r\n$newUrl = \'https://test-\r\nnbe.gateway.mastercard.com/api/rest/version/65/merchant/TESTEGPTEST/session/\'.$seeion_id;\r\n$data_two = array(\"apiOperation\" => \"UPDATE_SESSION\",\r\n\"order\" => array (\"currency\" => \"EGP\" ,\"id\" =>\r\n$last_invoice->id,\"amount\" => $last_invoice->price)\r\n);\r\n \r\n$postdata_two = json_encode($data_two);\r\n$ch = curl_init($newUrl);\r\ncurl_setopt($ch, CURLOPT_POST, 1);\r\ncurl_setopt($ch, CURLOPT_POSTFIELDS, $postdata_two);\r\ncurl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);\r\ncurl_setopt($ch, CURLOPT_HTTPHEADER, array(\'Content-Type:\r\napplication/json\'));\r\ncurl_setopt($ch, CURLOPT_USERPWD, \"$username:$password\");\r\n$result = curl_exec($ch);\r\ncurl_close($ch);\r\n// $seeion_id = json_decode($result)->session->id ;\r\nreturn view(\'user.marwan_payment\',compact(\'seeion_id\'));\r\n \r\n}\r\n \r\npublic function cancel_invoice($id){\r\n    $invoice=Invoice::findOrFail($id);\r\n    $invoice->update([\"status\"=>\"canceled\"]);\r\n    return view(\'user.cancel_payment\');\r\n    }\r\n \r\n    public function success_invoice($id){\r\n    $invoice=Invoice::findOrFail($id);\r\n    $invoice->update([\"status\"=>\"success\"]);\r\n    return view(\'user.sucdcess_payment\');\r\n    }\r\n\r\nInvoice form\r\n<form action=\"{{getRoute(\'invoices.store\')}}\"\r\n \r\n    method=\"POST\" id=\"invoice_form\">\r\n    @csrf\r\n    <div class=\"row\">\r\n        <div class=\"col-lg-6\">\r\n            <div class=\"form-group\">\r\n                <label for=\"\">الاسم <label>\r\n                <input class=\"form-control\" type=\"text\" name=\"name\" >\r\n            </div>\r\n        </div>\r\n        <div class=\"col-lg-6\">\r\n            <div class=\"form-group\">\r\n                <label for=\"\">الهاتف/>* label>\r\n                <input class=\"form-control\" type=\"number\" name=\"phone\" >\r\n            </div>\r\n        </div>\r\n        <div class=\"col-lg-12\">\r\n            <div class=\"form-group\">\r\n                <label for=\"\">االلكتروني البريد/>label>\r\n                <input class=\"form-control\" type=\"text\" name=\"email\" >\r\n            </div>\r\n        </div>\r\n        <div class=\"col-lg-12\">\r\n            <div class=\"form-group\">\r\n                <label for=\"\">الخدمة/>label>\r\n                <select name=\"product_id\" id=\"product_select\" class=\"form-control\">\r\n                    @foreach ($products as $product)\r\n                        <option product-price=\"{{ $product->price }}\" value=\"{{ $product->id }}\">{{ $product->name }}</option>\r\n                    @endforeach\r\n                </select>\r\n            </div>\r\n        </div>\r\n        <div class=\"col-lg-12\">\r\n            <div class=\"form-group\">\r\n                <label for=\"\">السعر) L.E)</label>\r\n                <input class=\"form-control\" type=\"text\" name=\"price\" id=\"price\" readonly>\r\n            </div>\r\n        </div>\r\n        <div class=\"col-lg-12 text-center\">\r\n            <button class=\"btn btn-primary \" type=\"submit\">ادفع</button>\r\n        </div>\r\n    </div>\r\n</form>\r\n \r\n<script>\r\n$(document).ready(function(){\r\n    $(\"#product_select\").on(\"change\",function(){\r\n        let value = $(this).find(\":selected\").attr(\"product-price\");\r\n        $(\"#price\").val(value);\r\n    });\r\n});ript>\r\n\r\nHow to show limited words of returned string\r\n {!! mb_substr ( $service->description , 0, 210) !!}...\r\n\r\nHow to control pagination\r\n{!! $data->links(\'admin.components.pagination.default\') !!}\r\n\r\n\'admin.components.pagination.default\'\r\n@if ($paginator->hasPages())\r\n<nav class=\"navigation\" aria-label=\"Page navigation\">\r\n    <ul class=\"pagination mt-5\">\r\n        {{-- Previous Page Link --}}\r\n        @if ($paginator->onFirstPage())\r\n            <li class=\"page-item disabled\"><span class=\"page-link arrow\" aria-label=\"Previous\"><span aria-hidden=\"true\">&laquo;</span></span></li>\r\n        @else\r\n            <li class=\"page-item\"><a class=\"page-link arrow\" href=\"{{ $paginator->previousPageUrl() }}\" aria-label=\"Previous\"><span aria-hidden=\"true\">&laquo;</span></a></li>\r\n        @endif\r\n \r\n        {{-- Pagination Elements --}}\r\n        @foreach ($elements as $element)\r\n            {{-- \"Three Dots\" Separator --}}\r\n            @if (is_string($element))\r\n                <li class=\"page-item disabled\"><span>{{ $element }}</span></li>\r\n            @endif\r\n \r\n            {{-- Array Of Links --}}\r\n            @if (is_array($element))\r\n                @foreach ($element as $page => $url)\r\n                    @if ($page == $paginator->currentPage())\r\n                        <li class=\"page-item active\"><span  class=\"page-link\">{{ $page }}</span></li>\r\n                    @else\r\n                        <li class=\"page-item\"><a class=\"page-link\" href=\"{{ $url }}\">{{ $page }}</a></li>\r\n                    @endif\r\n                @endforeach\r\n            @endif\r\n        @endforeach\r\n \r\n        {{-- Next Page Link --}}\r\n        @if ($paginator->hasMorePages())\r\n            <li class=\"page-item\"><a class=\"page-link arrow\" href=\"{{ $paginator->nextPageUrl() }}\" aria-label=\"Next\"><span aria-hidden=\"true\">&raquo;</span></a></li>\r\n        @else\r\n            <li class=\"page-item disabled\"><span class=\"page-link arrow\" aria-label=\"Next\"><span aria-hidden=\"true\">&raquo;</span></span></li>\r\n        @endif\r\n    </ul>\r\n</nav>\r\n@endif\r\n\r\nHow to get a part of url and add processing on it\r\n@extends(\'front.layouts.master\')\r\n@section(\'title\')\r\n    {{ settings()->website_title }} | {{ trans(\'site.services\') }}\r\n@endsection\r\n@section(\'content\')\r\n    <!-- Breadcrumb start -->\r\n    @include(\'front.components.breadcrumb\', [\'name\' => $service->title])\r\n    <section id=\"single_service\">\r\n        <div class=\"container py-5\">\r\n            <div class=\"row\">\r\n                <div class=\"col-md-4 col-sm-12 p-5\">\r\n                    <ul class=\"list-unstyled list-group\">\r\n                    @php\r\n                        $url_path = parse_url(URL::full(), PHP_URL_PATH);\r\n                        $parts = explode(\'/\', $url_path);\r\n                    @endphp\r\n                    @foreach ($services as $serv)\r\n                        <li class=\" p-1 border-0 single-service \">\r\n                            <a href=\"{{ Route(\'service-details\',\r\n \r\n                            $serv->id) }}\"\r\n \r\n                            class=\"text-decoration-none single-active-\r\n                            service d-flex justify-content-center list-group-item rounded py-3 px-5 <?php if\r\n \r\n                            ((int) end($parts) == $serv->id) {\r\n \r\n                            echo \'active\';\r\n                            } else {\r\n                            echo \'\';\r\n                            } ?>\">{{ $serv->title }}</a>\r\n                        </li>\r\n                    @endforeach\r\n                    </ul>\r\n                </div>\r\n                <div class=\"col-md-8 col-sm-12 p-4\">\r\n                    <div class=\"single-service-img w-100 mb-3\">\r\n                        <img class=\"w-100\" src=\"{{ asset($service->image) }}\" alt=\"{{ $service->title }}\">\r\n                    </div>\r\n                    <div class=\"single-service-content p-3 text-justify\">\r\n                        <h4>{{ $service->title }}</h4>\r\n                        {!! $service->description !!}\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </section>\r\n@endsection\r\n\r\nQR code\r\n@stack(\'scripts\')\r\n <script>\r\n    //=========================\r\n     // QR Codes\r\n     //==========================================\r\n \r\n   \r\n \r\n     let qrcode = new QRCode(document.getElementById(\"qrcode\"), {\r\n    text: \"{{ settings()->qr }}\",\r\n    width: 128,\r\n    height: 128,\r\n    colorDark : \"#000000\",\r\n    colorLight : \"#ffffff\",\r\n    correctLevel : QRCode.CorrectLevel.H\r\n});\r\n </script>\r\n\r\nSubmit contact form using ajax\r\n@extends(\'front.layouts.master\')\r\n@section(\'title\')\r\n    {{ settings()->website_title }} | {{ trans(\'site.contact\') }}\r\n@endsection\r\n \r\n@section(\'content\')\r\n    <!-- Breadcrumb start -->\r\n    @include(\'front.components.breadcrumb\', [\'name\' => trans(\'site.contact\')])\r\n \r\n \r\n \r\n    <!-- Contact form -->\r\n    <section id=\"contact_page\" class=\"py-3\" data-aos=\"fade-up\" data-aos-duration=\"500\" data-aos-delay=\"300\">\r\n        <div class=\"container\">\r\n            <div class=\"row\">\r\n                <div class=\"col-md-12\">\r\n                    <h2 class=\"text-center\">@lang(\'site.inquiry\')</h2>\r\n                </div>\r\n                <div class=\"col-md-12\">\r\n                    <div id=\"message-success\" class=\"alert success-message message-hide\">\r\n                        @lang(\'site.message_success\')\r\n                    </div>\r\n                </div>\r\n            <form method=\"post\" class=\"form-inline form-custom-control col-md-12\" id=\"contact-us\">\r\n                @method(\'post\')\r\n                @csrf\r\n                <div class=\"input-group\">\r\n                    <input type=\"text\" class=\"form-control\" name=\"name\" id=\"name\" placeholder=\"@lang(\'site.name\')\">\r\n                    <span class=\"error text-danger error-hide px-4\"></span>\r\n                </div>\r\n                <div class=\"input-group\">\r\n                    <input type=\"email\" class=\"form-control\" name=\"email\" id=\"email\" placeholder=\"@lang(\'site.email\')\">\r\n                    <span class=\"error text-danger error-hide px-4\"></span>\r\n                </div>\r\n                <div class=\"input-group\">\r\n                    <textarea class=\"form-control\" rows=\"5\" name=\"message\" id=\"message\" placeholder=\"@lang(\'site.message\')\"></textarea>\r\n                    <span class=\"error text-danger error-hide px-4\"></span>\r\n                </div>\r\n                <button type=\"submit\" class=\"btn submit_btn\">@lang(\'site.send\')</button>\r\n            </form>\r\n        </div>\r\n        </div>\r\n    </section>\r\n    <section class=\"contact-details py-5\" data-aos=\"fade-up\" data-aos-duration=\"500\" data-aos-delay=\"400\">\r\n        <div class=\"container\">\r\n            <div class=\"row\" data-aos=\"fade-up\" data-aos-duration=\"500\" data-aos-delay=\"300\">\r\n                <div class=\"col-md-12\">\r\n                    <h2 class=\"text-center\">Our Contact Information</h2>\r\n                    <ul class=\"list-unstyled d-flex flex-column flex-lg-row justify-content-center contact-ul\">\r\n                        <li class=\"px-2\">\r\n                            <a ><span  class=\"fa fa-map-marker px-1\"></span>@lang(\'site.address\') :\r\n                                {{ settings()->address }}</a>\r\n                        </li>\r\n                        <li class=\"px-2\">\r\n                            <a ><span  class=\"fa fa-envelope px-1\"></span>@lang(\'site.email\')\r\n                                : {{ settings()->email }}</a>\r\n                        </li>\r\n                        <li class=\"px-2\">\r\n                            <a ><span  class=\"fa fa-mobile px-1\"></span>@lang(\'site.phone\') :\r\n                                {{ settings()->phone }}</a>\r\n                        </li>\r\n                        <li class=\"px-2\">\r\n                            <a ><span class=\"fa-solid fa-house px-1\"></span>@lang(\'site.postal\') : {{ settings()->postal }}</a>\r\n                        </li>\r\n                    </ul>\r\n                </div>\r\n                <div class=\"col-md-12\">\r\n                    <ul class=\"list-unstyled social_media d-flex justify-content-center\">\r\n                        <li class=\"social_icons\">\r\n                            <a href=\"{{ settings()->facebook }}\" target=\"_blank\">\r\n                                <i class=\"fa fa-facebook\"></i>\r\n                            </a>\r\n                        </li>\r\n                        <li class=\"social_icons\">\r\n                            <a href=\"{{ settings()->twitter }}\" target=\"_blank\">\r\n                                <i class=\"fa fa-twitter\"></i>\r\n                            </a>\r\n                        </li>\r\n                        <li class=\"social_icons\">\r\n                            <a href=\"{{ settings()->email }}\" target=\"_blank\">\r\n                                <i class=\"fa fa-youtube\"></i>\r\n                            </a>\r\n                        </li>\r\n                        <li class=\"social_icons\">\r\n                            <a href=\"{{ settings()->instagram }}\" target=\"_blank\">\r\n                                <i class=\"fa fa-instagram\"></i>\r\n                            </a>\r\n                        </li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n            <div class=\"row\">\r\n                <div class=\"map-location\" data-aos=\"fade-up\" data-aos-duration=\"500\" data-aos-delay=\"500\">\r\n                    <iframe class=\"goole-maps\"\r\n                        src=\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d463880.04554274346!2d46.24820591719813!3d24.724722268098482!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3e2f03890d489399%3A0xba974d1c98e79fd5!2sRiyadh%20Saudi%20Arabia!5e0!3m2!1sen!2seg!4v1659529414423!5m2!1sen!2seg\"\r\n                        allowfullscreen=\"\" loading=\"lazy\" referrerpolicy=\"no-referrer-when-downgrade\"></iframe>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </section><!-- Contact form end -->\r\n \r\n \r\n    @push(\'scripts\')\r\n        <script>\r\n            $(\'#contact-us\').submit(function(e) {\r\n                e.preventDefault();\r\n                let formData = new FormData(this);\r\n                console.log(formData)\r\n                $.ajax({\r\n                    type: \'POST\',\r\n                    url: \"{{ route(\'direct_contact_post\') }}\",\r\n                    data: formData,\r\n                    contentType: false,\r\n                    processData: false,\r\n                    success: (response) => {\r\n                        if (response) {\r\n                            this.reset();\r\n                            // $(\'#message-success\').removeClass(\'hide\');\r\n                            // $(\'#message-success\').show();\r\n                            $(\'#message-success\').removeClass(\'message-hide\');\r\n                            $(\'#message-successalert\').text(response);\r\n                            setTimeout(() => {\r\n                                // $(\'#message-success\').fadeOut(\'fast\');\r\n                                $(\'#message-success\').addClass(\'message-hide\');\r\n                            }, 5000);\r\n                        }\r\n                    },\r\n                    error: function(response) {\r\n                        $.each(response.responseJSON.errors, function(key, value) {\r\n                            $(\"#\" + key).next().show();\r\n                            $(\"#\" + key).next().html(value[0]);\r\n                            $(\"#\" + key).next().removeClass(\'error-hide\');\r\n                            setTimeout(() => {\r\n                                $(\"#\" + key).next().fadeOut(\'fast\');\r\n                                $(\"#\" + key).next().addClass(\'error-hide\');\r\n \r\n                            }, 5000);\r\n                        });\r\n \r\n                    }\r\n                });\r\n            });\r\n        </script>\r\n    @endpush\r\n@endsection\r\n\r\nHow to receive an error from request\r\n<div class=\"col-lg-6\">\r\n    <div class=\"form-group\">\r\n        <label for=\"\">الهاتف <label>\r\n        <input class=\"form-control @error(\'phone\') is-invalid @enderror\" type=\"text\" name=\"phone\" value=\"{{ old(\'phone\') }}\">\r\n        @error(\'phone\')\r\n            <span class=\"text-danger\">{{ $message }}</span>\r\n        @enderror\r\n    </div>\r\n</div>\r\n\r\nHow to get all the routes\r\nRoute::get(\'routes\', function () {\r\n    $routeCollection = Route::getRoutes();\r\n    echo \"<table style=\'width:100%\'>\";\r\n    echo \"<tr>\";\r\n    echo \"<td width=\'10%\'><h4>HTTP Method</h4></td>\";\r\n    echo \"<td width=\'10%\'><h4>Route</h4></td>\";\r\n    echo \"<td width=\'10%\'><h4>Name</h4></td>\";\r\n    echo \"<td width=\'70%\'><h4>Corresponding Action</h4></td>\";\r\n    echo \"</tr>\";\r\n    foreach ($routeCollection as $value) {\r\n        echo \"<tr>\";\r\n        echo \"<td>\" . $value->methods()[0] . \"</td>\";\r\n        echo \"<td>\" . $value->uri() . \"</td>\";\r\n        echo \"<td>\" . $value->getName() . \"</td>\";\r\n        echo \"<td>\" . $value->getActionName() . \"</td>\";\r\n        echo \"</tr>\";\r\n    }\r\n    echo \"</table>\";\r\n});\r\n\r\nsocket .io laravel part\r\n<!DOCTYPE html>\r\n<html lang=\"{{ str_replace(\'_\', \'-\', app()->getLocale()) }}\">\r\n\r\n<head>\r\n    <meta charset=\"utf-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n    <title>Chat App Socket.io | CodeChef</title>\r\n</head>\r\n\r\n<body>\r\n\r\n    <div class=\"container\">\r\n        <div class=\"row chat-row\">\r\n            <div class=\"chat-content\">\r\n                <ul></ul>\r\n            </div>\r\n\r\n            <div class=\"chat-section\">\r\n                <div class=\"chat-box\">\r\n                    <div class=\"chat-input bg-primary\"  contenteditable=\"\">\r\n                        <form id=\'form\'>\r\n                            <input  id=\"chatInput\" type=\"text\">\r\n                            <button >Send</button>\r\n                        </form>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <script src=\"https://code.jquery.com/jquery-3.6.0.js\" integrity=\"sha256-H+K7U5CnXl1h5ywQfKtSj8PCmoN9aaq30gDh27Xc0jk=\"\r\n        crossorigin=\"anonymous\"></script>\r\n    <script src=\"https://cdn.socket.io/4.0.1/socket.io.min.js\"\r\n        integrity=\"sha384-LzhRnpGmQP+lOvWruF/lgkcqD+WDVt9fU3H4BWmwP5u5LTmkUGafMcpZKNObVMLU\" crossorigin=\"anonymous\">\r\n    </script>\r\n\r\n    <script>\r\n        $(function() {\r\n            let ip_address = \'127.0.0.1\';\r\n            let socket_port = \'3000\';\r\n            let socket = io(ip_address + \':\' + socket_port);\r\n            const input = document.getElementById(\'chatInput\');\r\n            const form = document.getElementById(\'form\');\r\n\r\n            const value = input.value;\r\n            console.log(value)\r\n            const message = \'asdfdasf\'\r\n            // let chatInput = $(\'#chatInput\');\r\n            form.addEventListener(\'submit\', (e) => {\r\n                e.preventDefault();\r\n                console.log(\'fired\', message)\r\n               \r\n                socket.emit(\'add_message\', message);\r\n            })\r\n\r\n            // chatInput.keypress(function(e) {\r\n            //     let message = $(this).html();\r\n            //     console.log(message);\r\n            //     if (e.which === 13 && !e.shiftKey) {\r\n            //         socket.emit(\'sendChatToServer\', message);\r\n            //         chatInput.html(\'\');\r\n            //         return false;\r\n            //     }\r\n            // });\r\n\r\n            socket.on(\'send_message\', (message) => {\r\n                console.log(\'message came: \', message)\r\n                $(\'.chat-content ul\').append(`<li>${message}</li>`);\r\n            });\r\n        });\r\n    </script>\r\n</body>\r\n\r\n</html>\r\n\r\nsocket .io laravel part\r\nconst express = require(\'express\');\r\n\r\nconst app = express();\r\n\r\nconst server = require(\'http\').createServer(app);\r\n\r\nconst io = require(\'socket.io\')(server, {\r\n    cors: { origin: \"*\"}\r\n});\r\n\r\nio.on(\'connection\', (socket) => {\r\n    console.log(\'connection\');\r\n    // socket.on(\'joined_room\', (user) => {\r\n\r\n    // })\r\n    socket.on(\'add_message\', (message) => {\r\n        console.log(message);\r\n\r\n        // io.sockets.emit(\'sendChatToClient\', message);\r\n       io.emit(\'send_message\', message);\r\n    });\r\n\r\n    socket.on(\'disconnect\', (socket) => {\r\n        console.log(\'Disconnect\');\r\n    });\r\n});\r\n\r\nserver.listen(3000, () => {\r\n    console.log(\'Server is running\');\r\n});\r\n\r\nHow to give code to guest\r\n @guest\r\n    Code goes here\r\n  @endguest\r\n\r\nHow to validate a youtube link and required_if\r\n        $rx = \'~\r\n        ^(?:https?://)?                           # Optional protocol\r\n        (?:www[.])?                              # Optional sub-domain\r\n        (?:youtube[.]com/watch[?]v=|youtu[.]be/) # Mandatory domain name (w/ query string in .com)\r\n        ([^&]{11})                               # Video id of 11 characters as capture group 1\r\n        ~x\';\r\n        $code = request()->isMethod(\'put\') ? \'required\' : \'required|unique:courses,code\';\r\n\r\n        $image = request()->isMethod(\'put\') ? \'nullable|image|max:900\' : \'required|image|max:900\';\r\n        $link = request()->isMethod(\'put\') ? [\'required_if:use_media,=,1\', request()->video_link!=null ?\"regex:$rx\":\"\"] :[\'required_if:use_media,=,1\',request()->video_link !=null ?\"regex:$rx\":\"\"];\r\n\r\nEvent delegation\r\n    <script>\r\n        $(document).ready(function() {\r\n            let i = 0;\r\n            $(\"#addchild\").on(\'click\', function() {\r\n                console.log(\'tet\');\r\n                i++;\r\n $(\"#childform\").append(\r\n \"<div class=\'form-group\' id=\'item\"+i+\"\'><label>@lang(\'site.child_age\') <i class=\'fas fa-user-times remove\'      inputid=\'item\"+i+\"\' style=\'color:red;\'></i> </label><select class=\'form-control selectpicker @error(\'child_age\') is-invalid @enderror\'name=\'child_age[]\'><option value=\'\' selected>@lang(\'site.select_age\')</option><option value=\'0\'>0</option><option value=\'1\'>1</option><option value=\'2\'>2</option><option value=\'3\'>3</option><option value=\'4\'>4</option><option value=\'5\'>5</option><option value=\'6\'>6</option><option value=\'7\'>7</option><option value=\'8\'>8</option><option value=\'9\'>9</option><option value=\'10\'>10</option><option value=\'11\'>11</option></select><div class=\'invalid-feedback d-none\'></div></div>\"\r\n                );\r\n            });\r\n\r\n            $(document).on(\'click\', \".remove\",function(){\r\n                let id = $(this).attr(\'inputid\');\r\n                $(\"#\"+id).remove();\r\n            });\r\n\r\n\r\n        });\r\n    </script>\r\n\r\nHow to handle active property in navbar\r\n<li class=\"nav-item\" \r\n<a class=\"nav-link {{ Route::is(\'home\') ? \'active\' : \'\' }}\" aria-current=\"page\" href=\"{{ route(\'home\') }}\">@lang(\'site.home\')</a>\r\n</li>\r\nHow to handle whatsapp and calls\r\n<p><a href=\"https://wa.me/966500774150\"><i style=\"font-size:200%\" class=\"fab fa-whatsapp\"></i></a> <a href=\"tel:00966500774150\"><i style=\"font-size:200%\" class=\"fas fa-phone-square\"></i></a></p>\r\n\r\nImportant jQuery reference\r\n    <script>\r\n        $(document).ready(function() {\r\n            let i = 0;\r\n            let adultPrice = 0;\r\n            let childPrice = 0;\r\n            let totalPrice = 0;\r\n            $(\"#adult\").on(\'change\', function() {\r\n                let adultNum = $(this).val();\r\n                adultPrice = adultNum * {{ $tour->price }};\r\n                totalPrice = adultPrice + childPrice;\r\n                $(\"#adultprice\").html(adultPrice);\r\n                $(\"#totalprice\").html(totalPrice);\r\n            });\r\n\r\n            $(document).on(\'change\', \'.child_age\', function() {\r\n\r\n                let ages = $(\'.child_age\').map(function() {\r\n                    return Number($(this).val());\r\n                }).get();\r\n\r\n                childPrice = 0;\r\n                ages.forEach(function(age) {\r\n                    if (age < 7) {\r\n                        childPrice += {{ $tour->price_infant }};\r\n                    } else {\r\n                        childPrice += {{ $tour->price_child }};\r\n                    }\r\n                });\r\n                totalPrice = adultPrice + childPrice;\r\n                $(\"#childprice\").html(childPrice);\r\n                $(\"#totalprice\").html(totalPrice);\r\n                console.log(totalPrice);\r\n\r\n            });\r\n\r\n            $(document).on(\'click\', \"#addchild\", function() {\r\n                console.log(\'tet\');\r\n                $(\"#childform\").append(\r\n                    `<div class=\'form-group\' id=\'item${i}\'>\r\n                        <label>\r\n                            @lang(\'site.child_age\') <i class=\'fas fa-user-times remove\' style=\'color:red;\' inputid=\'item${i}\'></i>\r\n                        </label>\r\n                        <select class=\'form-control selectpicker child_age ${i}\' name=\'child_age[]\' id=\"child_item${i}\">\r\n                            <option value=\'\' selected>@lang(\'site.select_age\')</option><option value=\'0\'>0</option><option value=\'1\'>1</option>\r\n                            <option value=\'2\'>2</option><option value=\'3\'>3</option><option value=\'4\'>4</option><option value=\'5\'>5</option>\r\n                            <option value=\'6\'>6</option><option value=\'7\'>7</option><option value=\'8\'>8</option><option value=\'9\'>9</option>\r\n                            <option value=\'10\'>10</option><option value=\'11\'>11</option>\r\n                        </select>\r\n                        <div class=\'invalid-feedback d-none\'></div>\r\n                    </div>`\r\n                );\r\n                i++;\r\n        });\r\n\r\n        $(document).on(\'click\', \".remove\", function() {\r\n            let id = $(this).attr(\'inputid\');\r\n\r\n            let value = $(\"#child_\" + id).val();\r\n            // console.log(value);\r\n            // console.log(childPrice);\r\n            if (value < 7) {\r\n                childPrice -= {{ $tour->price_infant }};\r\n            } else {\r\n                childPrice -= {{ $tour->price_child }};\r\n            }\r\n            totalPrice = adultPrice + childPrice;\r\n            $(\"#childprice\").html(childPrice);\r\n            $(\"#totalprice\").html(totalPrice);\r\n            $(\"#\" + id).remove();\r\n        });\r\n\r\n\r\n        });\r\n    </script>\r\nMultiple file receiving\r\n<input type=\"file\" name=\"images[]\" multiple  accept=\".png, .jpg, .jpeg, .svg\" />\r\n\r\nRequest has file method\r\nif($request->hasFile(\'images\'))\r\n\r\nScope search and hasMany functions\r\n    public function scopeSearch($query)\r\n    {\r\n        $query->when(request()->title, function ($q) {\r\n            return $q->whereHas(\'translations\', function ($q2) {\r\n                $q2->where(\'title\', \'like\', \'%\' . request()->title . \'%\');\r\n            });\r\n        })->when(request()->month, function ($q) {\r\n            return $q->whereMonth(\'start_date\', request()->month);\r\n        })->when(request()->year, function ($q) {\r\n            return $q->whereYear(\'start_date\', request()->year);\r\n        })->when(request()->city_id, function ($q) {\r\n            return $q->where(\'city_id\', request()->city_id);\r\n        })->when(request()->section_id, function ($q) {\r\n            return $q->where(\'section_id\', request()->section_id);\r\n        })->when(request()->category_id, function ($q) {\r\n            return $q->where(\'category_id\', request()->category_id);\r\n        });\r\n    }\r\n\r\nJson response \r\nfunction successResponse($data = [],$message=\'Success\')\r\n{\r\n    return response()->json([\'status\' => 200, \'msg\' => $message, \'data\' => $data], 200);\r\n}\r\n\r\nfunction failedResponse($data = [])\r\n{\r\n    return response()->json([\'status\' => 400, \'msg\' => \'Error\', \'data\' => $data], 400);\r\n}\r\n\r\ntry catch example\r\n        try{\r\n            $courses = $this->course->search()->latest(\'id\')->paginate(PAGINATION_COUNT);\r\n            $data[\'courses\'] = CourseResource::collection($courses)->response()->getData(true);\r\n   \r\n            return successResponse($data[\'courses\']);\r\n        }catch(Exception $e){\r\n            return failedResponse($e->getMessage());\r\n        }\r\n\r\nmodel constructor\r\n    private $course;\r\n    public function __construct(Course $course)\r\n    {\r\n        $this->course = $course;\r\n    }\r\n\r\nrequest route\r\nrequest()->routeIs(\'how_we_are.*\',\r\nEloquent whereHas and query builder\r\nuse Illuminate\\Database\\Eloquent\\Builder;\r\n$data[\'category\'] = CategoryResource::collection(Category::where(\'section_id\',\'!=\',null)->whereHas(\'courses\',function(Builder $q){\r\n            $q->where(\'section_id\',\'!=\',null)->where(\'city_id\',\'!=\',null);\r\n        })->latest()->get());\r\n\r\nToday\'s date and embedding variables in resource\r\n$dt=new DateTime();\r\n$courses = $this->course->where(\'section_id\',\'!=\',null)->where(\'city_id\',\'!=\',null)->where(\'start_date\',\'>=\',$dt->format(\'Y-m-d\'))->search()->latest(\'id\')->paginate(PAGINATION_COUNT);\r\n            $data= CourseResource::collection($courses)->response()->getData(true);\r\n\r\ninject query in sql laravel and get data+using arraypush\r\n$years = DB::select(\"SELECT distinct Year(start_date) as \'year\' from courses where city_id != null and section_id != null\");\r\n            $array = array();\r\n            foreach ($years as $year) {\r\n                array_push($array, $year->year);\r\n            }\r\n\r\ninject query in sql laravel and get result as boolean\r\n$years = DB::statement(\"SELECT distinct Year(start_date) as \'year\' from courses where city_id != null and section_id != null\");\r\n\r\nSort file method to hash files name\r\n            $file = $request->file(\'image\');\r\n            $data[\'image\']=$request->image->store(\'images\');\r\n            $file->move(\'images\',$data[\'image\']);\r\n\r\nto send errors without keys in array\r\n    protected function failedValidation(Validator $validator)\r\n    {\r\n        $response = failedResponse($validator->errors()->all());\r\n        throw new ValidationException($validator,$response);\r\n    }\r\n\r\nUsing oop encapsulation accessories get and set in laravel\r\n    public function setPasswordAttribute($value)\r\n    {\r\n        return $this->attributes[\'password\'] = bcrypt($value);\r\n    }\r\n\r\n    public function getImageAttribute($val){ \r\n        return asset($val);\r\n    }\r\n\r\nto avoid installing packages issues\r\ngit update –ignore-platform-reqs\r\n\r\nexcept method\r\n$validator = $request->except([\'image\',\'email\']);\r\n\r\nGreat way to remove nullable inputs from a request       \r\n     try {\r\n            $validator = collect(request()->except(\'email\', \'image\'))->filter(function ($request) {\r\n                return is_string($request) && !empty($request) || is_array($request) && count($request);\r\n            });\r\n            $user = User::findorfail(auth()->user()->id);\r\n            if ($request->hasFile(\'image\')) {\r\n                $image = $request->image->store(\'images\');\r\n                $request->image->move(\'images\', $image);\r\n                $validator[\'image\'] = $image;\r\n            } else {\r\n                $validator[\'image\'] = $user->image;\r\n            }\r\n            $user->update($validator->toArray());\r\n            return successResponse($user, trans(\'general.updated_success\'));\r\n            // return responseJson(1, \'success\', [\'token\' => $token, \'user\' => $user]);\r\n        } catch (\\Exception $e) {\r\n            return failedResponse($e->getMessage());\r\n        }\r\n\r\nAdd this functions to a request that you want to be use in API post\r\nuse Illuminate\\Contracts\\Validation\\Validator;\r\nuse Illuminate\\Foundation\\Http\\FormRequest;\r\nuse Illuminate\\Validation\\ValidationException;\r\n\r\n    protected function failedValidation(Validator $validator)\r\n    {\r\n        $response = failedResponse($validator->errors());\r\n        throw new ValidationException($validator,$response);\r\n    }\r\n\r\nVery important php functions\r\nstr_contains($string, \'lazy\');\r\nreturn gettype($data[\'enrolled_courses\']);\r\necho ucwords(\"hello world\"); //Hello World\r\necho ucwords(\"hello|world\", \"|\"); //Hello|World\r\n$data[\'code\']=strtoupper($data[\'code\']);\r\narray_unique($array);\r\n\'category_id\'=>\\random_int(1,4),\r\n\r\nChange from timestamp to date and also other controls like change date format\r\n\'last_modified\'=>date(\'d-m-Y\',strtotime($this->updated_at)),\r\nchange datetime to am and pm\r\n date(\'h:i:s a  m/d/Y\', strtotime($value->date_time))\r\n\r\nConfig app time zone\r\n    /*\r\n    |--------------------------------------------------------------------------\r\n    | Application Timezone\r\n    |--------------------------------------------------------------------------\r\n    |\r\n    | Here you may specify the default timezone for your application, which\r\n    | will be used by the PHP date and date-time functions. We have gone\r\n    | ahead and set this to a sensible default for you out of the box.\r\n    |\r\n    */\r\n\r\n    \'timezone\' => \'Africa/Cairo\',\r\n\r\nOld in create select and checkbox\r\n<select class=\"form-control selectpicker @error(\'section_id\') is-invalid @enderror\"\r\n    name=\"section_id\" title=\"@lang(\'general.section_name\')\" id=\"section\">\r\n    @foreach ($sections as $section)\r\n        <option value=\"{{ $section->id }}\" {{ old(\'section_id\')==$section->id ? \'selected\':\'\' }}>{{ $section->title }}</option>\r\n    @endforeach\r\n</select>\r\n\r\n\r\n<div class=\"d-flex justify-content-start\">\r\n    <input type=\"checkbox\" name=\"trending\" placeholder=\"@lang(\'general.trending\')\" class=\"form-check\"\r\n        value=\"1\" {{ old(\'trending\') == \'1\' ? \'checked\' : \'\' }}>\r\n    <label class=\"p-3\">@lang(\'general.trending\')</label>\r\n</div>\r\n\r\nOld in edit select and checkbox\r\n<select class=\"form-control selectpicker @error(\'section_id\') is-invalid @enderror\"\r\n    name=\"section_id\" title=\"@lang(\'general.section_name\')\" id=\"section\">\r\n    @foreach ($sections as $section)\r\n        <option value=\"{{ $section->id }}\"\r\n            {{ old(\'section_id\', $data->section_id) == $section->id ? \'selected\' : \'\' }}>\r\n            {{ $section->title }}</option>\r\n    @endforeach\r\n</select>\r\n\r\n<div class=\"d-flex justify-content-start\">\r\n        <input type=\"checkbox\" name=\"trending\" value=\"1\" {{old(\'trending\',$data->trending) == 1  ? \'checked\' : \'\' }}  placeholder=\"@lang(\'general.trending\')\" class=\"form-check @error(\'trending\') is-invalid @enderror\" >\r\n        <label class=\"p-3\">@lang(\'general.trending\')</label>\r\n</div>\r\n\r\nHow to get most used array in a relation table + using WhereIn\r\n$most_enrolled=DB::select(\'select course_id,count(*) as course_count from subscriptions group by course_id order by course_count desc \');\r\n$ids=array();\r\nforeach($most_enrolled as $course){\r\n    array_push($ids,$course->course_id);\r\n}\r\n$data[\'most_enrolled\']=CourseResource::collection(Course::whereIn(\'id\',$ids)->take(8)->get());\r\n\r\nUsing WhereBetween\r\n$query->whereBetween(\'age\', [$ageFrom, $ageTo]);\r\n\r\nmin and max in eloquent\r\n$min=Course::min(\'price\');\r\n$max=Course::max(\'price\');\r\n\r\ndynamic form validation and using request() method\r\npublic function rules() {\r\n    // dd(request()->all());\r\n    $rules = [];\r\n    foreach(request()->input(\'formOne\')as $key => $val) {\r\n        $rules[\'formOne.\'.$key.\'.*\'] =\'required\';\r\n      }\r\n      return $rules;\r\n  }\r\n\r\n  public function messages() {\r\n    $messages = [];\r\n    foreach(request()->input(\'formOne\') as $key => $val) {\r\n      $messages[\'formOne.\'.$key.\'.date.required\'] = \'The field Date is required.\';\r\n      $messages[\'formOne.\'.$key.\'.board_id.required\'] = \'The field Date is required.\';\r\n      $messages[\'formOne.\'.$key.\'.part.required\'] = \'The field part is required.\';\r\n    }\r\n    return $messages;\r\n  }\r\n\r\nFirst or create and create or update\r\npublic function run()\r\n{\r\n    $role = Role::firstOrCreate([\r\n        \'name\' => \'super_admin\',\r\n        \'display_name\' => \'super admin\',\r\n        \'description\' => \'has all permissions\',\r\n        \'is_super\' => 1,\r\n    ]);\r\n\r\n    foreach (\\config(\'laratrust_seeder.roles\') as $key => $values){\r\n        foreach ($values as $value){\r\n                Permission::updateOrCreate([\r\n                \'name\' => $value . \'-\' . $key,\r\n                \'display_name\' => $value . \' \' . $key,\r\n                \'description\' => $value . \' \' . $key,\r\n            ]);\r\n\r\n        }\r\n    }\r\n    $permissions = Permission::all();\r\n    $role->syncPermissions($permissions);\r\n\r\n}\r\n\r\nhow we get header from api\r\nclass APILocalizationMiddleware\r\n{\r\n\r\n    public function handle(Request $request, Closure $next)\r\n    {\r\n        if( $request->header(\'locale\') == \'en\'){\r\n            App::setLocale(\'en\');\r\n        }else{\r\n            App::setLocale(\'ar\');\r\n        }\r\n        return $next($request);\r\n    }\r\n}\r\n\r\nwhere in for method Year and Month\r\n})->when(request()->month, function ($q) {\r\n    return $q->whereRaw(\'MONTH(start_date) in(\' . request()->month . \')\');\r\n})->when(request()->year, function ($q) {\r\n    return $q->whereRaw(\'YEAR(start_date) in(\' . request()->year . \')\');\r\n\r\nchange date format using Carbon\r\n    public function setStartDateAttribute($val)\r\n    {\r\n        $this->attributes[\'start_date\'] = Carbon::parse($val)->format(\'Y-m-d H:i:s\');\r\n    }\r\n\r\nAdding column using migrations\r\npublic function up()\r\n{\r\n    Schema::create(\'users\', function ($table) {\r\n        $table->integer(\"paid\");\r\n    });\r\n}\r\n\r\nremoving column using migrations\r\npublic function up()\r\n{\r\n    if (Schema::hasColumn(\'posts\', \'body\')){\r\n\r\n        Schema::table(\'posts\', function (Blueprint $table) {\r\n            $table->dropColumn(\'body\');\r\n        });\r\n    }\r\n}\r\n\r\nDisable an input according to a condition using jquery\r\nif ($(\'#section\').val() == 3) {\r\n    $(\'#trending\').attr(\'disabled\', \'disabled\');\r\n\r\n} else\r\n    $(\'#trending\').removeAttr(\'disabled\');\r\n\r\nHow to disable foreign key checks in migrations\r\n public function up()\r\n    {\r\n        Schema::disableForeignKeyConstraints();\r\n   \r\n        Schema::create(\'tb_users\', function (Blueprint $table) {\r\n            $table->engine = \'InnoDB\';\r\n   \r\n            $table->increments(\'id_user\');\r\n            $table->string(\'name\');\r\n            $table->string(\'username\');\r\n            $table->string(\'email\')->unique();\r\n            $table->integer(\'id_level\')->unsigned();\r\n            $table->string(\'password\', 60);\r\n            $table->rememberToken();\r\n            $table->boolean(\'activated\')->default(false);\r\n            $table->timestamps();\r\n   \r\n            $table->foreign(\'id_level\')->references(\'id_level\')->on(\'tb_levels\');\r\n        });\r\n   \r\n        Schema::enableForeignKeyConstraints();\r\n    }\r\n   \r\n    /**\r\n     * Reverse the migrations.\r\n     *\r\n     * @return void\r\n     */\r\n    public function down()\r\n    {\r\n        we can just use this line Schema::disableForeignKeyConstraints();\r\n        Schema::table(\'tb_users\', function(Blueprint $table){\r\n            $table->dropForeign(\'tb_users_id_level_foreign\');\r\n            $table->dropColumn(\'id_level\');\r\n        });\r\n        Schema::drop(\'tb_users\');\r\n        Schema::enableForeignKeyConstraints();\r\n    }\r\n\r\nUsing js methods typeof and json.parse and json.stringify\r\n  const cart = JSON.parse(localStorage.getItem(\'products\')); // removes “ ” from string to be object\r\n  console.log(typeof cart); // get variable type\r\n  JSON.stringify(cartArr) // transfer from array to object\r\n\r\ne-commerce cart using js and localstorage\r\nproducts.blade.php\r\n@extends(\'frontend.layouts.master\')\r\n@section(\'content\')\r\n    <main id=\"main\">\r\n        <!-- Intro Single-->\r\n        <section class=\"intro-single\">\r\n            <div class=\"container\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-md-12 col-lg-8\">\r\n                        <div class=\"title-single-box\">\r\n                            <h1 class=\"title-single\">منتجاتنا</h1>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-md-12 col-lg-4\">\r\n                        <nav class=\"breadcrumb-box d-flex justify-content-lg-end\" aria-label=\"breadcrumb\">\r\n                            <ol class=\"breadcrumb\">\r\n                                <li class=\"breadcrumb-item\"><a href=\"{{ route(\'home\') }}\">الرئيسية</a></li>\r\n                                <li class=\"breadcrumb-item active\" aria-current=\"page\"> <a\r\n                                        href=\"{{ route(\'products\') }}\">منتجاتنا</a></li>\r\n                            </ol>\r\n                        </nav>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </section>\r\n        <!-- End Intro Single-->\r\n        <!-- Services-->\r\n        {{-- <section class=\"section-property pb-5\">\r\n            <div class=\"container\">\r\n                <div class=\"row\">\r\n                    @foreach ($products as $product)\r\n                        <div class=\"col-lg-4\">\r\n                            <div class=\"carousel-item-b\">\r\n                                <div class=\"card-box-a card-shadow\">\r\n                                    <div class=\"img-box-a\"><img class=\"img-a img-fluid\" src=\"{{ asset($product->image) }}\"\r\n                                            alt=\"{{ $product->title }}\"></div>\r\n                                    <div class=\"card-overlay\">\r\n                                        <div class=\"card-overlay-a-content\">\r\n                                            <div class=\"card-header-a\">\r\n                                                <h2 class=\"card-title-a\"><a\r\n                                                        href=\"{{ route(\'product\', $product->id) }}\">{{ $product->title }}</a>\r\n                                                </h2>\r\n                                            </div>\r\n                                        </div>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    @endforeach\r\n                </div>\r\n\r\n                <div class=\"row\">\r\n                    <div class=\"col-sm-12\">\r\n                        {{ $products->links(\'frontend.pagination.default\') }}\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </section> --}}\r\n        <!-- End Services-->\r\n\r\n        <!-- electronic section start -->\r\n        <div class=\"fashion_section\">\r\n            <div id=\"electronic_main_slider\" class=\"carousel slide\" data-ride=\"carousel\">\r\n                <div class=\"carousel-inner\">\r\n                    <div class=\"carousel-item active\">\r\n                        <div class=\"container\">\r\n                            {{-- <h1 class=\"fashion_taital\">Electronic</h1> --}}\r\n                            <div class=\"fashion_section_2\">\r\n                                <div class=\"row\">\r\n                                    @foreach ($products as $product)\r\n                                        <div class=\"col-lg-4 col-sm-4\">\r\n                                            <div class=\"box_main\">\r\n                                                <h4 class=\"shirt_text\">{{ $product->title }}</h4>\r\n                                                <p class=\"price_text\">السعر <span style=\"color: #262626;\">\r\n                                                        {{ $product->price }} س.ر</span></p>\r\n                                                <div><img class=\"electronic_img img-box-a img-a img-fluid\"\r\n                                                        src=\"{{ asset($product->image) }}\"></div>\r\n                                                <div class=\"btn_main\" id=\"product{{ $loop->index }}\"\r\n                                                    product=\"{{ $product }}\">\r\n                                                    <div class=\"row\">\r\n                                                        <div class=\"col-md-6 col-lg-6 col-xl-7 d-flex\"\r\n                                                            id=\"toggle{{ $loop->index }}\">\r\n                                                            <a class=\"btn btn-success px-4 mx-2\"\r\n                                                                onclick=\"toogle({{ $product }},{{ $product->category }},{{ $loop->index }})\"><i\r\n                                                                    class=\"fas fa-shopping-cart\"></i> اضف للسلة</a>\r\n                                                        </div>\r\n\r\n                                                        <div class=\"col-md-4 col-lg-4 col-xl-1 offset-lg-1\">\r\n                                                            <a href=\"{{ route(\'product\', $product->id) }}\"\r\n                                                                class=\"btn btn-success px-4 mx-3\">تفاصيل</a>\r\n                                                        </div>\r\n                                                    </div>\r\n                                                </div>\r\n                                            </div>\r\n                                        </div>\r\n                                    @endforeach\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n        <!-- electronic section end -->\r\n\r\n    </main>\r\n@endsection\r\n@push(\'css\')\r\n    <link rel=\"stylesheet\" href=\"https://use.fontawesome.com/releases/v5.15.4/css/all.css\"\r\n        integrity=\"sha384-DyZ88mC6Up2uqS4h/KRgHuoeGwBcD4Ng9SiP4dIRy0EXTlnuz47vAwmeGwVChigm\" crossorigin=\"anonymous\">\r\n@endpush\r\n@push(\'scripts\')\r\n    <script>\r\n        let cart;\r\n        let count = !localStorage.getItem(\"itemsCount\") ? 0 : localStorage.getItem(\"itemsCount\");\r\n\r\n        localStorage.setItem(\"itemsCount\", count);\r\n\r\n        if (localStorage.getItem(\"products\") !== null && JSON.parse(localStorage.getItem(\"products\")).length) {\r\n            cartArr = JSON.parse(localStorage.getItem(\"products\"));\r\n        } else {\r\n            cartArr = [];\r\n        }\r\n\r\n        function toogle(product, cat, index) {\r\n\r\n            if (!cartArr.length || findProduct(cartArr, product).index === -1) {\r\n                product[\'qty\'] = 1;\r\n                product[\'category\'] = cat.title;\r\n                cartArr.push(product);\r\n                localStorage.setItem(\"products\", JSON.stringify(cartArr));\r\n                localStorage.setItem(\"itemsCount\", ++count);\r\n                console.log(\'count of items\',\r\n                    localStorage.getItem(\"itemsCount\")\r\n                );\r\n\r\n                $(\'#cart\').remove();\r\n                $(\'#flag\').append(`\r\n                        <a href=\"{{ route(\'cart\') }}\" id=\"cart\">\r\n                            <i class=\"fas fa-shopping-cart fa-lg text-success\"></i>${localStorage.getItem(\"itemsCount\")}\r\n                        </a>\r\n                        `);\r\n            }\r\n\r\n            $(\'#toggle\' + index).empty();\r\n            $(\'#toggle\' + index).append(`\r\n            <a class=\"d-flex\">\r\n                <button class=\"btn btn-link\" id=\"btnRemove${index}\">\r\n                    <i class=\"fas fa-minus\"></i>\r\n                </button>\r\n\r\n                <input id=\"form${index}\" min=\"1\" max=\"${product.stock}\" name=\"quantity\"\r\n                    value=\"1\" type=\"number\"\r\n                    class=\"form-control form-control-sm\" />\r\n\r\n                <button class=\"btn btn-link\" id=\"btn${index}\"\r\n                    >\r\n                    <i class=\"fas fa-plus\"></i>\r\n                </button>\r\n            </a>\r\n           \r\n            `);\r\n\r\n            var btnAdd = document.querySelector(`#btn${index}`);\r\n            btnAdd.addEventListener(\'click\', function() {\r\n                this.parentNode.querySelector(\'input[type=number]\').stepUp();\r\n                addToCart(index, product);\r\n            });\r\n\r\n            var btnRemove = document.querySelector(`#btnRemove${index}`);\r\n\r\n            btnRemove.addEventListener(\'click\', function() {\r\n                this.parentNode.querySelector(\'input[type=number]\').stepDown();\r\n                deletFromCart(index, product)\r\n            });\r\n\r\n            const input = document.querySelector(`#form${index}`);\r\n            input.value = findProduct(JSON.parse(localStorage.getItem(\"products\")), product).product.qty;\r\n        }\r\n\r\n        function addToCart(index, product) {\r\n\r\n            if (!cartArr.length || findProduct(cartArr, product).index === -1) {\r\n                product[\'qty\'] = 2;\r\n                cartArr.push(product);\r\n                localStorage.setItem(\"products\", JSON.stringify(cartArr));\r\n                localStorage.setItem(\"itemsCount\", ++count);\r\n            } else {\r\n                let newArr = cartArr.map(item => {\r\n                    if (item.id === product.id && item[\'qty\'] <= product.stock) {\r\n                        item[\'qty\']++;\r\n                        localStorage.setItem(\"itemsCount\", ++count);\r\n                    }\r\n                    return item;\r\n                })\r\n                cartArr = newArr;\r\n                localStorage.setItem(\"products\", JSON.stringify(cartArr));\r\n            }\r\n\r\n\r\n\r\n            $(\'#cart\').remove();\r\n            $(\'#flag\').append(`\r\n                        <a href=\"{{ route(\'cart\') }}\" id=\"cart\">\r\n                            <i class=\"fas fa-shopping-cart fa-lg text-success\"></i>${localStorage.getItem(\"itemsCount\")}\r\n                        </a>`);\r\n        }\r\n\r\n        function deletFromCart(index, product) {\r\n            if (findProduct(JSON.parse(localStorage.getItem(\"products\")), product).product.qty > 1) {\r\n                localStorage.setItem(\"itemsCount\", --count);\r\n\r\n                let newArr = cartArr.map(item => {\r\n                    if (item.id === product.id) {\r\n                        item[\'qty\']--;\r\n                    }\r\n                    return item;\r\n                })\r\n                cartArr = newArr;\r\n                localStorage.setItem(\"products\", JSON.stringify(cartArr));\r\n\r\n                $(\'#cart\').remove();\r\n                $(\'#flag\').append(`\r\n                                    <a href=\"{{ route(\'cart\') }}\" id=\"cart\">\r\n                                    <i class=\"fas fa-shopping-cart fa-lg text-success\"></i>${localStorage.getItem(\"itemsCount\")}\r\n                                    </a>`);\r\n\r\n            }\r\n        }\r\n\r\n        function findProduct(arr, product) {\r\n            let index = -1;\r\n            for (let i = 0; i < arr.length; i++) {\r\n                if (arr[i].id === product.id) {\r\n                    index = i\r\n                }\r\n            }\r\n            let modProduct = arr.find(item => item.id === product.id);\r\n            return {\r\n                index,\r\n                product: modProduct\r\n            };\r\n        }\r\n    </script>\r\n@endpush\r\ncart.balde.php\r\n@extends(\'frontend.layouts.master\')\r\n@section(\'content\')\r\n    <main id=\"main\">\r\n        <!-- Intro Single-->\r\n        <section class=\"intro-single\">\r\n            <div class=\"container\">\r\n                @if (session(\'success\'))\r\n                    <div class=\"alert alert-success alert-dismissible fade show\" role=\"alert\">{{ session(\'success\') }}\r\n                        <button class=\"btn-close\" type=\"button\" data-bs-dismiss=\"alert\" aria-label=\"Close\"></button>\r\n                    </div>\r\n                @endif\r\n                <div class=\"row\">\r\n                    <div class=\"col-md-12 col-lg-8\">\r\n                        <div class=\"title-single-box\">\r\n                            <h1 class=\"title-single\">عربة التسوق</h1>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-md-12 col-lg-4\">\r\n                        <nav class=\"breadcrumb-box d-flex justify-content-lg-end\" aria-label=\"breadcrumb\">\r\n                            <ol class=\"breadcrumb\">\r\n                                <li class=\"breadcrumb-item\"><a href=\"{{ route(\'home\') }}\">الرئيسية</a></li>\r\n                                <li class=\"breadcrumb-item active\" aria-current=\"page\"> <a\r\n                                        href=\"{{ route(\'products\') }}\">عربة التسوق</a></li>\r\n                            </ol>\r\n                        </nav>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </section>\r\n        <!-- End Intro Single-->\r\n        <!-- Services-->\r\n        <section class=\"section-property pb-5\">\r\n            {{-- <div class=\"container\">\r\n                <div class=\"row\">\r\n                    @foreach ($products as $product)\r\n                        <div class=\"col-lg-4\">\r\n                            <div class=\"carousel-item-b\">\r\n                                <div class=\"card-box-a card-shadow\">\r\n                                    <div class=\"img-box-a\"><img class=\"img-a img-fluid\" src=\"{{ asset($product->image) }}\"\r\n                                            alt=\"{{ $product->title }}\"></div>\r\n                                    <div class=\"card-overlay\">\r\n                                        <div class=\"card-overlay-a-content\">\r\n                                            <div class=\"card-header-a\">\r\n                                                <h2 class=\"card-title-a\"><a\r\n                                                        href=\"{{ route(\'product\', $product->id) }}\">{{ $product->title }}</a>\r\n                                                </h2>\r\n                                            </div>\r\n                                        </div>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    @endforeach\r\n                </div>\r\n\r\n                <div class=\"row\">\r\n                    <div class=\"col-sm-12\">\r\n                        {{ $products->links(\'frontend.pagination.default\') }}\r\n                    </div>\r\n                </div>\r\n            </div> --}}\r\n        </section>\r\n        <!-- End Services-->\r\n\r\n        {{-- start card --}}\r\n        <section class=\"h-100 h-custom\" style=\"background-color: #cecece;\">\r\n            <div class=\"container py-5 h-100\">\r\n                <div class=\"row d-flex justify-content-center align-items-center h-100\">\r\n                    <div class=\"col-12\">\r\n                        <div class=\"card card-registration card-registration-2\" style=\"border-radius: 15px;\">\r\n                            <div class=\"card-body p-0\">