\nif ($request->has(\'specifications\')) {\r\n// return \'yes\';\r\n$specifications = array_map(function ($value) {\r\nreturn intval(($value));\r\n}, $request->specifications);\r\n$project->specifications()->attach($specifications);\r\n}\r\n\r\n//edit\r\npublic function edit(Project $project)\r\n{\r\n$all_specifications = $this->specification->get();\r\n$specifications = $project->specifications->pluck(\'id\');\r\nreturn view(\'admin.projects.edit\', compact(\'project\', \'specifications\', \'all_specifications\'));\r\n}\r\n\r\n    public function services()\r\n    {\r\n        return $this->belongsToMany(Service::class , \'color_product\');\r\n    }\r\n\r\n\r\n<?php\r\n\r\nnamespace App\\Http\\Controllers\\Dashboard;\r\n\r\nuse App\\Http\\Controllers\\Controller;\r\nuse App\\Http\\Requests\\Dashboard\\PackageRequest;\r\nuse App\\Models\\Package;\r\nuse App\\Models\\Service;\r\nuse Illuminate\\Http\\Request;\r\nuse Illuminate\\Support\\Carbon;\r\n\r\nclass PackageController extends Controller\r\n{\r\n    private $package;\r\n    private $service;\r\n\r\n    public function __construct(Package $package, Service $service)\r\n    {\r\n        $this->middleware([\'permission:read-package\'])->only(\'index\', \'show\');\r\n        $this->middleware([\'permission:create-package\'])->only(\'create\', \'store\');\r\n        $this->middleware([\'permission:update-package\'])->only(\'edit\', \'update\');\r\n        $this->middleware([\'permission:delete-package\'])->only(\'destroy\');\r\n        $this->package = $package;\r\n        $this->service = $service;\r\n    }\r\n\r\n    public function index()\r\n    {\r\n        try {\r\n            $packages = $this->package->latest(\'id\')->get();\r\n            return view(\'admin.package.index\', compact(\'packages\'));\r\n        } catch (\\Exception $e) {\r\n            return redirect()->back()->with([\'error\' => __(\'message.something_wrong\')]);\r\n        }\r\n    }\r\n\r\n    public function create()\r\n    {\r\n        $services = $this->service->latest(\'id\')->get();\r\n        return view(\'admin.package.create\', compact(\'services\'));\r\n    }\r\n   \r\n    public function store(PackageRequest $request)\r\n    {\r\n        try {\r\n            if (!$request->has(\'status\'))\r\n            $request->request->add([\'status\' => 0]);\r\n            else\r\n            $request->request->add([\'status\' => 1]);\r\n           \r\n            $requested_data = $request->except([\'_token\', \'profile_avatar_remove\', \'services\',\'image\']);\r\n            $package = $this->package->create($requested_data);\r\n            $package->uploadFile();\r\n            if ($request->has(\'services\')) {\r\n                // return \'yes\';\r\n                $services = array_map(function ($value) {\r\n                    return intval(($value));\r\n                }, $request->services);\r\n                $package->services()->attach($services);\r\n            }\r\n\r\n\r\n            return redirect()->route(\'package.index\')->with([\'success\' => __(\'message.created_successfully\')]);\r\n        } catch (\\Exception $e) {\r\n            return redirect()->back()->with([\'error\' => __($e->getMessage())]);\r\n        }\r\n    }\r\n   \r\n    public function show(Package $package)\r\n    {\r\n        return view(\'admin.package.show\', compact(\'package\'));\r\n    }\r\n   \r\n    public function edit(Package $package)\r\n    {\r\n        $services = $this->service->latest(\'id\')->get();\r\n        $ids=[];\r\n        foreach ($package->services as $service)\r\n        array_push($ids, $service->id);\r\n        return view(\'admin.package.edit\', compact(\'package\',\'services\',\'ids\'));\r\n    }\r\n\r\n    public function update(PackageRequest $request, Package $package)\r\n    {\r\n        try {\r\n            if (!$request->has(\'status\'))\r\n                $request->request->add([\'status\' => 0]);\r\n            else\r\n                $request->request->add([\'status\' => 1]);\r\n\r\n            $requested_data = $request->except([\'_token\', \'profile_avatar_remove\', \'image\',\'services\']);\r\n            $requested_data[\'updated_at\'] = Carbon::now();\r\n            $package->update($requested_data);\r\n\r\n            $package->updateFile();\r\n\r\n            $package->services()->detach();\r\n            if ($request->has(\'services\')) {\r\n                // return \'yes\';\r\n                $services = array_map(function ($value) {\r\n                    return intval(($value));\r\n                }, $request->services);\r\n                $package->services()->attach($services);\r\n            }\r\n\r\n            return redirect()->route(\'package.index\')->with([\'success\' => __(\'message.updated_successfully\')]);\r\n        } catch (\\Exception $e) {\r\n            return redirect()->back()->with([\'error\' => __($e->getMessage())]);\r\n        }\r\n    }\r\n\r\n    public function destroy(Package $package)\r\n    {\r\n        try {\r\n            $package->deleteFile();\r\n            $package->delete();\r\n            return redirect()->route(\'package.index\')->with([\'success\' => __(\'message.deleted_successfully\')]);\r\n        } catch (\\Exception $e) {\r\n            return redirect()->back()->with([\'error\' => __(\'message.deleted_successfully\')]);\r\n        }\r\n    }\r\n}\r\nHow to get selected option value and text\r\nvar conceptName = $(\'#aioConceptName\').find(\":selected\").text();\r\nvar conceptName = $(\'#aioConceptName\').find(\":selected\").val();\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\nHow to keep all form inputs values even if after reload or after shutdown the device\r\n@push(\'scripts\')\r\n    <script>\r\n        $(document).ready(function() {\r\n        //    save data once entered\r\n            $(\"input\").each(function() {\r\n                $(this).bind(\"input\", function(event) {\r\n                    localStorage.setItem($(this).attr(\'name\')+\'student\', $(this).val());\r\n                });\r\n                if (localStorage.getItem($(this).attr(\'name\')+\'student\') !== null)\r\n                            $(this).val(localStorage.getItem($(this).attr(\'name\')+\'student\'));\r\n            });\r\n        });\r\n    </script>\r\n@endpush','2025-03-31 07:06:22','2025-07-19 05:56:50',1,0,1),(55,'React Refrence','','React Reference\r\n\r\nIn React webiste if page after reload loses data use settime out to make it wait for one second before fetching data in use effect like here \r\nuseEffect(() => {\r\n  const timer = setTimeout(() => {\r\n    const { type } = getQueryParams();\r\n    if (type) {\r\n      setValues((prevValues) => ({\r\n        ...prevValues,\r\n        kind: [type], // Set the kind based on the query parameter\r\n      }));\r\n    }\r\n  }, 1000); // 1 second delay\r\n\r\n  // Cleanup the timer when the component unmounts or location changes\r\n  return () => clearTimeout(timer);\r\n}, [location.search]);\r\n\r\nnode –v\r\nnpm –version\r\nnpm install –g create-react-app\r\nnpx create-react-app hello-world-example\r\nnpm –version\r\nnpx create-react-app hello-world-example\r\nnpm init react-app hello-world\r\nyarn create react-app hello-world-example\r\ncd hello-world-example\r\nnpm start //opens in production mode\r\nnpm run dev //opens in development mode\r\nhttp://localhost:3000/\r\nnpm build\r\nnpm run build\r\n\r\nPackages and resources\r\nhttps://www.learmoreseekmore.com/2022/09/reactjs-v18-crud-example.html \r\nBasic Concepts of Flexbox \r\nImporting a Component \r\nBabeljs.io \r\nNPM docs: package.json \r\ngit docs: gitignore \r\nNPM docs: node modules folder \r\nwebpack docs: DevServer \r\nwebpack/webpack-dev-server on GitHub \r\nVisual Studio Code keyboard shortcuts (Windows)\r\nVisual Studio Code keyboard shortcuts (macOS) Components and props \r\nIntoducing JSX \r\nStyling and CSS in React \r\nIntroducing expressions in JSX \r\nHandling Events \r\nSupported Events \r\nSyntheticEvent \r\nHow do I pass an event handler (like onClick) to a component? \r\nJavaScript Expressions as Props \r\nJavaScript Expressions as Children \r\nReact docs website URL which discusses the issue in depth \r\nData flows down \r\nThe Power Of Not Mutating Data \r\nAdd Inverse Data Flow \r\nComponent state \r\nState: A Component\'s Memory \r\nSharing State Between Components \r\nState as a Snapshot \r\nBasic useState examples \r\nSynchronizing with effects - putting it all together \r\nFetch API \r\nThe event loop in JavaScript \r\nReact Router v6 \r\nnav: The Navigation Section element \r\nConditional (ternary) operator in JavaScript \r\nif...else \r\nReact Router v6 \r\nnav: The Navigation Section element \r\nConditional (ternary) operator in JavaScript \r\nif...else \r\nhttps://medium.com/@shubham3480/adding-multi-lingual-support-in-react-44fa34a9500c#:~:text=To%20add%20multi%2Dlanguage%20support,React%2C%20Vue%2C%20etc.) \r\nhttps://nextui.org/\r\nNotes\r\nLearn react from github app and this refrence\r\n.htaccess in react\r\n<IfModule mod_rewrite.c>\r\n  RewriteEngine On\r\n  RewriteBase /\r\n  RewriteRule ^index\\.html$ - [L]\r\n  RewriteCond %{REQUEST_FILENAME} !-f\r\n  RewriteCond %{REQUEST_FILENAME} !-d\r\n  RewriteCond %{REQUEST_FILENAME} !-l\r\n  RewriteRule . /index.html [L]\r\n</IfModule>\r\nWeek1 Solution1 your first component\r\nfunction Heading() { \r\n  return ( \r\n    <h1>This is an h1 heading.</h1> \r\n  ) \r\n} \r\n \r\nfunction App() { \r\n  return ( \r\n    <div className=\"App\"> \r\n     This is the starting \r\n     code for \"Your first\r\n     component\" ungraded lab \r\n      <Heading /> \r\n    </div> \r\n  ); \r\n} \r\n \r\nexport default App;\r\n\r\nWeek1 Solution 2 creating and importing components\r\nfunction Heading() {\r\n      return (\r\n        <h1>This is an h1 heading</h1>\r\n      )\r\n  }\r\n  \r\n  export default Heading;\r\n\r\n  import Heading from \"./Heading\";\r\n\r\n    function App() {\r\n      return (\r\n        <div className=\"App\">\r\n          <Heading />\r\n        </div>\r\n      );\r\n    }\r\n\r\n    export default App;\r\n\r\nWeek1 Solution3 passing props\r\n\r\nimport Heading from \"./Heading\";\r\n\r\nfunction App() {\r\n  return (\r\n    <div className=\"App\">\r\n      <Heading firstName=\"Bob\" />\r\n      <Heading firstName=\r\n      \"Any name other than Bob\" />\r\n    </div>\r\n  );\r\n}\r\n\r\nexport default App;\r\n\r\n  function Heading(props) {\r\n    return (\r\n      <h1>Hello,{props.firstName}</h1>\r\n    )\r\n  }\r\n\r\n  export default Heading;\r\n\r\n\r\nWeek1 Soution4 Multible components\r\n\r\nimport \"./App.css\";\r\nimport Card from \"./Card\";\r\n\r\nfunction App() {\r\nreturn (\r\n    <div className=\"App\">\r\n        <h1>Task: Add three Card elements</h1>\r\n        <Card h2=\"First card\'s h2\" h3=\"First card\'s h3\" />\r\n        <Card h2=\"Second card\'s h2\" h3=\"Second card\'s h3\" />\r\n        <Card h2=\"Third card\'s h2\" h3=\"Third card\'s h3\" />\r\n    </div>\r\n  );\r\n};\r\n\r\nexport default App;\r\n\r\nfunction Card(props) {\r\n  return (\r\n      <div className=\"card\">\r\n          <h2>{props.h2}</h2>\r\n          <h3>{props.h3}</h3>\r\n      </div>\r\n    );\r\n};\r\n\r\nexport default Card;\r\nWeek2 Solution1 Dynamic Events\r\nfunction App() {\r\n\r\n    function handleClick() {\r\n      let randomNum = Math.floor(Math.random() * 3) + 1;\r\n      console.log(randomNum);\r\n      let userInput = prompt(\'type a number\');\r\n      alert(`Computer number: ${randomNum}, Your guess: ${userInput}`);\r\n    }\r\n  \r\n    return (\r\n      <div>\r\n        <h1>Task: Add a button and handle a click event</h1>\r\n        <button onClick={handleClick}>Guess the number between 1 and 3</button>\r\n      </div>\r\n    );\r\n  }\r\n  \r\n  export default App;\r\n\r\nWeek2 Solution2 Manging state in react\r\nimport React from \"react\";\r\nimport Fruits from \"./Fruits\";\r\nimport FruitsCounter from \"./FruitsCounter\";\r\n\r\nfunction App() {\r\n  const [fruits] = React.useState([\r\n      {fruitName: \'apple\', id: 1},\r\n      {fruitName: \'apple\', id: 2},\r\n      {fruitName: \'plum\', id: 3},\r\n  ]);\r\n\r\n  return (\r\n    <div className=\"App\">\r\n      <h1>Where should the state go?</h1>\r\n      <Fruits fruits={fruits} />\r\n      <FruitsCounter fruits={fruits} />\r\n    </div>\r\n  );\r\n}\r\n\r\nexport default App;\r\n\r\n\r\nfunction Fruits(props) {\r\n  return (\r\n      <div>\r\n          {props.fruits.map(f => <p key={f.id}>{f.fruitName}</p>)}\r\n      </div>\r\n  )\r\n}\r\n\r\nexport default Fruits;\r\n\r\nfunction FruitsCounter(props) {\r\n  return (\r\n      <h2>Total fruits: {props.fruits.length}</h2>\r\n  )\r\n}\r\n\r\nexport default FruitsCounter;\r\nWeek3 Solution1 Creatin a route\r\nfunction Contact() {\r\n  return  <h1>Contact Little Lemon on this page.</h1>\r\n}\r\nexport default Contact;\r\n\r\nimport \"./App.css\";\r\nimport Homepage from \"./Homepage\";\r\nimport AboutLittleLemon from \"./AboutLittleLemon\";\r\nimport Contact from \"./Contact\";\r\nimport { Routes, Route, Link } from \"react-router-dom\";\r\n\r\nfunction App() {\r\n  return (\r\n    <div> \r\n    <nav>\r\n      <Link to=\"/\" className=\"nav-item\">Homepage</Link>\r\n      <Link to=\"/about\" className=\"nav-item\">About Little Lemon</Link>\r\n      <Link to=\"/contact\" className=\"nav-item\">Contact</Link>\r\n    </nav>\r\n      <Routes> \r\n        <Route path=\"/\" element={<Homepage />}></Route>\r\n        <Route path=\"/about\" element={<AboutLittleLemon />}></Route>\r\n        <Route path=\"/contact\" element={<Contact />}></Route>\r\n      </Routes>\r\n    </div>\r\n  );\r\n};\r\n\r\nexport default App;\r\n\r\n\r\nWeek3 Solution2 Displaying images\r\nimport logo from\"./assets/logo.png\"\r\n\r\nfunction App() {\r\n  return (\r\n    <div className=\"App\">\r\n      <h1>Task: Add an image below</h1>\r\n      <img src={logo} alt=\"Logo\" />\r\n    </div>\r\n  );\r\n};\r\n\r\nexport default App;\r\n\r\nWeek3 Solution3 Song selection\r\nimport React from \"react\"; \r\n \r\nfunction App() { \r\n \r\n  const bird1 = new Audio( \r\n    \"https://upload.wikimedia.org/wikipedia/commons/9/9b/Hydroprogne_caspia_-_Caspian_Tern_XC432679.mp3\" \r\n  ); \r\n \r\n  const bird2 = new Audio( \r\n    \"https://upload.wikimedia.org/wikipedia/commons/b/b5/Hydroprogne_caspia_-_Caspian_Tern_XC432881.mp3\" \r\n  ); \r\n \r\n  function toggle1() { \r\n    if (bird1.paused) { \r\n      bird1.play(); \r\n    } else { \r\n      bird1.pause(); \r\n    } \r\n  }; \r\n \r\n  function toggle2() { \r\n    if (bird2.paused) { \r\n      bird2.play(); \r\n    } else { \r\n      bird2.pause(); \r\n    } \r\n  }; \r\n \r\n  return ( \r\n    <div> \r\n      <button onClick={toggle1}>Caspian Tern 1</button> \r\n      <button onClick={toggle2}>Caspian Tern 2</button> \r\n    </div> \r\n  ); \r\n} \r\n \r\nexport default App;\r\nWeek4 Solution1 Bulid a calculator app\r\nimport React, { useState, useRef } from \"react\"; \r\nimport \"./App.css\"; \r\n \r\nfunction App() { \r\n  const inputRef = useRef(null); \r\n  const resultRef = useRef(null); \r\n  const [result, setResult] = useState(0); \r\n \r\n  function plus(e) { \r\n    e.preventDefault(); \r\n    // const inputVal = inputRef.current.value; \r\n    // const newResult = result + Number(inputVal); \r\n    // setResult(newResult); \r\n    setResult((result) => result + Number(inputRef.current.value)); \r\n  } \r\n \r\n  function minus(e) { \r\n    e.preventDefault(); \r\n    const inputVal = inputRef.current.value; \r\n    const newResult = result - Number(inputVal); \r\n    setResult(newResult); \r\n  } \r\n \r\n  function times(e) { \r\n    e.preventDefault(); \r\n    const inputVal = inputRef.current.value; \r\n    const newResult = result * Number(inputVal); \r\n    setResult(newResult); \r\n  } \r\n \r\n  function divide(e) { \r\n    e.preventDefault(); \r\n    const inputVal = inputRef.current.value; \r\n    const newResult = result / Number(inputVal); \r\n    setResult(newResult); \r\n  } \r\n \r\n  function resetInput(e) { \r\n    e.preventDefault(); \r\n    inputRef.current.value = 0; \r\n  } \r\n \r\n  function resetResult(e) { \r\n    e.preventDefault(); \r\n    setResult(0); \r\n  } \r\n \r\n  return ( \r\n    <div className=\"App\"> \r\n      <div> \r\n        <h1>Simplest Working Calculator</h1> \r\n      </div> \r\n      <form> \r\n        <p ref={resultRef}>{result}</p> \r\n        <input \r\n          pattern=\"[0-9]\" \r\n          ref={inputRef} \r\n          type=\"number\" \r\n          placeholder=\"Type a number\" \r\n        /> \r\n        <button onClick={plus}>add</button> \r\n        <button onClick={minus}>subtract</button> \r\n        <button onClick={times}>multiply</button> \r\n        <button onClick={divide}>divide</button> \r\n        <button onClick={resetInput}>reset input</button> \r\n        <button onClick={resetResult}>reset result</button> \r\n      </form> \r\n    </div> \r\n  ); \r\n} \r\n \r\nexport default App;\r\n\r\n\r\n\r\nCalculator App\r\nApp.css\r\n* {\r\n  font-family: sans-serif;\r\n}\r\ninput,\r\nbutton {\r\n  font-size: 20px;\r\n  padding: 10px;\r\n  border-radius: 5px;\r\n}\r\ninput {\r\n  display: block;\r\n  margin-bottom: 20px;\r\n}\r\nbutton {\r\n  border: 1px solid gray;\r\n  background: whitesmoke;\r\n  margin-right: 5px;\r\n}\r\nbutton:nth-last-child(2),\r\nbutton:nth-last-child(1) {\r\n  background: tomato;\r\n  color: white;\r\n}\r\n\r\nApp.js\r\nimport {\r\n  useState,\r\n  useRef\r\n} from \"react\"; \r\nimport \"./App.css\";\r\n\r\nfunction App() { \r\n  const inputRef = useRef(null); \r\n  const resultRef = useRef(null); \r\n  const [result, setResult] = useState(0); \r\n \r\n  function plus(e) { \r\n    e.preventDefault(); \r\n    setResult((result) => result + Number(inputRef.current.value)); \r\n  }; \r\n\r\n  function minus(e) { \r\n    e.preventDefault(); \r\n    setResult((result) => result - Number(inputRef.current.value)); \r\n  }; \r\n\r\n  function times(e) { \r\n    e.preventDefault(); \r\n    setResult((result) => result * Number(inputRef.current.value)); \r\n  }; \r\n \r\n  function divide(e) { \r\n    e.preventDefault(); \r\n    setResult((result) => result / Number(inputRef.current.value)); \r\n  }; \r\n \r\n  function resetInput(e) { \r\n    e.preventDefault(); \r\n    inputRef.current.value=\"\";\r\n  }; \r\n \r\n  function resetResult(e) { \r\n    e.preventDefault(); \r\n    setResult(0);\r\n  }; \r\n \r\n  return ( \r\n    <div className=\"App\"> \r\n      <div> \r\n        <h1>Simplest Working Calculator</h1> \r\n      </div> \r\n      <form> \r\n        <p ref={resultRef}> \r\n          {result} \r\n        </p> \r\n        <input\r\n          pattern=\"[0-9]\" \r\n          ref={inputRef} \r\n          type=\"number\" \r\n          placeholder=\"Type a number\" \r\n        /> \r\n        <button onClick={plus}>add</button> \r\n        <button onClick={minus}>subtract</button> \r\n        <button onClick={times}>multiply</button> \r\n        <button onClick={divide}>divide</button> \r\n        <button onClick={resetInput}>reset input</button> \r\n        <button onClick={resetResult}>reset result</button> \r\n      </form> \r\n    </div> \r\n  ); \r\n} \r\n \r\nexport default App; \r\n\r\nIndex.js\r\nimport React from \'react\';\r\nimport ReactDOM from \'react-dom/client\';\r\nimport \'./index.css\';\r\nimport App from \'./App\';\r\nimport reportWebVitals from \'./reportWebVitals\';\r\n\r\nconst root = ReactDOM.createRoot(document.getElementById(\'root\'));\r\nroot.render(\r\n  <React.StrictMode>\r\n    <App />\r\n  </React.StrictMode>\r\n);\r\n\r\n// If you want to start measuring performance in your app, pass a function\r\n// to log results (for example: reportWebVitals(console.log))\r\n// or send to an analytics endpoint. Learn more: https://bit.ly/CRA-vitals\r\nreportWebVitals();\r\n\r\n\r\n\r\nbase.js\r\nimport axios from \"axios\";\r\n\r\nlet url = \"https://yousab-tech.com/worldpersonaltrainersuperstar/public/api\";\r\n\r\nexport const api = axios.create({\r\n  baseURL: url,\r\n});\r\ncontact.js\r\nimport { api } from \"./base\";\r\n\r\nexport const postContact = async ({ locale,values }) => {\r\n  api.defaults.headers = { locale };\r\n  const response = await api.post(\"/message\",{\r\n    name:values.name,\r\n    email:values.email,\r\n    phone:values.phone,\r\n    message:values.message\r\n  });\r\n  return response.data;\r\n};\r\nContact-us page\r\nimport React, { useState } from \"react\";\r\nimport { postContact } from \"../../apis/contact\";\r\nimport AlertSnackbar from \"../../components/AlertSnackbar\";\r\nimport Error from \"../../components/Error\";\r\n\r\nconst ContactusPage = () => {\r\n  const locale = \"en\";\r\n  const [text, setText] = useState(\"\");\r\n  const [error, setError] = useState(false);\r\n  const [disabled, setDisabled] = useState(false);\r\n  const [errors, setErrors] = useState({});\r\n  const [success, setSuccess] = useState(false);\r\n  const [values, setValues] = useState({\r\n    name: \"\",\r\n    email: \"\",\r\n    phone: \"\",\r\n    message: \"\",\r\n  });\r\n\r\n  const { name, email, phone, message } = values;\r\n\r\n  const handleChange = (e) => {\r\n    setValues({ ...values, [e.target.name]: e.target.value });\r\n  };\r\n  const handleSubmit = (e) => {\r\n    e.preventDefault();\r\n    postContact({ locale: \"en\", values })\r\n      .then((res) => {\r\n        setText(\"Sent successfully!\");\r\n        setSuccess(true);\r\n      })\r\n      .catch((err) => {\r\n        // let res = JSON.parse();\r\n        setErrors(err.response.data.data);\r\n        setError(true);\r\n        setDisabled(false);\r\n      });\r\n  };\r\n\r\n  const handleClose = () => {\r\n    setSuccess(false);\r\n    setError(false);\r\n  };\r\n\r\n  return (\r\n    <section id=\"middle\" className=\"darkgrey_section last_content_section\">\r\n      {success && (\r\n        <AlertSnackbar\r\n          open={success}\r\n          type={\"success\"}\r\n          message={text}\r\n          handleClose={handleClose}\r\n        />\r\n      )}\r\n      {error && (\r\n        <Error errorsShow={error} error={errors} handleClose={handleClose} />\r\n      )}\r\n      <div className=\"container\">\r\n        <div className=\"row\">\r\n          <div className=\"col-sm-12 text-center\">\r\n            <h2 className=\"block-header\">\r\n              <strong>Contact</strong> Form\r\n            </h2>\r\n          </div>\r\n        </div>\r\n        <div className=\"row\">\r\n          <div className=\"contact-form\">\r\n            <form\r\n              onSubmit={handleSubmit}\r\n              className=\"contact-form\"\r\n              method=\"post\"\r\n              action=\"/\"\r\n            >\r\n              <div className=\"col-sm-6\">\r\n                <p className=\"contact-form-name\">\r\n                  <label htmlFor=\"name\">\r\n                    Name <span className=\"required\">*</span>\r\n                  </label>\r\n                  <input\r\n                    type=\"text\"\r\n                    aria-required=\"true\"\r\n                    size=\"30\"\r\n                    value={name}\r\n                    name=\"name\"\r\n                    id=\"name\"\r\n                    className=\"form-control\"\r\n                    placeholder=\"Name\"\r\n                    onChange={handleChange}\r\n                  />\r\n                </p>\r\n                <p className=\"contact-form-email\">\r\n                  <label htmlFor=\"email\">\r\n                    Email <span className=\"required\">*</span>\r\n                  </label>\r\n                  <input\r\n                    type=\"email\"\r\n                    aria-required=\"true\"\r\n                    size=\"30\"\r\n                    value={email}\r\n                    name=\"email\"\r\n                    id=\"email\"\r\n                    className=\"form-control\"\r\n                    placeholder=\"Email\"\r\n                    onChange={handleChange}\r\n                  />\r\n                </p>\r\n                <p className=\"contact-form-subject\">\r\n                  <label htmlFor=\"subject\">\r\n                    Phone <span className=\"required\">*</span>\r\n                  </label>\r\n                  <input\r\n                    type=\"text\"\r\n                    aria-required=\"true\"\r\n                    size=\"30\"\r\n                    value={phone}\r\n                    name=\"phone\"\r\n                    id=\"mobile\"\r\n                    className=\"form-control\"\r\n                    placeholder=\"Mobile Number\"\r\n                    onChange={handleChange}\r\n                  />\r\n                </p>\r\n              </div>\r\n              <div className=\"col-sm-6\">\r\n                <p className=\"contact-form-message\">\r\n                  <label htmlFor=\"message\">Message</label>\r\n                  <textarea\r\n                    aria-required=\"true\"\r\n                    rows=\"9\"\r\n                    cols=\"50\"\r\n                    value={message}\r\n                    name=\"message\"\r\n                    id=\"message\"\r\n                    className=\"form-control\"\r\n                    placeholder=\"Message\"\r\n                    onChange={handleChange}\r\n                  ></textarea>\r\n                </p>\r\n              </div>\r\n              <div className=\"col-sm-12 text-center\">\r\n                <p className=\"contact-form-submit text-center vertical-margin-40\">\r\n                  <input\r\n                    type=\"submit\"\r\n                    value=\"Send Message\"\r\n                    id=\"contact_form_submit\"\r\n                    name=\"contact_submit\"\r\n                    className=\"theme_btn\"\r\n                  />\r\n                </p>\r\n              </div>\r\n            </form>\r\n          </div>\r\n        </div>\r\n\r\n        <div className=\"row\">\r\n          <div className=\"block widget_text col-md-4 col-sm-4\">\r\n            <h3>Address</h3>\r\n            <p>\r\n              WorldPT Superstars\r\n              <br />\r\n              Dubai, UAE\r\n            </p>\r\n          </div>\r\n\r\n          <div className=\"block widget_text col-md-4 col-sm-4\">\r\n            <h3>Phone/Email</h3>\r\n            <p>\r\n              <span>\r\n                <strong>Phone:</strong>{\" \"}\r\n              </span>\r\n              +971 55 123456\r\n              <br />\r\n              <span>\r\n                <strong>Email:info@worldpt.com</strong>{\" \"}\r\n              </span>\r\n            </p>\r\n          </div>\r\n\r\n          <div className=\"block widget_text col-md-4 col-sm-4\">\r\n            <h3>Social Media</h3>\r\n            <p>\r\n              <a className=\"socialico-twitter\" href=\"#\" title=\"Twitter\">\r\n                #\r\n              </a>\r\n              <a className=\"socialico-facebook\" href=\"#\" title=\"Facebook\">\r\n                #\r\n              </a>\r\n              <a className=\"socialico-google\" href=\"#\" title=\"Google\">\r\n                #\r\n              </a>\r\n              <a className=\"socialico-linkedin\" href=\"#\" title=\"Lindedin\">\r\n                #\r\n              </a>\r\n            </p>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </section>\r\n  );\r\n};\r\n\r\nexport default ContactusPage;\r\n\r\nproduct.js\r\nimport { api } from \"./base\";\r\n\r\nexport const getProducts = async ({ locale }) => {\r\n  api.defaults.headers = { locale };\r\n  const res = await api.get(\"/products\");\r\n  return res.data;\r\n};\r\n\r\nexport const getProduct = async ({ locale, productId }) => {\r\n  api.defaults.headers = { locale };\r\n  const res = await api.get(`/product/${productId}`);\r\n  return res.data;\r\n};\r\n\r\nexport const filterProducts = async ({ locale }) => {\r\n  api.defaults.headers = { locale };\r\n  const res = await api.post(`/products`, data);\r\n  return res.data;\r\n};\r\n\r\n\r\ncartSlice.js\r\nimport { createSlice } from \"@reduxjs/toolkit\";\r\nimport { calcTotal } from \"../../helpers/settings\";\r\n\r\nconst initialState = {\r\n  items: [],\r\n  totalQty: 0,\r\n  totalPrice: 0,\r\n};\r\n\r\nconst cartSlice = createSlice({\r\n  name: \"cart\",\r\n  initialState,\r\n  reducers: {\r\n    addToCart: (state, action) => {\r\n      let product = action.payload.product;\r\n      const foundProduct = state.items.find((item) => item.id === product.id);\r\n      let newArr;\r\n      if (foundProduct) {\r\n        newArr = state.items.map((item) => {\r\n          if (item.id === product.id) {\r\n            item.qty += action.payload.qty;\r\n            item[\"totalPrice\"] = item.qty * Number(item.current_price);\r\n          }\r\n          return item;\r\n        });\r\n        state.totalPrice = calcTotal(newArr);\r\n        state.items = newArr;\r\n        localStorage.setItem(\"cart\", JSON.stringify(state));\r\n      } else {\r\n        product[\"qty\"] = action.payload.qty;\r\n        state.totalQty++;\r\n        product[\"totalPrice\"] = product[\"qty\"] * Number(product.current_price);\r\n        state.totalPrice += product[\"totalPrice\"];\r\n        state.items = [...state.items, product];\r\n        localStorage.setItem(\"cart\", JSON.stringify(state));\r\n      }\r\n    },\r\n\r\n    saveCart: (state, action) => {\r\n      if (localStorage.getItem(\"cart\")) {\r\n        let cart = JSON.parse(localStorage.getItem(\"cart\"));\r\n        state.items = cart.items;\r\n        state.totalPrice = cart.totalPrice;\r\n        state.totalQty = cart.totalQty;\r\n      }\r\n    },\r\n\r\n    addQty: (state, action) => {\r\n      const newArr = state.items.map((item) => {\r\n        if (item.id === action.payload) {\r\n          item[\"qty\"]++;\r\n          item[\"totalPrice\"] = item.qty * Number(item.current_price);\r\n        }\r\n        return item;\r\n      });\r\n      state.totalPrice = calcTotal(newArr);\r\n      state.items = newArr;\r\n      localStorage.setItem(\"cart\", JSON.stringify(state));\r\n    },\r\n\r\n    removeItem: (state, action) => {\r\n      const newArr = state.items.filter((item) => item.id !== action.payload);\r\n      state.totalPrice = calcTotal(newArr);\r\n      state.totalQty--;\r\n      state.items = newArr;\r\n      localStorage.setItem(\"cart\", JSON.stringify(state));\r\n    },\r\n\r\n    decreaseQty: (state, action) => {\r\n      const newArr = state.items.map((item) => {\r\n        if (item.id === action.payload && item.qty > 1) {\r\n          item[\"qty\"]--;\r\n          item[\"totalPrice\"] = item.qty * Number(item.current_price);\r\n        }\r\n        return item;\r\n      });\r\n      state.totalPrice = calcTotal(newArr);\r\n      state.items = newArr;\r\n      localStorage.setItem(\"cart\", JSON.stringify(state));\r\n    },\r\n\r\n    emptyCart: (state, action) => {\r\n      state.items = [];\r\n      state.totalQty = 0;\r\n      state.totalPrice = 0;\r\n      localStorage.removeItem(\"cart\");\r\n    },\r\n  },\r\n});\r\n\r\nexport const {\r\n  addToCart,\r\n  saveCart,\r\n  removeItem,\r\n  addQty,\r\n  decreaseQty,\r\n  setTotalPriceCart,\r\n  emptyCart,\r\n} = cartSlice.actions;\r\n\r\nconst cartReducer = cartSlice.reducer;\r\nexport default cartReducer;\r\n\r\nproducts.jsx\r\nimport React, { Fragment, useEffect, useState } from \"react\";\r\nimport { useDispatch, useSelector } from \"react-redux\";\r\nimport { Link } from \"react-router-dom\";\r\nimport { getProducts } from \"../../apis/products\";\r\nimport { addToCart } from \"../../store/cartSlice\";\r\n\r\nconst ProductsPage = () => {\r\n  const locale = \"en\";\r\n  const dispatch = useDispatch();\r\n  const [products, setProducts] = useState([]);\r\n\r\n  const cart = useSelector(state => state.cart);\r\n  console.log({cart});\r\n\r\n  useEffect(() => {\r\n    getProducts({ locale })\r\n      .then((res) => {\r\n        setProducts(res.data.products);\r\n        console.log(res);\r\n      })\r\n      .catch((err) => {\r\n        console.log({ err });\r\n      });\r\n  }, []);\r\n\r\n  const handleAddCart = product => {\r\n    dispatch(addToCart({ product, qty: 1 }))\r\n  }\r\n\r\n  const displayProducts = () => {\r\n    return products?.map((product) => {\r\n      return (\r\n        <div className=\"col-sm-6 col-md-3\">\r\n          <div className=\"thumbnail\">\r\n            <img src={product.image} alt=\"team\" />\r\n            <div className=\"caption\">\r\n              <p>\r\n                <Link to={`/product/${product.id}`} style={{ color: \"#fff\" }}>\r\n                  {product.title}\r\n                </Link>\r\n              </p>\r\n            </div>\r\n            <p className=\"team-social text-center\">\r\n              <button onClick={() => handleAddCart(product)} style={{\r\n                background: \'transparent\',\r\n                border: \'none\',\r\n                color: \'orangered\',\r\n              }} className=\"rt-icon-shopping-cart\" title=\"Facebook\">\r\n                Add to Cart\r\n              </button>\r\n            </p>\r\n          </div>\r\n        </div>\r\n      );\r\n    });\r\n  };\r\n\r\n  return (\r\n    <Fragment>\r\n      <section className=\"darkgrey_section last_content_section\">\r\n        <div className=\"container\">\r\n          <div className=\"row\">\r\n            <div className=\"col-md-3 col-xm-12 bg_dark box_paddng\">\r\n              <h3 style={{ color: \"#f6502d\" }}>Store</h3>\r\n              <form className=\"contact-form\" method=\"post\" action=\"/\">\r\n                <p className=\"contact-form-name\">\r\n                  Choose Category\r\n                  <label>\r\n                    <span className=\"required\">*</span>\r\n                  </label>\r\n                  <select defaultValue={\"2147483647\"} className=\"form-control\">\r\n                    <option value=\"2147483647\"> - No Preference - </option>\r\n                    <option value=\"AFG\">Afghanistan</option>\r\n                    <option value=\"ALA\">Åland Islands</option>\r\n                    <option value=\"ALB\">Albania</option>\r\n                    <option value=\"DZA\">Algeria</option>\r\n                    <option value=\"ASM\">American Samoa</option>\r\n                    <option value=\"AND\">Andorra</option>\r\n                    <option value=\"AGO\">Angola</option>\r\n                    <option value=\"AIA\">Anguilla</option>\r\n                  </select>\r\n                </p>\r\n                <p className=\"contact-form-name\">\r\n                  Choose Goal\r\n                  <label>\r\n                    <span className=\"required\">*</span>\r\n                  </label>\r\n                  <select defaultValue={\"2147483647\"} className=\"form-control\">\r\n                    <option value=\"2147483647\">- No Preference -</option>\r\n                    <option value=\"AFG\">Afghanistan</option>\r\n                    <option value=\"ALA\">Åland Islands</option>\r\n                    <option value=\"ALB\">Albania</option>\r\n                    <option value=\"DZA\">Algeria</option>\r\n                    <option value=\"ASM\">American Samoa</option>\r\n                    <option value=\"AND\">Andorra</option>\r\n                    <option value=\"AGO\">Angola</option>\r\n                    <option value=\"AIA\">Anguilla</option>\r\n                  </select>\r\n                </p>\r\n\r\n                <p className=\"contact-form-name\">\r\n                  Choose Brand\r\n                  <label>\r\n                    <span className=\"required\">*</span>\r\n                  </label>\r\n                  <select defaultValue={\"2147483647\"} className=\"form-control\">\r\n                    <option value=\"2147483647\">- No Preference -</option>\r\n                    <option value=\"AFG\">Afghanistan</option>\r\n                    <option value=\"ALA\">Åland Islands</option>\r\n                    <option value=\"ALB\">Albania</option>\r\n                    <option value=\"DZA\">Algeria</option>\r\n                    <option value=\"ASM\">American Samoa</option>\r\n                    <option value=\"AND\">Andorra</option>\r\n                    <option value=\"AGO\">Angola</option>\r\n                  </select>\r\n                </p>\r\n\r\n                <p className=\"contact-form-name\">\r\n                  Choose Ingredient\r\n                  <label>\r\n                    <span className=\"required\">*</span>\r\n                  </label>\r\n                  <select defaultValue={\"2147483647\"} className=\"form-control\">\r\n                    <option value=\"2147483647\">- No Preference -</option>\r\n                    <option value=\"AFG\">Afghanistan</option>\r\n                    <option value=\"ALA\">Åland Islands</option>\r\n                    <option value=\"ALB\">Albania</option>\r\n                    <option value=\"DZA\">Algeria</option>\r\n                    <option value=\"ASM\">American Samoa</option>\r\n                    <option value=\"AND\">Andorra</option>\r\n                    <option value=\"AGO\">Angola</option>\r\n                  </select>\r\n                </p>\r\n              </form>\r\n\r\n              <div className=\"clearfix\"></div>\r\n              <div className=\"border_line_001\"></div>\r\n\r\n              <div className=\"col-md-12\">\r\n                <h3 style={{ color: \"#f6502d\" }}>Top Rated Products</h3>\r\n                <div className=\"carousel slide\" data-ride=\"carousel\">\r\n                  <div className=\"carousel-inner\">\r\n                    <div className=\"item active\">\r\n                      <Link to=\"#\">\r\n                        <img\r\n                          src=\"img/megamenu_products_001.jpg\"\r\n                          className=\"img-responsive\"\r\n                          alt=\"product 1\"\r\n                        />\r\n                      </Link>\r\n                      <h4>\r\n                        <small>Products Title ##1</small>\r\n                      </h4>\r\n                    </div>\r\n                    <div className=\"item\">\r\n                      <Link to=\"#\">\r\n                        <img\r\n                          src=\"img/megamenu_products_002.jpg\"\r\n                          className=\"img-responsive\"\r\n                          alt=\"product 2\"\r\n                        />\r\n                      </Link>\r\n                      <h4>\r\n                        <small>Products Title ##1</small>\r\n                      </h4>\r\n                    </div>\r\n                  </div>\r\n                </div>\r\n\r\n                <div className=\"tagcloud\">\r\n                  <Link to=\"#\" className=\"tag-link\" style={{ color: \"#000\" }}>\r\n                    View all Collection{\" \"}\r\n                  </Link>\r\n                </div>\r\n              </div>\r\n            </div>\r\n\r\n            <div className=\"col-md-9\">\r\n              <div className=\"row\">{displayProducts()}</div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </section>\r\n\r\n      <section id=\"events\" className=\"darkgrey_section last_content_section\">\r\n        <div className=\"container\">\r\n          <div className=\"row\">\r\n            <div className=\"col-sm-12\">\r\n              <div className=\"owl-carousel owl-items-4 classes\">\r\n                <div className=\"owl-carousel-item\">\r\n                  <Link to=\"class-single.html\">\r\n                    <img src=\"img/add_001.jpg\" alt=\"Owl Image\" />\r\n                  </Link>\r\n                </div>\r\n\r\n                <div className=\"owl-carousel-item\">\r\n                  <Link to=\"class-single.html\">\r\n                    <img src=\"img/add_002.jpg\" alt=\"Owl Image\" />\r\n                  </Link>\r\n                </div>\r\n\r\n                <div className=\"owl-carousel-item\">\r\n                  <Link to=\"class-single.html\">\r\n                    <img src=\"img/add_003.jpg\" alt=\"Owl Image\" />\r\n                  </Link>\r\n                </div>\r\n\r\n                <div className=\"owl-carousel-item\">\r\n                  <Link to=\"class-single.html\">\r\n                    <img src=\"img/add_004.jpg\" alt=\"Owl Image\" />\r\n                  </Link>\r\n                </div>\r\n\r\n                <div className=\"owl-carousel-item\">\r\n                  <Link to=\"class-single.html\">\r\n                    <img src=\"img/add_005.jpg\" alt=\"Owl Image\" />\r\n                  </Link>\r\n                </div>\r\n              </div>\r\n            </div>\r\n\r\n            <div className=\"clearfix\"></div>\r\n\r\n            <div className=\"col-md-4\">\r\n              {\" \"}\r\n              <img src=\"upload/ad1.jpg\" />{\" \"}\r\n            </div>\r\n            <div className=\"col-md-4\">\r\n              {\" \"}\r\n              <img src=\"upload/ad3.jpg\" />\r\n            </div>\r\n            <div className=\"col-md-4\">\r\n              {\" \"}\r\n              <img src=\"upload/ad4.jpg\" />{\" \"}\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </section>\r\n\r\n      <div id=\"events\" className=\"col-md-12\">\r\n        <div className=\"row\">\r\n          <div className=\"col-sm-12 text-center\">\r\n            <h2 className=\"block-header\">\r\n              <strong>More</strong> Courses\r\n            </h2>\r\n          </div>\r\n        </div>\r\n        <div className=\"row\">\r\n          <div className=\"col-sm-12\">\r\n            <div className=\"owl-carousel owl-items-4 shop\">\r\n              <div className=\"owl-carousel-item\">\r\n                <Link to=\"class-single.html\">\r\n                  <img src=\"example/horizontal_slider3.jpg\" alt=\"Owl Image\" />\r\n                </Link>\r\n\r\n                <h3>\r\n                  <Link to=\"class-single.html\">Basketball Match</Link>\r\n                </h3>\r\n              </div>\r\n\r\n              <div className=\"owl-carousel-item\">\r\n                <Link to=\"class-single.html\">\r\n                  <img src=\"example/horizontal_slider2.jpg\" alt=\"Owl Image\" />\r\n                </Link>\r\n\r\n                <h3>\r\n                  <Link to=\"class-single.html\">Weight Training</Link>\r\n                </h3>\r\n              </div>\r\n\r\n              <div className=\"owl-carousel-item\">\r\n                <Link to=\"class-single.html\">\r\n                  <img src=\"example/horizontal_slider4.jpg\" alt=\"Owl Image\" />\r\n                </Link>\r\n\r\n                <h3>\r\n                  <Link to=\"class-single.html\">Powerlifting 101</Link>\r\n                </h3>\r\n              </div>\r\n\r\n              <div className=\"owl-carousel-item\">\r\n                <Link to=\"class-single.html\">\r\n                  <img src=\"example/horizontal_slider2.jpg\" alt=\"Owl Image\" />\r\n                </Link>\r\n\r\n                <h3>\r\n                  <Link to=\"class-single.html\">Bodybuilding</Link>\r\n                </h3>\r\n              </div>\r\n\r\n              <div className=\"owl-carousel-item\">\r\n                <Link to=\"class-single.html\">\r\n                  <img src=\"example/horizontal_slider3.jpg\" alt=\"Owl Image\" />\r\n                </Link>\r\n\r\n                <h3>\r\n                  <Link to=\"class-single.html\">Basketball Match</Link>\r\n                </h3>\r\n              </div>\r\n\r\n              <div className=\"owl-carousel-item\">\r\n                <Link to=\"class-single.html\">\r\n                  <img src=\"example/horizontal_slider2.jpg\" alt=\"Owl Image\" />\r\n                </Link>\r\n\r\n                <h3>\r\n                  <Link to=\"class-single.html\">Weight Training</Link>\r\n                </h3>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </Fragment>\r\n  );\r\n};\r\n\r\nexport default ProductsPage;\r\nRoutes\r\n\r\n  import { Fragment, useState } from \"react\";\r\n  import reactLogo from \"./assets/react.svg\";\r\n  import viteLogo from \"/vite.svg\";\r\n  import \"./App.css\";\r\n  import { Route, Routes } from \"react-router-dom\";\r\n  import HomePage from \"@/pages/HomePage\";\r\n  import Menubar from \"@/components/Menubar\";\r\n  import AppContainer from \"@/components/AppContainer\";\r\n  import AboutusPage from \"@/pages/AboutusPage\";\r\n  import CareersPage from \"@/pages/CareersPage\";\r\n  import ContactusPage from \"@/pages/ContactusPage\";\r\n  import SignPage from \"@/pages/SignPage\";\r\n  import ProductsPage from \"./pages/ProductsPage\";\r\n  import ProductDetails from \"./pages/ProductDetails\";\r\n  import CoursesPage from \"./pages/CoursesPage\";\r\n  import CourseDetails from \"./pages/CourseDetails\";\r\n  import TrainersPage from \"./pages/TrainersPage\";\r\n  import TrainerDetails from \"./pages/TrainerDetails\";\r\n  import offerDetails from \"./pages/offerDetails\";\r\n  import NewsPage from \"./pages/NewsPage\";\r\n  import NewsDetails from \"./pages/NewsDetails\";\r\n  import CareerDetailsPage from \"./pages/CareerDetailsPage\";\r\n  import CartPage from \"./pages/CartPage\";\r\n  import RegisterPage from \"./pages/RegisterPage\";\r\n\r\n  function App() {\r\n    return (\r\n      <Fragment>\r\n        <Routes>\r\n          <Route path=\"/\" element={<AppContainer/>}>\r\n            <Route path=\"/\" element={<HomePage />} />\r\n            <Route path=\"/about\" element={<AboutusPage />} />\r\n            <Route path=\"/careers\" element={<CareersPage />} />\r\n            <Route path=\"/career/details/:careerId\" element={<CareerDetailsPage />} />\r\n            <Route path=\"/contact-us\" element={<ContactusPage />} />\r\n            <Route path=\"/sign-in\" element={<SignPage />} />\r\n            <Route path=\"/register\" element={<RegisterPage />} />\r\n            <Route path=\"/courses\" element={<CoursesPage />} />\r\n            <Route path=\"/trainers\" element={<TrainersPage />} />\r\n            <Route path=\"/trainers/:trainerId\" element={<TrainerDetails />} />\r\n            <Route path=\"/offer/:offerId\" element={<offerDetails />} />\r\n            <Route path=\"/course/details/:courseId\" element={<CourseDetails />} />\r\n            <Route path=\"/products\" element={<ProductsPage />} />\r\n            <Route path=\"/product/:productId\" element={<ProductDetails />} />\r\n            <Route path=\"/news\" element={<NewsPage />} />\r\n            <Route path=\"/news/:newId\" element={<NewsDetails />} />\r\n            <Route path=\"/cart\" element={<CartPage />} />\r\n          </Route>\r\n        </Routes>\r\n      </Fragment>\r\n    );\r\n  }\r\n\r\n  export default App;\r\n\r\norderCart.js\r\nimport React, { Fragment, useEffect, useState } from \"react\";\r\nimport { orderPost } from \"../../apis/ordersApi\";\r\nimport { useParams } from \"react-router-dom\";\r\nimport PhoneInput from \"react-phone-input-2\";\r\nimport \"react-phone-input-2/lib/style.css\";\r\n\r\nimport { CircularProgress } from \"@mui/material\";\r\nimport Error from \"../Error\";\r\nimport { useDispatch } from \"react-redux\";\r\nimport { emptyCart } from \"../../store/cartSlice\";\r\n\r\nconst OrderCart = ({ cart }) => {\r\n  const dispatch = useDispatch();\r\n  const { lang } = useParams();\r\n  const locale = lang;\r\n  const dir = lang === \"en\" ? \"ltr\" : \"rtl\";\r\n  const [open, setOpen] = useState(false);\r\n  const [error, setError] = useState(false);\r\n  const [errors, setErrors] = useState({});\r\n  const [disabled, setDisabled] = useState(false);\r\n  const [text, setText] = useState(\"\");\r\n  const [country, setCountry] = useState(\"\");\r\n  const [values, setValues] = useState({\r\n    email: \"\",\r\n    name: \"\",\r\n    address: \"\",\r\n    message: \"\",\r\n  });\r\n  const [phone, setPhone] = useState(\"\");\r\n\r\n  useEffect(() => {\r\n    console.log({ country });\r\n  }, []);\r\n\r\n  const { email, name, address, message } = values;\r\n\r\n  const handleChange = (e) => {\r\n    setValues({ ...values, [e.target.name]: e.target.value });\r\n  };\r\n\r\n  const handleSubmit = (e) => {\r\n    e.preventDefault();\r\n    setDisabled(true);\r\n    const data = { ...values, phone, ...cart };\r\n    console.log({data})\r\n    orderPost({ locale, values: data })\r\n      .then((res) => {\r\n        setText(lang === \"en\" ? \"Order is successful!\" : \"تم الطلب بنجاح!\");\r\n        setOpen(true);\r\n        setDisabled(false);\r\n        setError(false);\r\n        dispatch(emptyCart());\r\n        setValues({ email: \"\", name: \"\", address: \"\", message: \"\" });\r\n        setPhone(\"\");\r\n      })\r\n      .catch((err) => {\r\n        setError(true);\r\n        setErrors(err.response.data.data);\r\n        setDisabled(false);\r\n      });\r\n  };\r\n\r\n  const handleClose = () => {\r\n    setOpen(false);\r\n    setError(false);\r\n  };\r\n\r\n  return (\r\n    <Fragment>\r\n      <form className=\"\" onSubmit={handleSubmit}>\r\n        <div className=\"form-group\">\r\n          <input\r\n            name=\"name\"\r\n            type=\"text\"\r\n            value={name}\r\n            onChange={handleChange}\r\n            className=\"form-control\"\r\n            placeholder={\"name\"}\r\n          />\r\n        </div>\r\n        <div className=\"form-group\">\r\n          <input\r\n            name=\"email\"\r\n            type=\"text\"\r\n            value={email}\r\n            onChange={handleChange}\r\n            className=\"form-control\"\r\n            placeholder={\"email\"}\r\n          />\r\n        </div>\r\n        <div className=\"form-group\">\r\n          <PhoneInput\r\n            name=\"phone\"\r\n            country={lang === \"ar\" ? \"sa\" : \"us\"}\r\n            value={phone}\r\n            onChange={(phone) => setPhone(phone)}\r\n            dir=\"ltr\"\r\n            inputClass=\"form-control\"\r\n            inputStyle={{\r\n              borderColor: \"#e1e6eb\",\r\n              boxShadow: \"none\",\r\n              width: \"100%\",\r\n              height: 40,\r\n              fontSize: 13,\r\n              lineHeight: 20,\r\n              borderRadius: \"6px !important\",\r\n              direction: lang === \"en\" ? \"ltr\" : \"rtl\",\r\n              paddingInlineStart: lang === \"ar\" && 50,\r\n            }}\r\n          />\r\n        </div>\r\n        <div className=\"form-group\">\r\n          <input\r\n            name=\"address\"\r\n            type=\"text\"\r\n            value={address}\r\n            onChange={handleChange}\r\n            className=\"form-control\"\r\n            placeholder={\"address\"}\r\n          />\r\n        </div>\r\n        <div className=\"form-group\">\r\n          <textarea\r\n            name=\"message\"\r\n            className=\"form-control\"\r\n            rows={6}\r\n            value={message}\r\n            onChange={handleChange}\r\n            placeholder={\"message\"}\r\n            defaultValue={\"\"}\r\n            style={{ minHeight: 100 }}\r\n          />\r\n        </div>\r\n        {!disabled ? (\r\n          <button type=\"submit\" className=\"site-button \">\r\n            <span className=\"font-weight-700 inline-block  p-lr15\">\r\n              {\"submit\"}\r\n            </span>\r\n          </button>\r\n        ) : (\r\n          <button disabled type=\"submit\" className=\"site-button \">\r\n            <CircularProgress color=\"success\" />\r\n          </button>\r\n        )}\r\n      </form>\r\n    </Fragment>\r\n  );\r\n};\r\n\r\nexport default OrderCart;\r\n\r\norderApi.js\r\nimport { api } from \"./base\";\r\n\r\nexport const orderPost = async ({ locale, values }) => {\r\n  api.defaults.headers = { locale };\r\n  const res = await api.post(`/order`, values);\r\n  return res.data;\r\n};\r\nsettingsSlice\r\nimport { createAsyncThunk, createSlice } from \"@reduxjs/toolkit\";\r\nimport { getSettings } from \"../../apis/settings\";\r\n\r\nexport const settingsFetch = createAsyncThunk(\"settings/fetch\", getSettings);\r\n\r\nconst initialState = {\r\n  settingsLoaded: false,\r\n  settingsLoading: false,\r\n  settingsError: null,\r\n  settingsData: null\r\n};\r\n\r\nexport const settingsSlice = createSlice({\r\n  name: \"settings\",\r\n  initialState,\r\n    extraReducers: builder => {\r\n        builder.addCase(settingsFetch.pending, (state, action) => {\r\n            state.settingsLoading = true;\r\n        });\r\n        \r\n        builder.addCase(settingsFetch.fulfilled, (state, action) => {\r\n            state.settingsLoading = false;\r\n            state.settingsLoaded = true;\r\n            state.settingsData = action.payload.data.settings;\r\n        });\r\n\r\n        builder.addCase(settingsFetch.rejected, (state, action) => {\r\n            state.settingsLoading = false;\r\n            state.settingsLoaded = false;\r\n            state.settingsError = action.payload;\r\n        });\r\n\r\n    }\r\n});\r\n\r\n// Action creators are generated for each case reducer function\r\n\r\nconst settingsReducer = settingsSlice.reducer;\r\n\r\nexport default settingsReducer;\r\n\r\n\r\nmenueBar.jsx\r\nimport React, { Fragment, useEffect, useState } from \"react\";\r\nimport { useDispatch, useSelector } from \"react-redux\";\r\nimport { Link, NavLink } from \"react-router-dom\";\r\nimport { settingsFetch } from \"../../store/settingsSlice\";\r\nimport ShoppingCartOutlinedIcon from \"@mui/icons-material/ShoppingCartOutlined\";\r\nimport { saveCart } from \"../../store/cartSlice\";\r\nimport styles from \"../../styles/Menubar.module.css\";\r\nimport SegmentIcon from \"@mui/icons-material/Segment\";\r\nimport { Box, Drawer } from \"@mui/material\";\r\n\r\nconst Menubar = () => {\r\n  const dispatch = useDispatch();\r\n  const [open, setOpen] = useState(false);\r\n\r\n  const locale = \"en\";\r\n  const data = useSelector((state) => state.settings);\r\n  const cart = useSelector((state) => state.cart);\r\n\r\n  const { settingsData, settingsLoaded, settingsLoading, settingsError } = data;\r\n\r\n  useEffect(() => {\r\n    dispatch(settingsFetch({ locale }));\r\n  }, [dispatch]);\r\n\r\n  useEffect(() => {\r\n    dispatch(saveCart());\r\n  }, []);\r\n\r\n  const toggleDrawer = () => {\r\n    setOpen(!open);\r\n  };\r\n\r\n  const handleClose = () => {\r\n    setOpen(false);\r\n  };\r\n\r\n  const DrawerList = (\r\n    <Box\r\n      sx={{ width: 250, zIndex: 1999 }}\r\n      role=\"presentation\"\r\n      onClick={toggleDrawer}\r\n    >\r\n      <ul\r\n        style={{\r\n          listStyle: \"none\",\r\n          marginTop: 50,\r\n          display: \"flex\",\r\n          flexDirection: \"column\",\r\n          gap: 20,\r\n        }}\r\n      >\r\n        <li>\r\n          <Link to=\"/\">Home</Link>\r\n        </li>\r\n        <li>\r\n          <Link to=\"about\">About</Link>\r\n        </li>\r\n\r\n        <li>\r\n          <Link to=\"/careers\">Careers</Link>\r\n        </li>\r\n        <li>\r\n          <Link to=\"/trainers\">Trainers</Link>\r\n        </li>\r\n        <li>\r\n          <Link to=\"/courses\">Courses</Link>\r\n        </li>\r\n        <li>\r\n          <Link to=\"/news\">News</Link>\r\n        </li>\r\n        <li className=\"dropdown mega-dropdown\">\r\n          <Link to=\"/products\">Store</Link>\r\n        </li>\r\n        <li>\r\n          <Link to=\"/contact-us\">Contact</Link>\r\n        </li>\r\n        <li\r\n          style={{\r\n            position: \"relative\",\r\n          }}\r\n        >\r\n          <NavLink to={`/cart`}>\r\n            <ShoppingCartOutlinedIcon sx={{fontSize: 22}} />\r\n          </NavLink>\r\n          {!!cart.totalQty && <div className=\"cart-badge\">{cart.totalQty}</div>}\r\n        </li>\r\n      </ul>\r\n    </Box>\r\n  );\r\n\r\n  return (\r\n    <Fragment>\r\n      <header style={{ zIndex: 10 }} id=\"header\">\r\n        <div className=\"top_beed\">\r\n          <div className=\"container\">\r\n            <div className=\"row\">\r\n              <div className=\"col-md-12\">\r\n                <nav id=\"primary_nav_wrap\" className=\"pull-right\">\r\n                  <ul>\r\n                    <li>\r\n                      <Link to=\"#\">Search Map</Link>\r\n                      <ul>\r\n                        <li>\r\n                          <Link to=\"/trainers\">Find trainers </Link>\r\n                        </li>\r\n                        <li>\r\n                          <Link to=\"/courses\">Find courses</Link>\r\n                        </li>\r\n                        <li>\r\n                          <Link to=\"/careers\">Find jobs</Link>\r\n                        </li>\r\n                      </ul>\r\n                    </li>\r\n                    <li>\r\n                      <Link to=\"/news\">News</Link>\r\n                    </li>\r\n                    <li>\r\n                      <Link to=\"#\">Policy</Link>\r\n                    </li>\r\n                    <li>\r\n                      <Link to=\"/register\">Sign Up</Link>\r\n                    </li>\r\n                    <li>\r\n                      <Link to=\"/sign-in\">Sign in</Link>\r\n                    </li>\r\n                  </ul>\r\n                </nav>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n        <div className=\"clearfix\"></div>\r\n        <div className=\"col-sm-4 m_t_10 social_raw_full\">\r\n          <Link to=\"#\" className=\"social_007\"></Link>\r\n          <Link to=\"#\" className=\"social_006\"></Link>\r\n          <Link to=\"#\" className=\"social_005\"></Link>\r\n          <Link to=\"#\" className=\"social_004\"></Link>\r\n          <Link to=\"#\" className=\"social_003\"></Link>\r\n          <Link to=\"#\" className=\"social_002\"></Link>\r\n          <Link to=\"#\" className=\"social_001\"></Link>\r\n        </div>\r\n        <div className={`container ${styles.navbar_container}`}>\r\n          <div className=\"\">\r\n            <Link to=\"/\">\r\n              {settingsLoaded && (\r\n                <img src={settingsData.logo} className=\"img-responsive\" />\r\n              )}\r\n            </Link>\r\n          </div>\r\n          <nav className=\"navbar navbar-default\">\r\n            <div className=\"navbar-header\">\r\n              <button\r\n                className=\"navbar-toggle\"\r\n                type=\"button\"\r\n                data-toggle=\"collapse\"\r\n                data-target=\".js-navbar-collapse\"\r\n              >\r\n                <span className=\"icon-bar\"></span>\r\n                <span className=\"icon-bar\"></span>\r\n                <span className=\"icon-bar\"></span>\r\n                <span className=\"icon-bar\"></span>\r\n              </button>\r\n            </div>\r\n\r\n            <div\r\n              style={{ margin: 0 }}\r\n              className=\"collapse navbar-collapse js-navbar-collapse pull-right\"\r\n            >\r\n              <ul className={`nav navbar-nav ${styles.navbar_responsive}`}>\r\n                <li>\r\n                  <Link to=\"/\">Home</Link>\r\n                </li>\r\n                <li>\r\n                  <Link to=\"about\">About</Link>\r\n                </li>\r\n\r\n                <li>\r\n                  <Link to=\"/careers\">careers</Link>\r\n                </li>\r\n                <li>\r\n                  <Link to=\"/trainers\">trainers</Link>\r\n                </li>\r\n                <li>\r\n                  <Link to=\"/courses\">courses</Link>\r\n                </li>\r\n                <li>\r\n                  <Link to=\"/news\">news</Link>\r\n                </li>\r\n                <li className=\"dropdown mega-dropdown\">\r\n                  <Link to=\"/products\">Store</Link>\r\n                </li>\r\n                <li>\r\n                  <Link to=\"/contact-us\">contact</Link>\r\n                </li>\r\n                <li\r\n                  style={{\r\n                    position: \"relative\",\r\n                  }}\r\n                >\r\n                  <NavLink to={`/cart`}>\r\n                    <ShoppingCartOutlinedIcon sx={{fontSize: 22}}/>\r\n                  </NavLink>\r\n                  {!!cart.totalQty && (\r\n                    <div className=\"cart-badge\">{cart.totalQty}</div>\r\n                  )}\r\n                </li>\r\n              </ul>\r\n            </div>\r\n            <div onClick={toggleDrawer} className={`${styles.burger_btn}`}>\r\n              <SegmentIcon className={`${styles.burger_icon}`} />\r\n            </div>\r\n          </nav>\r\n        </div>\r\n      </header>\r\n\r\n      <Drawer open={open} onClose={handleClose}>\r\n        {DrawerList}\r\n      </Drawer>\r\n    </Fragment>\r\n  );\r\n};\r\n\r\nexport default Menubar;\r\n\r\ni18.js\r\nimport i18next from \"i18next\";\r\nimport HttpBackend from \"i18next-http-backend\";\r\nimport LanguageDetector from \"i18next-browser-languagedetector\";\r\nimport { initReactI18next } from \"react-i18next\";\r\nimport { defaultLang } from \"./helpers/settings\";\r\nimport translationEN from \"./locales/en/translation.json\";\r\nimport translationAR from \"./locales/ar/translation.json\";\r\n\r\nconst resources = {\r\n  en: {\r\n    translation: translationEN,\r\n  },\r\n  ar: {\r\n    translation: translationAR,\r\n  },\r\n};\r\n\r\ni18next.use(LanguageDetector).use(initReactI18next).init({\r\n  resources,\r\n  // The default language\r\n  fallbackLng: [\'ar\', \'en\'],\r\n  lng: defaultLang,\r\n  supportedLngs: [\'ar\', \'en\'],\r\n  defaultLang\r\n});\r\n\r\nen/translation.json\r\n{\r\n  \"home\": \"Home\",\r\n  \"about\": \"About\",\r\n  \"percentage2\": \"Percentage\",\r\n  \"title\": \"Title\",\r\n  \"ar\": \"Arabic\",\r\n  \"en\": \"English\",\r\n  \"description\": \"Description\",\r\n  \"image\": \"Image\",\r\n  \"add_new\": \"Add New\",\r\n  \"save\": \"Save\",\r\n  \"cancel\": \"Cancel\"\r\n}\r\n\r\nar/translation.js\r\n{\r\n  \"home\": \"الرئيسية\",\r\n  \"about\": \"من نحن\",\r\n  \"title\": \"العنوان\",\r\n  \"ar\": \"العربية\",\r\n  \"en\": \"الانجلبزبة\",\r\n  \"description\": \"الوصف\",\r\n  \"image\": \"الصورة\",\r\n  \"add_new\": \"اضافة جديد\"\r\n}\r\n\r\nIndex.js\r\n/* eslint-disable jsx-a11y/anchor-is-valid */\r\n\r\nimport React from \"react\";\r\nimport ReactDOM from \"react-dom/client\";\r\nimport App from \"./App\";\r\nimport { BrowserRouter } from \"react-router-dom\";\r\nimport { store } from \"./store\";\r\nimport { Provider } from \"react-redux\";\r\nimport { HelmetProvider } from \"react-helmet-async\";\r\n\r\nimport \"./styles/index.css\";\r\nimport \"./swiper.css\";\r\nimport \"./i18n\";\r\n\r\nconst root = ReactDOM.createRoot(document.getElementById(\"root\"));\r\nroot.render(\r\n  <React.StrictMode>\r\n    <Provider store={store}>\r\n      <HelmetProvider>\r\n        <BrowserRouter basename={process.env.REACT_APP_BASE_NAME}>\r\n          <App />\r\n        </BrowserRouter>\r\n      </HelmetProvider>\r\n    </Provider>\r\n  </React.StrictMode>\r\n);\r\n\r\nhomeSlice\r\nimport { createAsyncThunk, createSlice } from \"@reduxjs/toolkit\";\r\nimport { getHome } from \"../../apis/home\";\r\n\r\nexport const homeFetch = createAsyncThunk(\"home/fetch\", getHome);\r\n\r\nconst initialState = {\r\n  homeLoaded: false,\r\n  homeLoading: false,\r\n  homeError: null,\r\n  homeData: {}\r\n};\r\n\r\nexport const homeSlice = createSlice({\r\n  name: \"home\",\r\n  initialState,\r\n    extraReducers: builder => {\r\n        builder.addCase(homeFetch.pending, (state, action) => {\r\n            state.homeLoading = true;\r\n        });\r\n        \r\n        builder.addCase(homeFetch.fulfilled, (state, action) => {\r\n            state.homeLoading = false;\r\n            state.homeLoaded = true;\r\n            state.homeData = action.payload.data;\r\n        });\r\n\r\n        builder.addCase(homeFetch.rejected, (state, action) => {\r\n            state.homeLoading = false;\r\n            state.homeLoaded = false;\r\n            state.homeError = action.payload;\r\n        });\r\n\r\n    }\r\n});\r\n\r\n// Action creators are generated for each case reducer function\r\n\r\nconst homeReducer = homeSlice.reducer;\r\n\r\nexport default homeReducer;\r\n\r\nhome.jsx\r\nimport { Fragment, useEffect, useState } from \"react\";\r\nimport { loadScript, route, publicUrlFor } from \"../../../globals/constants\";\r\nimport FastImage from \"../../../globals/elements/fastimg\";\r\nimport CountUp from \"react-countup\";\r\nimport SectionSlider1 from \"../../sections/home/home1/section-slider1\";\r\nimport { NavLink, useParams } from \"react-router-dom\";\r\nimport SectionHome1Team from \"../../sections/home/home1/section-home1-team\";\r\nimport SectionHome1Plans from \"../../sections/home/home1/section-home1-plans\";\r\nimport SectionHome1Blogs from \"../../sections/home/home1/section-home1-blogs\";\r\nimport SectionHome1Testimonials from \"../../sections/home/home1/section-home1-testimonials\";\r\nimport _data from \"../../../globals/data/data.json\";\r\nimport { getCounters } from \"../../../api/countersApi\";\r\nimport { useDispatch, useSelector } from \"react-redux\";\r\nimport { homeFetch } from \"../../../store/homeSlice\";\r\nimport { postContactUs } from \"../../../api/contactusApi\";\r\nimport SwiperWrapper from \"../SwiperWrapper\";\r\nimport { SwiperSlide } from \"swiper/react\";\r\nimport { Pagination, Navigation, FreeMode, Autoplay } from \"swiper/modules\";\r\nimport \"swiper/css/navigation\";\r\nimport { useTranslation } from \"react-i18next\";\r\nimport HomeSlider from \"../../sections/home/home1/HomeSlider\";\r\nimport { Audio } from \"react-loader-spinner\";\r\nimport Loader from \"../Loader\";\r\nimport ChooseusSlider from \"../../sections/home/home1/ChooseusSlider\";\r\nimport { pagesFetch } from \"../../../store/pagesSlice\";\r\nimport { JSONTree } from \"react-json-tree\";\r\nimport Error from \"../Error\";\r\nimport AlertToast from \"../Alert\";\r\nimport PhoneInput from \"react-phone-input-2\";\r\nimport \"react-phone-input-2/lib/style.css\";\r\n\r\nfunction Home1Page() {\r\n  const { lang } = useParams();\r\n  const { t } = useTranslation();\r\n  const dir = lang === \"en\" ? \"ltr\" : \"rtl\";\r\n  const locale = lang;\r\n  const dispatch = useDispatch();\r\n  const [open, setOpen] = useState(false);\r\n  const [text, setText] = useState(\"\");\r\n  const [alert, setAlert] = useState(\"\");\r\n  const [success, setSuccess] = useState(false);\r\n  const [error, setError] = useState(false);\r\n  const [errors, setErrors] = useState({});\r\n  const [disabled, setDisabled] = useState(false);\r\n  const [values, setValues] = useState({\r\n    email: \"\",\r\n    name: \"\",\r\n    message: \"\",\r\n  });\r\n  const [phone, setPhone] = useState(\"\");\r\n\r\n  const { email, name, message } = values;\r\n\r\n  const { homeData, pages } = useSelector((state) => state);\r\n\r\n  useEffect(() => {\r\n    dispatch(homeFetch({ locale }));\r\n    dispatch(pagesFetch({ locale }));\r\n  }, []);\r\n\r\n  const sliders = homeData.sliders;\r\n  const counters = homeData.counters;\r\n  const features = homeData.features;\r\n  const partners = homeData.partners;\r\n  const services = homeData.services;\r\n  const teams = homeData.teams;\r\n  const testimonials = homeData.testimonials;\r\n  const chooseus = homeData.chooseus;\r\n  const { aboutSection } = homeData;\r\n  const { serviceSection } = homeData;\r\n  const { teamSection } = homeData;\r\n  const { testimonialSection } = homeData;\r\n  const { chooseusSection } = homeData;\r\n  const { contactSection } = pages;\r\n\r\n  const { isLoading, loaded } = homeData;\r\n  const errorFetch = homeData.error;\r\n\r\n  useEffect(() => {\r\n    loadScript(\"js/custom.js\");\r\n  });\r\n\r\n  if (isLoading) {\r\n    return <Loader />;\r\n  }\r\n\r\n  if (errorFetch) {\r\n    return <h1>Fetching data error!</h1>;\r\n  }\r\n\r\n  const handleChange = (e) => {\r\n    setValues({ ...values, [e.target.name]: e.target.value });\r\n  };\r\n\r\n  const handleSubmit = (e) => {\r\n    e.preventDefault();\r\n    values[\"phone\"] = phone;\r\n    postContactUs({ locale, values })\r\n      .then((res) => {\r\n        setText(lang === \"en\" ? \"Order is successful!\" : \"تم الطلب بنجاح!\");\r\n        setOpen(true);\r\n        setDisabled(false);\r\n        setError(false);\r\n        setErrors({});\r\n        setValues({\r\n          name: \"\",\r\n          email: \"\",\r\n          message: \"\",\r\n        });\r\n        setPhone(\"\");\r\n      })\r\n      .catch((err) => {\r\n        setError(true);\r\n        setErrors(err.response.data.data);\r\n        setDisabled(false);\r\n      });\r\n  };\r\n\r\n  const handleClose = () => {\r\n    setOpen(false);\r\n    setError(false);\r\n  };\r\n\r\n  const generateCounters = () => {\r\n    return (\r\n      loaded &&\r\n      counters?.map((counter) => {\r\n        return (\r\n          <div key={counter.id} className=\"col-md-6 col-sm-6\">\r\n            <div className=\"m-b30 text-black mt-icon-box-wraper center bdr-1 bdr-solid bdr-gray-light  bg-white p-a20\">\r\n              <div className=\"counter font-42 font-weight-800 m-b15 site-text-primary\">\r\n                <CountUp end={Number(counter.count)} duration={10} />\r\n              </div>\r\n              <h4 className=\"m-tb0\">{counter.title}</h4>\r\n            </div>\r\n          </div>\r\n        );\r\n      })\r\n    );\r\n  };\r\n\r\n  const generateServices = () => {\r\n    return (\r\n      loaded &&\r\n      services?.map((service) => {\r\n        return (\r\n          <SwiperSlide key={service.id}>\r\n            <div\r\n              style={{ height: 300, width: 300 }}\r\n              className=\"item overflow-hide\"\r\n            >\r\n              <div className=\"mt-box\">\r\n                <div\r\n                  style={{ height: \"100%\" }}\r\n                  className=\"mt-img-effect overlay-2\"\r\n                >\r\n                  <FastImage\r\n                    src={service?.image}\r\n                    proImage={service?.image}\r\n                    alt={service?.title}\r\n                    style={{ height: 300 }}\r\n                  />\r\n                  <div className=\"overlay-2-bg bg-black\" />\r\n                  <div className=\"overlay-2-content\">\r\n                    <div className=\"p-a30 p-b20 d-flex flex-column align-items-center justify-content-center\">\r\n                      <h4 className=\"m-t0 m-b15 site-text-primary\">\r\n                        {service?.title}\r\n                      </h4>\r\n                      <div\r\n                        className=\"m-b20 text-white\"\r\n                        style={{\r\n                          fontSize: \"0.7rem\",\r\n                        }}\r\n                        dangerouslySetInnerHTML={{\r\n                          __html: service?.description,\r\n                        }}\r\n                      />\r\n\r\n                      <NavLink\r\n                        to={`/${lang}/service/detail/${service.id}`}\r\n                        className=\"site-button\"\r\n                      >\r\n                        {t(\"read_more\")}\r\n                      </NavLink>\r\n                    </div>\r\n                  </div>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </SwiperSlide>\r\n        );\r\n      })\r\n    );\r\n  };\r\n\r\n  return (\r\n    <div dir={dir}>\r\n      <AlertToast open={open} message={text} handleClose={handleClose} />\r\n\r\n      {/* Slider */}\r\n      {loaded && <HomeSlider slides={sliders} />}\r\n      {/* Shipment Solution*/}\r\n      <div\r\n        className=\"section-full p-t80 p-b50 bg-no-repeat bg-center bg-white\"\r\n        style={{\r\n          backgroundImage: `url(${publicUrlFor(\r\n            \"images/background/bg-map.png\"\r\n          )})`,\r\n        }}\r\n      >\r\n        <div className=\"container\">\r\n          <div className=\"row\">\r\n            <div className=\"col-lg-5 col-md-12\">\r\n              <div className=\"mt-box m-b30\">\r\n                <div className=\"mt-thum-bx mt-img-effect  mt-img-overlay2\">\r\n                  {loaded && (\r\n                    <FastImage\r\n                      src={aboutSection.image[0].url}\r\n                      proImage={aboutSection.image[0].url}\r\n                      alt=\"about image\"\r\n                    />\r\n                  )}\r\n                  <a\r\n                    href=\"https://player.vimeo.com/video/66491481\"\r\n                    className=\"mfp-video play-now\"\r\n                  >\r\n                    <i className=\"icon fa fa-play\" />\r\n                    <span className=\"ripple\" />\r\n                  </a>\r\n                </div>\r\n              </div>\r\n            </div>\r\n            <div className=\"col-lg-7 col-md-12\">\r\n              <div className=\"sx-shipment-wrap\">\r\n                <div className=\"mt-box m-b25\">\r\n                  <h2 className=\"display-block m-b15 m-t0\">\r\n                    {loaded && aboutSection.title}\r\n                  </h2>\r\n                  <h5 className=\"display-block m-b15 m-t0\">\r\n                    {loaded && aboutSection.subtitle}\r\n                  </h5>\r\n                  <div\r\n                    className=\"m-b15\"\r\n                    dangerouslySetInnerHTML={{\r\n                      __html: loaded && aboutSection.description,\r\n                    }}\r\n                  />\r\n\r\n                  <NavLink to={`/${lang}/about-us`} className=\"site-button\">\r\n                    {t(\"read_more\")}\r\n                  </NavLink>\r\n                </div>\r\n                <div className=\"row\">{generateCounters()}</div>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      {/* Latest Project */}\r\n      <div\r\n        className=\"section-full  p-tb80 bg-full-height bg-secondry bg-repeat-x city-slide-image\"\r\n        style={{\r\n          backgroundImage: `url(${publicUrlFor(\r\n            \"images/background/bg-trans-1.png\"\r\n          )})`,\r\n        }}\r\n      >\r\n        <div className=\"container-fluid\">\r\n          <div className=\"fillter-left-content\">\r\n            <div className=\"filter-left-part shake_image\">\r\n              <FastImage src=\"images/truck-2.png\" alt=\"\" />\r\n              <span className=\"tyre-position\">\r\n                <FastImage\r\n                  src=\"images/rotate-tyer.png\"\r\n                  alt=\"\"\r\n                  className=\"spin-tyres\"\r\n                />\r\n              </span>\r\n              <FastImage\r\n                className=\"blink-image\"\r\n                src=\"images/light-blink.png\"\r\n                alt=\"\"\r\n              />\r\n            </div>\r\n            <div className=\"container\">\r\n              <div className=\"section-head text-center sx-title-mid-area\">\r\n                <div className=\"mt-box  text-white m-b30\">\r\n                  <h2 className=\"m-tb0\">{loaded && serviceSection.title}</h2>\r\n                  <p className=\"m-b15\">{loaded && serviceSection.subtitle}</p>\r\n                </div>\r\n              </div>\r\n              <div className=\" filter-carousal-1-outer\">\r\n                <div className=\"filter-carousal-1\">\r\n                  {/* IMAGE CAROUSEL START */}\r\n                  <div className=\"section-content\">\r\n                    <SwiperWrapper\r\n                      slidesPerView={3}\r\n                      spaceBetween={30}\r\n                      modules={[Navigation]}\r\n                      loop\r\n                      className=\"mySwiper\"\r\n                    >\r\n                      {generateServices()}\r\n                    </SwiperWrapper>\r\n                    {/* </div> */}\r\n                  </div>\r\n                </div>\r\n              </div>\r\n              <div className=\"text-center p-t30\">\r\n                <NavLink to={`/${lang}/services`} className=\"site-button\">\r\n                  {t(\"more_our_services\")}\r\n                </NavLink>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      {/* Our Team */}\r\n      {loaded && <SectionHome1Team team={teams} teamSection={teamSection} />}\r\n\r\n      {/* Why Choose */}\r\n      <div className=\"section-full bg-change-section overlay-wraper p-t80 p-b50\">\r\n        <div className=\"overlay-main bg-secondry opacity-09\" />\r\n        <div className=\"bg-changer\">\r\n          <ChooseusSlider slides={sliders} />\r\n        </div>\r\n        <div className=\"container\">\r\n          {/* TITLE START*/}\r\n          <div className=\"section-head text-center text-white\">\r\n            <h2 data-title=\"Choose us\">{loaded && chooseusSection.title} </h2>\r\n            <div className=\"mt-separator-outer\">\r\n              <div className=\"mt-separator site-bg-primary\" />\r\n            </div>\r\n          </div>\r\n          {/* TITLE END*/}\r\n          <div className=\"section-content\">\r\n            <div className=\"row\">\r\n              {loaded &&\r\n                chooseus.map((item) => {\r\n                  return (\r\n                    <div\r\n                      key={item.id}\r\n                      className=\"col-lg-4 col-md-6 col-sm-6 m-b30\"\r\n                    >\r\n                      <div className=\"mt-icon-box-wraper  p-a30 bgcall-block hover-shadow hover-border-outer hover-border m-b30\">\r\n                        <div className=\"icon-md radius m-b15\">\r\n                          <FastImage\r\n                            src={item.image}\r\n                            proImage={item.image}\r\n                            alt={item.title}\r\n                          />\r\n                        </div>\r\n                        <div className=\"icon-content\">\r\n                          <h4 className=\"mt-tilte  m-b15 site-text-primary\">\r\n                            {item.title}\r\n                          </h4>\r\n                          <div\r\n                            className=\"text-white\"\r\n                            dangerouslySetInnerHTML={{\r\n                              __html: item.description,\r\n                            }}\r\n                          />\r\n                        </div>\r\n                      </div>\r\n                    </div>\r\n                  );\r\n                })}\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      {/* Testimonials */}\r\n      <div dir=\"ltr\">\r\n        {loaded && (\r\n          <SectionHome1Testimonials\r\n            testimonials={testimonials}\r\n            testimonialSection={testimonialSection}\r\n          />\r\n        )}\r\n      </div>\r\n\r\n      {/* Contact Us  */}\r\n\r\n      {error && (\r\n        <Error error={errors} errorsShow={error} handleClose={handleClose} />\r\n      )}\r\n      <div\r\n        className=\"section-full bg-white bg-right-center bg-no-repeat\"\r\n        style={{\r\n          backgroundImage: `url(${publicUrlFor(\r\n            \"images/background/bg-trans-2.png\"\r\n          )})`,\r\n        }}\r\n        dir={\"ltr\"}\r\n      >\r\n        <div className=\"container\">\r\n          <div className=\"row conntact-home\">\r\n            <div className=\"col-lg-5 col-md-5 col-sm-12\">\r\n              <div className=\"contact-home1-left bg-secondry\">\r\n                <div className=\"contact-tag-line bg-white site-text-primary\">\r\n                  {t(\"contact\")}\r\n                </div>\r\n                <div className=\"section-content p-lr30 p-tb30\">\r\n                  <div\r\n                    className=\"call-back-form\"\r\n                    style={{ zIndex: 1, position: \"relative\" }}\r\n                    dir={dir}\r\n                  >\r\n                    <h2 className=\"text-white m-t0\">{t(\"contact_us\")}</h2>\r\n                    <form\r\n                      className=\"cons-contact-form2 form-transparent\"\r\n                      onSubmit={handleSubmit}\r\n                    >\r\n                      <div className=\"form-group\">\r\n                        <input\r\n                          name=\"name\"\r\n                          type=\"text\"\r\n                          value={name}\r\n                          onChange={handleChange}\r\n                          className=\"form-control\"\r\n                          placeholder={t(\"name\")}\r\n                        />\r\n                      </div>\r\n                      <div className=\"form-group\">\r\n                        <input\r\n                          name=\"email\"\r\n                          type=\"text\"\r\n                          value={email}\r\n                          onChange={handleChange}\r\n                          className=\"form-control\"\r\n                          placeholder={t(\"email\")}\r\n                        />\r\n                      </div>\r\n                      <div className=\"form-group home-phone-page\">\r\n                        <PhoneInput\r\n                          name=\"phone\"\r\n                          country={lang === \"ar\" ? \"sa\" : \"us\"}\r\n                          value={phone}\r\n                          onChange={(phone) => setPhone(phone)}\r\n                          dir=\"ltr\"\r\n                          inputClass=\"form-control\"\r\n                          inputStyle={{\r\n                            border: \'none\',\r\n                            borderBottom: \'1px solid rgb(22, 28, 42)\',\r\n                            background: \'transparent\',\r\n                            boxShadow: \"none\",\r\n                            width: \"100%\",\r\n                            height: 40,\r\n                            fontSize: 13,\r\n                            lineHeight: 20,\r\n                            borderRadius: \"6px !important\",\r\n                            direction: lang === \"en\" ? \"ltr\" : \"rtl\",\r\n                            paddingInlineStart: lang === \"ar\" && 50,\r\n                          }}\r\n                          buttonStyle={{\r\n                            background: \'transparent\'\r\n                          }}\r\n                        />\r\n                      </div>\r\n                      <div className=\"form-group\">\r\n                        <textarea\r\n                          name=\"message\"\r\n                          className=\"form-control\"\r\n                          rows={3}\r\n                          value={message}\r\n                          onChange={handleChange}\r\n                          placeholder={t(\"message\")}\r\n                          defaultValue={\"\"}\r\n                        />\r\n                      </div>\r\n                      <button type=\"submit\" className=\"site-button \">\r\n                        <span className=\"font-weight-700 inline-block  p-lr15\">\r\n                          {t(\"submit\")}\r\n                        </span>\r\n                      </button>\r\n                    </form>\r\n                  </div>\r\n                </div>\r\n              </div>\r\n            </div>\r\n            <div className=\"section-content contact-home1-right\">\r\n              <div className=\"mt-box\">\r\n                <div className=\"mt-media\">\r\n                  <FastImage\r\n                    proImage={pages ? contactSection?.image[0].url : null}\r\n                    alt=\"\"\r\n                  />\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      {/* Our Client Logo */}\r\n      <div className=\"section-full bg-white p-tb50\">\r\n        <div className=\"container\">\r\n          <div className=\"section-head text-center text-white\">\r\n            <h2 style={{ color: \"#000\" }}>{t(\"partners\")} </h2>\r\n            <div className=\"mt-separator-outer\">\r\n              <div className=\"mt-separator site-bg-primary\" />\r\n            </div>\r\n          </div>\r\n          <div className=\"section-content\">\r\n            <SwiperWrapper\r\n              slidesPerView={5}\r\n              spaceBetween={30}\r\n              freeMode={true}\r\n              loop\r\n              autoplay\r\n              pagination={{\r\n                clickable: true,\r\n              }}\r\n              breakpoints={{\r\n                415: {\r\n                  slidesPerView: 1,\r\n                  spaceBetween: 5,\r\n                },\r\n                640: {\r\n                  slidesPerView: 2,\r\n                  spaceBetween: 40,\r\n                },\r\n                768: {\r\n                  slidesPerView: 4,\r\n                  spaceBetween: 40,\r\n                },\r\n                1024: {\r\n                  slidesPerView: 5,\r\n                  spaceBetween: 50,\r\n                },\r\n              }}\r\n              modules={[FreeMode, Pagination, Autoplay]}\r\n            >\r\n              {loaded &&\r\n                partners.map((item, index) => {\r\n                  return (\r\n                    <SwiperSlide key={index}>\r\n                      <FastImage\r\n                        src={item.image}\r\n                        proImage={item.image}\r\n                        alt=\"\"\r\n                        style={{\r\n                          width: 150,\r\n                          height: 150,\r\n                        }}\r\n                      />\r\n                    </SwiperSlide>\r\n                  );\r\n                })}\r\n            </SwiperWrapper>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  );\r\n}\r\nexport default Home1Page;\r\n\r\nhow to changer port in react\r\ncreate file name it .env and add the port with its port number\r\nPORT=5173\r\npackage.json\r\n{\r\n  \"name\": \"gym_boula\",\r\n  \"private\": true,\r\n  \"version\": \"0.0.0\",\r\n  \"type\": \"module\",\r\n  \"scripts\": {\r\n    \"dev\": \"vite\",\r\n    \"build\": \"vite build\",\r\n    \"lint\": \"eslint . --ext js,jsx --report-unused-disable-directives --max-warnings 0\",\r\n    \"start\": \"vite preview\"\r\n  },\r\n  \"dependencies\": {\r\n    \"@emotion/react\": \"^11.11.3\",\r\n    \"@emotion/styled\": \"^11.11.0\",\r\n    \"@googlemaps/markerclusterer\": \"^2.5.3\",\r\n    \"@mui/icons-material\": \"^5.15.10\",\r\n    \"@mui/material\": \"^5.15.10\",\r\n    \"@mui/x-date-pickers\": \"^6.19.5\",\r\n    \"@reduxjs/toolkit\": \"^2.1.0\",\r\n    \"@vis.gl/react-google-maps\": \"^1.0.0\",\r\n    \"axios\": \"^1.6.7\",\r\n    \"axois\": \"^0.0.1-security\",\r\n    \"dayjs\": \"^1.11.10\",\r\n    \"i18next\": \"^23.10.0\",\r\n    \"i18next-browser-languagedetector\": \"^7.2.0\",\r\n    \"query-string\": \"^9.0.0\",\r\n    \"react\": \"^18.2.0\",\r\n    \"react-dom\": \"^18.2.0\",\r\n    \"react-i18next\": \"^14.0.5\",\r\n    \"react-phone-input-2\": \"^2.15.1\",\r\n    \"react-redux\": \"^9.1.0\",\r\n    \"react-router-dom\": \"^6.21.1\",\r\n    \"react-router-to-array\": \"^0.1.3\",\r\n    \"swiper\": \"^11.0.5\"\r\n  },\r\n  \"devDependencies\": {\r\n    \"@types/react\": \"^18.2.43\",\r\n    \"@types/react-dom\": \"^18.2.17\",\r\n    \"@vitejs/plugin-react\": \"^4.2.1\",\r\n    \"eslint\": \"^8.55.0\",\r\n    \"eslint-plugin-react\": \"^7.33.2\",\r\n    \"eslint-plugin-react-hooks\": \"^4.6.0\",\r\n    \"eslint-plugin-react-refresh\": \"^0.4.5\",\r\n    \"vite\": \"^5.0.8\"\r\n  }\r\n}','2025-03-31 07:06:28','2025-07-13 05:58:06',1,0,1),(56,'Angular Refrence','','Angular Catalog\r\n\r\nTo get the npm version,\r\nnpm -v\r\nTo get the node version,\r\nnode -v\r\nTo get the Angular version,\r\nng v\r\nTo get the Jasmine version,\r\njasmine -v\r\nTo get the Karma version,\r\nkarma --version\r\nTo install Angular CLI,\r\nnpm install @angular/cli -g\r\nnpm install @angular/cli\r\nTo install the next version of Angular CLI,\r\nnpm install @angular/cli@next\r\nTo get help in the terminal,\r\nng help\r\nTo create a new project in Angular,\r\nng new project-name\r\nTo skip external dependencies while creating a new project,\r\nng new project-name --skip-install\r\nTo run the Angular project,\r\nng serve (or) npm start (or) ng serve --force\r\nng s -o // to open the project after serve\r\nDry Run,\r\nng new project-name --dry-run\r\nTo create a new component in the Angular Project,\r\nng generate component component-name\r\nng g c component-name\r\nTo avoid creating a new folder while creating a new component,\r\nng generate component component-name --flat\r\nTo create a build,\r\nng build\r\nTo create a build for a specific environment,\r\nng build --prod\r\nTo run test cases,\r\nng test\r\nTo run the end-to-end test,\r\nng e2e\r\nFor Angular Documentation,\r\nng doc\r\nTo change the angular-cli.json config file,\r\nng set\r\nTo create a directive in Angular,\r\nng generate directive directive-name\r\nng g d directive-name\r\nTo create a service in Angular,\r\nng generate service service-name\r\nng g s service-name\r\nTo create a class,\r\nng generate class class-name\r\nng g cl class-name\r\nTo create an interface,\r\nng generate interface interface-name\r\nng g i interface-name\r\nTo create a pipe,\r\nng generate pipe pipe-name\r\nng g p pipe-name\r\nTo create enum,\r\nng generate enum enum-name\r\nng g e enum-name\r\nTo create a module,\r\nng generate module module-name\r\nng g m module-name\r\nTo create a spec file for the module,\r\nng g m module-name --spec true -d\r\nTo create a module with routing,\r\nng g m module-name --routing\r\nTo create a guard to the route,\r\nng g guard guard-name\r\nTo remove node_modules,\r\nrm -rf node_modules\r\nTo uninstall Angular CLI,\r\nnpm uninstall --save-dev @angular/cli\r\nnpm uninstall -g angular-cli @angular/cli\r\nTo install the latest version of Angular CLI,\r\nnpm install --save-dev @angular/cli@latest\r\nTo update Angular CLI,\r\nng update @angular/cli\r\nng update @angular/core\r\nTo clean cache,\r\nnpm cache clean\r\nTo install TypeScript latest version,\r\nnpm install -g typescript@latest\r\nTo install Jasmine/Karma latest version,\r\nnpm install -g karma-jasmine@latest\r\nTo install TypeScript specific version,\r\nnpm install typescript@version-number\r\nTo install Jasmine specific version,\r\nnpm install -g jasmine@version-number\r\nTo install Karma specific version,\r\nnpm install -g karma@version-number\r\nTo run server json\r\nnpm run json-run db.json\r\nTo install bootstrap v5\r\nnpm install –save bootstrap@5 \r\n--force or --legacy-peer-deps in case of unable to resolve dependency tree Error\r\nAdd app-routing module\r\nng generate module app-routing --flat --module=app \r\nAdd ngx spinner\r\nnpm i ngx-spinner\r\nInstall ngx spinner\r\nnpm install ngx-spinner –save\r\n\r\n.htaccess in react\r\n<IfModule mod_rewrite.c>\r\n  RewriteEngine On\r\n  RewriteBase /\r\n  RewriteRule ^index\\.html$ - [L]\r\n  RewriteCond %{REQUEST_FILENAME} !-f\r\n  RewriteCond %{REQUEST_FILENAME} !-d\r\n  RewriteCond %{REQUEST_FILENAME} !-l\r\n  RewriteRule . /index.html [L]\r\n</IfModule>\r\n\r\n\r\nAngular packages\r\nhttps://www.positronx.io/free-angular-tutorials/ //Very important\r\nhttps://www.positronx.io/laravel-angular-token-based-authentication-with-jwt/\r\nhttps://www.positronx.io/laravel-jwt-authentication-tutorial-user-login-signup-api/\r\nIf you send the Accept header as application/json this will cause the Exception Handler to return JSON when handling the Unauthorized Exception	\r\nhttps://www.positronx.io/angular-internationalization-i18n-with-ngx-translate-tutorial/\r\nhttps://github.com/gilsdav/ngx-translate-router //localization\r\nhttps://www.youtube.com/@Kazanova22/videos //ITI Angulara and other courses\r\nhttps://www.positronx.io/how-to-integrate-owl-carousel-2-in-angular/\r\nhttps://www.learmoreseekmore.com/2022/06/angular-14-crud-example.html\r\nhttps://www.positronx.io/how-to-create-server-side-pagination-in-angular-app/\r\nhttps://getbootstrap.com/docs/5.0/components/\r\nhttps://napster2210.github.io/ngx-spinner/\r\nhttps://www.npmjs.com/package/ngx-spinner\r\nhttps://angular.io/guide/inputs-outputs\r\n//install font awesome in angular\r\nhttps://michalsnik.github.io/aos/\r\nhttps://www.npmjs.com/package/ngx-spinner\r\nhttps://animate.style/\r\nhttps://developer.mozilla.org/en-US/docs/Web/CSS/position //css guide\r\n//get current route\r\nhttps://stackoverflow.com/questions/34597835/how-to-get-current-route\r\n//sliders in different programming languages\r\nhttps://keen-slider.io/\r\nnpm i @fortawesome/fontawesome-free\r\n\"node_modules/@fortawesome/fontawesome-free/css/all.min.css\",\r\n\"node_modules/@fortawesome/fontawesome-free/js/all.min.js\",\r\nTo set default locale without localstorage to avoid changing current lang on reloading\r\nhttps://stackoverflow.com/questions/61010958/change-default-locale-in-angular\r\n\r\nAngular Lifecycle hooks\r\nngOnChanges: Called after a bound input (@input) property changes\r\nngOnInit: Called once the component is initialized (after constructor directly)\r\nngDoCheck: Called during every change detection run\r\nngAfterContentInit: Called after content (ng-content) has projected into view\r\nngAfterContentChecked: Called every time the projected content has been checked\r\nngAfterViewInit: Called after the components view (and child views) has been initialized\r\nngAfterViewChecked: Called every time the view (and child views) have been checked \r\nngOnDestroy: Called once the component is about to be destroyed\r\nNote: check them by console.log()\r\n\r\nTry\r\nngxspinner\r\nInstall bootstrap \r\nAnimate.css \r\nAos //animate on scroll\r\nallmediatrackby for loop\r\nProperty binding for attrbutes we add attrbute . before attrbilute name \r\n[attr.disabled]\r\nAngular material\r\nbudgets (warnings)\r\n** in routing to go for 404 page on error\r\n{ path: \'**\', component: NotFoundComponent },\r\nSafe pipe  dom sainitizer for empeddig \r\nAngular animation inout trigers\r\nbox shadow css generator\r\nColor site //to help in design colors\r\nGoogle fonts\r\nFontawsome cdn to use fontawesome in angular\r\nQuerySelector to reach elements in index\r\nngxlightbox\r\nngx pagination\r\n@input\r\n@output\r\nodd and even in css\r\n\r\nAngular notes\r\n1-Variables that should be affected by many functions in different components must be put in a service\r\n2-we can access parent class in a child class but we can not do the opposite\r\n3-Always use Solid principles \r\n4-Get data from api according to current route\r\nuse reload method to refire the get function after changing the language, this would help to avoid recalling request functions in sitchLang function\r\n5-use bootstrap flex to easily position items\r\n6-use onChange to refire apis in site \r\n7-Use Angular Course Udemy maximilian Resources as an angular code ref\r\n\r\n\r\n\r\n	\r\nAngular 14 CRUD Project\r\n\r\nNotes\r\nLearn angular from github app\r\n\r\n//index.html\r\n<!doctype html>\r\n<html lang=\"en\" dir=\"ltr\">\r\n<head>\r\n  <meta charset=\"utf-8\">\r\n  <title>Angular CRUD</title>\r\n  <base href=\"/\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n  <link rel=\"icon\" type=\"image/x-icon\" href=\"favicon.ico\">\r\n</head>\r\n<body>\r\n  <app-root></app-root>\r\n</body>\r\n</html>\r\n//app.module.ts\r\nimport { NgModule } from \'@angular/core\';\r\nimport { BrowserModule } from \'@angular/platform-browser\';\r\nimport { AppComponent } from \'./app.component\';\r\n\r\nimport { FruitsRoutingModule } from \'./fruits/fruits-routing.module\';\r\nimport { FruitsModule } from \'./fruits/fruits.module\';\r\n\r\nimport { PostsRoutingModule } from \'./posts/posts-routing.module\';\r\nimport { PostsModule } from \'./posts/posts.module\';\r\n\r\nimport { HttpClientModule, HttpClient } from \'@angular/common/http\';\r\nimport { AppRoutingModule } from \'./app-routing.module\';\r\nimport { FormsModule, ReactiveFormsModule } from \'@angular/forms\';\r\nimport { TranslateModule, TranslateLoader } from \'@ngx-translate/core\';\r\nimport { TranslateHttpLoader } from \'@ngx-translate/http-loader\';\r\nexport function HttpLoaderFactory(http: HttpClient) {\r\n  return new TranslateHttpLoader(http);\r\n}\r\n\r\n\r\n\r\n@NgModule({\r\n  declarations: [\r\n    AppComponent,\r\n  ],\r\n  imports: [\r\n    BrowserModule,\r\n    AppRoutingModule,\r\n    FruitsRoutingModule,\r\n    FruitsModule,\r\n    PostsRoutingModule,\r\n    PostsModule,\r\n    HttpClientModule,\r\n    FormsModule,\r\n    ReactiveFormsModule,\r\n    TranslateModule.forRoot({\r\n      defaultLanguage: \'en\',\r\n      loader: {\r\n        provide: TranslateLoader,\r\n        useFactory: HttpLoaderFactory,\r\n        deps: [HttpClient]\r\n      }\r\n    })\r\n\r\n  ],\r\n  providers: [],\r\n  bootstrap: [AppComponent]\r\n})\r\nexport class AppModule { }\r\n**************************************************************************\r\napp.component.html\r\n<nav class=\"navbar navbar-expand-lg navbar-dark bg-warning\">\r\n  <div class=\"container-fluid\">\r\n    <div class=\"container\">\r\n      <div class=\"row\">\r\n        <div class=\"col-1\">\r\n          <span class=\"form-inline\">\r\n            <select class=\"form-control\" #selectedLang (change)=\"switchLang(selectedLang.value)\">\r\n              <option *ngFor=\"let language of translate.getLangs()\" [value]=\"language\"\r\n                [selected]=\"language === translate.currentLang\">\r\n                {{ language }}\r\n              </option>\r\n            </select>\r\n          </span>\r\n        </div>\r\n        <div class=\"col text-center\">\r\n          <a class=\"navbar-brand text-dark fw-bold\">{{ \'dashboard\' | translate }}</a>\r\n        </div>\r\n        <div class=\"col-3  align-items-center d-flex justify-content-end\">\r\n          <a class=\"navbar-brand text-dark\" routerLink=\"/fruits/home\" routerLinkActive=\"active\"\r\n            [routerLinkActiveOptions]=\"{exact:true}\">{{ \'fruits\' | translate }}</a>\r\n          <a class=\"navbar-brand text-dark\" routerLink=\"/posts/home\" routerLinkActive=\"active\"\r\n            [routerLinkActiveOptions]=\"{exact:true}\">{{ \'posts\' | translate }}</a>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n</nav>\r\n<router-outlet></router-outlet>\r\n\r\n****************************************************************************\r\napp.component.ts\r\nimport { Component } from \'@angular/core\';\r\nimport { TranslateService } from \'@ngx-translate/core\';\r\nimport { FruitsService } from \'./fruits/fruits.service\';\r\n\r\n@Component({\r\n  selector: \'app-root\',\r\n  templateUrl: \'./app.component.html\',\r\n  styleUrls: [\'./app.component.css\']\r\n})\r\nexport class AppComponent {\r\n  title = \'Angular_CRUD\';\r\n\r\n\r\n\r\n  constructor(public translate: TranslateService, private fruitService: FruitsService) {\r\n    // this language will be used as a fallback when a translation isn\'t found in the current language\r\n    translate.addLangs([\'en\', \'ar\']);\r\n    translate.setDefaultLang(\'en\');\r\n    document.getElementsByTagName(\"html\")[0].setAttribute(\"lang\", this.translate.getDefaultLang());\r\n\r\n    // the lang to use, if the lang isn\'t available, it will use the current loader to get them\r\n    // translate.use(\'en\');\r\n  }\r\n  public static appLang: string = \'en\';\r\n\r\n  switchLang(lang: string) {\r\n\r\n    AppComponent.appLang = lang;\r\n    this.translate.use(lang);\r\n\r\n    this.fruitService.get(lang).subscribe((data) => {\r\n      this.fruitService.allFruits = data.data.fruits;\r\n    });\r\n\r\n    if (lang === \'ar\') {\r\n      document.getElementsByTagName(\"html\")[0].setAttribute(\"dir\", \"rtl\");\r\n      document.getElementsByTagName(\"html\")[0].setAttribute(\"lang\", \"ar\");\r\n    }\r\n    else {\r\n      document.getElementsByTagName(\"html\")[0].setAttribute(\"dir\", \"ltr\");\r\n      document.getElementsByTagName(\"html\")[0].setAttribute(\"lang\", \"en\");\r\n    }\r\n  }\r\n\r\n\r\n}\r\n\r\n********************************************************************\r\napp-routing.module.ts\r\n\r\nimport { NgModule } from \'@angular/core\';\r\nimport { RouterModule, Routes } from \'@angular/router\';\r\n\r\n\r\nconst routes: Routes = [\r\n    {\r\n      path: \'\',\r\n      redirectTo: \'posts/home\',\r\n      pathMatch: \'full\',\r\n    }    \r\n  ];\r\n\r\n  @NgModule({\r\n    imports: [RouterModule.forRoot(routes)],\r\n    exports: [RouterModule]\r\n  })\r\n\r\n  export class AppRoutingModule {\r\n}\r\n********************************************************************\r\nfruits.module.ts\r\nimport { NgModule } from \'@angular/core\';\r\nimport { CommonModule } from \'@angular/common\';\r\n\r\nimport { FruitsRoutingModule } from \'./fruits-routing.module\';\r\nimport { HomeComponent } from \'./home/home.component\';\r\nimport { CreateComponent } from \'./create/create.component\';\r\nimport { FormsModule, ReactiveFormsModule } from \'@angular/forms\';\r\nimport { EditComponent } from \'./edit/edit.component\';\r\nimport {TranslateModule} from \'@ngx-translate/core\';\r\n\r\n\r\n@NgModule({\r\n  declarations: [\r\n    HomeComponent,\r\n    CreateComponent,\r\n    EditComponent\r\n  ],\r\n  imports: [\r\n    CommonModule,\r\n    FruitsRoutingModule,\r\n    FormsModule,\r\n    ReactiveFormsModule,\r\n    TranslateModule,\r\n  ]\r\n})\r\nexport class FruitsModule { }\r\n*************************************************************************\r\nfruits.service.ts\r\nimport { Injectable } from \'@angular/core\';\r\nimport { HttpClient } from \'@angular/common/http\';\r\nimport { Fruits } from \'./fruits\';\r\nimport { Observable } from \'rxjs\';\r\n@Injectable({\r\n  providedIn: \'root\',\r\n})\r\nexport class FruitsService {\r\n  constructor(private http: HttpClient) {}\r\n\r\n  allFruits: Fruits[] = [];\r\n\r\n  get(lang:string):Observable<any>  {\r\n    return this.http.get<any>(\'http://127.0.0.1:8000/api/fruits?lang=\'+lang);\r\n  }\r\n\r\n  create(payload: any) {\r\n    return this.http.post<any>(\'http://localhost:3000/fruits\', payload);\r\n  }\r\n\r\n  getById(id: number , lang:string) {\r\n    // return this.http.get<any>(`http://localhost:3000/fruits/${id}`);\r\n    console.log(id);\r\n   \r\n    return this.http.get<any>(`http://127.0.0.1:8000/api/fruit/${id}?lang=${lang}`);\r\n   }\r\n   \r\n   update(payload:any){\r\n    return this.http.put(`http://localhost:3000/fruits/${payload.id}`,payload);\r\n   }\r\n\r\n   delete(id:number){\r\n    return this.http.delete<any>(`http://localhost:3000/fruits/${id}`);\r\n }\r\n\r\n}\r\n\r\n****************************************************************************\r\nfruits.ts\r\nexport interface Fruits {\r\n    id: number;\r\n    name: string;\r\n    quantity: number;\r\n    price: number;\r\n  }\r\n*******************************************************************************\r\nfruits-routing.module.ts\r\nimport { NgModule } from \'@angular/core\';\r\nimport { RouterModule, Routes } from \'@angular/router\';\r\nimport { HomeComponent } from \'./home/home.component\';\r\nimport { CreateComponent } from \'./create/create.component\';\r\nimport { EditComponent } from \'./edit/edit.component\';\r\n\r\n\r\n\r\nconst routes: Routes = [  {\r\n  path: \'fruits/home\',\r\n  component: HomeComponent,\r\n},\r\n{\r\n  path: \'fruits/create\',\r\n  component: CreateComponent,\r\n},\r\n{\r\n  path:\'fruits/edit/:id\',\r\n  component: EditComponent\r\n}\r\n];\r\n\r\n@NgModule({\r\n  imports: [RouterModule.forRoot(routes)],\r\n  exports: [RouterModule]\r\n})\r\nexport class FruitsRoutingModule { }\r\n**************************************************************************\r\nhome.component.html\r\n<!-- Modal -->\r\n<div class=\"modal fade\" id=\"deleteModal\" tabindex=\"-1\" aria-labelledby=\"exampleModalLabel\" aria-hidden=\"true\">\r\n  <div class=\"modal-dialog\">\r\n    <div class=\"modal-content\">\r\n      <div class=\"modal-header\">\r\n        <h5 class=\"modal-title\" id=\"exampleModalLabel\">{{ \'warning\' | translate }}</h5>\r\n        <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\r\n      </div>\r\n      <div class=\"modal-body\">\r\n        {{ \'sure\' | translate }}\r\n      </div>\r\n      <div class=\"modal-footer\">\r\n        <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">{{ \'close\' | translate }}</button>\r\n        <button type=\"button\" class=\"btn btn-danger\" (click)=\"delete()\">{{ \'confirm_delete\' | translate }}</button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<div class=\"container\">\r\n  <div class=\"container\">\r\n    <div class=\"row mt-2\">\r\n      <div class=\"col col-md-12 offset-md-12\">\r\n        <a class=\"btn btn-success\" routerLink=\"/fruits/create\">{{ \'create\' | translate }}</a>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <table class=\"table\">\r\n    <thead>\r\n      <tr>\r\n        <th scope=\"col\">#</th>\r\n        <th scope=\"col\">{{ \'name\' | translate }}</th>\r\n        <th scope=\"col\">{{ \'quantity\' | translate }}</th>\r\n        <th scope=\"col\">{{ \'price\' | translate }}</th>\r\n        <th scope=\"col\"></th>\r\n        <th scope=\"col\"></th>\r\n      </tr>\r\n    </thead>\r\n    <tbody>\r\n     <ng-container *ngFor=\"let item of _fruitService.allFruits; let indexOfelement=index;\">\r\n      <tr>\r\n        <th scope=\"row\">{{ indexOfelement+1 }}</th>\r\n        <td>{{ item.name }}</td>\r\n        <td>{{ item.quantity }}</td>\r\n        <td>{{ item.price }}</td>\r\n        <td>\r\n          <a class=\"btn btn-primary\" [routerLink]=\"[\'/fruits/edit\', item.id]\">{{ \'edit\' | translate }}</a>\r\n        </td>\r\n        <td>\r\n          <button type=\"button\" (click)=\"openDeleteModal(item.id)\" class=\"btn btn-danger\">{{ \'delete\' |          translate }}</button>\r\n        </td>\r\n      </tr>\r\n    </ng-container>\r\n    </tbody>\r\n  </table>\r\n</div>\r\n***************************************************************************\r\nhome.component.ts\r\nimport { Component, OnInit } from \'@angular/core\';\r\nimport { AppComponent } from \'src/app/app.component\';\r\nimport { Fruits } from \'../fruits\';\r\nimport { FruitsService } from \'../fruits.service\';\r\n \r\ndeclare var window: any;\r\n \r\n@Component({\r\n  selector: \'app-home\',\r\n  templateUrl: \'./home.component.html\',\r\n  styleUrls: [\'./home.component.css\'],\r\n})\r\nexport class HomeComponent implements OnInit {\r\n  deleteModal: any;\r\n  idTodelete: number = 0;\r\n\r\n \r\n  constructor(public _fruitService: FruitsService) {\r\n    this.get(AppComponent.appLang);\r\n  }\r\n \r\n  ngOnInit(): void {\r\n    this.deleteModal = new window.bootstrap.Modal(\r\n      document.getElementById(\'deleteModal\')\r\n    );\r\n \r\n   \r\n   \r\n  }\r\n \r\n  get(lang: string) {\r\n      this._fruitService.get(lang).subscribe((data) => {\r\n      this._fruitService.allFruits = data.data.fruits;\r\n    });\r\n  }\r\n \r\n  openDeleteModal(id: number) {\r\n    this.idTodelete = id;\r\n    this.deleteModal.show();\r\n  }\r\n \r\n  delete() {\r\n    this._fruitService.delete(this.idTodelete).subscribe({\r\n      next: (data) => {\r\n        this._fruitService.allFruits = this._fruitService.allFruits .filter(_ => _.id != this.idTodelete)\r\n        this.deleteModal.hide();\r\n      },\r\n    });\r\n  }\r\n}\r\n**************************************************************************\r\nedit.component.html\r\n<div class=\"container\">\r\n  <legend>{{ \'edit_item\' | translate }}</legend>\r\n  <form [formGroup]=\"fruitForm\" (ngSubmit)=\"update()\">\r\n     \r\n    <div class=\"form-group\">\r\n        <label for=\"name\">{{ \'name\' | translate }}</label>\r\n        <input\r\n            formControlName=\"name\"\r\n            [(ngModel)] = \"form.name\"\r\n            id=\"name\"\r\n            type=\"text\"\r\n            class=\"form-control\">\r\n        <div *ngIf=\"f[\'name\'].touched && f[\'name\'].invalid\" class=\"alert alert-danger\">\r\n            <div *ngIf=\"f[\'name\'].errors && f[\'name\'].errors[\'required\']\">{{ \'name_required\' | translate }}</div>\r\n            <div *ngIf=\"f[\'name\'].errors && f[\'name\'].errors[\'minlength\']\">{{ \'name_character\' | translate }}</div>\r\n        </div>\r\n    </div>\r\n     \r\n    <div class=\"form-group\">\r\n        <label for=\"price\">{{ \'price\' | translate }}</label>\r\n        <input\r\n            formControlName=\"price\"\r\n            [(ngModel)] = \"form.price\"\r\n            id=\"price\"\r\n            type=\"text\"\r\n            class=\"form-control\">\r\n        <div *ngIf=\"f[\'price\'].touched && f[\'price\'].invalid\" class=\"alert alert-danger\">\r\n            <div *ngIf=\"f[\'price\'].errors && f[\'price\'].errors[\'required\']\">{{ \'price_required\' | translate }}</div>\r\n            <div *ngIf=\"f[\'price\'].errors && f[\'price\'].errors[\'pattern\']\">{{ \'price_number\' | translate }}</div>\r\n        </div>\r\n    </div>\r\n     \r\n    <div class=\"form-group\">\r\n        <label for=\"quantity\">{{ \'quantity\' | translate }}</label>\r\n        <input\r\n            formControlName=\"quantity\"\r\n            [(ngModel)] = \"form.quantity\"\r\n            id=\"quantity\"\r\n            type=\"number\"\r\n            class=\"form-control\">\r\n        <div *ngIf=\"f[\'quantity\'].touched && f[\'quantity\'].invalid\" class=\"alert alert-danger\">\r\n            <div *ngIf=\"f[\'quantity\'].errors && f[\'quantity\'].errors[\'required\']\">{{ \'quantity_required\' | translate }}</div>\r\n            <div *ngIf=\"f[\'quantity\'].errors && f[\'quantity\'].errors[\'pattern\']\">{{ \'quantity_number\' | translate }}</div>\r\n        </div>\r\n    </div>\r\n   \r\n    <div class=\"pt-2\">\r\n      <button class=\"btn btn-primary\" [disabled]=\"fruitForm.invalid\" type=\"submit\">{{ \'edit\' | translate }}</button>\r\n    </div>\r\n</form>\r\n</div>\r\n****************************************************************************\r\nedit.component.ts\r\nimport { Component, OnInit, Input, Output } from \'@angular/core\';\r\nimport { ActivatedRoute, Router } from \'@angular/router\';\r\nimport { Fruits } from \'../fruits\';\r\nimport { FruitsService } from \'../fruits.service\';\r\nimport { FormGroup, FormControl, Validators} from \'@angular/forms\';\r\nimport { AppComponent } from \'src/app/app.component\';\r\n@Component({\r\n  selector: \'app-edit\',\r\n  templateUrl: \'./edit.component.html\',\r\n  styleUrls: [\'./edit.component.css\'],\r\n})\r\nexport class EditComponent implements OnInit {\r\n  form: Fruits = {\r\n    id: 0,\r\n    name: \'\',\r\n    price: 0,\r\n    quantity: 0,\r\n  };\r\n\r\n  fruitForm= new FormGroup({\r\n    name: new FormControl(\'\', [Validators.required, Validators.minLength(3)]),\r\n    price: new FormControl(\'\', [Validators.required,Validators.pattern(\'[0-9]*\')]),\r\n    quantity: new FormControl(\'\', [Validators.required,Validators.pattern(\'[0-9]*\')]),\r\n  });\r\n\r\n  // @Output() x = 50;\r\n  constructor(\r\n    private route: ActivatedRoute,\r\n    private router: Router,\r\n    private fruitService: FruitsService\r\n  ) {\r\n  }\r\n\r\n  ngOnInit(): void {\r\n    this.route.paramMap.subscribe((param) => {\r\n      var id = Number(param.get(\'id\'));      \r\n      this.getById(id);\r\n\r\n    });\r\n  }\r\n\r\n  getById(id: number) {\r\n    this.fruitService.getById(id , AppComponent.appLang).subscribe((data) => {\r\n      this.form = data.data.fruit;\r\n    });\r\n  }\r\n\r\n  update() {\r\n    this.fruitService.update(this.form)\r\n      .subscribe({\r\n        next: (data) => {\r\n          this.router.navigate([\"/fruits/home\"]);\r\n        },\r\n        error: (err) => {\r\n          console.log(err);\r\n        }\r\n      })\r\n  }\r\n\r\n  get f(){\r\n    return this.fruitForm.controls;\r\n  }\r\n \r\n\r\n\r\n}\r\n**************************************************************************\r\ncreate.component.html\r\n<div class=\"container\">\r\n    <legend>{{ \'create_item\' | translate }}</legend>\r\n    <form [formGroup]=\"fruitForm\" (ngSubmit)=\"create()\">\r\n       \r\n      <div class=\"form-group\">\r\n          <label for=\"name\">{{ \'name\' | translate }}</label>\r\n          <input\r\n              formControlName=\"name\"\r\n              [(ngModel)] = \"form.name\"\r\n              id=\"name\"\r\n              type=\"text\"\r\n              class=\"form-control\">\r\n          <div *ngIf=\"f[\'name\'].touched && f[\'name\'].invalid\" class=\"alert alert-danger\">\r\n              <div *ngIf=\"f[\'name\'].errors && f[\'name\'].errors[\'required\']\">{{ \'name_required\' | translate }}</div>\r\n              <div *ngIf=\"f[\'name\'].errors && f[\'name\'].errors[\'minlength\']\">{{ \'name_character\' | translate }}</div>\r\n          </div>\r\n      </div>\r\n       \r\n      <div class=\"form-group\">\r\n          <label for=\"price\">{{ \'price\' | translate }}</label>\r\n          <input\r\n              formControlName=\"price\"\r\n              [(ngModel)] = \"form.price\"\r\n              id=\"price\"\r\n              type=\"text\"\r\n              class=\"form-control\">\r\n          <div *ngIf=\"f[\'price\'].touched && f[\'price\'].invalid\" class=\"alert alert-danger\">\r\n              <div *ngIf=\"f[\'price\'].errors && f[\'price\'].errors[\'required\']\">{{ \'price_required\' | translate }}</div>\r\n              <div *ngIf=\"f[\'price\'].errors && f[\'price\'].errors[\'pattern\']\">{{ \'price_number\' | translate }}</div>\r\n          </div>\r\n      </div>\r\n       \r\n      <div class=\"form-group\">\r\n          <label for=\"quantity\">{{ \'quantity\' | translate }}</label>\r\n          <input\r\n              formControlName=\"quantity\"\r\n              [(ngModel)] = \"form.quantity\"\r\n              id=\"quantity\"\r\n              type=\"number\"\r\n              class=\"form-control\">\r\n          <div *ngIf=\"f[\'quantity\'].touched && f[\'quantity\'].invalid\" class=\"alert alert-danger\">\r\n              <div *ngIf=\"f[\'quantity\'].errors && f[\'quantity\'].errors[\'required\']\">{{ \'quantity_required\' | translate }}</div>\r\n              <div *ngIf=\"f[\'quantity\'].errors && f[\'quantity\'].errors[\'pattern\']\">{{ \'quantity_number\' | translate }}</div>\r\n          </div>\r\n      </div>\r\n     \r\n      <div class=\"pt-2\">\r\n        <button class=\"btn btn-primary\" [disabled]=\"fruitForm.invalid\" type=\"submit\">{{ \'submit\' | translate }}</button>\r\n      </div>\r\n  </form>\r\n  </div>\r\n\r\n******************************************************************************\r\ncreate.component.ts\r\nimport { Component, OnInit } from \'@angular/core\';\r\nimport { Router } from \'@angular/router\';\r\nimport { Fruits } from \'../fruits\';\r\nimport { FruitsService } from \'../fruits.service\';\r\nimport { FormGroup, FormControl, Validators} from \'@angular/forms\';\r\n\r\n@Component({\r\n  selector: \'app-create\',\r\n  templateUrl: \'./create.component.html\',\r\n  styleUrls: [\'./create.component.css\'],\r\n})\r\nexport class CreateComponent implements OnInit {\r\n  form: Fruits = {\r\n    id: 0,\r\n    name: \'\',\r\n    price: 0,\r\n    quantity: 0,\r\n  };\r\n\r\n  fruitForm= new FormGroup({\r\n    name: new FormControl(\'\', [Validators.required, Validators.minLength(3)]),\r\n    price: new FormControl(\'\', [Validators.required,Validators.pattern(\'[0-9]*\')]),\r\n    quantity: new FormControl(\'\', [Validators.required,Validators.pattern(\'[0-9]*\')]),\r\n  });\r\n\r\n//  form: any;\r\n\r\n  constructor(private fruitService: FruitsService,\r\n    private router: Router) { }\r\n\r\n  ngOnInit(): void { }\r\n\r\n  create() {\r\n    this.fruitService.create(this.form)\r\n    .subscribe({\r\n      next: (data) => {\r\n        this.router.navigate([\"/fruits/home\"])\r\n      },\r\n      error: (err) => {\r\n        console.log(err);\r\n      }\r\n    })\r\n  }\r\n\r\n  get f(){\r\n    return this.fruitForm.controls;\r\n  }\r\n \r\n}\r\n************************************************************************\r\nAngular Basics\r\n\r\n<p>{{ \'Server\' }} with ID {{ serverId }} is {{ getServerStatus() }}</p>\r\n***********************************************************************\r\nimport { Component } from \'@angular/core\';\r\n\r\n@Component({\r\n  selector: \'app-server\',\r\n  templateUrl: \'./server.component.html\'\r\n})\r\nexport class ServerComponent {\r\n  serverId: number = 10;\r\n  serverStatus: string = \'offline\';\r\n\r\n  getServerStatus() {\r\n    return this.serverStatus;\r\n  }\r\n}\r\n**********************************************************************\r\n<div class=\"container\">\r\n  <div class=\"row\">\r\n    <div class=\"col-xs-12\">\r\n      <h3>I\'m in the AppComponent!</h3>\r\n      <hr>\r\n      <app-servers></app-servers>\r\n      <!--<div app-servers></div>-->\r\n      <!--<div class=\"app-servers\"></div>-->\r\n    </div>\r\n  </div>\r\n</div>\r\n*********************************************************************\r\nimport { Component } from \'@angular/core\';\r\n\r\n@Component({\r\n  selector: \'app-root\',\r\n  templateUrl: \'./app.component.html\',\r\n  // styleUrls: [\'./app.component.css\']\r\n  styles: [`\r\n    h3 {\r\n      color: dodgerblue;\r\n    }\r\n  `]\r\n})\r\nexport class AppComponent {\r\n}\r\n\r\n*******************************************************************\r\n\r\n<p\r\n  [ngStyle]=\"{backgroundColor: getColor()}\"\r\n  [ngClass]=\"{online: serverStatus === \'online\'}\">\r\n  {{ \'Server\' }} with ID {{ serverId }} is {{ getServerStatus() }}\r\n</p>\r\n******************************************************************\r\nimport { Component } from \'@angular/core\';\r\n\r\n@Component({\r\n  selector: \'app-server\',\r\n  templateUrl: \'./server.component.html\',\r\n  styles: [`\r\n    .online {\r\n      color: white;\r\n    }\r\n  `]\r\n})\r\nexport class ServerComponent {\r\n  serverId: number = 10;\r\n  serverStatus: string = \'offline\';\r\n\r\n  constructor() {\r\n    this.serverStatus = Math.random() > 0.5 ? \'online\' : \'offline\';\r\n  }\r\n\r\n  getServerStatus() {\r\n    return this.serverStatus;\r\n  }\r\n\r\n  getColor() {\r\n    return this.serverStatus === \'online\' ? \'green\' : \'red\';\r\n  }\r\n}\r\n*********************************************************************\r\n<label>Server Name</label>\r\n<input\r\n  type=\"text\"\r\n  class=\"form-control\"\r\n  (input)=\"onUpdateServerName($event)\">\r\n\r\n  <p>{{ serverName }}</p>\r\n  <p [innerText]=\"allowNewServer\"></p>\r\n  <p>{{ serverCreationStatus }}</p>\r\n\r\n\r\n<br>\r\n\r\n<input\r\n  type=\"text\"\r\n  class=\"form-control\"\r\n  [(ngModel)]=\"serverName\">\r\n\r\n<button\r\n  class=\"btn btn-primary\"\r\n  [disabled]=\"!allowNewServer\"\r\n  (click)=\"onCreateServer()\">Add Server</button>\r\n\r\n<p *ngIf=\"serverCreated\">Server was created, server name is {{ serverName }}</p>\r\n<app-server *ngFor=\"let server of servers\"></app-server>\r\n*****************************************************************************\r\nimport { Component, OnInit } from \'@angular/core\';\r\n\r\n@Component({\r\n  // selector: \'[app-servers]\',\r\n  // selector: \'.app-servers\',\r\n  selector: \'app-servers\',\r\n  // template: `\r\n  //   <app-server></app-server>\r\n  //   <app-server></app-server>`,\r\n  templateUrl: \'./servers.component.html\',\r\n  styleUrls: [\'./servers.component.css\']\r\n})\r\nexport class ServersComponent implements OnInit {\r\n  allowNewServer = false;\r\n  serverCreationStatus = \'No server was created!\';\r\n  serverName = \'Testserver\';\r\n  serverCreated = false;\r\n  servers = [\'Testserver\', \'Testserver 2\'];\r\n\r\n  constructor() {\r\n    setTimeout(() => {\r\n      this.allowNewServer = true;\r\n    }, 2000);\r\n  }\r\n\r\n  ngOnInit() {\r\n  }\r\n\r\n  onCreateServer() {\r\n    this.serverCreated = true;\r\n    this.servers.push(this.serverName);\r\n    this.serverCreationStatus = \'Server was created! Name is \' + this.serverName;\r\n  }\r\n\r\n  onUpdateServerName(event: Event) {\r\n    this.serverName = (<HTMLInputElement>event.target).value;\r\n  }\r\n}\r\n\r\n*************************************************************************\r\nAngular Login and Register\r\n\r\nauth-state.service.ts\r\nimport { Injectable } from \'@angular/core\';\r\nimport { BehaviorSubject } from \'rxjs/internal/BehaviorSubject\';\r\nimport { TokenService } from \'../shared/token.service\';\r\n@Injectable({\r\n  providedIn: \'root\',\r\n})\r\nexport class AuthStateService {\r\n  private userState = new BehaviorSubject<boolean>(this.token.isLoggedIn()!);\r\n  userAuthState = this.userState.asObservable();\r\n  constructor(public token: TokenService) {}\r\n  setAuthState(value: boolean) {\r\n    this.userState.next(value);\r\n  }\r\n}\r\nauth.interceptor.ts\r\nimport { Injectable } from \"@angular/core\";\r\nimport { HttpInterceptor, HttpRequest, HttpHandler } from \"@angular/common/http\";\r\nimport { TokenService } from \"../shared/token.service\";\r\n@Injectable()\r\nexport class AuthInterceptor implements HttpInterceptor {\r\n    constructor(private tokenService: TokenService) { }\r\n    intercept(req: HttpRequest<any>, next: HttpHandler) {\r\n        const accessToken = this.tokenService.getToken();\r\n        req = req.clone({\r\n            setHeaders: {\r\n                Authorization: \"Bearer \" + accessToken\r\n            }\r\n        });\r\n        return next.handle(req);\r\n    }\r\n}\r\nauth.service.ts\r\nimport { Injectable } from \'@angular/core\';\r\nimport { Observable } from \'rxjs\';\r\nimport { HttpClient } from \'@angular/common/http\';\r\n// User interface\r\nexport class User {\r\n  name!: String;\r\n  email!: String;\r\n  password!: String;\r\n  password_confirmation!: String;\r\n}\r\n@Injectable({\r\n  providedIn: \'root\',\r\n})\r\nexport class AuthService {\r\n  constructor(private http: HttpClient) {}\r\n  // User registration\r\n  register(user: User): Observable<any> {\r\n    return this.http.post(\'http://127.0.0.1:8000/api/auth/register\', user);\r\n  }\r\n  // Login\r\n  signin(user: User): Observable<any> {\r\n    return this.http.post<any>(\'http://127.0.0.1:8000/api/auth/login\', user);\r\n  }\r\n  // Access user profile\r\n  profileUser(): Observable<any> {\r\n    return this.http.get(\'http://127.0.0.1:8000/api/auth/user-profile\');\r\n  }\r\n}\r\ntoken.service.ts\r\nimport { Injectable } from \'@angular/core\';\r\n@Injectable({\r\n  providedIn: \'root\',\r\n})\r\nexport class TokenService {\r\n  private issuer = {\r\n    login: \'http://127.0.0.1:8000/api/auth/login\',\r\n    register: \'http://127.0.0.1:8000/api/auth/register\',\r\n  };\r\n  constructor() {}\r\n  handleData(token: any) {\r\n    localStorage.setItem(\'auth_token\', token);\r\n  }\r\n  getToken() {\r\n    return localStorage.getItem(\'auth_token\');\r\n  }\r\n  // Verify the token\r\n  isValidToken() {\r\n    const token = this.getToken();\r\n    if (token) {\r\n      const payload = this.payload(token);\r\n      if (payload) {\r\n        return Object.values(this.issuer).indexOf(payload.iss) > -1\r\n          ? true\r\n          : false;\r\n      }\r\n      return false;\r\n    } else {\r\n      return false;\r\n    }\r\n  }\r\n  payload(token: any) {\r\n    const jwtPayload = token.split(\'.\')[1];\r\n    return JSON.parse(atob(jwtPayload));\r\n  }\r\n  // User state based on valid token\r\n  isLoggedIn() {\r\n    return this.isValidToken();\r\n  }\r\n  // Remove token\r\n  removeToken() {\r\n    localStorage.removeItem(\'auth_token\');\r\n  }\r\n}\r\n\r\napp.module.ts\r\nimport { NgModule } from \'@angular/core\';\r\nimport { BrowserModule } from \'@angular/platform-browser\';\r\nimport { AppComponent } from \'./app.component\';\r\nimport { AppRoutingModule } from \'./app-routing.module\';\r\nimport { SigninComponent } from \'./components/signin/signin.component\';\r\nimport { SignupComponent } from \'./components/signup/signup.component\';\r\nimport { HttpClientModule, HTTP_INTERCEPTORS } from \'@angular/common/http\';\r\nimport { ReactiveFormsModule, FormsModule } from \'@angular/forms\';\r\nimport { AuthInterceptor } from \'shared/auth.interceptor\';\r\nimport { UserProfileComponent } from \'./components/user-profile/user-profile.component\';\r\n\r\n\r\n\r\n\r\n@NgModule({\r\n  declarations: [\r\n    AppComponent,\r\n    SigninComponent,\r\n    SignupComponent,\r\n    UserProfileComponent\r\n  ],\r\n  imports: [\r\n    BrowserModule, HttpClientModule,ReactiveFormsModule,\r\n    FormsModule, AppRoutingModule,\r\n  ],\r\n  providers: [    {\r\n    provide: HTTP_INTERCEPTORS,\r\n    useClass: AuthInterceptor,\r\n    multi: true\r\n  }],\r\n  bootstrap: [AppComponent]\r\n})\r\nexport class AppModule { }\r\n\r\napp-routing.module.ts\r\nimport { NgModule } from \'@angular/core\';\r\nimport { Routes, RouterModule } from \'@angular/router\';\r\nimport { SigninComponent } from \'./components/signin/signin.component\';\r\nimport { SignupComponent } from \'./components/signup/signup.component\';\r\nimport { UserProfileComponent } from \'./components/user-profile/user-profile.component\';\r\nconst routes: Routes = [\r\n  { path: \'\', redirectTo: \'/login\', pathMatch: \'full\' },\r\n  { path: \'login\', component: SigninComponent },\r\n  { path: \'register\', component: SignupComponent },\r\n  { path: \'profile\', component: UserProfileComponent },\r\n];\r\n@NgModule({\r\n  imports: [RouterModule.forRoot(routes)],\r\n  exports: [RouterModule],\r\n})\r\nexport class AppRoutingModule {}\r\n\r\n\r\napp.component.html\r\n<div class=\"d-flex flex-column flex-md-row align-items-center mb-5 p-4 shadow sticky-top\">\r\n  <h5 class=\"my-0 mr-md-auto font-weight-normal\">Laravel Angular JWT Auth</h5>\r\n  <nav class=\"my-2 my-md-0 mr-md-3\">\r\n    <a class=\"p-2 text-dark\" routerLink=\"/profile\" routerLinkActive=\"active\" *ngIf=\"isSignedIn\">User Profile</a>\r\n    <a class=\"p-2 text-dark\" *ngIf=\"!isSignedIn\" routerLink=\"/login\" routerLinkActive=\"active\">Log in</a>\r\n    <a class=\"p-2 text-dark\" routerLink=\"/register\" routerLinkActive=\"active\">Register</a>\r\n  </nav>\r\n  <button class=\"btn btn-outline-primary\" (click)=\"signOut()\" *ngIf=\"isSignedIn\">Log out</button>\r\n</div>\r\n<router-outlet></router-outlet>\r\napp.component.css\r\n.active{\r\n    background: black;\r\n    color: white !important;\r\n    border-radius: 10px;\r\n}\r\n\r\napp.component.ts\r\nimport { Component, OnInit } from \'@angular/core\';\r\nimport { Router } from \'@angular/router\';\r\nimport { TokenService } from \'shared/token.service\';\r\nimport { AuthStateService } from \'shared/auth-state.service\';\r\n@Component({\r\n  selector: \'app-root\',\r\n  templateUrl: \'./app.component.html\',\r\n  styleUrls: [\'./app.component.css\'],\r\n})\r\nexport class AppComponent implements OnInit {\r\n  isSignedIn!: boolean;\r\n  constructor(\r\n    private auth: AuthStateService,\r\n    public router: Router,\r\n    public token: TokenService\r\n  ) {}\r\n  ngOnInit() {\r\n    this.auth.userAuthState.subscribe((val) => {\r\n      this.isSignedIn = val;\r\n    });\r\n  }\r\n  // Signout\r\n  signOut() {\r\n    this.auth.setAuthState(false);\r\n    this.token.removeToken();\r\n    this.router.navigate([\'login\']);\r\n  }\r\n}\r\nsignin.component.html\r\n<div class=\"container\">\r\n  <div class=\"row align-items-center justify-content-center\">\r\n    <div class=\"col-md-6\">\r\n      <div class=\"auth-wrapper\">\r\n        <form class=\"form-signin\" [formGroup]=\"loginForm\" (ngSubmit)=\"onSubmit()\">\r\n          <h3 class=\"h3 mb-3 font-weight-normal text-center\">Sign in</h3>\r\n          <!-- Errors -->\r\n          <div *ngIf=\"errors?.email\" class=\"alert alert-danger mt-3\">\r\n            {{ errors?.email }}\r\n          </div>\r\n          <div *ngIf=\"errors?.password\" class=\"alert alert-danger mt-3\">\r\n            {{ errors?.password }}\r\n          </div>\r\n          <div *ngIf=\"errors?.error\" class=\"alert alert-danger mt-3\">\r\n            {{ errors?.error }}\r\n          </div>\r\n          <!-- Login -->\r\n          <div class=\"form-group\">\r\n            <label>Email address</label>\r\n            <input type=\"email\" class=\"form-control\" formControlName=\"email\">\r\n          </div>\r\n          <div class=\"form-group\">\r\n            <label>Password</label>\r\n            <input type=\"password\" class=\"form-control\" formControlName=\"password\">\r\n          </div>\r\n          <button type=\"submit\" class=\"btn px-4 mt-3 btn-block btn-primary\">Log in</button>\r\n        </form>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\nsignin.component.ts\r\nimport { Component, OnInit } from \'@angular/core\';\r\nimport { Router } from \'@angular/router\';\r\nimport { AuthService } from \'shared/auth.service\';\r\nimport { FormBuilder, FormGroup } from \'@angular/forms\';\r\nimport { TokenService } from \'shared/token.service\';\r\nimport { AuthStateService } from \'shared/auth-state.service\';\r\n@Component({\r\n  selector: \'app-signin\',\r\n  templateUrl: \'./signin.component.html\',\r\n  styleUrls: [\'./signin.component.css\'],\r\n})\r\nexport class SigninComponent implements OnInit {\r\n  loginForm: FormGroup;\r\n  errors:any = null;\r\n  constructor(\r\n    public router: Router,\r\n    public fb: FormBuilder,\r\n    public authService: AuthService,\r\n    private token: TokenService,\r\n    private authState: AuthStateService\r\n  ) {\r\n    this.loginForm = this.fb.group({\r\n      email: [],\r\n      password: [],\r\n    });\r\n  }\r\n  ngOnInit() {}\r\n  onSubmit() {\r\n    this.authService.signin(this.loginForm.value).subscribe(\r\n      (result) => {\r\n        this.responseHandler(result);\r\n      },\r\n      (error) => {\r\n        this.errors = error.error;\r\n      },\r\n      () => {\r\n        this.authState.setAuthState(true);\r\n        this.loginForm.reset();\r\n        this.router.navigate([\'profile\']);\r\n      }\r\n    );\r\n  }\r\n  // Handle response\r\n  responseHandler(data:any) {\r\n    this.token.handleData(data.access_token);\r\n  }\r\n}\r\nsignup.component.html\r\n<div class=\"auth-wrapper\">\r\n    <form class=\"form-signin\" [formGroup]=\"registerForm\" (ngSubmit)=\"onSubmit()\">\r\n      <h3 class=\"h3 mb-3 font-weight-normal text-center\">Register User</h3>\r\n      <!-- Errors -->\r\n      <div *ngIf=\"errors?.name\" class=\"alert alert-danger mt-3\">\r\n        {{ errors?.name }}\r\n      </div>\r\n      <div *ngIf=\"errors?.email\" class=\"alert alert-danger mt-3\">\r\n        {{ errors?.email }}\r\n      </div>\r\n      <div *ngIf=\"errors?.password\" class=\"alert alert-danger mt-3\">\r\n        {{ errors?.password }}\r\n      </div>\r\n      <div *ngIf=\"errors?.password_confirmation\" class=\"alert alert-danger mt-3\">\r\n        {{ errors?.password_confirmation }}\r\n      </div>\r\n      <!-- Signup form -->\r\n      <div class=\"form-group\">\r\n        <label>Name</label>\r\n        <input type=\"text\" class=\"form-control\" formControlName=\"name\" />\r\n      </div>\r\n      <div class=\"form-group\">\r\n        <label>Email address</label>\r\n        <input type=\"email\" class=\"form-control\" formControlName=\"email\" />\r\n      </div>\r\n      <div class=\"form-group\">\r\n        <label>Password</label>\r\n        <input type=\"password\" class=\"form-control\" formControlName=\"password\" />\r\n      </div>\r\n      <div class=\"form-group\">\r\n        <label>Confirm Password</label>\r\n        <input\r\n          type=\"password\"\r\n          class=\"form-control\"\r\n          formControlName=\"password_confirmation\"\r\n        />\r\n      </div>\r\n      <button type=\"submit\" class=\"btn btn-block btn-primary\">\r\n        Register User\r\n      </button>\r\n    </form>\r\n  </div>\r\nsignup.component.ts\r\nimport { Component, OnInit } from \'@angular/core\';\r\nimport { Router } from \'@angular/router\';\r\nimport { AuthService } from \'shared/auth.service\';\r\nimport { FormBuilder, FormGroup } from \'@angular/forms\';\r\n@Component({\r\n  selector: \'app-signup\',\r\n  templateUrl: \'./signup.component.html\',\r\n  styleUrls: [\'./signup.component.css\'],\r\n})\r\nexport class SignupComponent implements OnInit {\r\n  registerForm: FormGroup;\r\n  errors: any = null;\r\n  constructor(\r\n    public router: Router,\r\n    public fb: FormBuilder,\r\n    public authService: AuthService\r\n  ) {\r\n    this.registerForm = this.fb.group({\r\n      name: [\'\'],\r\n      email: [\'\'],\r\n      password: [\'\'],\r\n      password_confirmation: [\'\'],\r\n    });\r\n  }\r\n  ngOnInit() {}\r\n  onSubmit() {\r\n    this.authService.register(this.registerForm.value).subscribe(\r\n      (result) => {\r\n        console.log(result);\r\n      },\r\n      (error) => {\r\n        this.errors = error.error;\r\n      },\r\n      () => {\r\n        this.registerForm.reset();\r\n        this.router.navigate([\'login\']);\r\n      }\r\n    );\r\n  }\r\n}\r\nuser-profile.component.html\r\n<div class=\"container\">\r\n    <div class=\"card inner-main\">\r\n      <div class=\"card-header\">\r\n        User Profile\r\n      </div>\r\n      <div class=\"card-body\">\r\n        <p class=\"card-text\">Name: <strong>{{UserProfile.name}}</strong></p>\r\n        <p class=\"card-text\">Email: <strong>{{UserProfile.email}}</strong></p>\r\n      </div>\r\n    </div>\r\n  </div>\r\nuser-profile.component.ts\r\nimport { Component, OnInit } from \'@angular/core\';\r\nimport { AuthService } from \'shared/auth.service\';\r\n// User interface\r\nexport class User {\r\n  name: any;\r\n  email: any;\r\n}\r\n@Component({\r\n  selector: \'app-user-profile\',\r\n  templateUrl: \'./user-profile.component.html\',\r\n  styleUrls: [\'./user-profile.component.css\'],\r\n})\r\nexport class UserProfileComponent implements OnInit {\r\n  UserProfile!: User;\r\n  constructor(public authService: AuthService) {\r\n    this.authService.profileUser().subscribe((data: any) => {\r\n      this.UserProfile = data;\r\n    });\r\n  }\r\n  ngOnInit() {}\r\n}\r\n\r\nregister.json\r\n{\r\n    \"message\": \"User successfully registered\",\r\n    \"user\": {\r\n        \"name\": \"Boula\",\r\n        \"email\": \"boula.nessim.soliman@gmail.com\",\r\n        \"updated_at\": \"2022-09-26T13:44:21.000000Z\",\r\n        \"created_at\": \"2022-09-26T13:44:21.000000Z\",\r\n        \"id\": 2\r\n    }\r\n}\r\n\r\n\r\nlogin.json\r\n{\r\n    \"access_token\": \"eyJ0eXAiOiJKV1QiLCJhbGciOiJIUzI1NiJ9.eyJpc3MiOiJodHRwOlwvXC8xMjcuMC4wLjE6ODAwMFwvYXBpXC9hdXRoXC9sb2dpbiIsImlhdCI6MTY2NDE5OTk0MiwiZXhwIjoxNjY0MjAzNTQyLCJuYmYiOjE2NjQxOTk5NDIsImp0aSI6IjVSbjhVUlZSdXFua1hSbE4iLCJzdWIiOjIsInBydiI6Ijg3ZTBhZjFlZjlmZDE1ODEyZmRlYzk3MTUzYTE0ZTBiMDQ3NTQ2YWEifQ.dgTsZQhYVZq9BcKVf1rMoQ1BIvmkqqIDBP-1pZlHXJ0\",\r\n    \"token_type\": \"bearer\",\r\n    \"expires_in\": 3600,\r\n    \"user\": {\r\n        \"id\": 2,\r\n        \"name\": \"Boula\",\r\n        \"email\": \"boula.nessim.soliman@gmail.com\",\r\n        \"email_verified_at\": null,\r\n        \"created_at\": \"2022-09-26T13:44:21.000000Z\",\r\n        \"updated_at\": \"2022-09-26T13:44:21.000000Z\"\r\n    }\r\n}\r\n\r\n\r\nBootstrap classes\r\nbg-dark, text-dark, d-flex, alert alert-danger, mt-3 , mb-3,h3, mb-3, font-weight-normal, text-center\r\nalign-items-center, justify-content-center,my-0, mr-md-auto,d-flex, flex-column, flex-md-row, align-items-center, mb-5, p-4, shadow, sticky-top, text-dark,btn btn-outline-primary, btn btn-secondary,col col-md-12, offset-md-12, table, btn btn-primary, form-group, form-control, \r\nJs functions\r\nwindow.location.href.split(\'/\')[3]; //To get part of url\r\narr.push(obj) //to push an object inside array\r\nwindow.location.reload();\r\nUsing headers to get date according to lang\r\n  get(lang:string, model:string):Observable<any>  {\r\n    const httpOptions = {\r\n      headers: new HttpHeaders().set(\'content-type\', \'application/json\').set(\'locale\', lang)\r\n    }\r\n    return this.http.get(`${this.baseUrl}${model}`, httpOptions);\r\n  }\r\nOxford Training application\r\n\r\nhome.component.ts\r\nimport { Component, OnInit } from \'@angular/core\';\r\nimport { OwlOptions } from \'ngx-owl-carousel-o\';\r\nimport { AppComponent } from \'../app.component\';\r\nimport { AppService } from \'../app.service\';\r\n\r\n\r\n\r\n\r\n\r\n@Component({\r\n  selector: \'app-home\',\r\n  templateUrl: \'./home.component.html\',\r\n  styleUrls: [\'./home.component.css\']\r\n})\r\nexport class HomeComponent implements OnInit {\r\n\r\n  data: any = [];\r\n  allCategories: any[] = [];\r\n  trendingCats: any[] = [];\r\n  trendingCourses: any = [];\r\n  courses: any = [];\r\n\r\n\r\n\r\n  carouselOption: OwlOptions = {\r\n    loop: true,\r\n    mouseDrag: true,\r\n    touchDrag: false,\r\n    pullDrag: false,\r\n    dots: false,\r\n    autoplay: true,\r\n    navSpeed: 700,\r\n    autoplaySpeed: 200,\r\n    navText: [\'\', \'\'],\r\n    responsive: {\r\n      0: {\r\n        items: 1\r\n      },\r\n      400: {\r\n        items: 1\r\n      },\r\n      740: {\r\n        items: 1\r\n      },\r\n      940: {\r\n        items: 4\r\n      }\r\n    },\r\n    nav: false\r\n  }\r\n\r\n  constructor(public _appService: AppService, public app: AppComponent) {\r\n    this.get();\r\n  }\r\n\r\n  get() {\r\n    this._appService.get(this.app.translate.currentLang, \'home\').subscribe((data) => {\r\n      this.data = data.data;\r\n      console.log(\'get fun in home is fired\');\r\n      console.log(this.data);\r\n      this.getTrendingCats();\r\n    });\r\n\r\n    this._appService.get(this.app.translate.currentLang, \'categories\').subscribe((data) => {\r\n      this.allCategories = data.data.category;\r\n    });\r\n  }\r\n\r\n  getTrendingCats() {\r\n    this.trendingCourses = this.data[\'trending-courses\'];\r\n    let categories: any = [];\r\n    for (let course of this.trendingCourses) {\r\n      categories.push({ category_id: course.category_id, category_name: course.category });\r\n    }\r\n\r\n    this.trendingCats = categories.filter((item: any, index: number, arr: any) => {\r\n      return this.findIndex(arr, item.category_id) === index;\r\n    });\r\n  }\r\n\r\n  findIndex(arr: any, itemId: any) {\r\n    let index;\r\n    for (let i = 0; i < arr.length; i++) {\r\n      if (arr[i].category_id === itemId) {\r\n        index = i;\r\n      }\r\n    }\r\n    return index;\r\n  }\r\n\r\n  getCoursesByCategoryId(categoryId: number): void {\r\n    for (let item of this.trendingCourses) {\r\n      if (item.category_id === categoryId)\r\n        this.courses.push(item);\r\n    }\r\n\r\n    console.log(\'courses\', this.courses);\r\n\r\n  }\r\n\r\n\r\n\r\n  ngOnInit(): void {\r\n  }\r\n\r\n}\r\napp.component.ts\r\nimport { Component, Inject, LOCALE_ID } from \'@angular/core\';\r\nimport { TranslateService } from \'@ngx-translate/core\';\r\nimport { LocalizeRouterService } from \'@gilsdav/ngx-translate-router\';\r\nimport { AppService } from \'./app.service\';\r\n\r\n\r\n@Component({\r\n  selector: \'app-root\',\r\n  templateUrl: \'./app.component.html\',\r\n  styleUrls: [\'./app.component.css\']\r\n})\r\nexport class AppComponent {\r\n  title = \'oxford-training\';\r\n\r\n\r\n\r\n\r\n\r\n  public static appLang: any = localStorage.getItem(\"language\");\r\n\r\n  constructor(@Inject(LOCALE_ID) public activeLocale: string, public translate: TranslateService, private localize: LocalizeRouterService,\r\n    public _appService: AppService) {\r\n    // this language will be used as a fallback when a translation isn\'t found in the current language\r\n    translate.addLangs([\'en\', \'ar\']);\r\n    this.translate.currentLang = AppComponent.appLang;\r\n    translate.use(AppComponent.appLang);\r\n    document.getElementsByTagName(\"html\")[0].setAttribute(\"lang\", this.translate.currentLang);\r\n    if (AppComponent.appLang === \'ar\') {\r\n      document.getElementsByTagName(\"html\")[0].setAttribute(\"dir\", \"rtl\");\r\n    }\r\n    else {\r\n      document.getElementsByTagName(\"html\")[0].setAttribute(\"dir\", \"ltr\");\r\n    }\r\n\r\n  }\r\n\r\n\r\n  switchLang(lang: string) {\r\n    AppComponent.appLang = lang;\r\n    AppComponent.appLang=window.location.pathname.slice(-2)==\'ar\';\r\n    this.translate.currentLang = AppComponent.appLang;\r\n    this.translate.use(AppComponent.appLang);\r\n    localStorage.setItem(\"language\", lang);\r\n    this.localize.changeLanguage(lang);\r\n    if (localStorage.getItem(\"language\") === \'ar\') {\r\n      document.getElementsByTagName(\"html\")[0].setAttribute(\"dir\", \"rtl\");\r\n    }\r\n    else {\r\n      document.getElementsByTagName(\"html\")[0].setAttribute(\"dir\", \"ltr\");\r\n    }\r\n\r\n     window.location.reload();\r\n\r\n\r\n  }\r\n}\r\napp.service.ts\r\nimport { Injectable } from \'@angular/core\';\r\nimport { Observable } from \'rxjs\';\r\nimport { HttpClient, HttpHeaders } from \'@angular/common/http\';\r\n\r\n\r\n@Injectable({\r\n  providedIn: \'root\'\r\n})\r\nexport class AppService {\r\n\r\n  constructor(private http: HttpClient ) {}\r\n\r\n  baseUrl: any = \"http://127.0.0.1:8000/api/\";\r\n\r\n\r\n  get(lang:string, model:string):Observable<any>  {\r\n    const httpOptions = {\r\n      headers: new HttpHeaders().set(\'content-type\', \'application/json\').set(\'locale\', lang)\r\n    }\r\n\r\n    return this.http.get(`${this.baseUrl}${model}`, httpOptions);\r\n  }\r\n}\r\n\r\napp.module.ts\r\nimport { LOCALE_ID, NgModule } from \'@angular/core\';\r\nimport { BrowserModule } from \'@angular/platform-browser\';\r\n\r\nimport { AppComponent } from \'./app.component\';\r\nimport { NavbarComponent } from \'./navbar/navbar.component\';\r\nimport { PreloaderComponent } from \'./preloader/preloader.component\';\r\nimport { HomeComponent } from \'./home/home.component\';\r\nimport { FooterComponent } from \'./footer/footer.component\';\r\nimport { AppRoutingModule } from \'./app-routing.module\';\r\nimport { HttpClient, HttpClientModule } from \'@angular/common/http\';\r\nimport { TranslateLoader, TranslateModule, TranslateService } from \'@ngx-translate/core\';\r\nimport { TranslateHttpLoader } from \'@ngx-translate/http-loader\';\r\nimport { CarouselModule } from \'ngx-owl-carousel-o\';\r\nimport { BrowserAnimationsModule } from \'@angular/platform-browser/animations\';\r\nimport { AboutComponent } from \'./about/about.component\';\r\nimport { LocalizeParser, LocalizeRouterModule, LocalizeRouterSettings, ManualParserLoader } from \'@gilsdav/ngx-translate-router\';\r\nimport {Location} from \'@angular/common\';\r\n// import {LocalizeRouterHttpLoader} from \'@gilsdav/ngx-translate-router-http-loader\';\r\nimport {RouterModule} from \'@angular/router\';\r\nimport {routes} from \'../app/app-routing.module\';\r\n\r\n\r\n\r\n\r\n// AOT compilation support\r\n// AOT compilation support\r\nexport function httpTranslateLoader(http: HttpClient) {\r\n  return new TranslateHttpLoader(http);\r\n}\r\n@NgModule({\r\n  declarations: [\r\n    AppComponent,\r\n    NavbarComponent,\r\n    PreloaderComponent,\r\n    HomeComponent,\r\n    FooterComponent,\r\n    AboutComponent\r\n  ],\r\n  imports: [\r\n    BrowserModule,\r\n    AppRoutingModule,\r\n    HttpClientModule,\r\n    BrowserAnimationsModule,\r\n    CarouselModule,\r\n    TranslateModule.forRoot({\r\n      loader: {\r\n        provide: TranslateLoader,\r\n        useFactory: httpTranslateLoader,\r\n        deps: [HttpClient]\r\n      }\r\n    }),\r\n    RouterModule.forRoot(routes),\r\n    LocalizeRouterModule.forRoot(routes, {\r\n      parser: {\r\n        provide: LocalizeParser,\r\n        useFactory: (translate: TranslateService, location: Location, settings: LocalizeRouterSettings) =>\r\n            new ManualParserLoader(translate, location, settings, [\'en\',\'ar\']),\r\n        deps: [TranslateService, Location, LocalizeRouterSettings]\r\n      }\r\n    })\r\n  ],\r\n  providers: [{\r\n    provide: LOCALE_ID,\r\n    useValue: AppComponent.appLang\r\n  }],\r\n  bootstrap: [AppComponent]\r\n})\r\nexport class AppModule { }\r\nHow to make an attribute dynamic ba addin attr.\r\nattr.data-bs-target=\"{{ cat.category_id }}\"\r\n\r\nHow to make @Input()\r\n//breadcrumb.component.ts\r\nexport class BreadcrumbComponent {\r\n  @Input() item = \'\';\r\n}\r\n//breadcrumb.component.html\r\n<li class=\"breadcrumb-item  fw-bold active\" aria-current=\"page\">{{item}}</li>\r\n//client-page.component.html\r\n<app-breadcrumb [item]=\"currentItem\"></app-breadcrumb>\r\n//client-page.component.ts\r\nexport class ClientPageComponent {\r\n  currentItem:string=\'CLIENT\';\r\n}\r\n//media-page.component.html\r\n<app-breadcrumb [item]=\"currentItem | translate\"></app-breadcrumb>\r\n//media-page.component.ts\r\ncurrentItem:string=\'media\';\r\n\r\nAngular .htaccess\r\n<IfModule mod_rewrite.c>\r\n\r\n  RewriteEngine On\r\n  RewriteBase /\r\n  RewriteRule ^index\\.html$ - [L]\r\n  RewriteCond %{REQUEST_FILENAME} !-f\r\n  RewriteCond %{REQUEST_FILENAME} !-d\r\n  RewriteCond %{REQUEST_FILENAME} !-l\r\n  RewriteRule . /index.html [L]\r\n\r\n</IfModule>','2025-03-31 07:06:36','2025-07-13 05:58:06',1,0,1),(57,'ReactNative Refrence','','React Native Reference\r\nWe can open expo app on browser by clicking w after runung npx expo start\r\nnode –v\r\nnpm –version\r\nnpm install –g create-react-app\r\nnpx create-react-app hello-world-example\r\nnpm –version\r\nnpx create-react-app hello-world-example\r\nnpm init react-app hello-world\r\nyarn create react-app hello-world-example\r\ncd hello-world-example\r\nnpm start\r\nexpo start //recommended\nnpx @react-native-community/cli init MyNewApp //create a reactNative cli app\nnpx react-native start\nnpx react-native run-android\r\nnpx expo start\r\nnpx expo start --no-dev // to fix build errors \nbefore building\r\nnpx expo start --no-dev --minify //run if as in build\nadb devices\nadb logcat *:S ReactNative:V ReactNativeJS:V //in gitbash to debug apk\nexpo build:ios\r\nexpo build:android\r\nexpo build:status\r\nexpo publish\r\neas build -p android \r\neas build -p ios\r\neas login\r\neas logout\r\neas whoami\n\r\n\r\n\r\nhow to build an expo app\r\nhttps://stackoverflow.com/questions/53040047/generate-an-apk-file-from-an-aab-file-android-app-bundle\r\njava -jar \"C:\\Users\\User\\Desktop\\generateAPK/bundletool.jar\" build-apks --bundle=C:\\Users\\User\\Desktop\\generateAPK/my_app.aab --output=C:\\Users\\User\\Desktop\\generateAPK/myapp.apks --mode=universal\r\n\r\nhttp://localhost:3000/\r\nPackages and resources\r\nReact Native Dev Environment Setup\r\nDownload Node.js\r\nThe Missing Package Manager for macOS (or Linux) — Homebrew\r\nWatchman A file watching service | Watchman (facebook.github.io)\r\nDownload Visual Studio Code - Mac, Linux, Windows\r\nDownload Android Studio & App Tools - Android Developers\r\nXcode on the Mac App Store (apple.com)\r\nCocoaPods Guides - Getting Started\r\nSetting up the development environment\r\nSetting up the development environment · React Native\r\nFirst steps - Expo Documentation\r\nWhat is Expo – Expo Documentation\r\nCore components and APIs · React Native \r\nCore components and Native components · React Native\r\nUsing libraries · React Native\r\nView · React Native\r\nText · React Native\r\nScrollView · React Native\r\nStyleSheet · React Native\r\nStyle · React Native\r\nColor Reference · React Native\r\nFlatList · React Native\r\nExpo Documentation\r\nScrollView · React Native\r\nSectionList · React Native\r\nUsing List Views · React Native\r\nTextInput · React Native\r\nKeyboardAvoidingView · React Native\r\nkeyboardDismissMode · React Native\r\nonFocus · React Native\r\nonBlur · React Native\r\nclearButtonMode · React Native\r\nA visual guide to the React Native TextInput keyboardType prop values\r\nPressable · React Native\r\nButton · React Native\r\nTouchableHighlight· React Native\r\nTouchableOpacity· React Native\r\nTouchableWithoutFeedback· React Native\r\nImage · React Native\r\nImageBackground · React Native\r\nImage Style Props · React Native\r\nGitHub - react-native-community/hooks: React Native APIs turned into React Hooks for use in functional React components\r\nuseColorScheme · React Native\r\nuseWindowDimensions · React Native\r\nIntroducing Hooks – React (reactjs.org)\r\nGetting started | React Navigation\r\nHello React Navigation | React Navigation\r\nTroubleshooting | React Navigation\r\nMoving between screens | React Navigation\r\nPassing parameters to routes | React Navigation\r\nConfiguring the header bar | React Navigation\r\nTab navigation | React Navigation\r\nBottom Tabs Navigator | React Navigation\r\nMaterial Bottom Tabs Navigator | React Navigation\r\nMaterial Top Tabs Navigator | React Navigation\r\nDrawer navigation | React Navigation\r\nDrawer Navigator | React Navigation\r\nMultiple drawers | React Navigation\r\n\r\nExpo\r\nnpx create-expo-app FirstProject\r\ncd FirstProject\r\nnpm start\r\nUse Expo Go app to use it as emulator\r\nNotes\r\nLearn react from github app\r\n\r\nSolution: Your first React Native component\r\ncomponents/LittleLemonHeader.js\r\nimport * as React from \'react\';  \r\nimport { View, Text } from \'react-native\';\r\n    \r\nexport default function LittleLemonHeader() {\r\n    return (\r\n      <View style={{ flex: 0.2, backgroundColor: \'#F4CE14\' }}>\r\n        <Text style={{ padding: 40, fontSize: 30, color: \'black\' }}>\r\n          Welcome to Little Lemon\r\n        </Text>\r\n      </View>\r\n    );\r\n}\r\ncomponents/LittleLemonFooter.js\r\nimport * as React from \'react\';\r\nimport { View, Text } from \'react-native\';\r\n\r\nexport default function LittleLemonFooter() {\r\n  return (\r\n    <View\r\n      style={{\r\n        backgroundColor: \'#F4CE14\',\r\n        marginBottom: 10,\r\n      }}>\r\n      <Text\r\n        style={{\r\n          fontSize: 18,\r\n          color: \'black\',\r\n          textAlign: \'center\',\r\n        }}>\r\n        All rights reserved by Little Lemon, 2022{\' \'}\r\n      </Text>\r\n    </View>\r\n  );\r\n}\r\n\r\nApp.js\r\nimport * as React from \'react\';\r\nimport { View } from \'react-native\';\r\n\r\nimport LittleLemonHeader from \'./components/LittleLemonHeader\';\r\nimport LittleLemonFooter from \'./components/LittleLemonFooter\';\r\nexport default function App() {\r\n  return (\r\n    <>\r\n      <View\r\n        style={{\r\n          flex: 1,\r\n          backgroundColor: \'#495E57\',\r\n        }}>\r\n        <LittleLemonHeader />\r\n      </View>\r\n      <View style={{ backgroundColor: \'#495E57\' }}>\r\n        <LittleLemonFooter />\r\n      </View>\r\n    </>\r\n  );\r\n}\r\n\r\nSolution: Build a React Native screen\r\nWelcomeScreen.js\r\nimport * as React from \'react\';\r\nimport { View, Text } from \'react-native\';\r\n\r\nexport default function WelcomeScreen() {\r\n  return (\r\n    <View style={{ flex: 1 }}>\r\n      <Text\r\n        style={{\r\n          padding: 40,\r\n          fontSize: 30,\r\n          color: \'#EDEFEE\',\r\n          textAlign: \'center\',\r\n        }}>\r\n        Welcome to Little Lemon\r\n      </Text>\r\n      <Text\r\n        style={{\r\n          fontSize: 24,\r\n          padding: 20,\r\n          marginVertical: 8,\r\n          color: \'#EDEFEE\',\r\n          textAlign: \'center\',\r\n        }}>\r\n        Little Lemon is a charming neighborhood bistro that serves simple food\r\n        and classic cocktails in a lively but casual environment. We would love\r\n        to hear your experience with us!\r\n      </Text>\r\n    </View>\r\n  );\r\n}\r\nApp.js\r\nimport * as React from \'react\';\r\nimport { View, Text } from \'react-native\';\r\n\r\nimport LittleLemonHeader from \'./components/LittleLemonHeader\';\r\nimport LittleLemonFooter from \'./components/LittleLemonFooter\';\r\nimport WelcomeScreen from \"./WelcomeScreen\";\r\n\r\nexport default function App() {\r\n  return (\r\n    <>\r\n      <View\r\n        style={{\r\n          flex: 1,\r\n          backgroundColor: \'#495E57\',\r\n        }}>\r\n        <LittleLemonHeader />\r\n        <WelcomeScreen />\r\n      </View>\r\n      <View style={{ backgroundColor: \'#495E57\' }}>\r\n        <LittleLemonFooter />\r\n      </View>\r\n    </>\r\n  );\r\n}\r\nSolution: Build a scrollable component\r\nWelcomeScreen.js\r\nimport * as React from \'react\';\r\nimport { ScrollView, Text } from \'react-native\';\r\n\r\nexport default function WelcomeScreen() {\r\n  return (\r\n    <ScrollView indicatorStyle={\"white\"} style={{ flex: 1 }}>\r\n      <Text\r\n        style={{\r\n          padding: 40,\r\n          fontSize: 50,\r\n          color: \'#EDEFEE\',\r\n          textAlign: \'center\',\r\n        }}>\r\n        Welcome to Little Lemon\r\n      </Text>\r\n      <Text\r\n        style={{\r\n          fontSize: 38,\r\n          padding: 20,\r\n          marginVertical: 8,\r\n          color: \'#EDEFEE\',\r\n          textAlign: \'center\',\r\n        }}>\r\n        Little Lemon is a charming neighborhood bistro that serves simple food\r\n        and classic cocktails in a lively but casual environment. We would love\r\n        to hear more about your experience with us!\r\n      </Text>\r\n    </ScrollView>\r\n  );\r\n}\r\nApp.js\r\nimport * as React from \'react\';\r\nimport { View, Text } from \'react-native\';\r\n\r\nimport LittleLemonHeader from \'./components/LittleLemonHeader\';\r\nimport LittleLemonFooter from \'./components/LittleLemonFooter\';\r\nimport WelcomeScreen from \"./WelcomeScreen\";\r\n\r\nexport default function App() {\r\n  return (\r\n    <>\r\n      <View\r\n        style={{\r\n          flex: 1,\r\n          backgroundColor: \'#495E57\',\r\n        }}>\r\n        <LittleLemonHeader />\r\n        <WelcomeScreen />\r\n      </View>\r\n      <View style={{ backgroundColor: \'#495E57\' }}>\r\n        <LittleLemonFooter />\r\n      </View>\r\n    </>\r\n  );\r\n}\r\nSolution: Style a component\r\nLittleLemonFooter.js\r\nimport * as React from \'react\';\r\nimport { View, Text, StyleSheet } from \'react-native\';\r\n\r\nexport default function LittleLemonFooter() {\r\n  return (\r\n    <View style={styles.container}>\r\n      <Text style={styles.footerText}>\r\n        All rights reserved by Little Lemon, 2022{\' \'}\r\n      </Text>\r\n    </View>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  container: {\r\n    backgroundColor: \'#EE9972\',\r\n    marginBottom: 20,\r\n  },\r\n  footerText: {\r\n    fontSize: 18,\r\n    color: \'black\',\r\n    textAlign: \'center\',\r\n    fontStyle: \'italic\',\r\n  },\r\n});\r\n\r\nLittleLemonHeader.js\r\nimport * as React from \'react\';\r\nimport { View, Text, StyleSheet } from \'react-native\';\r\n\r\nexport default function LittleLemonHeader() {\r\n  return (\r\n    <View style={styles.container}>\r\n      <Text style={styles.headerText}>Little Lemon</Text>\r\n    </View>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  container: {\r\n    backgroundColor: \'#EE9972\',\r\n  },\r\n  headerText: {\r\n    padding: 40,\r\n    fontSize: 30,\r\n    color: \'black\',\r\n    textAlign: \'center\',\r\n  },\r\n});\r\n\r\nWelcomeScreen.js\r\nimport * as React from \'react\';\r\nimport { ScrollView, Text, StyleSheet } from \'react-native\';\r\n\r\nexport default function WelcomeScreen() {\r\n  return (\r\n    <ScrollView indicatorStyle=\"white\" style={styles.container}>\r\n      <Text style={styles.headerText}>Welcome to Little Lemon</Text>\r\n      <Text style={styles.regularText}>\r\n        Little Lemon is a charming neighborhood bistro that serves simple food\r\n        and classic cocktails in a lively but casual environment. We would love\r\n        to hear more about your experience with us!\r\n      </Text>\r\n    </ScrollView>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  container: {\r\n    flex: 1,\r\n  },\r\n  headerText: {\r\n    padding: 40,\r\n    fontSize: 30,\r\n    color: \'#EDEFEE\',\r\n    textAlign: \'center\',\r\n  },\r\n  regularText: {\r\n    fontSize: 24,\r\n    padding: 20,\r\n    marginVertical: 8,\r\n    color: \'#EDEFEE\',\r\n    textAlign: \'center\',\r\n  },\r\n});\r\n\r\n\r\n\r\nApp.js\r\nimport * as React from \'react\';\r\nimport { View, Text, StyleSheet } from \'react-native\';\r\n\r\nimport LittleLemonHeader from \'./components/LittleLemonHeader\';\r\nimport LittleLemonFooter from \'./components/LittleLemonFooter\';\r\nimport WelcomeScreen from \'./WelcomeScreen\';\r\n\r\nexport default function App() {\r\n  return (\r\n    <>\r\n      <View style={styles.container}>\r\n        <LittleLemonHeader />\r\n        <WelcomeScreen />\r\n      </View>\r\n      <View style={styles.footerContainer}>\r\n        <LittleLemonFooter />\r\n      </View>\r\n    </>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  container: {\r\n    flex: 1,\r\n    backgroundColor: \'#333333\',\r\n  },\r\n  footerContainer: { backgroundColor: \'#333333\' },\r\n});\r\n\r\nSolution: Render a large list using FlatList\r\nMenuItems.js\r\nimport React from \'react\';\r\n\r\nimport { View, Text, StyleSheet, FlatList } from \'react-native\';\r\n\r\nconst menuItemsToDisplay = [\r\n  { name: \'Hummus\', price: \'$5.00\', id: \'1A\' },\r\n  { name: \'Moutabal\', price: \'$5.00\', id: \'2B\' },\r\n  { name: \'Falafel\', price: \'$7.50\', id: \'3C\' },\r\n  { name: \'Marinated Olives\', price: \'$5.00\', id: \'4D\' },\r\n  { name: \'Kofta\', price: \'$5.00\', id: \'5E\' },\r\n  { name: \'Eggplant Salad\', price: \'$8.50\', id: \'6F\' },\r\n  { name: \'Lentil Burger\', price: \'$10.00\', id: \'7G\' },\r\n  { name: \'Smoked Salmon\', price: \'$14.00\', id: \'8H\' },\r\n  { name: \'Kofta Burger\', price: \'$11.00\', id: \'9I\' },\r\n  { name: \'Turkish Kebab\', price: \'$15.50\', id: \'10J\' },\r\n  { name: \'Fries\', price: \'$3.00\', id: \'11K\' },\r\n  { name: \'Buttered Rice\', price: \'$3.00\', id: \'12L\' },\r\n  { name: \'Bread Sticks\', price: \'$3.00\', id: \'13M\' },\r\n  { name: \'Pita Pocket\', price: \'$3.00\', id: \'14N\' },\r\n  { name: \'Lentil Soup\', price: \'$3.75\', id: \'15O\' },\r\n  { name: \'Greek Salad\', price: \'$6.00\', id: \'16Q\' },\r\n  { name: \'Rice Pilaf\', price: \'$4.00\', id: \'17R\' },\r\n  { name: \'Baklava\', price: \'$3.00\', id: \'18S\' },\r\n  { name: \'Tartufo\', price: \'$3.00\', id: \'19T\' },\r\n  { name: \'Tiramisu\', price: \'$5.00\', id: \'20U\' },\r\n  { name: \'Panna Cotta\', price: \'$5.00\', id: \'21V\' },\r\n];\r\n\r\nconst Item = ({ name, price }) => (\r\n  <View style={menuStyles.innerContainer}>\r\n    <Text style={menuStyles.itemText}>{name}</Text>\r\n    <Text style={menuStyles.itemText}>{price}</Text>\r\n  </View>\r\n);\r\n\r\nconst MenuItems = () => {\r\n  const renderItem = ({ item }) => <Item name={item.name} price={item.price} />;\r\n\r\n  return (\r\n    <View style={menuStyles.container}>\r\n      <FlatList\r\n        data={menuItemsToDisplay}\r\n        keyExtractor={(item) => item.id}\r\n        renderItem={renderItem}></FlatList>\r\n    </View>\r\n  );\r\n};\r\n\r\nconst menuStyles = StyleSheet.create({\r\n  container: {\r\n    flex: 1,\r\n  },\r\n  innerContainer: {\r\n    paddingHorizontal: 40,\r\n    paddingVertical: 20,\r\n    flexDirection: \'row\',\r\n    justifyContent: \'space-between\',\r\n  },\r\n  itemText: {\r\n    color: \'#F4CE14\',\r\n    fontSize: 20,\r\n  },\r\n});\r\n\r\nexport default MenuItems;\r\n\r\nApp.js\r\n\r\nimport * as React from \'react\';\r\nimport { View, StyleSheet } from \'react-native\';\r\n\r\nimport LittleLemonHeader from \'./components/LittleLemonHeader\';\r\nimport LittleLemonFooter from \'./components/LittleLemonFooter\';\r\nimport MenuItems from \'./components/MenuItems\';\r\n\r\nexport default function App() {\r\n  return (\r\n    <>\r\n      <View style={styles.container}>\r\n        <LittleLemonHeader />\r\n        <MenuItems />\r\n      </View>\r\n      <View style={styles.footerContainer}>\r\n        <LittleLemonFooter />\r\n      </View>\r\n    </>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  container: {\r\n    flex: 1,\r\n    backgroundColor: \'#333333\',\r\n  },\r\n  footerContainer: { backgroundColor: \'#333333\' },\r\n});\r\n\r\nSolution: Render a large list using SectionList\r\nMenuItems.js\r\nimport React from \'react\';\r\n\r\nimport { View, Text, StyleSheet, SectionList } from \'react-native\';\r\n\r\nconst menuItemsToDisplay = [\r\n  {\r\n    title: \'Appetizers\',\r\n    data: [\r\n      { name: \'Hummus\', price: \'$5.00\' },\r\n      { name: \'Moutabal\', price: \'$5.00\' },\r\n      { name: \'Falafel\', price: \'$7.50\' },\r\n      { name: \'Marinated Olives\', price: \'$5.00\' },\r\n      { name: \'Kofta\', price: \'$5.00\' },\r\n      { name: \'Eggplant Salad\', price: \'$8.50\' },\r\n    ],\r\n  },\r\n  {\r\n    title: \'Main Dishes\',\r\n    data: [\r\n      { name: \'Lentil Burger\', price: \'$10.00\' },\r\n      { name: \'Smoked Salmon\', price: \'$14.00\' },\r\n      { name: \'Kofta Burger\', price: \'$11.00\' },\r\n      { name: \'Turkish Kebab\', price: \'$15.50\' },\r\n    ],\r\n  },\r\n  {\r\n    title: \'Sides\',\r\n    data: [\r\n      { name: \'Fries\', price: \'$3.00\', id: \'11K\' },\r\n      { name: \'Buttered Rice\', price: \'$3.00\' },\r\n      { name: \'Bread Sticks\', price: \'$3.00\' },\r\n      { name: \'Pita Pocket\', price: \'$3.00\' },\r\n      { name: \'Lentil Soup\', price: \'$3.75\' },\r\n      { name: \'Greek Salad\', price: \'$6.00\' },\r\n      { name: \'Rice Pilaf\', price: \'$4.00\' },\r\n    ],\r\n  },\r\n  {\r\n    title: \'Desserts\',\r\n    data: [\r\n      { name: \'Baklava\', price: \'$3.00\' },\r\n      { name: \'Tartufo\', price: \'$3.00\' },\r\n      { name: \'Tiramisu\', price: \'$5.00\' },\r\n      { name: \'Panna Cotta\', price: \'$5.00\' },\r\n    ],\r\n  },\r\n];\r\n\r\nconst Item = ({ name, price }) => (\r\n  <View style={menuStyles.innerContainer}>\r\n    <Text style={menuStyles.itemText}>{name}</Text>\r\n    <Text style={menuStyles.itemText}>{price}</Text>\r\n  </View>\r\n);\r\n\r\nconst MenuItems = () => {\r\n  const renderItem = ({ item }) => <Item name={item.name} price={item.price} />;\r\n\r\n  const renderSectionHeader = ({ section: { title } }) => (\r\n    <View style={menuStyles.headerStyle}>\r\n      <Text style={menuStyles.sectionHeader}>{title}</Text>\r\n    </View>\r\n  );\r\n\r\n  return (\r\n    <View style={menuStyles.container}>\r\n      <SectionList\r\n        sections={menuItemsToDisplay}\r\n        keyExtractor={(item, index) => item + index}\r\n        renderItem={renderItem}\r\n        renderSectionHeader={renderSectionHeader}></SectionList>\r\n    </View>\r\n  );\r\n};\r\n\r\nconst menuStyles = StyleSheet.create({\r\n  container: {\r\n    flex: 1,\r\n  },\r\n  innerContainer: {\r\n    paddingHorizontal: 40,\r\n    paddingVertical: 20,\r\n    flexDirection: \'row\',\r\n    justifyContent: \'space-between\',\r\n  },\r\n  itemText: {\r\n    color: \'#F4CE14\',\r\n    fontSize: 20,\r\n  },\r\n  headerStyle: {\r\n    backgroundColor: \'#F4CE14\',\r\n  },\r\n  sectionHeader: {\r\n    color: \'black\',\r\n    fontSize: 26,\r\n    flexWrap: \'wrap\',\r\n    textAlign: \'center\',\r\n  },\r\n});\r\n\r\nexport default MenuItems;\r\n\r\nApp.js\r\nimport * as React from \'react\';\r\nimport { View, StyleSheet } from \'react-native\';\r\n\r\nimport LittleLemonHeader from \'./components/LittleLemonHeader\';\r\nimport LittleLemonFooter from \'./components/LittleLemonFooter\';\r\nimport MenuItems from \'./components/MenuItems\';\r\n\r\nexport default function App() {\r\n  return (\r\n    <>\r\n      <View style={styles.container}>\r\n        <LittleLemonHeader />\r\n        <MenuItems />\r\n      </View>\r\n      <View style={styles.footerContainer}>\r\n        <LittleLemonFooter />\r\n      </View>\r\n    </>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  container: {\r\n    flex: 1,\r\n    backgroundColor: \'#333333\',\r\n  },\r\n  footerContainer: { backgroundColor: \'#333333\' },\r\n});\r\n\r\nSolution: Create a TextInput Component\r\nWelcomeScreen.js\r\nimport React, { useState } from \'react\';\r\nimport { ScrollView, Text, StyleSheet, TextInput } from \'react-native\';\r\n\r\nexport default function WelcomeScreen() {\r\n  const [firstName, onChangeFirstName] = useState(\'\');\r\n  return (\r\n    <ScrollView style={styles.container}>\r\n      <Text style={styles.headerText}>Welcome to Little Lemon</Text>\r\n      <Text style={styles.regularText}>\r\n        Little Lemon is a charming neighborhood bistro that serves simple food\r\n        and classic cocktails in a lively but casual environment. We would love\r\n        to hear more about your experience with us!\r\n      </Text>\r\n      <TextInput\r\n        style={styles.inputBox}\r\n        value={firstName}\r\n        onChangeText={onChangeFirstName}\r\n        placeholder={\'First Name\'}\r\n      />\r\n    </ScrollView>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  container: {\r\n    flex: 1,\r\n  },\r\n  headerText: {\r\n    padding: 40,\r\n    fontSize: 30,\r\n    color: \'#EDEFEE\',\r\n    textAlign: \'center\',\r\n  },\r\n  regularText: {\r\n    fontSize: 24,\r\n    padding: 20,\r\n    marginVertical: 8,\r\n    color: \'#EDEFEE\',\r\n    textAlign: \'center\',\r\n  },\r\n  inputBox: {\r\n    height: 40,\r\n    margin: 12,\r\n    borderWidth: 1,\r\n    padding: 10,\r\n    fontSize: 16,\r\n    borderColor: \'EDEFEE\',\r\n    backgroundColor: \'#EDEFEE\',\r\n  },\r\n});\r\n\r\nSolution: Create a login page\r\n\r\nLoginScreen.js\r\nimport React, { useState } from \'react\';\r\nimport { ScrollView, Text, StyleSheet, TextInput } from \'react-native\';\r\n\r\nexport default function LoginScreen() {\r\n  const [email, onChangeEmail] = useState(\'\');\r\n  const [password, onChangePassword] = useState(\'\');\r\n\r\n  return (\r\n    <ScrollView style={styles.container}>\r\n      <Text style={styles.headerText}>Welcome to Little Lemon</Text>\r\n      <Text style={styles.regularText}>Login to continue </Text>\r\n      <TextInput\r\n        style={styles.inputBox}\r\n        value={email}\r\n        onChangeText={onChangeEmail}\r\n        placeholder={\'email\'}\r\n        keyboardType={\'email-address\'}\r\n      />\r\n      <TextInput\r\n        style={styles.inputBox}\r\n        value={password}\r\n        onChangeText={onChangePassword}\r\n        placeholder={\'password\'}\r\n        keyboardType={\'default\'}\r\n        secureTextEntry={true}\r\n      />\r\n    </ScrollView>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  container: {\r\n    flex: 1,\r\n  },\r\n  headerText: {\r\n    padding: 40,\r\n    fontSize: 30,\r\n    color: \'#EDEFEE\',\r\n    textAlign: \'center\',\r\n  },\r\n  regularText: {\r\n    fontSize: 24,\r\n    padding: 20,\r\n    marginVertical: 8,\r\n    color: \'#EDEFEE\',\r\n    textAlign: \'center\',\r\n  },\r\n  inputBox: {\r\n    height: 40,\r\n    margin: 12,\r\n    borderWidth: 1,\r\n    padding: 10,\r\n    fontSize: 16,\r\n    borderColor: \'#EDEFEE\',\r\n    backgroundColor: \'#EDEFEE\',\r\n  },\r\n});\r\n\r\nSolution: Create a clickable text area with Pressable\r\nLoginScreen.js\r\nimport React, { useState } from \'react\';\r\nimport {\r\n  ScrollView,\r\n  Text,\r\n  StyleSheet,\r\n  TextInput,\r\n  Pressable,\r\n} from \'react-native\';\r\n\r\nexport default function LoginScreen() {\r\n  const [email, onChangeEmail] = useState(\'\');\r\n  const [password, onChangePassword] = useState(\'\');\r\n  const [loggedIn, onLogin] = useState(false);\r\n\r\n  return (\r\n    <ScrollView style={styles.container}>\r\n      <Text style={styles.headerText}>Welcome to Little Lemon</Text>\r\n      {loggedIn && <Text style={styles.headerText}>You are logged in!</Text>}\r\n\r\n      {!loggedIn && (\r\n        <>\r\n          <Text style={styles.regularText}>Login to continue </Text>\r\n          <TextInput\r\n            style={styles.inputBox}\r\n            value={email}\r\n            onChangeText={onChangeEmail}\r\n            placeholder={\'email\'}\r\n            keyboardType={\'email-address\'}\r\n          />\r\n          <TextInput\r\n            style={styles.inputBox}\r\n            value={password}\r\n            onChangeText={onChangePassword}\r\n            placeholder={\'password\'}\r\n            keyboardType={\'default\'}\r\n            secureTextEntry={true}\r\n          />\r\n          <Pressable onPress={() => onLogin(!loggedIn)} style={styles.button}>\r\n            <Text style={styles.buttonText}>Log in</Text>\r\n          </Pressable>\r\n        </>\r\n      )}\r\n    </ScrollView>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  container: {\r\n    flex: 1,\r\n  },\r\n  headerText: {\r\n    padding: 40,\r\n    fontSize: 30,\r\n    color: \'#EDEFEE\',\r\n    textAlign: \'center\',\r\n  },\r\n  regularText: {\r\n    fontSize: 24,\r\n    padding: 20,\r\n    marginVertical: 8,\r\n    color: \'#EDEFEE\',\r\n    textAlign: \'center\',\r\n  },\r\n  inputBox: {\r\n    height: 40,\r\n    margin: 12,\r\n    borderWidth: 1,\r\n    padding: 10,\r\n    fontSize: 16,\r\n    borderColor: \'EDEFEE\',\r\n    backgroundColor: \'#EDEFEE\',\r\n  },\r\n  button: {\r\n    fontSize: 22,\r\n    padding: 10,\r\n    marginVertical: 8,\r\n    margin: 100,\r\n    backgroundColor: \'#EE9972\',\r\n    borderColor: \'#EE9972\',\r\n    borderWidth: 2,\r\n    borderRadius: 50,\r\n  },\r\n  buttonText: {\r\n    color: \'black\',\r\n    textAlign: \'center\',\r\n    fontSize: 25,\r\n  },\r\n});\r\n\r\nSolution: Displaying Images in your app\r\nWelcomeScreen.js\r\nimport { ScrollView, View, Text, StyleSheet, Image } from \'react-native\';\r\n\r\nexport default function WelcomeScreen() {\r\n  return (\r\n    <ScrollView style={styles.container}>\r\n      <View style={styles.headerWrapper}>\r\n        <Image\r\n          style={styles.image}\r\n          source={require(\'./img/logo.png\')}\r\n          resizeMode=\"cover\"\r\n          accessible={true}\r\n          accessibilityLabel={\'Little Lemon Logo\'}\r\n        />\r\n\r\n        <Text style={styles.headerText}>Little Lemon</Text>\r\n      </View>\r\n      <Text style={styles.regularText}>\r\n        Little Lemon is a charming neighborhood bistro that serves simple food\r\n        and classic cocktails in a lively but casual environment. We would love\r\n        to hear your experience with us!\r\n      </Text>\r\n    </ScrollView>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  container: {\r\n    flex: 1,\r\n  },\r\n  headerWrapper: {\r\n    flexDirection: \'row\',\r\n    justifyContent: \'center\',\r\n    margin: 10,\r\n  },\r\n  headerText: {\r\n    paddingRight: 10,\r\n    paddingLeft: 20,\r\n    paddingTop: 30,\r\n    paddingBottom: 10,\r\n    fontSize: 30,\r\n    color: \'#EDEFEE\',\r\n    textAlign: \'center\',\r\n  },\r\n  regularText: {\r\n    fontSize: 24,\r\n    padding: 20,\r\n    marginVertical: 8,\r\n    color: \'#EDEFEE\',\r\n    textAlign: \'center\',\r\n  },\r\n  image: {\r\n    width: 100,\r\n    height: 100,\r\n    borderRadius: 20,\r\n  },\r\n});\r\n\r\nSolution: Hooks in React Native\r\nWelcomeScreen.js\r\nimport {\r\n  ScrollView,\r\n  View,\r\n  Text,\r\n  StyleSheet,\r\n  Image,\r\n  useColorScheme,\r\n} from \'react-native\';\r\n\r\nexport default function WelcomeScreen() {\r\n  const colorScheme = useColorScheme();\r\n\r\n  return (\r\n    <ScrollView\r\n      style={[\r\n        styles.container,\r\n        colorScheme === \'light\'\r\n          ? { backgroundColor: \'#fff\' }\r\n          : { backgroundColor: \'#333333\' },\r\n      ]}>\r\n      <View style={styles.headerWrapper}>\r\n        <Image\r\n          style={styles.image}\r\n          source={require(\'./img/logo.png\')}\r\n          resizeMode=\"cover\"\r\n          accessible={true}\r\n          accessibilityLabel={\'Little Lemon Logo\'}\r\n        />\r\n\r\n        <Text\r\n          style={[\r\n            styles.headerText,\r\n            colorScheme === \'light\'\r\n              ? { color: \'#333333\' }\r\n              : { color: \'#EDEFEE\' },\r\n          ]}>\r\n          Little Lemon\r\n        </Text>\r\n      </View>\r\n      <Text\r\n        style={[\r\n          styles.regularText,\r\n          colorScheme === \'light\' ? { color: \'#333333\' } : { color: \'#EDEFEE\' },\r\n        ]}>\r\n        Little Lemon is a charming neighborhood bistro that serves simple food\r\n        and classic cocktails in a lively but casual environment. We would love\r\n        to hear your experience with us!\r\n      </Text>\r\n    </ScrollView>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  container: {\r\n    flex: 1,\r\n  },\r\n  headerWrapper: {\r\n    flexDirection: \'row\',\r\n    justifyContent: \'center\',\r\n    margin: 10,\r\n  },\r\n  headerText: {\r\n    paddingRight: 10,\r\n    paddingLeft: 20,\r\n    paddingTop: 30,\r\n    paddingBottom: 10,\r\n    fontSize: 30,\r\n    color: \'#EDEFEE\',\r\n    textAlign: \'center\',\r\n  },\r\n  regularText: {\r\n    fontSize: 24,\r\n    padding: 20,\r\n    marginVertical: 8,\r\n    color: \'#EDEFEE\',\r\n    textAlign: \'center\',\r\n  },\r\n  image: {\r\n    width: 100,\r\n    height: 100,\r\n    borderRadius: 20,\r\n  },\r\n});\r\n\r\nSolution: Set up Routes\r\nApp.js\r\nimport * as React from \'react\';\r\nimport { View, Text, StyleSheet } from \'react-native\';\r\n\r\nimport LittleLemonHeader from \'./components/LittleLemonHeader\';\r\nimport LittleLemonFooter from \'./components/LittleLemonFooter\';\r\nimport WelcomeScreen from \'./WelcomeScreen\';\r\nimport LoginScreen from \'./LoginScreen\';\r\nimport { NavigationContainer } from \'@react-navigation/native\';\r\nimport { createNativeStackNavigator } from \'@react-navigation/native-stack\';\r\n\r\nconst Stack = createNativeStackNavigator();\r\n\r\nexport default function App() {\r\n  return (\r\n    <>\r\n      <NavigationContainer>\r\n        <View style={styles.container}>\r\n          <LittleLemonHeader />\r\n          <Stack.Navigator initialRouteName=\"Login\">\r\n            <Stack.Screen name=\"Welcome\" component={WelcomeScreen} />\r\n            <Stack.Screen name=\"Login\" component={LoginScreen} />\r\n          </Stack.Navigator>\r\n        </View>\r\n        <View style={styles.footerContainer}>\r\n          <LittleLemonFooter />\r\n        </View>\r\n      </NavigationContainer>\r\n    </>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  container: {\r\n    flex: 1,\r\n    backgroundColor: \'#333333\',\r\n  },\r\n  footerContainer: { backgroundColor: \'#333333\' },\r\n});\r\n\r\nSolution: Moving between screens\r\nLoginScreen.js\r\nimport React, { useState } from \'react\';\r\nimport {\r\n  ScrollView,\r\n  Text,\r\n  StyleSheet,\r\n  TextInput,\r\n  Pressable,\r\n} from \'react-native\';\r\n\r\nexport default function LoginScreen({ navigation }) {\r\n  const [email, onChangeEmail] = useState(\'\');\r\n  const [password, onChangePassword] = useState(\'\');\r\n\r\n  return (\r\n    <ScrollView style={styles.container}>\r\n      <Text style={styles.headerText}>Welcome to Little Lemon</Text>\r\n      <Text style={styles.regularText}>Login to continue </Text>\r\n      <TextInput\r\n        style={styles.inputBox}\r\n        value={email}\r\n        onChangeText={onChangeEmail}\r\n        placeholder={\'email\'}\r\n        keyboardType={\'email-address\'}\r\n      />\r\n      <TextInput\r\n        style={styles.inputBox}\r\n        value={password}\r\n        onChangeText={onChangePassword}\r\n        placeholder={\'password\'}\r\n        keyboardType={\'default\'}\r\n        secureTextEntry={true}\r\n      />\r\n      <Pressable\r\n        onPress={() => navigation.navigate(\'Welcome\')}\r\n        style={styles.button}>\r\n        <Text style={styles.buttonText}>Log in</Text>\r\n      </Pressable>\r\n    </ScrollView>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  container: {\r\n    flex: 1,\r\n    backgroundColor: \'#333333\',\r\n  },\r\n  headerText: {\r\n    padding: 40,\r\n    fontSize: 30,\r\n    color: \'#EDEFEE\',\r\n    textAlign: \'center\',\r\n  },\r\n  regularText: {\r\n    fontSize: 24,\r\n    padding: 20,\r\n    marginVertical: 8,\r\n    color: \'#EDEFEE\',\r\n    textAlign: \'center\',\r\n  },\r\n  inputBox: {\r\n    height: 40,\r\n    margin: 12,\r\n    borderWidth: 1,\r\n    padding: 10,\r\n    fontSize: 16,\r\n    borderColor: \'EDEFEE\',\r\n    backgroundColor: \'#EDEFEE\',\r\n  },\r\n  button: {\r\n    fontSize: 22,\r\n    padding: 10,\r\n    marginVertical: 8,\r\n    margin: 100,\r\n    backgroundColor: \'#EE9972\',\r\n    borderColor: \'#EE9972\',\r\n    borderWidth: 2,\r\n    borderRadius: 50,\r\n  },\r\n  buttonText: {\r\n    color: \'black\',\r\n    textAlign: \'center\',\r\n    fontSize: 25,\r\n  },\r\n});\r\n\r\nSolution: Configure Tab Navigation\r\nApp.js\r\nimport * as React from \'react\';\r\nimport { View, StyleSheet } from \'react-native\';\r\n\r\nimport LittleLemonHeader from \'./components/LittleLemonHeader\';\r\nimport LittleLemonFooter from \'./components/LittleLemonFooter\';\r\nimport WelcomeScreen from \'./WelcomeScreen\';\r\nimport LoginScreen from \'./LoginScreen\';\r\nimport { NavigationContainer } from \'@react-navigation/native\';\r\nimport Ionicons from \'@expo/vector-icons/Ionicons\';\r\nimport { createBottomTabNavigator } from \'@react-navigation/bottom-tabs\';\r\n\r\nconst Tab = createBottomTabNavigator();\r\n\r\nexport default function App() {\r\n  return (\r\n    <>\r\n      <NavigationContainer>\r\n        <View style={styles.container}>\r\n          <LittleLemonHeader />\r\n          <Tab.Navigator\r\n            screenOptions={({ route }) => ({\r\n              tabBarIcon: ({size}) => {\r\n                let iconName;\r\n                if (route.name === \'Welcome\') {\r\n                  iconName = \'ios-home\';\r\n                } else if (route.name === \'Login\') {\r\n                  iconName = \'ios-enter\';\r\n                }\r\n                return <Ionicons name={iconName} size={size} />;\r\n              },\r\n            })}\r\n            initialRouteName=\"Login\">\r\n            <Tab.Screen name=\"Welcome\" component={WelcomeScreen} />\r\n            <Tab.Screen name=\"Login\" component={LoginScreen} />\r\n          </Tab.Navigator>\r\n        </View>\r\n        <View style={styles.footerContainer}>\r\n          <LittleLemonFooter />\r\n        </View>\r\n      </NavigationContainer>\r\n    </>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  container: {\r\n    flex: 1,\r\n    backgroundColor: \'#333333\',\r\n  },\r\n  footerContainer: { backgroundColor: \'#333333\' },\r\n});\r\n\r\nSolution: Configure Drawer Navigation\r\nApp.js \r\nimport { View, StyleSheet } from \'react-native\';\r\nimport LittleLemonHeader from \'./components/LittleLemonHeader\';\r\nimport LittleLemonFooter from \'./components/LittleLemonFooter\';\r\nimport WelcomeScreen from \'./WelcomeScreen\';\r\nimport LoginScreen from \'./LoginScreen\';\r\nimport { NavigationContainer } from \'@react-navigation/native\';\r\nimport { createDrawerNavigator } from \'@react-navigation/drawer\';\r\n\r\nconst Drawer = createDrawerNavigator();\r\n\r\nexport default function App() {\r\n  return (\r\n    <>\r\n      <NavigationContainer>\r\n        <View style={styles.container}>\r\n          <LittleLemonHeader />\r\n          <Drawer.Navigator useLegacyImplementation initialRouteName=\"Login\">\r\n            <Drawer.Screen name=\"Welcome\" component={WelcomeScreen} />\r\n            <Drawer.Screen name=\"Login\" component={LoginScreen} />\r\n          </Drawer.Navigator>\r\n        </View>\r\n        <View style={styles.footerContainer}>\r\n          <LittleLemonFooter />\r\n        </View>\r\n      </NavigationContainer>\r\n    </>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  container: {\r\n    flex: 1,\r\n    backgroundColor: \'#333333\',\r\n  },\r\n  footerContainer: { backgroundColor: \'#333333\' },\r\n});\r\n\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\api\\base.js\r\nimport axios from \'axios\';\r\n\r\nexport const api = axios.create({\r\n    baseURL: \'https://yousab-tech.com/jaiden/public/api\',\r\n});\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\api\\cartFn.js\r\nimport AsyncStorage from \'@react-native-async-storage/async-storage\';\r\n\r\nexport const storeCart = async (value) => {\r\n  try {\r\n    await AsyncStorage.setItem(\"cart\", JSON.stringify(value));\r\n  } catch (e) {\r\n    console.log({ error: e });\r\n  }\r\n};\r\n\r\nexport const getCart = async () => {\r\n  try {\r\n    const jsonValue = await AsyncStorage.getItem(\"cart\");\r\n    return jsonValue != null ? JSON.parse(jsonValue) : null;\r\n  } catch (e) {\r\n    console.log({ error: e });\r\n  }\r\n};\r\n\r\nexport const removeCart = async () => {\r\n  try {\r\n    await AsyncStorage.removeItem(\"cart\");\r\n  } catch (e) {\r\n    console.log({ error: e });\r\n  }\r\n};\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\api\\home.js\r\nimport { api } from \"./base\"\r\n\r\nexport const getHome = async ({locale}) => {\r\n    api.defaults.headers = {locale};\r\n    const res = await api.get(\'/home\');\r\n    return res.data;\r\n}\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\api\\login.js\r\nimport AsyncStorage from \"@react-native-async-storage/async-storage\";\r\nimport { api } from \"./base\";\r\n\r\nexport const login = async ({ values }) => {\r\n  const res = await api.post(`/auth/login`, values);\r\n  return res;\r\n};\r\nexport const register = async ({ values }) => {\r\n  const res = await api.post(`/auth/register`, values);\r\n  return res;\r\n};\r\n\r\nexport const storeLogin = async (value) => {\r\n  try {\r\n    const token = JSON.stringify(value);\r\n    await AsyncStorage.setItem(\"token\", token);\r\n  } catch (err) {\r\n    // saving error\r\n    console.log(\"async storage error\", err);\r\n  }\r\n};\r\nexport const storeLogout = async () => {\r\n  try {\r\n    await AsyncStorage.removeItem(\"token\");\r\n  } catch (err) {\r\n    // saving error\r\n    console.log(\"async storage error\", err);\r\n  }\r\n};\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\api\\orders.js\r\nimport { api } from \"./base\";\r\n\r\nexport const orderPost = async ({ token, values }) => {\r\n  api.defaults.headers = { Authorization: `Bearer ${token}` };\r\n  const res = await api.post(`/auth/order`, values);\r\n  return res.data;\r\n};\r\n\r\nexport const getPendingOrders = async ({ token, type }) => {\r\n  api.defaults.headers = { Authorization: `Bearer ${token}` };\r\n  console.log({ type });\r\n  const res = await api.get(`/auth/orders/${type}`);\r\n  return res.data;\r\n};\r\nexport const getSingleOrder = async ({ token, orderId }) => {\r\n  api.defaults.headers = { Authorization: `Bearer ${token}` };\r\n  const res = await api.get(`/auth/order/${orderId}`);\r\n  return res.data;\r\n};\r\n\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\api\\products.js\r\nimport { api } from \"./base\";\r\n\r\nexport const createProduct = async ({ values }) => {\r\n  const res = await api.post(`/products/store`, values);\r\n  return res.data;\r\n};\r\n\r\nexport const getProducts = async ({ locale }) => {\r\n  api.defaults.headers = { locale };\r\n  const res = await api.get(\"/products\");\r\n  return res.data;\r\n};\r\n\r\nexport const getProduct = async ({ locale, itemId }) => {\r\n  api.defaults.headers = { locale };\r\n  const res = await api.get(`/product/${itemId}`);\r\n  return res.data;\r\n};\r\nexport const getProductEdit = async ({ locale, itemId }) => {\r\n  api.defaults.headers = { locale };\r\n  const res = await api.get(`/products/${itemId}/edit`);\r\n  return res.data;\r\n};\r\n\r\nexport const removeProduct = async ({ itemId }) => {\r\n  const res = await api.delete(`/products/${itemId}`);\r\n  return res.data;\r\n};\r\n\r\nexport const productUpdate = async ({ itemId, values }) => {\r\n  const res = await api.post(`/products/${itemId}`, values);\r\n  return res.data;\r\n};\r\n\r\nexport const productsFilter = async ({ title }) => {\r\n  const res = await api.post(\"/products-filter\", { title });\r\n  return res.data;\r\n};\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\api\\users.js\r\nimport { api } from \"./base\";\r\n\r\nexport const getRolesRegister = async () => {\r\n  const res = await api.get(\"/roles_register\");\r\n  return res.data;\r\n};\r\n\r\nexport const getGovernorates = async ({ locale }) => {\r\n  api.defaults.headers = { locale };\r\n  const res = await api.get(\"/governorates\");\r\n  return res.data;\r\n};\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\navigations\\AppNavigation.js\r\nimport { createNativeStackNavigator } from \"@react-navigation/native-stack\";\r\nimport AsyncStorage from \"@react-native-async-storage/async-storage\";\r\nimport React, { useState, useEffect } from \"react\";\r\nimport {\r\n  Onboarding1,\r\n  Onboarding2,\r\n  Onboarding3,\r\n  Onboarding4,\r\n  Signup,\r\n  Verification,\r\n  Login,\r\n  StartUpScreen,\r\n  ForgotPassword,\r\n  ResetPassword,\r\n  LocationAccess,\r\n  SuccessRegister,\r\n  AddNewAddress,\r\n  Address,\r\n  Faqs,\r\n  PaymentDeclined,\r\n  PaymentMethod,\r\n  PaymentSuccess,\r\n  Settings,\