\n        />\r\n        <Stack.Screen\r\n          name=\"NewsList\"\r\n          component={NewsList}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"NewsSingle\"\r\n          component={NewsSingle}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"ProductsListAdmin\"\r\n          component={ProductsListAdmin}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"ProductViewAdmin\"\r\n          component={ProductDetailsV1}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"EditProductAdmin\"\r\n          component={EditProductAdmin}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"NewsListAdmin\"\r\n          component={NewsListAdmin}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"AddAdvertisment\"\r\n          component={AddAdvertisment}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"AdminAdvertismentEdit\"\r\n          component={AdminAdvertismentEdit}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"AdminAdvertismentList\"\r\n          component={AdminAdvertismentList}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"AdminAdvertismentShow\"\r\n          component={AdminAdvertismentShow}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"Cart\"\r\n          component={Cart}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"EditCart\"\r\n          component={EditCart}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"AddNewPaymentCard\"\r\n          component={AddNewPaymentCard}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"PaymentCardSuccess\"\r\n          component={PaymentCardSuccess}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"PaymentCardDeclined\"\r\n          component={PaymentCardDeclined}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"SubmitQuestion\"\r\n          component={SubmitQuestion}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"UserReviews\"\r\n          component={UserReviews}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"ProductByKeywords\"\r\n          component={ProductByKeywords}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"ShopView\"\r\n          component={ShopView2}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"ProductDetails\"\r\n          component={ProductDetailsV2}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"AdvertismentSingle\"\r\n          component={AdvertismentSingle}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"ProductReviews\"\r\n          component={ProductReviews}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"PaymentMethodNoCard\"\r\n          component={PaymentMethodNoCard}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"TrackingOrders\"\r\n          component={TrackingOrderV2}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"MyOrderDetails\"\r\n          component={MyOrderDetails}\r\n          options={{\r\n            headerShown: true,\r\n            headerTitle: \"Order Details\",\r\n          }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"Call\"\r\n          component={Call}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"Message\"\r\n          component={Message}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"Favourite\"\r\n          component={Favourite}\r\n          options={{ headerShown: false }}\r\n        />\r\n      </Stack.Navigator>\r\n    </NavigationContainer>\r\n  );\r\n};\r\n\r\nexport default AppNavigation;\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\store\\userSlice\\index.js\r\nimport { createSlice } from \"@reduxjs/toolkit\";\r\nimport { storeLogin, storeLogout } from \"../../api/login\";\r\n// import { storeLogin } from \"../../api/login\";\r\n\r\nconst initialState = {\r\n  data: null,\r\n  isLoggedIn: false,\r\n};\r\n\r\nexport const loginSlice = createSlice({\r\n  name: \"login\",\r\n  initialState,\r\n  reducers: {\r\n    setLogin: (state, action) => {\r\n      storeLogin(action.payload);\r\n      state.data = action.payload;\r\n      state.isLoggedIn = true;\r\n    },\r\n    setLogout: (state, action) => {\r\n      storeLogout();\r\n      state.data = null;\r\n      state.isLoggedIn = false;\r\n    },\r\n  },\r\n});\r\n\r\n// Action creators are generated for each case reducer function\r\nexport const { setLogin, setLogout } = loginSlice.actions;\r\nconst loginReducer = loginSlice.reducer;\r\nexport default loginReducer;\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\store\\cartSlice\\index.js\r\nimport { createSlice } from \"@reduxjs/toolkit\";\r\nimport { calcTotal } from \"../../helpers/settings\";\r\nimport { storeCart, getCart, removeCart } from \"../../api/cartFn\";\r\n\r\nconst initialState = {\r\n  items: [],\r\n  totalQty: 0,\r\n  totalPrice: 0,\r\n};\r\n\r\nconst cartSlice = createSlice({\r\n  name: \"cart\",\r\n  initialState,\r\n  reducers: {\r\n    addToCart: (state, action) => {\r\n      let product = action.payload.product;\r\n      const foundProduct = state.items?.find((item) => item.id === product.id);\r\n      let newArr;\r\n      if (foundProduct) {\r\n        newArr = state.items.map((item) => {\r\n          if (item.id === product.id) {\r\n            item.qty += action.payload.qty;\r\n            item[\"totalPrice\"] = item.qty * item.price;\r\n          }\r\n          return item;\r\n        });\r\n        state.totalPrice = calcTotal(newArr);\r\n        state.items = newArr;\r\n        storeCart(state);\r\n      } else {\r\n        product[\"qty\"] = action.payload.qty;\r\n        state.totalQty++;\r\n        product[\"totalPrice\"] = product[\"qty\"] * product.price;\r\n        state.totalPrice += product[\"totalPrice\"];\r\n        state.items = [...state.items, product];\r\n        storeCart(state);\r\n      }\r\n    },\r\n\r\n    saveCart: (state, action) => {\r\n      if (getCart()) {\r\n        let cart = getCart();\r\n        state.items = cart.items;\r\n        state.totalPrice = cart.totalPrice;\r\n        state.totalQty = cart.totalQty;\r\n      }\r\n    },\r\n\r\n    addQty: (state, action) => {\r\n      const newArr = state.items.map((item) => {\r\n        if (item.id === action.payload) {\r\n          item[\"qty\"]++;\r\n          item[\"totalPrice\"] = item.qty * item.price;\r\n        }\r\n        return item;\r\n      });\r\n      state.totalPrice = calcTotal(newArr);\r\n      state.items = newArr;\r\n      storeCart(state);\r\n    },\r\n\r\n    decreaseQty: (state, action) => {\r\n      const newArr = state.items.map((item) => {\r\n        if (item.id === action.payload && item.qty > 1) {\r\n          item[\"qty\"]--;\r\n          item[\"totalPrice\"] = item.qty * item.price;\r\n        }\r\n        return item;\r\n      });\r\n      state.totalPrice = calcTotal(newArr);\r\n      state.items = newArr;\r\n      storeCart(state);\r\n    },\r\n\r\n    removeItem: (state, action) => {\r\n      const newArr = state.items.filter((item) => item.id !== action.payload);\r\n      state.totalPrice = calcTotal(newArr);\r\n      state.totalQty--;\r\n      state.items = newArr;\r\n      storeCart(state);\r\n    },\r\n\r\n    emptyCart: (state, action) => {\r\n      state.items = [];\r\n      state.totalQty = 0;\r\n      state.totalPrice = 0;\r\n      removeCart();\r\n    },\r\n  },\r\n});\r\n\r\nexport const {\r\n  addToCart,\r\n  saveCart,\r\n  removeItem,\r\n  addQty,\r\n  decreaseQty,\r\n  setTotalPriceCart,\r\n  emptyCart,\r\n} = cartSlice.actions;\r\nconst cartReducer = cartSlice.reducer;\r\nexport default cartReducer;\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\store\\userRegisterSlice\\index.js\r\nimport { createSlice } from \"@reduxjs/toolkit\";\r\n\r\nconst initialState = {\r\n  roleId: 2,\r\n};\r\n\r\nexport const userRegisterSlice = createSlice({\r\n  name: \"userRegister\",\r\n  initialState,\r\n  reducers: {\r\n    setUserRegister: (state, action) => {\r\n      state.roleId = action.payload;\r\n    },\r\n  },\r\n});\r\n\r\n// Action creators are generated for each case reducer function\r\nexport const { setUserRegister } = userRegisterSlice.actions;\r\nconst userRegisterReducer = userRegisterSlice.reducer;\r\nexport default userRegisterReducer;\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\screens\\Faqs.js\r\nimport { View, Text, TouchableOpacity, Image, LayoutAnimation, StyleSheet } from \'react-native\'\r\nimport React, { useState } from \'react\'\r\nimport { SafeAreaView } from \'react-native-safe-area-context\'\r\nimport { COLORS, SIZES, icons } from \'../constants\'\r\nimport { commonStyles } from \'../styles/CommonStyles\'\r\nimport { ScrollView } from \'react-native-virtualized-view\'\r\nimport Button from \'../components/Button\'\r\nimport { FaqsData } from \'../data/faqs\'\r\n\r\nconst Faqs = ({ navigation }) => {\r\n    /**\r\n     * Render FAQS header\r\n     */\r\n    function renderHeader() {\r\n        return (\r\n            <View style={{\r\n                flexDirection: \'row\',\r\n                alignItems: \'center\',\r\n                marginTop: 20,\r\n            }}>\r\n                <TouchableOpacity\r\n                    onPress={() => navigation.goBack()}\r\n                    style={commonStyles.header1Icon}\r\n                >\r\n                    <Image\r\n                        resizeMode=\'contain\'\r\n                        source={icons.arrowLeft}\r\n                        style={{ height: 24, width: 24, tintColor: COLORS.black }}\r\n                    />\r\n                </TouchableOpacity>\r\n                <Text style={{ marginLeft: 12, fontSize: 17, fontFamily: \'regular\' }}>FAQS</Text>\r\n            </View>\r\n        )\r\n    }\r\n\r\n    /***\r\n     * Render common question asked\r\n     */\r\n\r\n    function renderFAQS(){\r\n        const [expanded, setExpanded] = useState(-1);\r\n      \r\n        const toggleExpand = (index) => {\r\n          LayoutAnimation.configureNext(LayoutAnimation.Presets.easeInEaseOut);\r\n          if (expanded === index) {\r\n            setExpanded(-1);\r\n          } else {\r\n            setExpanded(index);\r\n          }\r\n        };\r\n\r\n        \r\n        return (\r\n            <View style={styles.container}>\r\n            {FaqsData.map((faq, index) => (\r\n                <View key={index} style={styles.faqContainer}>\r\n                <TouchableOpacity onPress={() => toggleExpand(index)} activeOpacity={0.8}>\r\n                    <View style={styles.questionContainer}>\r\n                    <Text style={styles.question}>{faq.question}</Text>\r\n                    <Text style={styles.icon}>{expanded === index ? \'-\' : \'+\'}</Text>\r\n                    </View>\r\n                </TouchableOpacity>\r\n                {expanded === index && <Text style={styles.answer}>{faq.answer}</Text>}\r\n                </View>\r\n            ))}\r\n            </View>\r\n        )\r\n    }\r\n\r\n    /**Render Button to ask question */\r\n\r\n    function renderActionButtons (){\r\n        return (\r\n            <Button\r\n              title=\"ASK QUESTION\"\r\n              onPress={()=>navigation.navigate(\"SubmitQuestion\")}\r\n              filled\r\n              style={{\r\n                width: SIZES.width - 32,\r\n                backgroundColor: COLORS.red,\r\n                borderColor: COLORS.red,\r\n                marginVertical: 12\r\n              }}\r\n            />\r\n        )\r\n    }\r\n    return (\r\n        <SafeAreaView style={{\r\n            flex: 1,\r\n            backgroundColor: COLORS.white\r\n        }}>\r\n            <View style={{\r\n                flex: 1,\r\n                marginHorizontal: 16\r\n            }}>\r\n                {renderHeader()}\r\n                <ScrollView>\r\n                    {renderFAQS()}\r\n                    {renderActionButtons()}\r\n                </ScrollView>\r\n            </View>\r\n        </SafeAreaView>\r\n    )\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n    container: {\r\n        flex: 1,\r\n        backgroundColor: \'#f8f8f8\',\r\n        paddingHorizontal: 16,\r\n        paddingTop: 20,\r\n      },\r\n      faqContainer: {\r\n        marginBottom: 20,\r\n        backgroundColor: \'#fff\',\r\n        borderRadius: 8,\r\n        shadowColor: \'#000\',\r\n        shadowOffset: { width: 0, height: 1 },\r\n        shadowOpacity: 0.1,\r\n        shadowRadius: 1,\r\n        elevation: 1,\r\n      },\r\n      questionContainer: {\r\n        flexDirection: \'row\',\r\n        justifyContent: \'space-between\',\r\n        alignItems: \'center\',\r\n        paddingVertical: 10,\r\n        paddingHorizontal: 16,\r\n      },\r\n      question: {\r\n        flex: 1,\r\n        fontSize: 16,\r\n        fontFamily: \'medium\',\r\n        color: \'#333\',\r\n      },\r\n      icon: {\r\n        fontSize: 18,\r\n        color: \'#666\',\r\n      },\r\n      answer: {\r\n        fontSize: 14,\r\n        marginTop: 10,\r\n        paddingHorizontal: 16,\r\n        paddingBottom: 10,\r\n        fontFamily: \'regular\',\r\n        color: \'#666\',\r\n      },\r\n  });\r\n\r\nexport default Faqs\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\screens\\Advertisments.js\r\nimport React, { useEffect, useState } from \"react\";\r\nimport {\r\n  Image,\r\n  ImageBackground,\r\n  SafeAreaView,\r\n  ScrollView,\r\n  StatusBar,\r\n  StyleSheet,\r\n  Text,\r\n  TouchableOpacity,\r\n  View,\r\n} from \"react-native\";\r\nimport { getAdvertisments } from \"../api/advertisments\";\r\nimport { commonStyles } from \"../styles/CommonStyles\";\r\nimport { COLORS, icons } from \"../constants\";\r\n\r\nconst Advertisments = ({ navigation }) => {\r\n  const [ads, setAds] = useState(null);\r\n\r\n  useEffect(() => {\r\n    getAdvertisments({ locale: \"en\" }).then((res) => {\r\n      setAds(res.data.advertisements);\r\n    });\r\n  }, []);\r\n\r\n  const renderHeader = () => {\r\n    return (\r\n      <View\r\n        style={{\r\n          flexDirection: \"row\",\r\n          alignItems: \"center\",\r\n          marginTop: 20,\r\n        }}\r\n      >\r\n        <TouchableOpacity\r\n          onPress={() => navigation.goBack()}\r\n          style={commonStyles.header1Icon}\r\n        >\r\n          <Image\r\n            resizeMode=\"contain\"\r\n            source={icons.arrowLeft}\r\n            style={{ height: 24, width: 24, tintColor: COLORS.black }}\r\n          />\r\n        </TouchableOpacity>\r\n        <Text style={{ marginLeft: 12, fontSize: 17, fontFamily: \"regular\" }}>\r\n          Advertisments\r\n        </Text>\r\n      </View>\r\n    );\r\n  };\r\n\r\n  const renderAds = () => {\r\n    return ads?.map((item) => {\r\n      return (\r\n        <TouchableOpacity\r\n          onPress={() =>\r\n            navigation.navigate(\"AdvertismentSingle\", {\r\n              itemId: item.id,\r\n            })\r\n          }\r\n        >\r\n          <View style={{ borderRadius: 8, overflow: \"hidden\" }}>\r\n            <ImageBackground\r\n              source={{ uri: item.image }}\r\n              resizeMode=\"cover\"\r\n              style={styles.image}\r\n            >\r\n              <Text style={styles.text}>{item.product.title}</Text>\r\n            </ImageBackground>\r\n          </View>\r\n        </TouchableOpacity>\r\n      );\r\n    });\r\n  };\r\n\r\n  return (\r\n    <SafeAreaView style={styles.area}>\r\n      <StatusBar hidden={true} />\r\n      <View style={{ flex: 1, paddingHorizontal: 16 }}>\r\n        {renderHeader()}\r\n        <ScrollView style={{ marginTop: 30 }}>{renderAds()}</ScrollView>\r\n      </View>\r\n    </SafeAreaView>\r\n  );\r\n};\r\n\r\nconst styles = StyleSheet.create({\r\n  container: {\r\n    flex: 1,\r\n  },\r\n  area: {\r\n    flex: 1,\r\n    backgroundColor: COLORS.white,\r\n  },\r\n  image: {\r\n    flex: 1,\r\n    justifyContent: \"center\",\r\n    width: \"100%\",\r\n    height: 200,\r\n    borderRadius: 8,\r\n  },\r\n  text: {\r\n    color: \"white\",\r\n    fontSize: 22,\r\n    lineHeight: 84,\r\n    fontWeight: \"bold\",\r\n    textAlign: \"center\",\r\n    justifyContent: \"flex-end\",\r\n    backgroundColor: \"#000000c0\",\r\n    position: \"absolute\",\r\n    bottom: 0,\r\n    width: \"100%\",\r\n  },\r\n});\r\n\r\nexport default Advertisments;\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\screens\\Settings.js\r\nimport { View, Text, TouchableOpacity, Image, StyleSheet, Switch, Modal, FlatList } from \'react-native\'\r\nimport React, { useState } from \'react\'\r\nimport { SafeAreaView } from \'react-native-safe-area-context\'\r\nimport { COLORS, FONTS, SIZES, icons } from \'../constants\'\r\nimport { commonStyles } from \'../styles/CommonStyles\'\r\nimport { StatusBar } from \'expo-status-bar\'\r\n\r\nconst Settings = ({ navigation }) => {\r\n    /**\r\n     * Render header component\r\n     */\r\n    function renderHeader() {\r\n        return (\r\n            <View style={{\r\n                flexDirection: \'row\',\r\n                alignItems: \'center\',\r\n                marginTop: 20,\r\n            }}>\r\n                <TouchableOpacity\r\n                    onPress={() => navigation.goBack()}\r\n                    style={commonStyles.header1Icon}\r\n                >\r\n                    <Image\r\n                        resizeMode=\'contain\'\r\n                        source={icons.arrowLeft}\r\n                        style={{ height: 24, width: 24, tintColor: COLORS.black }}\r\n                    />\r\n                </TouchableOpacity>\r\n                <Text style={{ marginLeft: 12, fontSize: 17, fontFamily: \'regular\' }}>Settings</Text>\r\n            </View>\r\n        )\r\n    }\r\n\r\n    /***\r\n     * Render App Settings\r\n     */\r\n\r\n    function renderAppSettings() {\r\n        const [notificationEnabled, setNotificationEnabled] = useState(false);\r\n        const [darkModeEnabled, setDarkModeEnabled] = useState(false);\r\n        const [locationEnabled, setLocationEnabled] = useState(true);\r\n        const [currency, setCurrency] = useState(\'USD\');\r\n        const [language, setLanguage] = useState(\'English\');\r\n        const [isCurrencyModalVisible, setCurrencyModalVisible] = useState(false);\r\n        const [isLanguageModalVisible, setLanguageModalVisible] = useState(false);\r\n\r\n        const handleNotificationToggle = () => {\r\n            setNotificationEnabled((prevValue) => !prevValue);\r\n        };\r\n\r\n        const handleDarkModeToggle = () => {\r\n            setDarkModeEnabled((prevValue) => !prevValue);\r\n        };\r\n\r\n        const handleLocationToggle = () => {\r\n            setLocationEnabled((prevValue) => !prevValue);\r\n          };\r\n        \r\n          const handleCurrencyChange = (value) => {\r\n            setCurrency(value);\r\n            setCurrencyModalVisible(false);\r\n          };\r\n        \r\n          const handleLanguageChange = (value) => {\r\n            setLanguage(value);\r\n            setLanguageModalVisible(false);\r\n          };\r\n\r\n          const currencies = [\r\n            { id: \'USD\', name: \'USD - United States Dollar\' },\r\n            { id: \'EUR\', name: \'EUR - Euro\' },\r\n            { id: \'GBP\', name: \'GBP - British Pound Sterling\' },\r\n            { \"id\": \"JPY\", name: \"JPY - Japanese Yen\" },\r\n            { \"id\": \"CAD\", name: \"CAD - Canadian Dollar\" },\r\n            { \"id\": \"AUD\", name: \"AUD - Australian Dollar\" },\r\n            { \"id\": \"CHF\", name: \"CHF - Swiss Franc\" },\r\n            { \"id\": \"CNY\", name: \"CNY - Chinese Yuan\" }\r\n            // Add more currencies here\r\n          ];\r\n        \r\n          const languages = [\r\n            { id: \'English\', name: \'English\' },\r\n            { id: \'Spanish\', name: \'Spanish\' },\r\n            { id: \'French\', name: \'French\' },\r\n            { \"id\": \"German\", name: \"German\" },\r\n            { \"id\": \"Italian\", name: \"Italian\" },\r\n            { \"id\": \"Portuguese\", name: \"Portuguese\" },\r\n            { \"id\": \"Japanese\", name: \"Japanese\" },\r\n            { \"id\": \"Chinese\", name: \"Chinese\" }\r\n            // Add more languages here\r\n          ];\r\n\r\n          const renderCurrencyItem = ({ item }) => (\r\n            <TouchableOpacity\r\n              style={[styles.optionButton, currency === item.id && styles.optionButtonSelected]}\r\n              onPress={() => handleCurrencyChange(item.id)}\r\n            >\r\n              <Text style={[styles.optionText, currency === item.id && styles.optionTextSelected]}>{item.name}</Text>\r\n            </TouchableOpacity>\r\n          );\r\n        \r\n          const renderLanguageItem = ({ item }) => (\r\n            <TouchableOpacity\r\n              style={[styles.optionButton, language === item.id && styles.optionButtonSelected]}\r\n              onPress={() => handleLanguageChange(item.id)}\r\n            >\r\n              <Text style={[styles.optionText, language === item.id && styles.optionTextSelected]}>{item.name}</Text>\r\n            </TouchableOpacity>\r\n          );\r\n       \r\n        return (\r\n          <View style={styles.container}>\r\n            <View style={styles.settingContainer}>\r\n              <Text style={styles.settingLabel}>Enable Notifications</Text>\r\n              <Switch\r\n                value={notificationEnabled}\r\n                onValueChange={handleNotificationToggle}\r\n                thumbColor={notificationEnabled ? COLORS.primary : COLORS.white3}\r\n                trackColor={{ false: COLORS.white3, true: COLORS.primary }}\r\n              />\r\n            </View>\r\n      \r\n            <View style={styles.settingContainer}>\r\n              <Text style={styles.settingLabel}>Dark Mode</Text>\r\n              <Switch\r\n                value={darkModeEnabled}\r\n                onValueChange={handleDarkModeToggle}\r\n                thumbColor={darkModeEnabled ? COLORS.primary : COLORS.white3}\r\n                trackColor={{ false: COLORS.white3, true: COLORS.primary }}\r\n              />\r\n            </View>\r\n\r\n            <View style={styles.settingContainer}>\r\n        <Text style={styles.settingLabel}>Enable Location</Text>\r\n        <Switch\r\n          value={locationEnabled}\r\n          onValueChange={handleLocationToggle}\r\n          thumbColor={locationEnabled ? COLORS.primary : COLORS.white3}\r\n          trackColor={{false: COLORS.white3, true: COLORS.primary }}\r\n        />\r\n      </View>\r\n\r\n      <View style={styles.settingContainer}>\r\n        <Text style={styles.settingLabel}>Currency</Text>\r\n        <TouchableOpacity\r\n          style={styles.modalButton}\r\n          onPress={() => setCurrencyModalVisible(true)}\r\n        >\r\n          <Text style={styles.modalButtonText}>{currency}</Text>\r\n        </TouchableOpacity>\r\n        <Modal\r\n          visible={isCurrencyModalVisible}\r\n          animationType=\"slide\"\r\n          onRequestClose={() => setCurrencyModalVisible(false)}\r\n        >\r\n          <View style={styles.modalContainer}>\r\n            <Text style={styles.modalTitle}>Select Currency</Text>\r\n            <FlatList\r\n              data={currencies}\r\n              renderItem={renderCurrencyItem}\r\n              keyExtractor={(item) => item.id}\r\n              showsVerticalScrollIndicator={false}\r\n            />\r\n            <TouchableOpacity\r\n              style={styles.modalCloseButton}\r\n              onPress={() => setCurrencyModalVisible(false)}\r\n            >\r\n              <Text style={styles.modalCloseButtonText}>Close</Text>\r\n            </TouchableOpacity>\r\n          </View>\r\n        </Modal>\r\n      </View>\r\n\r\n      <View style={styles.settingContainer}>\r\n        <Text style={styles.settingLabel}>Language</Text>\r\n        <TouchableOpacity\r\n          style={styles.modalButton}\r\n          onPress={() => setLanguageModalVisible(true)}\r\n        >\r\n          <Text style={styles.modalButtonText}>{language}</Text>\r\n        </TouchableOpacity>\r\n        <Modal\r\n          visible={isLanguageModalVisible}\r\n          animationType=\"slide\"\r\n          onRequestClose={() => setLanguageModalVisible(false)}\r\n        >\r\n          <View style={styles.modalContainer}>\r\n            <Text style={styles.modalTitle}>Select Language</Text>\r\n            <FlatList\r\n              data={languages}\r\n              renderItem={renderLanguageItem}\r\n              keyExtractor={(item) => item.id}\r\n              showsVerticalScrollIndicator={false}\r\n            />\r\n            <TouchableOpacity\r\n              style={styles.modalCloseButton}\r\n              onPress={() => setLanguageModalVisible(false)}\r\n            >\r\n              <Text style={styles.modalCloseButtonText}>Close</Text>\r\n            </TouchableOpacity>\r\n          </View>\r\n        </Modal>\r\n      </View>\r\n\r\n    </View>\r\n    )\r\n    }\r\n\r\n  return (\r\n   <SafeAreaView style={{\r\n    flex: 1,\r\n    backgroundColor: COLORS.white\r\n   }}>\r\n       <StatusBar hidden={true} />\r\n        <View style={{\r\n            marginHorizontal: 12\r\n        }}>     \r\n            {renderHeader()}\r\n        </View>\r\n        {renderAppSettings()}\r\n   </SafeAreaView>\r\n  )\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n    container: {\r\n        flex: 1,\r\n        backgroundColor: \'#f8f8f8\',\r\n        padding: 16,\r\n        marginTop: 16\r\n      },\r\n      title: {\r\n        fontSize: 24,\r\n        fontWeight: \'bold\',\r\n        marginBottom: 24,\r\n        color: \'#333\',\r\n      },\r\n      settingContainer: {\r\n        flexDirection: \'row\',\r\n        justifyContent: \'space-between\',\r\n        alignItems: \'center\',\r\n        marginBottom: 16,\r\n      },\r\n      settingLabel: {\r\n        fontSize: 16,\r\n        color: \'#333\',\r\n        fontFamily: \'regular\'\r\n      },\r\n      modalButton: {\r\n        paddingVertical: 8,\r\n        paddingHorizontal: 12,\r\n        borderRadius: 8,\r\n        backgroundColor: \'#fff\',\r\n        marginRight: 10,\r\n        borderWidth: 1,\r\n        borderColor: COLORS.primary,\r\n        \r\n      },\r\n      modalButtonText: {\r\n        fontSize: 16,\r\n        color: COLORS.primary,\r\n        fontFamily: \'regular\'\r\n      },\r\n      modalContainer: {\r\n        flex: 1,\r\n        backgroundColor: COLORS.white,\r\n        padding: 16,\r\n      },\r\n      modalTitle: {\r\n        fontFamily: \'semiBold\',\r\n        fontSize: 16,\r\n        marginBottom: 16,\r\n        color: \'#333\',\r\n      },\r\n      modalCloseButton: {\r\n        backgroundColor: COLORS.primary,\r\n        borderRadius: 8,\r\n        paddingVertical: 12,\r\n        alignItems: \'center\',\r\n        marginTop: 16,\r\n      },\r\n      modalCloseButtonText: {\r\n        fontSize: 16,\r\n        fontFamily: \'semiBold\',\r\n        color: \'#fff\',\r\n      },\r\n      optionButton: {\r\n        paddingVertical: 8,\r\n        paddingHorizontal: 12,\r\n        borderRadius: 8,\r\n        backgroundColor: \'#fff\',\r\n        marginRight: 10,\r\n        borderWidth: 1,\r\n        borderColor: \'rgba(0,0,0,.5)\',\r\n        marginBottom: 8,\r\n      },\r\n      optionButtonSelected: {\r\n        backgroundColor: COLORS.primary,\r\n        borderWidth: 0,\r\n      },\r\n      optionText: {\r\n        fontSize: 18,\r\n        color: \'rgba(0,0,0,.5)\',\r\n      },\r\n      optionTextSelected: {\r\n        color: \'#fff\',\r\n      },\r\n  });\r\n\r\nexport default Settings\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\screens\\ProductDetailsV1.js\r\nimport { View, Image, TouchableOpacity, Text, StyleSheet } from \"react-native\";\r\nimport React, { useEffect, useState } from \"react\";\r\nimport { SafeAreaView } from \"react-native-safe-area-context\";\r\nimport { COLORS, SIZES, icons, images } from \"../constants\";\r\nimport { commonStyles } from \"../styles/CommonStyles\";\r\nimport { useNavigation, useRoute } from \"@react-navigation/native\";\r\nimport {\r\n  Ionicons,\r\n  MaterialCommunityIcons,\r\n  Fontisto,\r\n  Octicons,\r\n} from \"@expo/vector-icons\";\r\nimport { ScrollView } from \"react-native-virtualized-view\";\r\nimport Button from \"../components/Button\";\r\nimport ColorPicker from \"../components/ColorPicker\";\r\nimport { StatusBar } from \"expo-status-bar\";\r\nimport { getProduct } from \"../api/products\";\r\n\r\nconst ProductDetailsV1 = () => {\r\n  const { postId } = useRoute().params;\r\n  const navigation = useNavigation();\r\n  const [product, setProduct] = useState({});\r\n\r\n  useEffect(() => {\r\n    getProduct({ locale: \"en\", itemId: postId }).then((res) => {\r\n      setProduct(res.data.product);\r\n    });\r\n  }, []);\r\n\r\n  const renderHeader = () => {\r\n    return (\r\n      <View\r\n        style={{\r\n          flexDirection: \"row\",\r\n          alignItems: \"center\",\r\n          marginTop: 20,\r\n        }}\r\n      >\r\n        <TouchableOpacity\r\n          onPress={() => navigation.goBack()}\r\n          style={commonStyles.header1Icon}\r\n        >\r\n          <Image\r\n            resizeMode=\"contain\"\r\n            source={icons.arrowLeft}\r\n            style={{ height: 24, width: 24, tintColor: COLORS.black }}\r\n          />\r\n        </TouchableOpacity>\r\n        <Text style={{ marginLeft: 12, fontSize: 17, fontFamily: \"regular\" }}>\r\n          Details\r\n        </Text>\r\n      </View>\r\n    );\r\n  };\r\n\r\n  const renderProductDetails = () => {\r\n    const [isFavourite, setIsFavourite] = useState(false);\r\n    const [quantity, setQuantity] = useState(2);\r\n    const navigation = useNavigation();\r\n    const [selectedColor, setSelectedColor] = useState(\"#FF0000\"); // Default color\r\n\r\n    const handleColorChange = (color) => {\r\n      setSelectedColor(color);\r\n    };\r\n\r\n    const [selectedSize, setSelectedSize] = useState(null);\r\n    const handleSizeSelection = (size) => {\r\n      setSelectedSize(size);\r\n    };\r\n    return (\r\n      <View style={{ marginVertical: 16 }}>\r\n        {/* Product details images */}\r\n        <View>\r\n          <Image\r\n            source={{uri: product.image}}\r\n            resizeMode=\"contain\"\r\n            style={{\r\n              width: SIZES.width - 32,\r\n              height: 184,\r\n              borderRadius: 32,\r\n              borderColor: COLORS.gray6,\r\n              borderWidth: 1,\r\n            }}\r\n          />\r\n        </View>\r\n        {/* Product details infos */}\r\n        <View style={{ marginVertical: 16 }}>\r\n          <View\r\n            style={{\r\n              flexDirection: \"column\",\r\n              height: 47,\r\n              borderRadius: 50,\r\n              paddingHorizontal: 16,\r\n              alignItems: \"center\",\r\n              borderWidth: 1,\r\n              borderColor: COLORS.gray6,\r\n            }}\r\n          >\r\n            <Text\r\n              style={{\r\n                marginLeft: 12,\r\n                fontFamily: \"regular\",\r\n                fontSize: 14,\r\n              }}\r\n            >\r\n              Company name: {product.company_name}\r\n            </Text>\r\n            <Text\r\n              style={{\r\n                marginLeft: 12,\r\n                fontFamily: \"regular\",\r\n                fontSize: 14,\r\n              }}\r\n            >\r\n              Category: {product?.category?.title}\r\n            </Text>\r\n          </View>\r\n          <Text\r\n            style={{\r\n              fontSize: 18,\r\n              fontFamily: \"bold\",\r\n              textTransform: \"capitalize\",\r\n              marginVertical: 10,\r\n            }}\r\n          >\r\n            {product && product.title}\r\n          </Text>\r\n          <View\r\n            style={{\r\n              backgroundColor: COLORS.tertiaryGray,\r\n              borderRadius: 24,\r\n              paddingHorizontal: 10,\r\n              paddingVertical: 16,\r\n            }}\r\n          >\r\n            <View\r\n              style={{\r\n                flexDirection: \"row\",\r\n                justifyContent: \"space-between\",\r\n                // marginBottom: 16,\r\n              }}\r\n            >\r\n              <Text style={{ fontSize: 28, fontFamily: \"regular\" }}>EGP {product.price}</Text>\r\n              \r\n            </View>\r\n          </View>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            {product.description}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Factory name: {product.factory_name}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Type: {product.type}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Active substances: {product.active_substances}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Retail units no: {product.retail_units_no}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Weight: {product.weight}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Price: {product.price}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Stock: {product.stock}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Discount: {product.discount}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Pharmaceutical form: {product.pharmaceutical_form}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Way used: {product.way_used}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Geographical distribution: {product.geographical_distribution}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Is active: {product.is_active ? \'true\' : \'false\'}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Is agent: {product.is_agent ? \'true\' : \'false\'}\r\n          </Text>\r\n\r\n          {/* <View style={{ flexDirection: \"row\", marginTop: 16 }}>\r\n            <TouchableOpacity\r\n              onPress={() => navigation.navigate(\"ProductReviews\")}\r\n              style={{ flexDirection: \"row\", alignItems: \"center\" }}\r\n            >\r\n              <Octicons name=\"star\" size={24} color={COLORS.primary} />\r\n              <Text style={{ marginLeft: 8 }}>4.7</Text>\r\n            </TouchableOpacity>\r\n            <View\r\n              style={{\r\n                flexDirection: \"row\",\r\n                alignItems: \"center\",\r\n                marginHorizontal: SIZES.padding3,\r\n              }}\r\n            >\r\n              <MaterialCommunityIcons\r\n                name=\"truck-delivery-outline\"\r\n                size={24}\r\n                color={COLORS.primary}\r\n              />\r\n              <Text style={{ marginLeft: 8 }}>Free</Text>\r\n            </View>\r\n            <View style={{ flexDirection: \"row\", alignItems: \"center\" }}>\r\n              <Fontisto name=\"stopwatch\" size={22} color={COLORS.primary} />\r\n              <Text style={{ marginLeft: 8 }}>3 days</Text>\r\n            </View>\r\n          </View> */}\r\n\r\n          {/* <View\r\n            style={{\r\n              flexDirection: \"row\",\r\n              alignItems: \"center\",\r\n              marginBottom: 10,\r\n            }}\r\n          >\r\n            <Text\r\n              style={{ fontSize: 14, fontFamily: \"regular\", marginRight: 20 }}\r\n            >\r\n              SIZE:{\" \"}\r\n            </Text>\r\n\r\n            <View style={{ flexDirection: \"row\", marginVertical: 18 }}>\r\n              <TouchableOpacity\r\n                style={[\r\n                  styles.checkboxContainer,\r\n                  selectedSize === \"X\" && styles.selectedCheckbox,\r\n                ]}\r\n                onPress={() => handleSizeSelection(\"X\")}\r\n              >\r\n                <Text style={[selectedSize === \"X\" && styles.checkboxText]}>\r\n                  X\r\n                </Text>\r\n              </TouchableOpacity>\r\n\r\n              <TouchableOpacity\r\n                style={[\r\n                  styles.checkboxContainer,\r\n                  selectedSize === \"XL\" && styles.selectedCheckbox,\r\n                ]}\r\n                onPress={() => handleSizeSelection(\"XL\")}\r\n              >\r\n                <Text style={[selectedSize === \"XL\" && styles.checkboxText]}>\r\n                  XL\r\n                </Text>\r\n              </TouchableOpacity>\r\n\r\n              <TouchableOpacity\r\n                style={[\r\n                  styles.checkboxContainer,\r\n                  selectedSize === \"M\" && styles.selectedCheckbox,\r\n                ]}\r\n                onPress={() => handleSizeSelection(\"M\")}\r\n              >\r\n                <Text style={[selectedSize === \"M\" && styles.checkboxText]}>\r\n                  M\r\n                </Text>\r\n              </TouchableOpacity>\r\n            </View>\r\n          </View>\r\n\r\n          <View>\r\n            <Text\r\n              style={{\r\n                fontSize: 14,\r\n                fontFamily: \"regular\",\r\n                textTransform: \"uppercase\",\r\n              }}\r\n            >\r\n              Select color:{\" \"}\r\n            </Text>\r\n            <ColorPicker onColorChange={handleColorChange} />\r\n          </View> */}\r\n\r\n          \r\n        </View>\r\n      </View>\r\n    );\r\n  };\r\n  return (\r\n    <SafeAreaView style={{ flex: 1, backgroundColor: COLORS.white }}>\r\n      <StatusBar hidden={true} />\r\n      <View style={{ flex: 1, paddingHorizontal: 16 }}>\r\n        {renderHeader()}\r\n        <ScrollView>{renderProductDetails()}</ScrollView>\r\n      </View>\r\n    </SafeAreaView>\r\n  );\r\n};\r\n\r\nconst styles = StyleSheet.create({\r\n  checkboxContainer: {\r\n    alignItems: \"center\",\r\n    justifyContent: \"center\",\r\n    height: 48,\r\n    width: 48,\r\n    borderRadius: 22,\r\n    borderWidth: 1,\r\n    borderColor: COLORS.gray,\r\n    backgroundColor: COLORS.gray,\r\n    marginRight: 12,\r\n  },\r\n  selectedCheckbox: {\r\n    backgroundColor: COLORS.primary,\r\n  },\r\n  checkboxText: {\r\n    color: COLORS.white,\r\n    fontSize: 16,\r\n    fontFamily: \"regular\",\r\n  },\r\n  selectedColorSwatch: {\r\n    width: 50,\r\n    height: 50,\r\n    borderRadius: 25,\r\n    borderWidth: 1,\r\n    borderColor: \"#ccc\",\r\n    marginTop: 20,\r\n  },\r\n  selectedColorText: {\r\n    fontSize: 18,\r\n    marginTop: 10,\r\n  },\r\n});\r\n\r\nexport default ProductDetailsV1;\r\n\r\nE:\\xampp\\htdocs\\expo_school_basic\\screens\\Appointments\\index.js\r\nimport React, { useEffect, useState } from \"react\";\r\nimport {\r\n  FlatList,\r\n  Image,\r\n  SafeAreaView,\r\n  Text,\r\n  TouchableOpacity,\r\n  View,\r\n} from \"react-native\";\r\nimport { useSelector } from \"react-redux\";\r\nimport { COLORS, icons } from \"../../constants\";\r\nimport { commonStyles } from \"../../styles/CommonStyles\";\r\nimport { getAppointments } from \"../../api/appointments\";\r\n\r\nconst Appointments = ({ navigation }) => {\r\n  const [items, setItems] = useState(null);\r\n  const user = useSelector((state) => state.user);\r\n  const token = user?.data.access_token;\r\n\r\n  useEffect(() => {\r\n    getAppointments({ token })\r\n      .then((res) => {\r\n        setItems(res.data);\r\n      })\r\n      .catch((err) => {\r\n        console.log({ error: err?.response.data.substring(0, 500) });\r\n      });\r\n  }, []);\r\n\r\n  return (\r\n    <SafeAreaView>\r\n      <View\r\n        style={{\r\n          flexDirection: \"row\",\r\n          alignItems: \"center\",\r\n          marginTop: 20,\r\n        }}\r\n      >\r\n        <TouchableOpacity\r\n          onPress={() => navigation.goBack()}\r\n          style={commonStyles.header1Icon}\r\n        >\r\n          <Image\r\n            resizeMode=\"contain\"\r\n            source={icons.arrowLeft}\r\n            style={{ height: 24, width: 24, tintColor: COLORS.black }}\r\n          />\r\n        </TouchableOpacity>\r\n        <Text style={{ marginLeft: 12, fontSize: 17, fontFamily: \"regular\" }}>\r\n          My Appointments\r\n        </Text>\r\n      </View>\r\n      <View>\r\n        <FlatList\r\n          // style={{ marginStart: 20 }}\r\n          horizontal={false}\r\n          data={items && items}\r\n          keyExtractor={(item) => item.id}\r\n          renderItem={({ item }) => {\r\n            return (\r\n              <View\r\n                style={{\r\n                  borderStyle: \"solid\",\r\n                  borderWidth: 3,\r\n                  borderColor: \"gray\",\r\n                  paddingHorizontal: 20,\r\n                  paddingVertical: 10,\r\n                  marginBottom: 20,\r\n                  marginHorizontal: 10,\r\n                }}\r\n              >\r\n                <Text>Notes: {item.notes}</Text>\r\n                <Text>Reasons: {item.reason}</Text>\r\n                <Text>Appointment: {item.appointment}</Text>\r\n                <Text>Date: {item.date}</Text>\r\n                <Text>Status: {item.result}</Text>\r\n              </View>\r\n            );\r\n          }}\r\n        />\r\n      </View>\r\n    </SafeAreaView>\r\n  );\r\n};\r\n\r\nexport default Appointments;\r\n\r\nE:\\xampp\\htdocs\\expo_school_basic\\screens\\Appointments\\CreateAppointment.js\r\nimport React, { useEffect, useState } from \"react\";\r\nimport {\r\n  Image,\r\n  SafeAreaView,\r\n  ScrollView,\r\n  Text,\r\n  TouchableOpacity,\r\n  View,\r\n} from \"react-native\";\r\nimport Input from \"../../components/Input\";\r\nimport { COLORS, icons } from \"../../constants\";\r\nimport { commonStyles } from \"../../styles/CommonStyles\";\r\nimport Button from \"../../components/Button\";\r\nimport { postAppointment } from \"../../api/appointments\";\r\nimport { useSelector } from \"react-redux\";\r\nimport { useToast } from \"react-native-toast-notifications\";\r\nimport DateTimePickerModal from \"react-native-modal-datetime-picker\";\r\nimport Actionsheet from \"../../components/ActionSheet\";\r\nimport { getStudents, getTeachers } from \"../../api/users\";\r\nimport { AntDesign } from \"@expo/vector-icons\";\r\n\r\nconst CreateAppointment = ({ navigation }) => {\r\n  const [notes, setNotes] = useState(\"\");\r\n  const [isOpen, setIsOpen] = useState(false);\r\n  const [isOpen1, setIsOpen1] = useState(false);\r\n  const [users, setUsers] = useState(null);\r\n  const [teachers, setTeachers] = useState(null);\r\n  const [pickedUsers, setPickedUsers] = useState([]);\r\n  const [pickedTeachers, setPickedTeachers] = useState([]);\r\n  const [reason, setReason] = useState(\"\");\r\n  const [appointment, setAppointment] = useState(\"\");\r\n  const [date, setDate] = useState(new Date(Date.now()));\r\n  const [isDatePickerVisible, setDatePickerVisibility] = useState(false);\r\n  const [result, setResult] = useState(\"pending\");\r\n  const [isLoading, setIsLoading] = useState(false);\r\n  const user = useSelector((state) => state.user);\r\n  const token = user?.data.access_token;\r\n  const toast = useToast();\r\n\r\n  useEffect(() => {\r\n    getStudents({ locale: \"en\" }).then((res) => {\r\n      console.log({ res: res.data.users[0] });\r\n      setUsers(res.data.users);\r\n    });\r\n    getTeachers({ locale: \"en\" }).then((res) => {\r\n      setTeachers(res.data.admins);\r\n    });\r\n  }, []);\r\n\r\n  const findUsers = (id) => {\r\n    const foundUsers = pickedUsers?.find((item) => item === id);\r\n    return foundUsers;\r\n  };\r\n\r\n  const findTeachers = (id) => {\r\n    const foundTeachers = pickedTeachers?.find((item) => item === id);\r\n    console.log({ foundTeachers });\r\n    return foundTeachers;\r\n  };\r\n\r\n  const handlePickUsers = (item) => {\r\n    if (findUsers(item.id)) {\r\n      let arr = pickedUsers?.filter((user) => user !== item.id);\r\n      setPickedUsers(arr);\r\n    } else {\r\n      setPickedUsers([...pickedUsers, item.id]);\r\n    }\r\n  };\r\n\r\n  const handlePickTeachers = (item) => {\r\n    if (findTeachers(item.id)) {\r\n      let arr = pickedTeachers?.filter((user) => user !== item.id);\r\n      setPickedTeachers(arr);\r\n    } else {\r\n      setPickedTeachers([...pickedTeachers, item.id]);\r\n    }\r\n  };\r\n\r\n  const onChange = (event, newDate) => {\r\n    setDate(newDate);\r\n  };\r\n\r\n  const showDatePicker = () => {\r\n    setDatePickerVisibility(true);\r\n  };\r\n\r\n  const hideDatePicker = () => {\r\n    setDatePickerVisibility(false);\r\n  };\r\n\r\n  const handleConfirm = (date) => {\r\n    hideDatePicker();\r\n    setDate(date);\r\n  };\r\n\r\n  const handleSubmit = () => {\r\n    const values = {\r\n      notes,\r\n      reason,\r\n      appointment,\r\n      date,\r\n      result,\r\n      employee_ids: pickedTeachers,\r\n      user_ids: pickedUsers,\r\n    };\r\n\r\n    console.log({ values: { pickedTeachers, pickedUsers } });\r\n    postAppointment({ values, token })\r\n      .then((res) => {\r\n        console.log({ resData: res.data });\r\n        toast.show(\"Made a appointment successfully!\", {\r\n          type: \"success\",\r\n          placement: \"top\",\r\n          duration: 4000,\r\n          offset: 30,\r\n          style: { top: 50 },\r\n          animationType: \"slide-in\",\r\n        });\r\n        setPickedTeachers([]);\r\n        setPickedUsers([]);\r\n        setNotes(\"\");\r\n        setReason(\"\");\r\n        setAppointment(\"\");\r\n      })\r\n      .catch((err) => {\r\n        console.log({ err: err?.response.data });\r\n      });\r\n  };\r\n\r\n  const handleCloseModel = () => {\r\n    setIsOpen(!isOpen);\r\n  };\r\n\r\n  const handleCloseModel1 = () => {\r\n    setIsOpen1(!isOpen1);\r\n  };\r\n\r\n  return (\r\n    <SafeAreaView>\r\n      <View\r\n        style={{\r\n          flexDirection: \"row\",\r\n          alignItems: \"center\",\r\n          marginTop: 20,\r\n        }}\r\n      >\r\n        <TouchableOpacity\r\n          onPress={() => navigation.goBack()}\r\n          style={commonStyles.header1Icon}\r\n        >\r\n          <Image\r\n            resizeMode=\"contain\"\r\n            source={icons.arrowLeft}\r\n            style={{ height: 24, width: 24, tintColor: COLORS.black }}\r\n          />\r\n        </TouchableOpacity>\r\n        <Text style={{ marginLeft: 12, fontSize: 17, fontFamily: \"regular\" }}>\r\n          Request a appointment\r\n        </Text>\r\n      </View>\r\n      <View\r\n        style={{\r\n          alignItems: \"center\",\r\n          padding: 15,\r\n        }}\r\n      >\r\n        <Text style={commonStyles.inputHeader}>Write your notes</Text>\r\n        <Input\r\n          id=\"appointment\"\r\n          value={notes}\r\n          onChangeText={setNotes}\r\n          autoCapitalize=\"none\"\r\n          placeholder=\"notes\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"default\"\r\n        />\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          Describe your reasons\r\n        </Text>\r\n        <Input\r\n          id=\"reason\"\r\n          value={reason}\r\n          onChangeText={setReason}\r\n          autoCapitalize=\"none\"\r\n          placeholder=\"Write your reasons here\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"default\"\r\n          multiline={true}\r\n          numberOfLines={4}\r\n          maxLength={100}\r\n        />\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          Appointment\r\n        </Text>\r\n        <Input\r\n          id=\"appointment\"\r\n          value={appointment}\r\n          onChangeText={setAppointment}\r\n          autoCapitalize=\"none\"\r\n          placeholder=\"Write your appointments here\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"default\"\r\n          multiline={true}\r\n          numberOfLines={4}\r\n          maxLength={100}\r\n        />\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          Pick a date\r\n        </Text>\r\n        <Button\r\n          title={date.toLocaleString(\"en-GB\", { hour12: true })}\r\n          isLoading={isLoading}\r\n          onPress={() => setDatePickerVisibility(true)}\r\n          style={{ ...commonStyles.btn, marginTop: 20 }}\r\n        />\r\n        <DateTimePickerModal\r\n          testID=\"dateTimePicker\"\r\n          isVisible={isDatePickerVisible}\r\n          mode=\"datetime\"\r\n          onConfirm={handleConfirm}\r\n          onCancel={hideDatePicker}\r\n          value={date}\r\n          is24Hour={false}\r\n          display=\"default\"\r\n          onChange={onChange}\r\n        />\r\n\r\n        <Button\r\n          title={\"Pick up users\"}\r\n          isLoading={isLoading}\r\n          onPress={() => setIsOpen(true)}\r\n          style={{ ...commonStyles.btn, marginTop: 20 }}\r\n        />\r\n\r\n        <Button\r\n          title={\"Pick up teachers\"}\r\n          isLoading={isLoading}\r\n          onPress={() => setIsOpen1(true)}\r\n          style={{ ...commonStyles.btn, marginTop: 20 }}\r\n        />\r\n\r\n        <Actionsheet\r\n          isOpen={isOpen}\r\n          onClose={handleCloseModel}\r\n          header={\"Select students\"}\r\n        >\r\n          {users && (\r\n            <ScrollView\r\n              style={{\r\n                backgroundColor: \"#fff\",\r\n                marginTop: -250,\r\n              }}\r\n            >\r\n              {users.map((item) => {\r\n                return (\r\n                  <TouchableOpacity\r\n                    key={item.id}\r\n                    style={{\r\n                      flexDirection: \"row\",\r\n                      justifyContent: \"space-between\",\r\n                      alignItems: \"center\",\r\n                      marginVertical: 12,\r\n                      backgroundColor: \"#fff\",\r\n                      paddingHorizontal: 20,\r\n                    }}\r\n                    onPress={() => handlePickUsers(item)}\r\n                  >\r\n                    <View\r\n                      style={{\r\n                        flexDirection: \"row\",\r\n                        alignItems: \"center\",\r\n                        width: \"100%\",\r\n                      }}\r\n                    >\r\n                      <View>\r\n                        <Image\r\n                          source={{\r\n                            uri: item.image\r\n                              ? item.image\r\n                              : \"../assets/images/user_avatar.png\",\r\n                          }}\r\n                          style={{\r\n                            height: 54,\r\n                            width: 54,\r\n                            borderRadius: 27,\r\n                            marginRight: 16,\r\n                          }}\r\n                        />\r\n                      </View>\r\n                      <View\r\n                        style={{\r\n                          justifyContent: \"space-between\",\r\n                          flexDirection: \"row\",\r\n                          width: 300,\r\n                        }}\r\n                      >\r\n                        <Text>{item.name}</Text>\r\n                        {findUsers(item.id) ? (\r\n                          <AntDesign\r\n                            name=\"checkcircle\"\r\n                            size={24}\r\n                            color=\"black\"\r\n                          />\r\n                        ) : (\r\n                          <AntDesign\r\n                            name=\"checkcircleo\"\r\n                            size={24}\r\n                            color=\"black\"\r\n                          />\r\n                        )}\r\n                      </View>\r\n                    </View>\r\n                  </TouchableOpacity>\r\n                );\r\n              })}\r\n            </ScrollView>\r\n          )}\r\n        </Actionsheet>\r\n        <Actionsheet\r\n          isOpen={isOpen1}\r\n          onClose={handleCloseModel1}\r\n          header={\"Select teachers\"}\r\n        >\r\n          {teachers && (\r\n            <ScrollView\r\n              style={{\r\n                backgroundColor: \"#fff\",\r\n                marginTop: -250,\r\n              }}\r\n            >\r\n              {teachers.map((item) => {\r\n                return (\r\n                  <TouchableOpacity\r\n                    key={item.id}\r\n                    style={{\r\n                      flexDirection: \"row\",\r\n                      justifyContent: \"space-between\",\r\n                      alignItems: \"center\",\r\n                      marginVertical: 12,\r\n                      backgroundColor: \"#fff\",\r\n                      paddingHorizontal: 20,\r\n                    }}\r\n                    onPress={() => handlePickTeachers(item)}\r\n                  >\r\n                    <View\r\n                      style={{\r\n                        flexDirection: \"row\",\r\n                        alignItems: \"center\",\r\n                        width: \"100%\",\r\n                      }}\r\n                    >\r\n                      <View>\r\n                        <Image\r\n                          source={{\r\n                            uri: item.image\r\n                              ? item.image\r\n                              : \"../assets/images/user_avatar.png\",\r\n                          }}\r\n                          style={{\r\n                            height: 54,\r\n                            width: 54,\r\n                            borderRadius: 27,\r\n                            marginRight: 16,\r\n                          }}\r\n                        />\r\n                      </View>\r\n                      <View\r\n                        style={{\r\n                          justifyContent: \"space-between\",\r\n                          flexDirection: \"row\",\r\n                          width: 300,\r\n                        }}\r\n                      >\r\n                        <Text>{item.name}</Text>\r\n                        {findTeachers(item.id) ? (\r\n                          <AntDesign\r\n                            name=\"checkcircle\"\r\n                            size={24}\r\n                            color=\"black\"\r\n                          />\r\n                        ) : (\r\n                          <AntDesign\r\n                            name=\"checkcircleo\"\r\n                            size={24}\r\n                            color=\"black\"\r\n                          />\r\n                        )}\r\n                      </View>\r\n                    </View>\r\n                  </TouchableOpacity>\r\n                );\r\n              })}\r\n            </ScrollView>\r\n          )}\r\n        </Actionsheet>\r\n\r\n        <Button\r\n          title=\"Submit\"\r\n          isLoading={isLoading}\r\n          filled\r\n          onPress={handleSubmit}\r\n          style={{ ...commonStyles.btn, marginTop: 20 }}\r\n        />\r\n      </View>\r\n    </SafeAreaView>\r\n  );\r\n};\r\n\r\nexport default CreateAppointment;\r\nE:\\xampp\\htdocs\\expo_school_basic\\screens\\Bookings\\CreateBooking.js\r\nimport React, { Fragment, useCallback, useEffect, useState } from \"react\";\r\nimport {\r\n  Image,\r\n  SafeAreaView,\r\n  StyleSheet,\r\n  Text,\r\n  TouchableOpacity,\r\n  View,\r\n} from \"react-native\";\r\nimport Input from \"../../components/Input\";\r\nimport { COLORS, icons } from \"../../constants\";\r\nimport { commonStyles } from \"../../styles/CommonStyles\";\r\nimport Button from \"../../components/Button\";\r\nimport { useSelector } from \"react-redux\";\r\nimport { useToast } from \"react-native-toast-notifications\";\r\nimport { createBooking } from \"../../api/bookings\";\r\nimport { getCourse } from \"../../api/courses\";\r\nimport SelectDropdown from \"react-native-select-dropdown\";\r\nimport { Switch } from \"native-base\";\r\nimport { DatePickerModal } from \"react-native-paper-dates\";\r\n\r\nconst CreateBooking = ({ route, navigation }) => {\r\n  const { courseId } = route.params;\r\n  const [amount, setAmount] = useState(\"\");\r\n  const [course, setCourse] = useState(null);\r\n  const [description, setDescription] = useState(\"\");\r\n  const [isReady, setIsReady] = useState(true);\r\n  const [zones, setZones] = useState([\r\n    {\r\n      name: \"full_zone1\",\r\n      value: \"Saturday - Monday - Wednesday\",\r\n    },\r\n    {\r\n      name: \"full_zone2\",\r\n      value: \"Sunday - Tuesday - Thursday\",\r\n    },\r\n    {\r\n      name: \"any\",\r\n      value: \"any\",\r\n    },\r\n  ]);\r\n  const [selectedZone, setSelectedZone] = useState(zones[0]);\r\n  const [isAppointments, setIsAppointments] = useState([\r\n    {\r\n      name: \"full_appointment1\",\r\n      value: \"From 08:30 AM To 02:30 PM\",\r\n    },\r\n    {\r\n      name: \"full_appointment2\",\r\n      value: \"From 02:30 PM To 07:00 PM\",\r\n    },\r\n    {\r\n      name: \"any\",\r\n      value: \"any\",\r\n    },\r\n  ]);\r\n  const [appointments, setAppointments] = useState([\r\n    {\r\n      name: \"full_appointment1\",\r\n      value: [\r\n        {\r\n          name: \"appointment1\",\r\n          value: \"08:30 AM\",\r\n        },\r\n        {\r\n          name: \"appointment2\",\r\n          value: \"10:00 AM\",\r\n        },\r\n        {\r\n          name: \"appointment3\",\r\n          value: \"11:30 AM\",\r\n        },\r\n        {\r\n          name: \"appointment4\",\r\n          value: \"01:00 PM\",\r\n        },\r\n        {\r\n          name: \"any\",\r\n          value: \"any\",\r\n        },\r\n      ],\r\n    },\r\n    {\r\n      name: \"full_appointment2\",\r\n      value: [\r\n        {\r\n          name: \"appointment5\",\r\n          value: \"02:30 PM\",\r\n        },\r\n        {\r\n          name: \"appointment6\",\r\n          value: \"04:00 PM\",\r\n        },\r\n        {\r\n          name: \"appointment7\",\r\n          value: \"05:30 PM\",\r\n        },\r\n        {\r\n          name: \"appointment8\",\r\n          value: \"07:00 PM\",\r\n        },\r\n        {\r\n          name: \"any\",\r\n          value: \"any\",\r\n        },\r\n      ],\r\n    },\r\n    {\r\n      name: \"any\",\r\n      value: \"any\",\r\n    },\r\n  ]);\r\n  const [selectedAppointments, setSelectedAppointments] = useState(\r\n    appointments[0]\r\n  );\r\n  const [selectedIsAppointments, setSelectedIsAppointments] = useState(\r\n    isAppointments[0]\r\n  );\r\n  const [selectedAppointment, setSelectedAppointment] = useState(\r\n    appointments[0].value[0]\r\n  );\r\n\r\n  // console.log({ course });\r\n  const [isLoading, setIsLoading] = useState(false);\r\n  const [date, setDate] = useState(undefined);\r\n  const [open, setOpen] = useState(false);\r\n\r\n  const onDismissSingle = useCallback(() => {\r\n    setOpen(false);\r\n  }, [setOpen]);\r\n\r\n  const onConfirmSingle = useCallback(\r\n    (params) => {\r\n      setOpen(false);\r\n      setDate(params.date);\r\n    },\r\n    [setOpen, setDate]\r\n  );\r\n  const user = useSelector((state) => state.user);\r\n  const token = user?.data.access_token;\r\n  const toast = useToast();\r\n\r\n  useEffect(() => {\r\n    getCourse({ courseId }).then((res) => {\r\n      console.log({ course: res.data });\r\n      setCourse(res.data.course);\r\n    });\r\n  }, []);\r\n\r\n  const onToggleSwitch = () => setIsReady(!isReady);\r\n\r\n  const handleSubmit = () => {\r\n    createBooking({\r\n      values: {\r\n        course_id: courseId,\r\n        category_id: course.category_id,\r\n        choose_zone: selectedZone.name,\r\n        is_appointment: selectedIsAppointments.name,\r\n        appointment: selectedAppointment.name,\r\n      },\r\n      token,\r\n    })\r\n      .then((res) => {\r\n        console.log({ resData: res.data });\r\n        toast.show(\"Made a booking successfully!\", {\r\n          type: \"success\",\r\n          placement: \"top\",\r\n          duration: 4000,\r\n          offset: 30,\r\n          style: { top: 50 },\r\n          animationType: \"slide-in\",\r\n        });\r\n        setBooking(\"\");\r\n      })\r\n      .catch((err) => {\r\n        console.log({ err: err?.response.data.substring(0, 400) });\r\n      });\r\n  };\r\n\r\n  return (\r\n    <SafeAreaView>\r\n      <View\r\n        style={{\r\n          flexDirection: \"row\",\r\n          alignItems: \"center\",\r\n          marginTop: 20,\r\n        }}\r\n      >\r\n        <TouchableOpacity\r\n          onPress={() => navigation.goBack()}\r\n          style={commonStyles.header1Icon}\r\n        >\r\n          <Image\r\n            resizeMode=\"contain\"\r\n            source={icons.arrowLeft}\r\n            style={{ height: 24, width: 24, tintColor: COLORS.black }}\r\n          />\r\n        </TouchableOpacity>\r\n        <Text style={{ marginLeft: 12, fontSize: 17, fontFamily: \"regular\" }}>\r\n          Request a booking\r\n        </Text>\r\n      </View>\r\n      <View\r\n        style={{\r\n          alignItems: \"center\",\r\n          padding: 15,\r\n        }}\r\n      >\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          Are you ready?\r\n        </Text>\r\n        <Switch\r\n          value={isReady}\r\n          isChecked={isReady}\r\n          onValueChange={onToggleSwitch}\r\n        />\r\n        {!isReady && (\r\n          <Fragment>\r\n            <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n              tell us when you are ready\r\n            </Text>\r\n            <TouchableOpacity onPress={() => setOpen(true)}>\r\n              <Input\r\n                id=\"description\"\r\n                value={new Date(date).toLocaleString(\"en-GB\", {\r\n                  year: \"numeric\",\r\n                  month: \"2-digit\",\r\n                  day: \"numeric\",\r\n                })}\r\n                onChangeText={setDate}\r\n                autoCapitalize=\"none\"\r\n                placeholder=\"Pick a date\"\r\n                placeholderTextColor={COLORS.black}\r\n                keyboardType=\"default\"\r\n                editable={false}\r\n              />\r\n            </TouchableOpacity>\r\n            <DatePickerModal\r\n              locale=\"en\"\r\n              mode=\"single\"\r\n              visible={open}\r\n              onDismiss={onDismissSingle}\r\n              date={date}\r\n              onConfirm={onConfirmSingle}\r\n            />\r\n          </Fragment>\r\n        )}\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          Select your zone\r\n        </Text>\r\n        <SelectDropdown\r\n          data={zones}\r\n          onSelect={(selectedItem, index) => {\r\n            console.log({ selectedItem });\r\n            const foundAppoint = zones.find(\r\n              (item) => item.name === selectedItem.name\r\n            );\r\n            setSelectedZone(foundAppoint);\r\n          }}\r\n          renderButton={(selectedItem, isOpened) => {\r\n            return (\r\n              <View style={styles.dropdownButtonStyle}>\r\n                <Text style={styles.dropdownButtonTxtStyle}>\r\n                  {selectedZone.value}\r\n                </Text>\r\n              </View>\r\n            );\r\n          }}\r\n          renderItem={(item, index, isSelected) => {\r\n            return (\r\n              <View\r\n                style={{\r\n                  ...styles.dropdownItemStyle,\r\n                  ...(isSelected && { backgroundColor: \"#D2D9DF\" }),\r\n                }}\r\n              >\r\n                <Text style={styles.dropdownItemTxtStyle}>{item.value}</Text>\r\n              </View>\r\n            );\r\n          }}\r\n          showsVerticalScrollIndicator={false}\r\n          dropdownStyle={styles.dropdownMenuStyle}\r\n        />\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          Select your appointment\r\n        </Text>\r\n        <SelectDropdown\r\n          data={isAppointments}\r\n          onSelect={(selectedItem, index) => {\r\n            console.log({ selectedItem });\r\n            const foundAppoint = appointments.find(\r\n              (item) => item.name === selectedItem.name\r\n            );\r\n            console.log({ foundAppoint });\r\n            setSelectedAppointments(foundAppoint);\r\n            setSelectedIsAppointments(selectedItem);\r\n            setSelectedAppointment(foundAppoint.value[0]);\r\n          }}\r\n          renderButton={(selectedItem, isOpened) => {\r\n            return (\r\n              <View style={styles.dropdownButtonStyle}>\r\n                <Text style={styles.dropdownButtonTxtStyle}>\r\n                  {selectedIsAppointments.value}\r\n                </Text>\r\n              </View>\r\n            );\r\n          }}\r\n          renderItem={(item, index, isSelected) => {\r\n            return (\r\n              <View\r\n                style={{\r\n                  ...styles.dropdownItemStyle,\r\n                  ...(isSelected && { backgroundColor: \"#D2D9DF\" }),\r\n                }}\r\n              >\r\n                <Text style={styles.dropdownItemTxtStyle}>{item.value}</Text>\r\n              </View>\r\n            );\r\n          }}\r\n          showsVerticalScrollIndicator={false}\r\n          dropdownStyle={styles.dropdownMenuStyle}\r\n        />\r\n        {selectedIsAppointments.name !== \"any\" && (\r\n          <Fragment>\r\n            <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n              Select your time\r\n            </Text>\r\n            <SelectDropdown\r\n              data={selectedAppointments.value}\r\n              onSelect={(selectedItem, index) => {\r\n                console.log({ selectedItem });\r\n                const foundAppoint = appointments.find(\r\n                  (item) => item.name === selectedItem.name\r\n                );\r\n                console.log({ selectedItem });\r\n                // setSelectedAppointments(foundAppoint);\r\n                // setSelectedAppointment(foundAppoint);\r\n              }}\r\n              renderButton={(selectedItem, isOpened) => {\r\n                return (\r\n                  <View style={styles.dropdownButtonStyle}>\r\n                    <Text style={styles.dropdownButtonTxtStyle}>\r\n                      {selectedItem\r\n                        ? selectedItem.value\r\n                        : selectedAppointment.value}\r\n                    </Text>\r\n                  </View>\r\n                );\r\n              }}\r\n              renderItem={(item, index, isSelected) => {\r\n                return (\r\n                  <View\r\n                    style={{\r\n                      ...styles.dropdownItemStyle,\r\n                      ...(isSelected && { backgroundColor: \"#D2D9DF\" }),\r\n                    }}\r\n                  >\r\n                    <Text style={styles.dropdownItemTxtStyle}>\r\n                      {item.value}\r\n                    </Text>\r\n                  </View>\r\n                );\r\n              }}\r\n              showsVerticalScrollIndicator={false}\r\n              dropdownStyle={styles.dropdownMenuStyle}\r\n            />\r\n          </Fragment>\r\n        )}\r\n        <Button\r\n          title=\"Submit\"\r\n          isLoading={isLoading}\r\n          filled\r\n          onPress={handleSubmit}\r\n          style={{ ...commonStyles.btn, marginTop: 20 }}\r\n        />\r\n      </View>\r\n    </SafeAreaView>\r\n  );\r\n};\r\n\r\nconst styles = StyleSheet.create({\r\n  dropdownButtonStyle: {\r\n    width: \"100%\",\r\n    height: 50,\r\n    backgroundColor: \"#E9ECEF\",\r\n    borderRadius: 12,\r\n    flexDirection: \"row\",\r\n    justifyContent: \"center\",\r\n    alignItems: \"center\",\r\n    paddingHorizontal: 12,\r\n    marginTop: 20,\r\n  },\r\n  dropdownButtonTxtStyle: {\r\n    flex: 1,\r\n    fontSize: 18,\r\n    fontWeight: \"500\",\r\n    color: \"#151E26\",\r\n  },\r\n  dropdownButtonArrowStyle: {\r\n    fontSize: 28,\r\n  },\r\n  dropdownButtonIconStyle: {\r\n    fontSize: 28,\r\n    marginRight: 8,\r\n  },\r\n  dropdownMenuStyle: {\r\n    backgroundColor: \"#E9ECEF\",\r\n    borderRadius: 8,\r\n  },\r\n  dropdownItemStyle: {\r\n    width: \"100%\",\r\n    flexDirection: \"row\",\r\n    paddingHorizontal: 12,\r\n    justifyContent: \"center\",\r\n    alignItems: \"center\",\r\n    paddingVertical: 8,\r\n  },\r\n  dropdownItemTxtStyle: {\r\n    flex: 1,\r\n    fontSize: 18,\r\n    fontWeight: \"500\",\r\n    color: \"#151E26\",\r\n  },\r\n  dropdownItemIconStyle: {\r\n    fontSize: 28,\r\n    marginRight: 8,\r\n  },\r\n});\r\n\r\nexport default CreateBooking;\r\n\r\nE:\\xampp\\htdocs\\expo_school_basic\\screens\\Bookings\\index.js\r\nimport React, { useEffect, useState } from \"react\";\r\nimport {\r\n  FlatList,\r\n  Image,\r\n  SafeAreaView,\r\n  Text,\r\n  TouchableOpacity,\r\n  View,\r\n} from \"react-native\";\r\nimport { useSelector } from \"react-redux\";\r\nimport { COLORS, icons } from \"../../constants\";\r\nimport { commonStyles } from \"../../styles/CommonStyles\";\r\nimport { getBookings } from \"../../api/bookings\";\r\nimport Card from \"../../components/Card\";\r\nimport { Heading } from \"native-base\";\r\nimport Loader from \"../../components/Loader\";\r\n\r\nconst Bookings = ({ navigation }) => {\r\n  const [categories, setCategories] = useState(null);\r\n  const [loading, setLoading] = useState(true);\r\n  const user = useSelector((state) => state.user);\r\n  const token = user?.data.access_token;\r\n\r\n  useEffect(() => {\r\n    getBookings({ token, locale: \"en\" })\r\n      .then((res) => {\r\n        console.log({ resData: res.data });\r\n        setCategories(res.data.bookings);\r\n        setLoading(false);\r\n      })\r\n      .catch((err) => {\r\n        console.log({ error: err?.response.data.substring(0, 100) });\r\n      });\r\n  }, []);\r\n\r\n  if (loading) {\r\n    return <Loader />;\r\n  }\r\n\r\n  const displayBookings = () => {\r\n    return categories?.map((item) => {\r\n      return (\r\n        <View key={item.id}>\r\n          <Heading fontSize=\"xl\" p=\"4\" pb=\"3\">\r\n            {item.category.title}\r\n          </Heading>\r\n          <FlatList\r\n            style={{ marginStart: 20 }}\r\n            horizontal={true}\r\n            data={item?.category.courses}\r\n            keyExtractor={(item) => item.id}\r\n            renderItem={({ item }) => <Card key={item.id} course={item} />}\r\n          />\r\n        </View>\r\n      );\r\n    });\r\n  };\r\n\r\n  return (\r\n    <SafeAreaView>\r\n      <View\r\n        style={{\r\n          flexDirection: \"row\",\r\n          alignItems: \"center\",\r\n          marginTop: 20,\r\n        }}\r\n      >\r\n        <TouchableOpacity\r\n          onPress={() => navigation.goBack()}\r\n          style={commonStyles.header1Icon}\r\n        >\r\n          <Image\r\n            resizeMode=\"contain\"\r\n            source={icons.arrowLeft}\r\n            style={{ height: 24, width: 24, tintColor: COLORS.black }}\r\n          />\r\n        </TouchableOpacity>\r\n        <Text style={{ marginLeft: 12, fontSize: 17, fontFamily: \"regular\" }}>\r\n          Bookings\r\n        </Text>\r\n      </View>\r\n      <View>{displayBookings()}</View>\r\n      <View>\r\n        <Text>{categories && categories[0].title}</Text>\r\n      </View>\r\n    </SafeAreaView>\r\n  );\r\n};\r\n\r\nexport default Bookings;\r\n\r\nE:\\xampp\\htdocs\\expo_school_basic\\screens\\Complains\\CreateComplain.js\r\nimport React, { useState } from \"react\";\r\nimport {\r\n  Image,\r\n  SafeAreaView,\r\n  Text,\r\n  TouchableOpacity,\r\n  View,\r\n} from \"react-native\";\r\nimport Input from \"../../components/Input\";\r\nimport { COLORS, icons } from \"../../constants\";\r\nimport { commonStyles } from \"../../styles/CommonStyles\";\r\nimport Button from \"../../components/Button\";\r\nimport { createComplain } from \"../../api/complains\";\r\nimport { useSelector } from \"react-redux\";\r\nimport { useToast } from \"react-native-toast-notifications\";\r\n\r\nconst CreateComplain = ({ navigation }) => {\r\n  const [complain, setComplain] = useState(\"\");\r\n  const [isLoading, setIsLoading] = useState(false);\r\n  const user = useSelector((state) => state.user);\r\n  const token = user?.data.access_token;\r\n  const toast = useToast();\r\n\r\n  const handleSubmit = () => {\r\n    createComplain({ values: complain, token })\r\n      .then((res) => {\r\n        console.log({ resData: res.data });\r\n        toast.show(\"Made a complain successfully!\", {\r\n          type: \"success\",\r\n          placement: \"top\",\r\n          duration: 4000,\r\n          offset: 30,\r\n          style: { top: 50 },\r\n          animationType: \"slide-in\",\r\n        });\r\n        setComplain(\"\");\r\n      })\r\n      .catch((err) => {\r\n        console.log({ err: err?.response.data.substring(0, 100) });\r\n      });\r\n  };\r\n\r\n  return (\r\n    <SafeAreaView>\r\n      <View\r\n        style={{\r\n          flexDirection: \"row\",\r\n          alignItems: \"center\",\r\n          marginTop: 20,\r\n        }}\r\n      >\r\n        <TouchableOpacity\r\n          onPress={() => navigation.goBack()}\r\n          style={commonStyles.header1Icon}\r\n        >\r\n          <Image\r\n            resizeMode=\"contain\"\r\n            source={icons.arrowLeft}\r\n            style={{ height: 24, width: 24, tintColor: COLORS.black }}\r\n          />\r\n        </TouchableOpacity>\r\n        <Text style={{ marginLeft: 12, fontSize: 17, fontFamily: \"regular\" }}>\r\n          Create a complain\r\n        </Text>\r\n      </View>\r\n      <View\r\n        style={{\r\n          alignItems: \"center\",\r\n          padding: 15,\r\n        }}\r\n      >\r\n        <Text style={commonStyles.inputHeader}>Write your complain</Text>\r\n        <Input\r\n          id=\"complain\"\r\n          value={complain}\r\n          onChangeText={setComplain}\r\n          autoCapitalize=\"none\"\r\n          placeholder=\"Write your complain here\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"default\"\r\n          multiline={true}\r\n          numberOfLines={4}\r\n          maxLength={100}\r\n        />\r\n        <Button\r\n          title=\"Submit\"\r\n          isLoading={isLoading}\r\n          filled\r\n          onPress={handleSubmit}\r\n          style={{ ...commonStyles.btn, marginTop: 20 }}\r\n        />\r\n      </View>\r\n    </SafeAreaView>\r\n  );\r\n};\r\n\r\nexport default CreateComplain;\r\n\r\nE:\\xampp\\htdocs\\expo_school_basic\\screens\\Complains\\index.j\r\nimport React, { useEffect, useState } from \"react\";\r\nimport {\r\n  FlatList,\r\n  Image,\r\n  SafeAreaView,\r\n  Text,\r\n  TouchableOpacity,\r\n  View,\r\n} from \"react-native\";\r\nimport { getComplains } from \"../../api/complains\";\r\nimport { useSelector } from \"react-redux\";\r\nimport { COLORS, icons } from \"../../constants\";\r\nimport { commonStyles } from \"../../styles/CommonStyles\";\r\n\r\nconst Complains = ({ navigation }) => {\r\n  const [items, setItems] = useState(null);\r\n  const user = useSelector((state) => state.user);\r\n  const token = user?.data.access_token;\r\n\r\n  useEffect(() => {\r\n    getComplains({ token })\r\n      .then((res) => {\r\n        console.log({ resData: res.data });\r\n        setItems(res.data);\r\n      })\r\n      .catch((err) => {\r\n        console.log({ error: err?.response.data.substring(0, 100) });\r\n      });\r\n  }, []);\r\n\r\n  return (\r\n    <SafeAreaView>\r\n      <View\r\n        style={{\r\n          flexDirection: \"row\",\r\n          alignItems: \"center\",\r\n          marginTop: 20,\r\n        }}\r\n      >\r\n        <TouchableOpacity\r\n          onPress={() => navigation.goBack()}\r\n          style={commonStyles.header1Icon}\r\n        >\r\n          <Image\r\n            resizeMode=\"contain\"\r\n            source={icons.arrowLeft}\r\n            style={{ height: 24, width: 24, tintColor: COLORS.black }}\r\n          />\r\n        </TouchableOpacity>\r\n        <Text style={{ marginLeft: 12, fontSize: 17, fontFamily: \"regular\" }}>\r\n          My complains\r\n        </Text>\r\n      </View>\r\n      <View>\r\n        <FlatList\r\n          // style={{ marginStart: 20 }}\r\n          horizontal={false}\r\n          data={items}\r\n          keyExtractor={(item) => item.id}\r\n          renderItem={({ item }) => {\r\n            return (\r\n              <View\r\n                style={{\r\n                  borderStyle: \"solid\",\r\n                  borderWidth: 3,\r\n                  borderColor: \"gray\",\r\n                  paddingHorizontal: 20,\r\n                  paddingVertical: 10,\r\n                  marginBottom: 20,\r\n                  marginHorizontal: 10,\r\n                }}\r\n              >\r\n                <Text>{item.complain}</Text>\r\n              </View>\r\n            );\r\n          }}\r\n        />\r\n      </View>\r\n    </SafeAreaView>\r\n  );\r\n};\r\n\r\nexport default Complains;\r\n\r\nE:\\xampp\\htdocs\\expo_school_basic\\screens\\Jobs\\index.js\r\nimport { Divider, ScrollView, Text } from \"native-base\";\r\nimport React, { useEffect, useState } from \"react\";\r\nimport { Image, TouchableOpacity, View } from \"react-native\";\r\nimport { SafeAreaView } from \"react-native-safe-area-context\";\r\nimport { getJobs } from \"../../api/jobs\";\r\nimport { commonStyles } from \"../../styles/CommonStyles\";\r\nimport { COLORS, icons } from \"../../constants\";\r\n\r\nconst Jobs = ({ navigation }) => {\r\n  const [jobs, setJobs] = useState(null);\r\n\r\n  useEffect(() => {\r\n    getJobs({ locale: \"en\" }).then((res) => {\r\n      setJobs(res.data.jobOpps);\r\n    });\r\n  }, []);\r\n\r\n  const displayJobs = () => {\r\n    return jobs?.map((item) => {\r\n      return (\r\n        <View\r\n          key={item.id}\r\n          style={{\r\n            shadowColor: \"#000\",\r\n            shadowOffset: { width: 0, height: 2 },\r\n            shadowOpacity: 0.3,\r\n            shadowRadius: 2,\r\n            elevation: 3,\r\n            marginBottom: 20,\r\n            padding: 20,\r\n          }}\r\n        >\r\n          <Text style={{ fontSize: 17, marginBottom: 10, fontWeight: \"bold\" }}>\r\n            {item.title}\r\n          </Text>\r\n          <Text style={{ marginBottom: 10 }}>{item.description}</Text>\r\n          <Text style={{ marginBottom: 10, fontWeight: \"bold\" }}>\r\n            Salary: EGP {item.salary}\r\n          </Text>\r\n          <TouchableOpacity\r\n            style={{\r\n              backgroundColor: \"#673ab7\",\r\n              alignItems: \"center\",\r\n              paddingVertical: 10,\r\n              border: \"none\",\r\n              borderRadius: 5,\r\n            }}\r\n            onPress={() =>\r\n              navigation.navigate(\"JobApply\", {\r\n                jobId: item.id,\r\n                jobTitle: item.title,\r\n              })\r\n            }\r\n          >\r\n            <Text\r\n              style={{\r\n                fontSize: 15,\r\n                textTransform: \"uppercase\",\r\n                color: \"#fff\",\r\n              }}\r\n            >\r\n              apply\r\n            </Text>\r\n          </TouchableOpacity>\r\n        </View>\r\n      );\r\n    });\r\n  };\r\n\r\n  return (\r\n    <SafeAreaView>\r\n      <View\r\n        style={{\r\n          flexDirection: \"row\",\r\n          alignItems: \"center\",\r\n          marginTop: 20,\r\n        }}\r\n      >\r\n        <TouchableOpacity\r\n          onPress={() => navigation.goBack()}\r\n          style={commonStyles.header1Icon}\r\n        >\r\n          <Image\r\n            resizeMode=\"contain\"\r\n            source={icons.arrowLeft}\r\n            style={{ height: 24, width: 24, tintColor: COLORS.black }}\r\n          />\r\n        </TouchableOpacity>\r\n        <Text style={{ marginLeft: 12, fontSize: 17, fontFamily: \"regular\" }}>\r\n          Jobs\r\n        </Text>\r\n      </View>\r\n\r\n      <ScrollView style={{ marginBottom: 100 }}>{displayJobs()}</ScrollView>\r\n    </SafeAreaView>\r\n  );\r\n};\r\n\r\nexport default Jobs;\r\n\r\nE:\\xampp\\htdocs\\expo_school_basic\\screens\\Jobs\\JobApply.js\r\nimport { Divider, ScrollView, Text } from \"native-base\";\r\nimport React, { useEffect, useState } from \"react\";\r\nimport { Image, StyleSheet, TouchableOpacity, View } from \"react-native\";\r\nimport { SafeAreaView } from \"react-native-safe-area-context\";\r\nimport { applyJob, getJobs } from \"../../api/jobs\";\r\nimport { commonStyles } from \"../../styles/CommonStyles\";\r\nimport { COLORS, icons } from \"../../constants\";\r\nimport Input from \"../../components/Input\";\r\nimport Button from \"../../components/Button\";\r\nimport { useToast } from \"react-native-toast-notifications\";\r\nimport DateTimePickerModal from \"react-native-modal-datetime-picker\";\r\nimport SelectDropdown from \"react-native-select-dropdown\";\r\nimport { Radio } from \"native-base\";\r\nimport * as DocumentPicker from \"expo-document-picker\";\r\n\r\nconst JobApply = ({ route, navigation }) => {\r\n  const { jobId, jobTitle } = route.params;\r\n  const toast = useToast();\r\n  const [isDatePickerVisible, setDatePickerVisibility] = useState(false);\r\n  const [email, setEmail] = useState(\"\");\r\n  const [name, setName] = useState(\"\");\r\n  const [phone, setPhone] = useState(\"\");\r\n  const [address, setAddress] = useState(\"\");\r\n  const [appliedFor, setAppliedFor] = useState(\"\");\r\n  const [dateOfBirth, setDateOfBirth] = useState(new Date(Date.now()));\r\n  const [nationality, setNationality] = useState(\"\");\r\n  const [idNumber, setIdNumber] = useState(\"\");\r\n  const [maritalStatus, setMaritalStatus] = useState(\"Single\");\r\n  const [gender, setGender] = useState(\"male\");\r\n  const [word, setWord] = useState(\"\");\r\n  const [excel, setExcel] = useState(\"\");\r\n  const [powerpoint, setPowerpoint] = useState(\"\");\r\n  const [explainMainTasks, setExplainMainTasks] = useState(\"\");\r\n  const [factorsPrompted, setFactorsPrompted] = useState(\"\");\r\n  const [period, setPeriod] = useState(\"\");\r\n  const [wordValue, setWordValue] = useState(\"poor\");\r\n  const [excelValue, setExcelValue] = useState(\"poor\");\r\n  const [powerpointValue, setPowerpointValue] = useState(\"poor\");\r\n  const [isLoading, setIsLoading] = useState(false);\r\n  const [success, setSuccess] = useState(false);\r\n  const [qualifications, setQualifications] = useState(\"\");\r\n  const [trainingCourses, setTrainingCourses] = useState(\"\");\r\n  const [langauges, setLangauges] = useState(\"\");\r\n  const [references, setReferences] = useState(\"\");\r\n  const [practicalExperiences, setPracticalExperiences] = useState(\"\");\r\n  const [file, setFile] = useState(null);\r\n\r\n  console.log({ file });\r\n\r\n  const handlePickDocument = async () => {\r\n    let result = await DocumentPicker.getDocumentAsync({\r\n      type: \"application/pdf\",\r\n    });\r\n    console.log({ result: result.assets });\r\n    if (result.canceled) {\r\n      console.log(\"cancelled\");\r\n    } else {\r\n      setFile(result.assets[0]);\r\n    }\r\n  };\r\n  const maritalStatuses = [\"single\", \"married\", \"divorced\", \"widowed\"];\r\n  const genders = [\"male\", \"female\"];\r\n\r\n  const handleConfirm = (date) => {\r\n    hideDatePicker();\r\n    setDateOfBirth(date);\r\n  };\r\n\r\n  const hideDatePicker = () => {\r\n    setDatePickerVisibility(false);\r\n  };\r\n\r\n  const onChange = (event, newDate) => {\r\n    setDateOfBirth(newDate);\r\n  };\r\n\r\n  const handleSubmit = () => {\r\n    setIsLoading(true);\r\n    const values = {\r\n      email,\r\n      name,\r\n      phone,\r\n      address,\r\n      jobOpp_id: jobId,\r\n      file,\r\n    };\r\n    applyJob({ values })\r\n      .then((res) => {\r\n        console.log({ res: res.data });\r\n        setIsLoading(false);\r\n        setSuccess(true);\r\n        toast.show(\"Applied successfully!\", {\r\n          type: \"success\",\r\n          placement: \"top\",\r\n          duration: 4000,\r\n          offset: 30,\r\n          style: { top: 50 },\r\n          animationType: \"slide-in\",\r\n        });\r\n        handleReset();\r\n      })\r\n      .catch((err) => {\r\n        console.log({ err: err.response.data.substring(0, 500) });\r\n        setIsLoading(false);\r\n      });\r\n  };\r\n\r\n  const handleReset = () => {\r\n    setEmail(\"\");\r\n    setName(\"\");\r\n    setPhone(\"\");\r\n    setAddress(\"\");\r\n  };\r\n\r\n  return (\r\n    <SafeAreaView style={{ flex: 1 }}>\r\n      <View\r\n        style={{\r\n          flexDirection: \"row\",\r\n          alignItems: \"center\",\r\n          marginTop: 20,\r\n        }}\r\n      >\r\n        <TouchableOpacity\r\n          onPress={() => navigation.goBack()}\r\n          style={commonStyles.header1Icon}\r\n        >\r\n          <Image\r\n            resizeMode=\"contain\"\r\n            source={icons.arrowLeft}\r\n            style={{ height: 24, width: 24, tintColor: COLORS.black }}\r\n          />\r\n        </TouchableOpacity>\r\n        <Text style={{ marginLeft: 12, fontSize: 17, fontFamily: \"regular\" }}>\r\n          Apply to {jobTitle}\r\n        </Text>\r\n      </View>\r\n      <ScrollView style={{ paddingHorizontal: 20 }}>\r\n        <Text style={commonStyles.inputHeader}>Email</Text>\r\n        <Input\r\n          id=\"email\"\r\n          value={email}\r\n          onChangeText={setEmail}\r\n          autoCapitalize=\"none\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"email-address\"\r\n          placeholder={\"Your email\"}\r\n        />\r\n        <Text style={commonStyles.inputHeader}>Full Name</Text>\r\n        <Input\r\n          id=\"name\"\r\n          value={name}\r\n          onChangeText={setName}\r\n          autoCapitalize=\"none\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"default\"\r\n          placeholder={\"Your full name\"}\r\n        />\r\n        <Text style={commonStyles.inputHeader}>Phone</Text>\r\n        <Input\r\n          id=\"phone\"\r\n          value={phone}\r\n          onChangeText={setPhone}\r\n          autoCapitalize=\"none\"\r\n          placeholder=\"ex: +123456789\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"default\"\r\n        />\r\n        <Text style={commonStyles.inputHeader}>Address</Text>\r\n        <Input\r\n          id=\"address\"\r\n          value={address}\r\n          onChangeText={setAddress}\r\n          autoCapitalize=\"none\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"default\"\r\n          placeholder={\"Your address\"}\r\n        />\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          Date of birth\r\n        </Text>\r\n        <Button\r\n          title={dateOfBirth.toLocaleString(\"en-GB\", {\r\n            year: \"numeric\",\r\n            month: \"2-digit\",\r\n            day: \"2-digit\",\r\n          })}\r\n          isLoading={isLoading}\r\n          onPress={() => setDatePickerVisibility(true)}\r\n          style={{ ...commonStyles.btn, marginTop: 20 }}\r\n        />\r\n        <DateTimePickerModal\r\n          testID=\"dateTimePicker\"\r\n          isVisible={isDatePickerVisible}\r\n          mode=\"date\"\r\n          onConfirm={handleConfirm}\r\n          onCancel={hideDatePicker}\r\n          value={dateOfBirth}\r\n          is24Hour={false}\r\n          display=\"default\"\r\n          onChange={onChange}\r\n        />\r\n\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          Your marital status\r\n        </Text>\r\n        <SelectDropdown\r\n          data={maritalStatuses}\r\n          onSelect={(selectedItem, index) => {\r\n            console.log({ selectedItem });\r\n            const marital = maritalStatuses.find(\r\n              (item) => item === selectedItem\r\n            );\r\n            setMaritalStatus(marital);\r\n          }}\r\n          renderButton={(selectedItem, isOpened) => {\r\n            return (\r\n              <View style={styles.dropdownButtonStyle}>\r\n                <Text style={styles.dropdownButtonTxtStyle}>\r\n                  {maritalStatus}\r\n                </Text>\r\n              </View>\r\n            );\r\n          }}\r\n          renderItem={(item, index, isSelected) => {\r\n            return (\r\n              <View\r\n                style={{\r\n                  ...styles.dropdownItemStyle,\r\n                  ...(isSelected && { backgroundColor: \"#D2D9DF\" }),\r\n                }}\r\n              >\r\n                <Text style={styles.dropdownItemTxtStyle}>{item}</Text>\r\n              </View>\r\n            );\r\n          }}\r\n          showsVerticalScrollIndicator={false}\r\n          dropdownStyle={styles.dropdownMenuStyle}\r\n        />\r\n\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          Your Gender\r\n        </Text>\r\n        <SelectDropdown\r\n          data={genders}\r\n          onSelect={(selectedItem, index) => {\r\n            console.log({ selectedItem });\r\n            const marital = genders.find((item) => item === selectedItem);\r\n            setGender(marital);\r\n          }}\r\n          renderButton={(selectedItem, isOpened) => {\r\n            return (\r\n              <View style={styles.dropdownButtonStyle}>\r\n                <Text style={styles.dropdownButtonTxtStyle}>{gender}</Text>\r\n              </View>\r\n            );\r\n          }}\r\n          renderItem={(item, index, isSelected) => {\r\n            return (\r\n              <View\r\n                style={{\r\n                  ...styles.dropdownItemStyle,\r\n                  ...(isSelected && { backgroundColor: \"#D2D9DF\" }),\r\n                }}\r\n              >\r\n                <Text style={styles.dropdownItemTxtStyle}>{item}</Text>\r\n              </View>\r\n            );\r\n          }}\r\n          showsVerticalScrollIndicator={false}\r\n          dropdownStyle={styles.dropdownMenuStyle}\r\n        />\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          How good are you in Microsoft Word?\r\n        </Text>\r\n        <Radio.Group\r\n          name=\"myRadioGroup\"\r\n          value={wordValue}\r\n          onChange={(nextValue) => {\r\n            setWordValue(nextValue);\r\n          }}\r\n        >\r\n          <Radio value=\"poor\" my=\"1\">\r\n            Poor\r\n          </Radio>\r\n          <Radio value=\"good\" my=\"1\">\r\n            Good\r\n          </Radio>\r\n          <Radio value=\"excellent\" my=\"1\">\r\n            Excellent\r\n          </Radio>\r\n        </Radio.Group>\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          How good are you in Microsoft Excel?\r\n        </Text>\r\n        <Radio.Group\r\n          name=\"myRadioGroup\"\r\n          value={excelValue}\r\n          onChange={(nextValue) => {\r\n            setExcelValue(nextValue);\r\n          }}\r\n        >\r\n          <Radio value=\"poor\" my=\"1\">\r\n            Poor\r\n          </Radio>\r\n          <Radio value=\"good\" my=\"1\">\r\n            Good\r\n          </Radio>\r\n          <Radio value=\"excellent\" my=\"1\">\r\n            Excellent\r\n          </Radio>\r\n        </Radio.Group>\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          How good are you in Microsoft Powerpoint?\r\n        </Text>\r\n        <Radio.Group\r\n          name=\"myRadioGroup\"\r\n          value={powerpointValue}\r\n          onChange={(nextValue) => {\r\n            setPowerpointValue(nextValue);\r\n          }}\r\n        >\r\n          <Radio value=\"poor\" my=\"1\">\r\n            Poor\r\n          </Radio>\r\n          <Radio value=\"good\" my=\"1\">\r\n            Good\r\n          </Radio>\r\n          <Radio value=\"excellent\" my=\"1\">\r\n            Excellent\r\n          </Radio>\r\n        </Radio.Group>\r\n\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          Describe your responsbilities in last job\r\n        </Text>\r\n        <Input\r\n          id=\"reason\"\r\n          value={explainMainTasks}\r\n          onChangeText={setExplainMainTasks}\r\n          autoCapitalize=\"none\"\r\n          placeholder=\"Write your description\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"default\"\r\n          multiline={true}\r\n          numberOfLines={4}\r\n        />\r\n\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          The factors prompted you to apply for this job\r\n        </Text>\r\n        <Input\r\n          id=\"reason\"\r\n          value={explainMainTasks}\r\n          onChangeText={setExplainMainTasks}\r\n          autoCapitalize=\"none\"\r\n          placeholder=\"Write your factors here\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"default\"\r\n          multiline={true}\r\n          numberOfLines={4}\r\n        />\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          Available day or night?\r\n        </Text>\r\n        <Radio.Group\r\n          name=\"myRadioGroup\"\r\n          value={period}\r\n          onChange={(nextValue) => {\r\n            setPeriod(nextValue);\r\n          }}\r\n        >\r\n          <Radio value=\"1\" my=\"1\">\r\n            Day\r\n          </Radio>\r\n          <Radio value=\"0\" my=\"1\">\r\n            Night\r\n          </Radio>\r\n        </Radio.Group>\r\n\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          qualifications\r\n        </Text>\r\n        <Input\r\n          id=\"qualifications\"\r\n          value={qualifications}\r\n          onChangeText={setQualifications}\r\n          autoCapitalize=\"none\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"default\"\r\n          placeholder=\"Your qualifications:ex. Engineering, specialization: ex. computer science, university: ex. AAST, graduation date: 2024-06-29, gpa: ex. 3.5\"\r\n          multiline={true}\r\n          numberOfLines={4}\r\n        />\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          languages\r\n        </Text>\r\n        <Input\r\n          id=\"langauges\"\r\n          value={langauges}\r\n          onChangeText={setLangauges}\r\n          autoCapitalize=\"none\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"default\"\r\n          placeholder=\"Example, English: reading (advanced), writing (intermediate), listening (weak), conversation (intermediate), Arabic: ...\"\r\n          multiline={true}\r\n          numberOfLines={4}\r\n        />\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          training courses\r\n        </Text>\r\n        <Input\r\n          id=\"trainingCourses\"\r\n          value={trainingCourses}\r\n          onChangeText={setTrainingCourses}\r\n          autoCapitalize=\"none\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"default\"\r\n          placeholder=\"Example, Teacher, certification title, certification date, entity\"\r\n          multiline={true}\r\n          numberOfLines={4}\r\n        />\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          practical experience\r\n        </Text>\r\n        <Input\r\n          id=\"practicalExperiences\"\r\n          value={practicalExperiences}\r\n          onChangeText={setPracticalExperiences}\r\n          autoCapitalize=\"none\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"default\"\r\n          placeholder=\"Example, entity, employment type, work time, reason of resignation\"\r\n          multiline={true}\r\n          numberOfLines={4}\r\n        />\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          references\r\n        </Text>\r\n        <Input\r\n          id=\"references\"\r\n          value={references}\r\n          onChangeText={setReferences}\r\n          autoCapitalize=\"none\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"default\"\r\n          placeholder=\"Example, the company name, manager name, your work type, manager number\"\r\n          multiline={true}\r\n          numberOfLines={4}\r\n        />\r\n\r\n        <View style={{ marginTop: 20 }}>\r\n          <TouchableOpacity onPress={handlePickDocument}>\r\n            <Text style={commonStyles.inputHeader}>Upload CV</Text>\r\n          </TouchableOpacity>\r\n          {file ? <Text>{file.name}</Text> : null}\r\n        </View>\r\n\r\n        <Button\r\n          title=\"SUBMIT\"\r\n          isLoading={isLoading}\r\n          filled\r\n          onPress={handleSubmit}\r\n          style={{ ...commonStyles.btn, marginTop: 50 }}\r\n        />\r\n      </ScrollView>\r\n    </SafeAreaView>\r\n  );\r\n};\r\n\r\nconst styles = StyleSheet.create({\r\n  dropdownButtonStyle: {\r\n    width: \"100%\",\r\n    height: 50,\r\n    backgroundColor: \"#E9ECEF\",\r\n    borderRadius: 12,\r\n    flexDirection: \"row\",\r\n    justifyContent: \"center\",\r\n    alignItems: \"center\",\r\n    paddingHorizontal: 12,\r\n    marginTop: 20,\r\n  },\r\n  dropdownButtonTxtStyle: {\r\n    flex: 1,\r\n    fontSize: 18,\r\n    fontWeight: \"500\",\r\n    color: \"#151E26\",\r\n    textTransform: \"capitalize\",\r\n  },\r\n  dropdownButtonArrowStyle: {\r\n    fontSize: 28,\r\n  },\r\n  dropdownButtonIconStyle: {\r\n    fontSize: 28,\r\n    marginRight: 8,\r\n  },\r\n  dropdownMenuStyle: {\r\n    backgroundColor: \"#E9ECEF\",\r\n    borderRadius: 8,\r\n  },\r\n  dropdownItemStyle: {\r\n    width: \"100%\",\r\n    flexDirection: \"row\",\r\n    paddingHorizontal: 12,\r\n    justifyContent: \"center\",\r\n    alignItems: \"center\",\r\n    paddingVertical: 8,\r\n  },\r\n  dropdownItemTxtStyle: {\r\n    flex: 1,\r\n    fontSize: 