s\'\r\nimport { getPost } from \'../../api/posts\'\r\nimport Loader from \'../../components/Loader\'\r\n\r\nconst PostDetails = ({ route, navigation }) => {\r\n    const { postId } = route.params;\r\n    const [post, setPost] = useState(null);\r\n    const [loading, setLoading] = useState(true);\r\n\r\n    useEffect(() => {\r\n        getPost({ locale: \'en\', postId }).then(res => {\r\n            setPost(res.data.post);\r\n            setLoading(false);\r\n        });\r\n    }, []);\r\n\r\n    if (loading) {\r\n        return <Loader />\r\n    }\r\n\r\n    return (\r\n        <View>\r\n            <ScrollView>\r\n                <View>\r\n                    <View style={styles.imageCountainer}>\r\n                        <Image style={styles.image} source={{ uri: post?.image }} alt={post?.title} />\r\n                    </View>\r\n                    <TouchableOpacity\r\n                        onPress={() => navigation.goBack()}\r\n                        style={{ ...commonStyles.header1Icon, position: \'absolute\', top: 34, left: 14, backgroundColor: \'#9f7aea\' }}\r\n                    >\r\n                        <Image\r\n                            resizeMode=\"contain\"\r\n                            source={icons.arrowLeft}\r\n                            style={{ height: 24, width: 24, tintColor: COLORS.white }}\r\n                        />\r\n                    </TouchableOpacity>\r\n                </View>\r\n                <View style={styles.detailsContainer}>\r\n                    <Heading fontSize=\"xl\" p=\"4\" pb=\"3\">\r\n                        {post?.title}\r\n                    </Heading>\r\n                    <View style={{ marginStart: 15 }}>\r\n                        <Text>{post?.description}</Text>\r\n                    </View>\r\n                </View>\r\n            </ScrollView>\r\n        </View>\r\n    )\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n    imageCountainer: {\r\n        position: \'relative\'\r\n    },\r\n 