 (loading) {\r\n    return <Loader />;\r\n  }\r\n\r\n  const handleSubmit = () => {};\r\n\r\n  return (\r\n    <View>\r\n      <ScrollView>\r\n        <View>\r\n          <View style={styles.imageCountainer}>\r\n            <Image\r\n              style={styles.image}\r\n              source={{ uri: course?.image }}\r\n              alt={course?.title}\r\n            />\r\n          </View>\r\n          <TouchableOpacity\r\n            onPress={() => navigation.goBack()}\r\n            style={{\r\n              ...commonStyles.header1Icon,\r\n              position: \"absolute\",\r\n              top: 34,\r\n              left: 14,\r\n              backgroundColor: \"#9f7aea\",\r\n            }}\r\n          >\r\n            <Image\r\n              resizeMode=\"contain\"\r\n              source={icons.arrowLeft}\r\n              style={{ height: 24, width: 24, tintColor: COLORS.white }}\r\n            />\r\n          </TouchableOpacity>\r\n        </View>\r\n        <View style={styles.detailsContainer}>\r\n          <Heading fontSize=\"xl\" p=\"4\" pb=\"3\">\r\n            {course?.title}\r\n          </Heading>\r\n          <View style={styles.categoryContainer}>\r\n            <View style={styles.categoryWrapper}>\r\n              <Text style={{ color: \"#fff\" }}>\r\n                Category: {course?.category}\r\n              </Text>\r\n              <Text style={{ color: \"#fff\" }}>${course?.course_price}</Text>\r\n            </View>\r\n          </View>\r\n          <View>\r\n            <View style={styles.titleWrapper}>\r\n              <Heading fontSize=\"md\" p=\"4\" pb=\"3\">\r\n                {course?.program?.title}\r\n              </Heading>\r\n            </View>\r\n            {course?.program?.levels.map((item) => {\r\n              return (\r\n                <View style={{ paddingStart: 15 }}>\r\n                  <Text>{item.title}</Text>\r\n                </View>\r\n              );\r\n            })}\r\n          </View>\r\n\r\n          {course?.courseAppointments.map((item) => {\r\n            return (\r\n              <View style={{ paddingStart: 15, marginTop: 15 }}>\r\n                <Heading fontSize={\"lg\"} style={{ marginBottom: 5 }}>\r\n                  Start date: {item?.start_date}\r\n                </Heading>\r\n                <Heading fontSize={\"lg\"}>End date: {item?.end_date}</Heading>\r\n                <Heading fontSize={\"lg\"}>Code: {item?.course_code}</Heading>\r\n              </View>\r\n            );\r\n          })}\r\n          <Button\r\n            title=\"Book\"\r\n            isLoading={clicked}\r\n            filled\r\n            onPress={() =>\r\n              user.isLoggedIn\r\n                ? navigation.navigate(\"CreateBooking\", {\r\n                    courseId,\r\n                  })\r\n                : navigation.navigate(\"Login\")\r\n            }\r\n            style={{\r\n              ...commonStyles.btn,\r\n              marginTop: 20,\r\n              backgroundColor: \"#9f7aea\",\r\n              borderColor: \"#9f7aea\",\r\n            }}\r\n          />\r\n        </View>\r\n      </ScrollView>\r\n    </View>\r\n  );\r\n};\r\n\r\nconst styles = StyleSheet.create({\r\n  imageCountainer: {\r\n    position: \"relative\",\r\n  },\r\n  image: {\r\n    width: \"100%\",\r\n    height: 270,\r\n  },\r\n  detailsContainer: {\r\n    borderTopLeftRadius: 40,\r\n    borderTopRightRadius: 40,\r\n    marginTop: -12,\r\n    paddingTop: 6,\r\n    paddingHorizontal: 15,\r\n    backgroundColor: \"#fff\",\r\n    minHeight: 610,\r\n  },\r\n  categoryContainer: {\r\n    width: \"100%\",\r\n  },\r\n  categoryWrapper: {\r\n    backgroundColor: \"#9f7aea\",\r\n    width: \"100%\",\r\n    height: 50,\r\n    display: \"flex\",\r\n    flexDirection: \"row\",\r\n    alignItems: \"center\",\r\n    justifyContent: \"space-between\",\r\n    paddingHorizontal: 15,\r\n    borderRadius: 50,\r\n  },\r\n});\r\n\r\nexport default CourseDetails;\r\n\r\nE:\\xampp\\htdocs\\expo_school_basic\\screens\\Login.js\r\nimport {\r\n  View,\r\n  Text,\r\n  TouchableOpacity,\r\n  Image,\r\n  ImageBackground,\r\n  StyleSheet,\r\n  TextInput,\r\n} from \"react-native\";\r\nimport React, { useState, useEffect } from \"react\";\r\nimport Checkbox from \"expo-checkbox\";\r\nimport * as Animatable from \"react-native-animatable\";\r\nimport Button from \"../components/Button\";\r\nimport { StatusBar } from \"expo-status-bar\";\r\nimport { useDispatch, useSelector } from \"react-redux\";\r\nimport { login } from \"../api/loginApi\";\r\nimport { COLORS, FONTS, images, icons } from \"../constants\";\r\nimport { commonStyles } from \"../styles/CommonStyles\";\r\nimport { setLogin } from \"../store/user\";\r\nimport Input from \"../components/Input\";\r\nimport { useNavigation, useRoute } from \"@react-navigation/native\";\r\nimport { useToast } from \"react-native-toast-notifications\";\r\nimport { Alert } from \"react-native\";\r\n\r\nconst Login = () => {\r\n  const route = useRoute();\r\n  const navigation = useNavigation();\r\n  const toast = useToast();\r\n  const message = route?.params?.message && route?.params?.message;\r\n  const [isChecked, setChecked] = useState(false);\r\n  const [error, setError] = useState(null);\r\n  const [isLoading, setIsLoading] = useState(false);\r\n  const dispatch = useDispatch();\r\n  const [email, setEmail] = useState(\"admin@gmail.com\");\r\n  const [password, setPassword] = useState(\"123456789\");\r\n\r\n  const handleSubmit = () => {\r\n    setIsLoading(true);\r\n    const values = { email, password, type: \"student\" };\r\n    login({ values })\r\n      .then((res) => {\r\n        console.log({ token: res.data });\r\n        dispatch(setLogin(res.data));\r\n        navigation.navigate(\"PersonalProfile\");\r\n      })\r\n      .catch((err) => {\r\n        console.log({ err: err.response.data });\r\n        const errors = err?.response.data;\r\n        const objKeys = Object.keys(errors);\r\n        const errorMessage = errors[objKeys[0]];\r\n        setError(errorMessage);\r\n        setIsLoading(false);\r\n      });\r\n  };\r\n\r\n  useEffect(() => {\r\n    if (message?.length) {\r\n      toast.show(message, {\r\n        type: \"success\",\r\n        placement: \"top\",\r\n        duration: 4000,\r\n        offset: 30,\r\n        style: { top: 50 },\r\n        animationType: \"slide-in\",\r\n      });\r\n    }\r\n    if (error) {\r\n      Alert.alert(\"An error occured\", error);\r\n    }\r\n    let timeout = setTimeout(() => {\r\n      setIsLoading(false);\r\n    }, 3000);\r\n    return () => clearTimeout(timeout);\r\n  }, [error]);\r\n\r\n  // implementing facebook authentication\r\n  const facebookAuthHandler = () => {\r\n    return null;\r\n  };\r\n\r\n  // implementing twitter authentication\r\n  const twitterAuthHandler = () => {\r\n    return null;\r\n  };\r\n\r\n  // implementing apple authentication\r\n  const appleAuthHandler = () => {\r\n    return null;\r\n  };\r\n\r\n  return (\r\n    <ImageBackground\r\n      source={images.background1}\r\n      style={{ flex: 1, backgroundColor: COLORS.blue }}\r\n    >\r\n      <StatusBar style=\"light\" />\r\n      <View style={commonStyles.header}>\r\n        <Text style={commonStyles.headerTitle}>Log In</Text>\r\n        <Text style={commonStyles.subHeaderTitle}>\r\n          Please sign in to your existing account\r\n        </Text>\r\n      </View>\r\n      <Animatable.View animation=\"fadeInUpBig\" style={commonStyles.footer}>\r\n        <Text style={commonStyles.inputHeader}>Email</Text>\r\n        <Input\r\n          id=\"email\"\r\n          value={email}\r\n          onChangeText={setEmail}\r\n          autoCapitalize=\"none\"\r\n          placeholder=\"example@gmail.com\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"email-address\"\r\n        />\r\n        <Text style={commonStyles.inputHeader}>Password</Text>\r\n        <Input\r\n          id=\"password\"\r\n          value={password}\r\n          onChangeText={setPassword}\r\n          autoCapitalize=\"none\"\r\n          placeholder=\"*************\"\r\n          placeholderTextColor={COLORS.black}\r\n          secureTextEntry={true}\r\n        />\r\n\r\n        <View style={commonStyles.checkBoxContainer}>\r\n          <View style={{ flexDirection: \"row\", alignItems: \"center\" }}>\r\n            <Checkbox\r\n              style={commonStyles.checkbox}\r\n              value={isChecked}\r\n              color={isChecked ? COLORS.primary : COLORS.black}\r\n              onValueChange={setChecked}\r\n            />\r\n            <Text style={{ ...FONTS.body4 }}>Remenber me</Text>\r\n          </View>\r\n          <TouchableOpacity\r\n            onPress={() => navigation.navigate(\"ForgotPassword\")}\r\n          >\r\n            <Text style={{ ...FONTS.body4, color: COLORS.primary }}>\r\n              Forgot Password ?\r\n            </Text>\r\n          </TouchableOpacity>\r\n        </View>\r\n\r\n        <Button\r\n          title=\"LOG IN\"\r\n          isLoading={isLoading}\r\n          filled\r\n          onPress={handleSubmit}\r\n          style={commonStyles.btn}\r\n        />\r\n        <View style={commonStyles.center}>\r\n          <Text style={{ ...FONTS.body4, color: COLORS.black }}>\r\n            Don\'t have an account?{\" \"}\r\n          </Text>\r\n          <TouchableOpacity onPress={() => navigation.navigate(\"Signup\")}>\r\n            <Text style={{ ...FONTS.body4, color: COLORS.primary }}>\r\n              SIGN UP\r\n            </Text>\r\n          </TouchableOpacity>\r\n        </View>\r\n        {/* <Text style={{ ...FONTS.body4, color: COLORS.black, textAlign: \'center\' }}>Or</Text>\r\n\r\n        <View style={commonStyles.socialContainer}>\r\n          <TouchableOpacity\r\n            onPress={facebookAuthHandler}\r\n            style={commonStyles.socialIconContainer}\r\n          >\r\n            <Image\r\n              source={icons.facebook}\r\n              r