ries] = useState(null);\r\n  const user = useSelector((state) => state.user);\r\n\r\n  useEffect(() => {\r\n    fetchCategories();\r\n  }, []);\r\n\r\n  const onRefresh = useCallback(() => {\r\n    setRefreshing(true);\r\n    fetchCategories();\r\n    setRefreshing(false);\r\n  }, []);\r\n\r\n  const fetchCategories = () => {\r\n    getCategories({ locale: \"en\" })\r\n      .then((res) => {\r\n        setCategories(res.data.categories);\r\n        setLoading(false);\r\n      })\r\n      .catch((err) => {\r\n        console.log({ err });\r\n      });\r\n  };\r\n\r\n  if (loading) {\r\n    return <Loader />;\r\n  }\r\n\r\n  return (\r\n    <SafeAreaView style={{ overflow: \"auto\" }}>\r\n      <View style={styles.header}>\r\n        <Heading fontSize=\"xl\" p=\"1\" my=\"3\" pt={5}>\r\n          All courses\r\n        </Heading>\r\n      </View>\r\n\r\n      <ScrollView\r\n        refreshControl={\r\n          <RefreshControl refreshing={refreshing} onRefresh={onRefresh} />\r\n        }\r\n        style={{ display: \"flex\", flexDirection: \"column\", marginBottom: 140 }}\r\n      >\r\n        <Header />\r\n        <Slider categories={categories} />\r\n        <Courses categories={categories} />\r\n        <Posts />\r\n      </ScrollView>\r\n    </SafeAreaView>\r\n  );\r\n};\r\n\r\nconst styles = StyleSheet.create({\r\n  header: {\r\n    paddingStart: 30,\r\n  },\r\n  text: {\r\n    fontSize: 26,\r\n    marginBottom: 10,\r\n  },\r\n});\r\n\r\nexport default Home;\r\n\r\nE:\\xampp\\htdocs\\expo_school_basic\\screens\\Messages.js\r\nimport {\r\n  View,\r\n  Text,\r\n  TouchableOpacity,\r\n  Image,\r\n  useWindowDimensions,\r\n  FlatList,\r\n} from \"react-native\";\r\nimport React, { useEffect, useState } from \"react\";\r\nimport { SafeAreaProvider } from \"react-native-safe-area-context\";\r\nimport { COLORS, icons } from \"../constants\";\r\nimport { commonStyles } from \"../styles/CommonStyles\";\r\nimport { TabView, SceneMap, TabBar } from \"react-native-tab-view\"