\n\r\n\r\ncode app\\Http\\Controllers\\API\\ActionController.php\r\n\r\n\r\n\r\n<?php\r\n\r\n\r\nnamespace App\\Http\\Controllers\\API;\r\n\r\n\r\nuse App\\Http\\Controllers\\Controller;\r\n\r\nuse App\\Http\\Requests\\API\\MessageRequest;\r\n\r\nuse App\\Models\\Message;\r\n\r\nuse App\\Models\\Task;\r\n\r\nuse Exception;\r\n\r\nuse Illuminate\\Http\\Request;\r\n\r\n\r\nuse Illuminate\\Support\\Facades\\DB;\r\n\r\n\r\nclass ActionController extends Controller\r\n\r\n{\r\n\r\n    public function postFunction(Request $request)\r\n\r\n    {\r\n\r\n\r\n        try {\r\n\r\n            $action = request()->query(\'action\');\r\n\r\n            if($action==\"contactus\"){\r\n\r\n                $request->validate([\r\n\r\n                \'message\' => \'required\',\r\n\r\n                ]);\r\n\r\n                  $data = Message::create($request->except(\'action\'));\r\n\r\n            }\r\n\r\n            return successResponse($data);\r\n\r\n        } catch (Exception $e) {\r\n\r\n            DB::table(\'tracks\')->insert([ \'dispatch_status\' => \'showing data of \' . json_encode([$e->getMessage()]), \'created_at\' => now(), ]);\r\n\r\n            return failedResponse($e->getMessage());\r\n\r\n        }\r\n\r\n    }\r\n\r\n\r\n    public function getFunction(Request $request)\r\n\r\n    {\r\n\r\n\r\n        try {\r\n\r\n            $action = request()->query(\'action\');\r\n\r\n            if($action==\"getTasks\")\r\n\r\n            $data = Task::get();\r\n\r\n            return successResponse($data);\r\n\r\n        } catch (Exception $e) {\r\n\r\n            DB::table(\'tracks\')->insert([ \'dispatch_status\' => \'showing data of \' . json_encode([$e->getMessage()]), \'created_at\' => now(), ]);\r\n\r\n            return failedResponse($e->getMessage());\r\n\r\n        }\r\n\r\n    }\r\n\r\n}\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\nReact or ReactNative Frontend Part\r\n\r\n\r\n\r\n\r\nimport axios from \"axios\"\r\n\r\n\r\n\r\n\r\nimport AsyncStorage from \'@react-native-async-storage/async-storage\';\r\n\r\n\r\n\r\n\r\nPost part\r\n\r\n\r\n\r\n\r\nconst formData = new FormData();\r\n\r\n\r\n\r\n\r\nformData.append(\'name\', \'John Doe\');\r\n\r\n\r\n\r\n\r\nformData.append(\'file\', selectedFile); // if you have a file\r\n\r\n\r\n\r\n\r\naxios.post(\r\n\r\n\r\n\r\n\r\n  \'https://yourdomain.com/public/api/postFunction?action=contactus\',\r\n\r\n\r\n\r\n\r\n  formData, // send FormData directly\r\n\r\n\r\n\r\n\r\n  {\r\n\r\n\r\n\r\n\r\n    headers: {\r\n\r\n\r\n\r\n      Authorization: `Bearer ${localStorage.getItem(\"token\")}` // if using ReactNative AsyncStorage.getItem(\'token\')\r\n\r\n\r\n\r\n\r\n      \'Content-Type\': \'multipart/form-data\', // important for files\r\n\r\n\r\n\r\n\r\n    },\r\n\r\n\r\n\r\n\r\n  }\r\n\r\n\r\n\r\n\r\n)\r\n\r\n\r\n\r\n.then((res) => {\r\n\r\n\r\n\r\n\r\n  console.log(\'Success\', res.data);\r\n\r\n\r\n\r\n})\r\n\r\n\r\n\r\n.catch((err) => {\r\n\r\n\r\n\r\n\r\n    alert(\'Failed to send post Function\');\r\n\r\n\r\n\r\n    axios.post(\'https://yousab-tech.com/workspace/public/api/track\', { data: err, label: \"postFunction\", time: new Date().toISOString(), }).catch((err) => { alert(\'Failed to send debug log\'); });\r\n\r\n\r\n\r\n  console.error(err);\r\n\r\n\r\n\r\n});\r\n\r\n\r\n\r\n\r\nGet Part\r\n\r\n\r\n\r\n\r\naxios.get(\'https://yourdomain.com/public/api/getFunction\', {\r\n\r\n\r\n\r\n  params: {\r\n\r\n\r\n\r\n    action: \'getTasks\',\r\n\r\n\r\n\r\n\r\n    id: 5,\r\n\r\n\r\n\r\n  },\r\n\r\n\r\n\r\n  headers: {\r\n\r\n\r\n\r\n    Authorization: `Bearer ${localStorage.getItem(\"token\")}`,\r\n\r\n\r\n\r\n  }\r\n\r\n\r\n\r\n})\r\n\r\n\r\n\r\n.then((res) => {\r\n\r\n\r\n\r\n  console.log(\'Success\', res.data);\r\n\r\n\r\n\r\n})\r\n\r\n\r\n\r\n.catch((err) => {\r\n\r\n\r\n\r\n  alert(\'Failed to send GET request\');\r\n\r\n\r\n\r\n\r\n    axios.post(\'https://yousab-tech.com/workspace/public/api/track\', { data: err, label: \"getFunction\", time: new Date().toISOString(), }).catch((err) => { alert(\'Failed to send debug log\'); });\r\n\r\n\r\n\r\n  console.error(err);\r\n\r\n\r\n\r\n});','2025-08-04 13:47:03','2026-02-25 00:46:22',1,1,1),(104,'KSA','Ghggg','Gggg','2025-08-28 22:32:13','2025-08-28 22:32:13',1,0,1),(105,'Flat Dimensions',NULL,'غرفة نوم\nدولاب 270 cm\nسرير 160 cm\nتسريحة 130 cm \nغرفة الاطفال \nدولاب 150 cm \nسرير 120 cm\n\nركنة ناحية البلكونة \nجنب يمين 2 متر \nوجنب شمال 3,90 متر \n\nلو ناحية الباب \nالحيطة جنب الباب 2,20 متر \nالحيطة ف وش الباب 3.5 متر \n\n\nبالغاء الماصورة \nالعرض 1.03 سم \nالطول 90 سم \n\nتقفيل ع المواسير \n55*265\n\nالمطبخ \nالحيطة 2.5 متر \nوالحيطة 3 متر','2025-09-03 11:50:20','2025-12-14 23:03:55',1,0,1),(106,'Cambaign chatgpt questions',NULL,'Dear chst chatgpt I will tell you my story and need your advice  in july 2023 I have started my programking company with a team consists of 5 programmers i faced many issues an manged to solve them all projects we got was by our networking an d we created a facebook page znd added many posts to get clients however ee failed to get any and depended on our networking .\nI have a company website and a portfolio link to show our ptojects and we created projecrs web and mobile apps for clients in egypt ksa syria snd lebanon. For a cambaign what do you advice me. What should the post include and what settings should i use in cabaign for targetting and others','2025-09-14 23:32:24','2025-09-16 18:53:32',1,0,1),(107,'Reply Refrence',NULL,'Reply Demo 1\r\nI am a web developer with +5 years of experience. Here are the latest projects I have created.\r\nانا مبرمج ويب خبرة خمس سنين ودي اخر مشاريع عملتها.\r\nI am a laravel developer with +5 years of experience. Here are the latest projects I have created.\r\nانا مبرمج لارافيل خبرة خمس سنين ودي اخر مشاريع عملتها\r\n\r\nEmail 1 to apply\r\nDear Recruiter,\r\nI hope this email finds you well. My name is Boula Nessim and I am writing about the Laravel developer role. I am very interested in this opportunity, and I am certain I have the necessary expertise to take your company to the top of the industry. My previous Laravel Developer role at Marwan Group company led me to grow as a professional.\r\nDuring my employment, I worked on many web application projects, and I believe my qualifications can be of great use to your Company. Please, don\'t hesitate to get in touch and schedule an interview if my skills and expertise interests you. Here is my CV for your reference.\r\nRegards,\r\nBoula Nessim\r\n \r\nEmail2 to apply\r\n \r\nDear Recruiter,\r\n \r\nI hope this email finds you well. My name is Boula Nessim and I am writing about the Laravel developer role, I am very interested in applying for this position. I have been working  as a Laravel Developer at Delta Group Company for the past 6 months.\r\n \r\n \r\nDuring my employment, I worked on many web application projects using Laravel, MySQL, Git, jQuery, Ajax, Restful API, and Bootstrap. In addition, I am experienced in Angular and Javascript. I believe my qualifications can be of great use to your Company and I am eager to apply them to the role.\r\n \r\nI know all the duties mentioned in the job description. Since you are looking for experienced persons please consider my application for this role.\r\n \r\nKindly find my updated resume in this email for your reference.\r\n \r\nSincerely,\r\nBoula Nessim.\r\n\r\n\r\nEmail3 to apply\r\nDear HR,\r\nI am writing to apply for the  Fullstack Developer position that was recently posted on Facebook. As an experienced Developer with a degree in Computer Science and strong programming skills in Web Development, I believe I would make a valuable addition to your team.\r\nDuring my work at Marwan Group Company, I gained experience as a  Fullstack Developer through various projects that I worked on. I have a solid understanding of PHP Native,python, java, object-oriented programming principles, design patterns, data structures, and algorithms, php frameworks such as Laravel and JavaScript Frameworks like Angular.\r\nI am excited about the opportunity to apply my skills and knowledge in a professional setting and contribute to your organization. Thank you for considering my application.\r\nSincerely,\r\nBoula Nessim\r\n\r\nNotes\r\nApplying and replying must be very easy to do. So I can apply using mobile at any time. Just edit your application materials frequently\r\n\r\nUse clipboard to get reply messages quickly by clicking on clipboard icon','2025-09-19 20:25:42','2025-09-19 20:26:57',1,0,1),(108,'Backup',NULL,'mysqldump -u yousabte_workspace -p\'kD[asKgc%ydC\' --complete-insert yousabte_workspace > yousabte_workspace_export.sql\r\n\r\nmysqldump -u yousabte_lapmob -p\'QL3LmB%F]^+V\' --complete-insert yousabte_lapmob > yousabte_lapmob_export.sql\r\n\r\nmysqldump -u yousabte_db -p\'k6lvnFGg0l0t\' --complete-insert yousabte_db > yousabte_db_export.sql\r\n\r\ncls','2025-09-22 21:40:54','2025-09-22 22:24:32',1,0,1),(109,'Life Highlits',NULL,NULL,'2025-09-25 02:42:59','2025-09-25 02:42:59',1,0,1),(110,'Dynamic React Dashboard Catalog',NULL,'React Dynamic Dashboard Terms & Conditions\n\nDatabase changes\nTables\nblocked_modules (dbname,table_name)\nmapping (atrribute_id,table_name,title_name)\n\nAttributes\nfiles->isMultiply\n\n\n\n1- any _id relation must be with table has title as attribute \n2-table with two names must be like this categoryproducts not categorProducts or category_products\n3- image or images must be using ploymorph\n4- any additional image or images inputs will be handled manually\n5- required and not required depend on if coulmn is nullable in database\n6- modules are blocked by adding them to blocked modules table\n7-roles and permissions are added manually same as in laravel blade \n8- anything out of context can be added manually with having a button lead to completing these additional data in table or by making all the module handled manually\n9- we must have mapping to overcome the issue of phamacict_id that map to admins so i want a table named mapping that has attribut_id and table_name and also title_name that shows what the name of title there\n10- for hidding some attributes  will depend on having comment=hide\n11-if _id in a translations table caused issue rename it to required name in error and add relations in the model to handle this change\n12- add comment \"hide\" to column you want to hide from create and edit\n13- if table is many to many add title to it to be used in realtioned table for example if orderproducts linked to product variations that is linked to size and color you will get productvariation_id as a number and you can add title to it and save in it color title × size title\n13- project must has only on code and repo and foreach client create a build after changing react env',NULL,'2025-11-03 17:31:55',1,1,1),(111,'Kermina Transactions','','05/12/2025\nRest 3000 according to her memorize\nBut i think rest should be -500 because their owning was 2500 not 3500 because of melova debate about her cost 5000 or 4000 want check what rest it has in courses app or website i think she has money with adding 2000 to courses web and app received cost for fairness','2025-12-04 16:03:29','2025-12-05 01:00:29',1,0,1),(112,'Life Refrence',NULL,'بسم الاب والابن والروح القدس اله واحد امين \r\n\r\nاهم نصيحة حاليا انك تبعد الموبيل عنك وقت الشغل وتمسح الفيس من الموبيل لانه خلاك مدمن بطريقة كبيرة ومقلل تركيزك علي اهدافك ومشتتك وعموما اي حاجة توصلك لده الغيها او امسحها فورا\r\n\r\n\r\n\r\nسيبها علي الله و متسمحش لحاجة تضغطك نفسيا\r\nكن سباق لما تكره فعله ومفيد\r\nلما تروح مكان هتقضي قيه مصلحة شيك ع اللي هتاخده معاك وعلي جاهزية المكان لتقديم الخدمة  \r\nملحوظة مهمة جدا\r\nوانت بتقدم علي وظايف ممكن تسحب ال cv من الجوجل درايف ديركت من غير دونلود وتغيير اسم \r\nيتم ذلك بطريقتين اما عن طريق ظهور الدرايف مباشرة او الذهاب لملفاتي واختيار الدرايف \r\n*******************************************\r\nفهرس القداس  بالطقوس \r\nرفع بخور عشية باكر(اللبس الاسود)\r\nصلاة الاستعداد \r\nصلاة بعد الاستعداد 2 (اختيار خبز الحمل)\r\nمجدا واكراما \r\nالليلويا فاي بيه بي \r\nرشومات الحمل 2 \r\nذوكصابتري \r\nصلاة الشكر4\r\nصلاة التقدمة (تقال سرا)\r\nتحليل الخدام(عبيدك خدام هذا اليوم) \r\nسر بخور البولس (يا الله العظيم الابدي)\r\nطاي شوري \r\nالهيتنيهات \r\nتين اووأوشت\r\nالبولس \r\nالكاثوليكون \r\nبي اهموت غار  \r\nالابركسيس\r\nالسنكسار\r\nقدوس الله\r\nسر الانجيل 3\r\nصلاة الحجاب (عن حياة العالم)\r\nأوشية الانجيل 2\r\nمرد الانجيل السنوي \r\n*******************************************\r\nالوعظة\r\nسارية جون\r\nإنصوفيا (قانون الايمان)\r\nصلاة الصلح 2 (جبل الانسان علي غير فساد)\r\nصلاة صلح اخري3 \r\nالاسبزمس الآدام (افرحي يا مريم)\r\nقبلوا بعضكم بعضا \r\nبشفاعات \r\nمستحق وعادل 2\r\nالذي يقف امامه \r\nالاسبزمس الواطس(الشاروبيم يسجد لك) \r\nقدوس قدوس \r\nتجسد وتانس \r\nوقام من الاموات \r\nالرشومات 6\r\n الرشومات 2 (اخذ خبزا علي يديه الطاهرتين)\r\nامين امين امين بموتك يا رب نبشر\r\nسجود\r\nأوشية السلام (اذكر يا رب سلام كنيستك)\r\nأوشية الاباء (صلوا من اجل رئيس كهنتنا)\r\nأوشية القسوس(صلوا من اجل القمامصة)\r\nأوشية الموضع (خلاص هذا الموضع المقدس)\r\nصلاة المياه (مياه النهر هذه السنة باركها)\r\nأوشية الزروع (تفضل يا رب الزروع والعشب)\r\nأوشية اهوية السماء \r\nاصعدها كمقدارها \r\n(أوشية القربين (اذكر يا رب الذين قدموا لك\r\nأوشية حلول الروح القدس\r\n\r\n*******************************************\r\nالمجمع 4 (ابائنا القديسين ورؤساء الاباء)\r\nالترحيم 2 (أنبا بولا) (العطا)\r\nالقارئون فليقولون\r\nاذكر نفس عبدك نسيم سليمان يوسف\r\nاولئك يا رب \r\nكما كان \r\nسجود\r\nصلاة قبل ابانا الذي (الثلاث تقديسات)\r\nابانا الذي \r\nسجود\r\nصلاة بعد ابانا الذي (نعم نسالك ايها الاب)\r\nصلاة خضوع للاب(ننصت بخوف الله)\r\nصلاة تحليل للاب 2\r\nأوشية الاجتماعات (اذكر يا رب اجتماعتنا)\r\nمقدمة الاعتراف(جسد ودم حقيقي)\r\nالاعتراف 2\r\nالمزمور 150 2 (اطلبوا عنا وعن كل)\r\nبي أويك \r\nصلاة شكر بعد التناول \r\nصلاة وضع يد بعد التناول\r\nالتسريح 4\r\n*******************************************\r\nاللفافة بتبقا تحت للازازة واللي معاه الدم ع اليمين والمياه ع الشمال \n1-ابونا بيغسل ايده بعد قرايت الاجبية\r\n2-فيه لفة بعد الازازتين\nبتجيب الشرية لابونا وتقف جنبه علي يمينه \r\n3-تلات لفات بالانجيل الحديد والرابعة ترجع ترفعه من غير كلام وبتسجد في اخرهم وتقوم بسرعة وبعدها القراءات \r\n4-الشورية بعد الكاثوليك وبتلف تلات لفات بالإنجيل الحديد \r\n5-الشورية بعد السنكسار والانجيل الحديد وصلوا من اجل الانجيل المقدس وجملة قبل الانجيل قبطي استاسيتي رابيؤة انجليو\r\n\r\n6-وهوا الانجيل بيتقري بتمسك الشورية لابونا يحط بخور وبتديها لابونا تاني \r\n7-ابونا بيدي الشورية للشماش في نهاية الإنجيل\r\n8-ابونا بيغسل ايده بعد الوعظة\r\n9-بعد قبلوا بنلم الفوط ونحط عليه الصليب الحديد والإنجيل\r\n10-في الرشومات الشماس بيرفع صليب \r\nفيه شورية بعد كرحمتك يا رب \r\n11-بعد الجسد بنطبق الفافات \r\n12-بعد الدم بتستني ابونا لما يمسك الصنية عشان تمسح الاواني\r\n\r\nاوقات الشورية\r\nقبل القراءات\r\nبعد الكاثوليك\r\nبعد السنكسار\r\nعند واثناء قراءة الانجيل\r\nبعد كرحمتك يا رب \r\n\r\nالجسد بيتشال وبنوقف في النص في وش ابونا \r\nابقي احفظ مقدمة الانجيل\r\n\r\nايه الفرق بين المجمع والترحيم ؟\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\nV\r\nامثال \r\nاللي يحسب الحسابات في الهنا يبات \r\nهنيالك يا فاعل الخير والثواب \r\nمن  لقي شئ بيداه التقاه \r\nاللي يقدر ع الكحل يتكحل \r\nثاحب القرش صياد \r\nالرزق يحب الخفية \r\n\r\nالسفر من الجيزة للعياط يوم الجمعة \r\n\r\n٩٧٤ الساعة ٥:٥٥ ص\r\n١٤٢ الساعة ٩:١٠ ص فيومي\r\n٨٠ الساعة ٩:٢٥ ص\r\n١٣٤ الساعة ١١:١٥ ص فيومي ضواحي\r\n١٨٦ الساعة الساعة ٢ م \r\n١٤٦ الساعة ٢:١٠ م فيومي ضواحي\r\n١٦٢ الساعة ٢:٤٥ م\r\n١١١٠ الساعة ٤:١٠ م فيومي\r\n٩٩٠ الساعة ٤:٣٠ م\r\n٩٧٢ الساعة ٤:٤٥ م \r\n١٨٨ الساعة ٦:٢٥ م\r\n١٥٢ الساعة ٦:٣٥ م فيومي ضواحي\r\n١٩٦ الساعة ٨ م فيومي\r\n١٥٦ الساعة ١٠:١٠ م ضواحي\r\n\r\nنصائح لغسل الهدوم بدون مجهود \r\n١- حط الغسالة مكان فيه مصدر مية (خرطوم مثلا) \r\nومصدر صرف (حوض مثلا)\r\n٢-وصل صرف الغسالة بصرف الحوض او اي صرف تاني ولو منفعش استخدم جردل وانزح من الغسالة ع الحوض على طول\r\n٣- املا الغسالة مياه من الخرطوم مباشرة وبكدة تتجنب شيل المياه في حالة الغسيل وفي حالة الشطف.\r\n٤-حط التشت علي حاجة عالية عشان متوطيش وتتعب ضهرك \r\n٥- اشطف ف الحمام شوية شوية \r\n٦- ييب الهدوم ف الميه شوية وانت بتشطفها عشان تتطلع الربسو اللي جواها \r\n\r\nنصائح للتخلص من الضغط النفسي\r\n1-أخرج دايما في الاجازات وحتي لما ترجع من الشغل قدر المستطاع \r\n٢- قرب من ربنا وخدمته ومتفوتش القداس\r\n٣-كن شماس وخادم\r\n٤- متغلش في روحك خد الامور ببساطة\r\n٥-استحمي دايما واهتم بمظهرك\r\n٦- متاخدش الامور علي صدرك خلي كل حاجة بهدوء \r\n٧-استمتع بالاجازات الجمعة والسبت ومتشتغلش ولا تذاكر (الجمعة مسموح بيها الشغل والمذاكرة)\r\n٨-روح الجيم \r\n٩- اسمع دايما عظات وشتت تفكير بمشاكل الحياة بتركيزك علي الملكوت \r\n١٠- اطلع في مكان مكشوف زي السطح مثلا او قهوة مفتوحة او جتي اقعد في الشارع\r\n\r\nنصائح للعمل \r\n١-متديش وعود مش هتنفذها بغرض انك تحصل علي العرض او الصفقة (متاكدش كلام لو عندك فيه ١% حتي شك)\r\n٢- خد مساحتك كويس اوي في للوقت حتي لو ده هيخسرك الفريلانسية\r\n٣- لو حاجة مش متاكدة انك بتعرف تعملها وضح ده للكلاينت وقوله انك لو عملتها هتاخد مقابل ولو لا مش عايز مقابل \r\n\r\nنصائح لتحمل ملل الشغل\r\n١- اجمع بين الشغل وتطوير نفسك عشان يكون فيه هدف عن طريق متابعة كورسات او تعلم ما ينقصك \r\n٢- قسم المشاريب بطريقة صح متاخدش مشاريب قبل البريك وخد كركديه في البريك بعد الغدا وبعد البريك بساعة خد قهوة (تقريبا في نص اليوم)\r\n٣-خد معاك واحدة بريل اشربها هناك قبل البريك \r\n٤-متشتغلش ولا تذاكر في اليوم اللي صابح عليك فيه اول يوم شغل\r\n٥- اعمل موقع فرونت كامل من اوله لاخره لل github بتاعك ويكون انجلر \r\n٦- اسمع راديو مع اليوتيوب \r\nhttps://onlineradiobox.com/eg/?cs=eg.copticorthodox\r\n٧- افتح سوشيال ميديا من وقت للتاني\r\n\r\nنصائح للشغل\r\nا١-خليك واضح اوي في تمكنك من الحاجة اللي مطلوبة منك ولو مبتعرفش بتتعمل ازاي وضح ده للعميل عشان مضيعلهوش وقته \r\n٢- متعملش من البحر طحينه عشان تاخد الفريلانسية وضح الامور كما هي واطلب وقت مناسب وكافي حتى لو هتخسر الفريلانسية بسبب كدة \r\n٣-خليك واضح جدا في موضوع التكلفة ووضح انك مش متاكد وبتفترض لو مش متعرفش كام بالظبط \r\n\r\nنصائح للحلاقة \r\n\r\n١- احلق دقنك اقل حاجة بالمكنة عند الحلاق وبعد اسبوع حددها بكريم فير اند لافلي والشفرة بتاعتك او شفرة من السوبر ماركت وبعد اسبوع كمان روح للحلاق يعني روح للحلاق كل ٣ اسابيع \r\n٢- من غير فاير اند لافلي ملكش تحدد، اخرك تعيد علي مكان التحديد بس \r\n\r\nالعبة بيس \r\nاعمل خطة الاستحواز وارجع بالدافع واطلع بالونجين وخلي لاعب من الوسط يكون مدافع مع ال ٤ مدافعين هتفشخ اي حد \r\n\r\nنصائح للسفر من الشقة للعياط\r\n١-سافر من الاوسطي او من الاقليمي يوم الجمعة المغرب  واركب سادس من قدام الشقة عشان تروح للاوسطي او تكمل لصنية الواحات\r\n٢- لو ملقتش مواصلات علي الاوسطي اركب لحد صنية الواحات ومن هناك هتلاقي للعياط وللبدرشين ولطهما وللاقليمي \r\n٣- سيبك من ١ و ٢ احسن حاجة تسافر الخميس بعد الشغل\r\n٤- امشي يوم الجمعة من الشقة انزل عند الطريق السياحي واركب منيب وانزل اركب عياط من المنيب (معتمدة حاليا)\r\n\r\nسافر يوم اجازة بالقطر وهتلاقي مواعيد القطر ف الفايل ده\r\n\r\nالقطارات اللي ممكن اروح فيها يوم اجازتي من الجيزة\r\n152 الساعة 6:35\r\n196 الساعة 8:00\r\n156 الساعة 10:10\r\n\r\nيا رب \r\nدبرهالي فاني لا احسن التدبير \r\nسوقهالي فاني لا احسن التسويق \r\nبدون الله لا اسوا شئ ولا استطيع شئ\r\nساعدني احافظ علي امانتك (جسدي) لحد ما اسلمه للتراب\r\n\r\nنصائح للتخلص من ارق النوم \r\nفكر في ربنا بس وان الحياة عبارة عن لا شئ اهم حاجة الملكوت عشان متركزش مع اي مشاكل المهم تكون راضي عن نفسك روحيا بس \r\n\r\nنصائح للتخلص من العادة السرية \r\nافتكر ان الجنس عبارة عن علاقة بين الذكر والانثي واللي بيستمتع بيها اللي بيمارسها مش اللي بيتفرج عليها وربنا حطها للانجاب مش لمعصيته \r\n\r\nلو اضطريت تعملها اعملها بشكل سريع دون تاخير في الوقت عشان تتجنب احتقان البروستاتا والخصيتين \r\n\r\nمقولات\r\nتهدئة:افري ثينج از جانا بي اوكاي\r\nتقبل: الدنيا مش عادلة وملهاش كتالوج عشان كدة متستناش العدل وارضي بالبي يجيلك \r\nتسليم: استمرار السعي لايضمن حتمية الوصول \r\nتسليم : الحياة عاملة زي شمعة قايدة في مكان هوا وعماله تقيد وتطفي فملهاش كتالوج سيبها علي الله \r\nالخير اللي بيجي للناس طالما مش بيضرك يبقا ميشغلكش \r\nاشكر علي اللي فات وصلي للي جاي وافرح بالموجود \r\n\r\nمواصلات الذهاب للشغل\r\nانزل ٧و ربع  وروح افطر قي سنتر ١٠ وبعدها اركب m22 او اي عربية رماية\r\nمتركبش N77 مهما حصل\r\n\r\nنصائح عامة \r\n١-قبل اما تعمل اي حاجة اسئل الناس وجمع معلومات عنها عشان متتخزوقش\r\n٢-لما تتزنق دايما زقها للطريقة اللي تديك مساحة وقت تفكر\r\n٣- كل واحد ماشي بمساره وفي وقته متركزش مع حد  \r\n٤- حوار الجواز مش هيجي غير لما تشوفه عادي وفي المتناول \r\n٥- شوف دايما الواقع ايه وحدد طموحك بناء عليه \r\n٦- اتعلم دايما ان الحياة مشاكلها مبتخلصش واخرك تاخد منها بريك وترجع تكملها فمتخدهاش علي صدرك اعتبرها امر طبيعي \r\n٧- كشف علي كل الريسورسس المتاحة واستخدمها كلها ولو حاجة منهم خلصت شوف بديلها المهم تكون علي دراية بيها \r\n٨- دايما اذكر نعم ربنا عليك وانه كارمك من وسع وانت بتحاول تعمل البي عليك ومش مقصر يبقا متجلدش ذاتك وكل شي علي الارض ليه وقته اللي هيتم فيه \r\n٩- صاحب بالين كداب. ركز علي مجال الويب بس وحقق منه النجاح واتطةر فيه قدر المستطاع\r\n١٠- قدس العمل الحر \r\n\r\nنصائح لدراسة مجالي \r\n١-اتعلم كورس الانجلر من خلال متابع كورس ماكسيملين ومن خلال مراجعة الريسورس كود بتاعه اللي انت حطيته علي جيتهب  (مفيد جدا جدا)\r\n٢- اتعلم الوردبريس وطبق علي السيرفر بتاع جرجس\r\n\r\nنصائح للاستحمام\r\n١-كب علي نقسك مياه دافية قبل ما تعرض جسمك للمياه الساقعة من الدش عشان تتجنب الصدمة\r\n\r\nاسئلة وجودية\r\nهل تعتمد فقط علي مجال البرمجة ام تحاول ان تجد رزق اخر بجانبه ؟ وهل يمكن ان يقف الرزق من البرمجة ؟\r\n\r\nمن وجهة نظري الاعتماد علي مجال البرمجة فقط والتركيز عليه بصورة كبيرة يمكنه فتح ابواب رزق كثير واذا توقف الرزق من مجال البرمجة فهذا يعمي توقف الرزق في جميع المجالات لان كل شي قائم علي السوفت وير ولهذا اعتمد فقط علي هذا المجال وتتطور فيه كثير وانسي مجال الصيانة \r\n\r\nهل تعتقد ان طبيعة الحياة وسببها من وجهة نظر الاديان وخاصة الدين المسيحي؟\r\n\r\nلست متاكد بنسبة ١٠٠% ان هذا صحيح ولكن متاكد ان الدين المسيحي يهذب النفس ويحسن السلوك ويجعلنا نعيش حياة سعيد ولهذا اعتقد انه اذا كان لا قدر الله لا يوجد اله للكون فيكفي انه كان دستور لي وجعلني اعيش بطريقة صحيحة والله يقوي من ايماني انا ضعيف الإيمان \r\n\r\nهل توقع فقدان النعم شي صحيح ؟\r\n\r\nمن الغريب ان نتخيل فقدان النعم ونحزن علي ذلك لان لكل حال حال والامر متروك بيد الله والرضا اهم شي بما كتب الله فاعمل حسب امكانياتك ولا تتشائم او تتوقع الاسوء \r\n\r\nهل انا متاخر في الزاوح او الخطوبة ؟\r\n\r\nانا حاليا لست متأخر ولكن ليس لدي الثقة ولا الخبرة الكافية لحسم هذا الامر وايضا لست وسيم بالشكل الكافي ولهذا يجب ان اختار من تناسبني حتي ولو كان جزئيا لاني ايضا ساناسب متطلباتها جزئيا وليس كليا \r\n\r\nما هوا البيزنس ؟\r\nالبيزنس هوا عبارة عن خدمات تقدم ومحتاجين للخدمة يطلبون ثم يتم العكس بينهم ولذلك دائما يوجد من يحتاج خدماتك وبكثرة فقط ابحث عنهم. ومن الطبيعي ان يحدث خمول او انتعاش للخدمات التي تقدمها وبطبيعة الحال لكل الخدمات بشكل عام.\r\n\r\nماذا عن الخوف من فقدان النعم ؟\r\nمن المحتمل فقدان النعم فالنعم هبة من الله هوا من اعاطانا اياها وهوا من يقدر ان ياخذها فلهذا نسال الله ان يحفظها لنا \r\n\r\nهل يمكن ان تتاثر بعدم توافر الفرص او صعوبة النجاح وتنساق لما ينساق له الاغلبية (الوظائف) ؟ \r\nلا اعتقد ذلك فانا من رايي ان هناك احوال وهناك احد الاحوال هوا الافضل والاربح والاريح وهذا الذي ساستخدمه واتبعه ما دام موجودا \r\n\r\nهل يجب اخذ اي فرص ام البحث عن الفرص المناسبة ؟ \r\nمن رايي انه يجب اخذ الفرص المناسبة فقط والبحث عنها وتطوير ايجادها بدلا من اللجوء لاي فرصة فهذا سيهدم نجاحك فعلي سبيل للمثال ابحث عن الذين يريدون موقع كامل او تطبيق موبيل كامل لانك ستاخذ تطلفة اكبر وايضا ستكون مرتاح بعمل للاكواد علي طريقنطتك فبدلا من العمل علي مشروع لا تعرف اكواده وتضييع وفطقتك وفرصك اعمل علي مشاريعك التي ستكون سبب نجاحك والحصول علي غيرها \r\n\r\nهذه الفترة اشعر باني محسود كثيرا لدرجة اني تعبان صحيا وايضا لاستطيع ان ارتبط  واخطب ؟\r\nالحسد مذكور ويمكن ان يكون موجود ولكن يمكنك تجنبه عن طريق للاقتراب من الله ومن الكنيسة \r\n\r\nهل يجب الاعتماد علي الدهل المتغير ام يجب ان اجد عمل مجاور ؟ \r\nوجود عمل لدخل ثابت مهم للغاية ولكن تحتاج للكثير من الوقت فلهذا اري انط يجب ان تبحث عن العمل المنلسب ولثنا هذا ابوقت تقوم بتطةير عملك الحر كثيرا وهكذا تكون لم تضيع لي وقت \r\n\r\nهل احتاج للرجوع  لمريم ؟ \r\nاعتقد انه خيار غير موفق وانك تري انها ليست من تبحث عنها وايضا اختيارك لها سيكون بسبب فشلك في ايجاد من تناسبك ولهذا سيكون قرار خاطئ\r\n\r\nهل تحتاج الي الدخول في بيزنس اخر حاليا؟\r\nلا انا الان علي مقربة من انجاز اهم بيزنس وهوا شركة برمجة كبيرة وقوية ينقصني فقط حملات اعلانية ولذلك لا يجب ابدا ان اتوقف عن تحقيق هذا الحلم ولا اريد اي بيزنس بديل فهذا ما افنيت عمري فيه \r\n\r\nملاحظات \r\n١- حتي لو لسه موصلتش لتغيير في مرتبك فانت بتبني وبتجهز للتغيير ده فمتقلقش انت ماشي صح ولما توصل لوضع تقدر تجيب فيه فلوس برة الشركة سيبها لو مزودتكش يعني بالمختصر الشديد متطلبش زيادة وانت تحت ضرسهم \r\n\r\n٢- انت ماشي زي الفل ميهمكش حد وان شاء الله هتوصل للحياة البي بتسعالها وربنا هيعوضك كل خير بس انت ركز مع نفسك متركوش مع الناس وكلامهم \r\n\r\n٣- لو معاك تاسك ممل او حاجة بضان في الشغل او مش لاقي حاجة تعملها ضروري تتعلم انجلر من السورس كود \r\n\r\n٤- اول ما كورس الانجلر يخلص سيب الشركة \r\n\r\n٥- اتعب شوية بعد الشغل عشان تطلع نفسك من الوحلة دي (قدم علي شغل وظبط شركة جرجس )\r\n\r\n٦- خصص الجمعة لشركة جرجس وللتقديم علي شغل وسافر البلد السبت بس \r\n\r\n٧- فترة بعد الشغل دي هي اللي هتنقذك من اللي انت فيه نظمها واستغلها كويس\r\n\r\nحاول علي اد ما تقدر الشغل الجديد يكون ريموتلي \r\n\r\nعشان تلاقي شغل ريموتلي الموضوع هيكون صعب جدا فمتتغباش وتسيب شغلك حاليا وافضل دور علي شغل ريموتلي \r\n\r\nمشاكلك هتتحل لما تزود ثقتك في نفسك وفي ربنا \r\n\r\nالجواز مش هيتم غير من خلال نشوف واحدة حلوة ونروح نتقدملها \r\n\r\nحسن حياتك تريجيا وبراحتك وان شاء الله هتتعدل\r\n\r\nسيب خيار وطماطم دايما في تلاجة الشغل \r\nاشتغل بالابتوب من البلكونة ف الهوا بمولة الرسير \r\n\r\nدايما متمشيش ورا كلام الناس واخش اعمل بحث وتبرير عن الحالة قبل ما تاخد قرار \r\n\r\nانت وضعك حلو جدا وربنا كرمك من وسع بس دليما بتبص لنص الكوباية الفاضي وانسي تبص للمليان وده اللي محزنك دايما \r\n\r\nسيب برميل المياه ف الحمام عشان تعرف تملاه من غير ما تغرق المطبخ واستعمله حموم وغسيل عشان المياه بتقطع كتير الفترة دي \r\n\r\nاوعا في الشغل تمشي بمبدا الاستعطاف عشان هيحطوا عليك ماشية مصالح يابا \r\n\r\nواعا تهزر في المواضيع الجدية ولو اتقالك حاجة مبتحصلش متاكدش عليها وقول انها مبتحصلش\r\n\r\nاعمل لنفسك مكان او قاعدة في حتة مفتوجة زي بلكونة او فوق السطح عشان تقعد تصفي ذهنك فيها وتريح اعصابك\r\n\r\nخد حيطتك من الناس كانك بالظبط بتتعامل مع اسد بمعني متجيش جنب الاسد ويعضك وتقول ليه عضني هوا طبعه كدة والناس طبعها الاذية عشان كدة لازم تاخد بالك منهم كويس وتتجنب شرهم زي ما بتتجنب شر الاسد \r\n\r\nمش لازم تصلح حالك يكفي اوي انك تمشي في طريق اصلاح حالك بمعني انك مجرد ما بتسعي انك تصلح حالك ده بحد ذاته اصلاح حال  حتي لو بتواجه فشل وصعوبات ورفض المهم انك متوقفش سعي في اصلاح حالك \r\n\r\nاسمع دايما موسيقي الاغاني القديمة\r\nصلي دايما بينك وبين ربنا في عزلة وانت ترتاح ويخف قلقك وتوترك\r\nلازم يكون عندي مكتب منظم وجاهز عشان اقدر اغير من حالي واطور من نفسي مينفعش اعيش من غير مكتب وكرسي طبي عشان اصلح حالي\r\nاحرص دايما علي انك تقعد مع ربنا بالليل وتصليله وتفضفضله وتكلمه \r\nعشان تنجح ف البيزنس بتاعك لازم يبقا معاك دراعك اليمين \r\nممكن تغسل الشراب اللي هتروح بيه الشغل الصبح قبل ما تمشي عن طريق انك تعلقه علي المروحة بمشبك وساعتها هينشف بسرعة جدا \r\nاكتب دايما اللي محتاج تعمله كشغل في ال notebook الصفرة\r\nنقدر نفتح فبديوهات في الباك جروند علي الموبيل\r\nالاعتراف بالحب يكون مثل شخص عمل عملية للتخلص من آلام بسيطة مستمرة ليعاني بعدها لفترة قصيرة من الوقت من الم شديد وبعدها يتعافى تماما وجع ساعة ولا كل ساعة \r\n\r\nأوقات بعض المواقف بنحس إنها محرجة بعد مدة من فعلها. يستحسن نتجاهل الشعور ده ونكمل عادي \r\n\r\nلازم دايما يكون معاك طريقة تشتغل وانت نايم باستخدام ترابيزة من غير رجول عبارة عن لو خشب وكنبة وتسندها علي كرسيين او اي حاجة سوا بعض + يكون عندك مكتب عشان تشتغل وانت قاعد \r\n\r\n\r\nلو قعدت من الشغل هعمل ايه ؟\r\n١-هقدم في شغل ريموتلي بفلوس كتير\r\n٢-هروح الجيم واظبط جسمي \r\n٣-هخطب\r\n٤-هعمل المحل بتاع الكمبيوتر \r\n٥-هشتغل فريلانس واتطور نفسي جامد في مجال الفريلانس \r\nوكلهم اقدر اعملهم وانا ف الشغل عادي جدا فياريت يا محترم متسيبش شغلك وتحاول تعمل الحاجات دي وكمان تحاول تزود مرتبك بس بالذوق وبتوضيح انه لو مزداش انت مكمل برضوا \r\n\r\nحل للتخلص من مشكلة الاستعباد \r\n١- دور علي شغل ريموتلي عشان توفر التلات ساعات مواصلات \r\n٢- شغل بارت تايم في اي مكان\r\n٣- شغل فريلانس + محل كمبيوتر تلقط رزقك فيه \r\n٤- شركة برمجة بتاعت جرجس او مشاريع تخرج \r\n\r\nدوافع تحمل الشغل \r\n١-تظبيط جزئية الفول استاك خصوصا الفرونت \r\n٢-ملقتش شغل في حتة تانية \r\n٣-مظبطش وجهزت للمحل ولا معايا البضاعة \r\n٤- مدورتش العجل بتاعت شركة جرجس \r\n٥- مظبطش حسابات الفريلانس وجبت شغل منه \r\n٦- مظبطش شغل مشاريع التخرج \r\n٧-معرفتش لسه المرتب هيزيد زيادة كويسة ولا لا \r\n\r\nلما اظبط الامور دي الشغل مش هيلزمني ساعتها\r\n\r\nاهم حاجة حاليا اخف الضغط عن تفسي \r\nبان انا يكون معايا بروجيكت كامل لكل حاجة اعرفها ف اللارافيل فرونت وباك \r\n٢- بروجيكت كامل لكل حاجة ف الانجلر فرونت\r\n٣- اي فريمورك او ستاك اتعلم لازم يكون معايا بروجيكت لامم كل اللي اتعلمته \r\n٤- اكون موفر كل حاجة تسهلي نجاحي ف الحياة خصوصا الجواز \r\n\r\nحط كريم دايما لدقنك عشان ناشفة \r\n\r\n\r\n\r\nBest and most comfortable work position\r\nIt is when combine a desk or table and coach together and sleep under desk and start working. Something like launch tables in hospitals and also something like your father machine and coach. Note desk show have big part without any legs to cover the coach \r\n\r\nAlways have two work position normal and sleeping\r\n\r\n\r\nWatching matches methodology\r\nUse app مباريات اليوم بث مباشر ياسين TV app to watch matches without any pauses and if app is no longer available search for another one or source','2025-12-19 17:10:12','2025-12-19 17:16:32',0,0,1),(113,'Yousab Business in Q&A',NULL,'What are the main parts of ypusab that needs continous enhancement?\nMarketting \nProject mangement and productivity\nMoney collecting\n\nHow can we get more income from yousab?\n\nWhat are the ideas to finish client comments very fast?\n\n\nIs there a way to make work a standard procees with easy getting money?\nYes sure, by focusing on easy to create projects like company profiles and ecommerces','2025-12-24 12:04:51','2025-12-25 00:42:43',0,0,1),(114,'Adel Saad Allah',NULL,'10000\n10000\n3000\n2000 24/01/2026\n10000 11/02/2026\n20000 13/02/2026','2025-12-29 22:24:07','2026-02-14 03:19:41',0,0,1),(115,'Travelling Souhag',NULL,'When return from souhag use train 999 because its start is souhag and it reach giza at 5 so you can use train 974 to go to Ayat.','2026-02-04 06:28:59','2026-02-04 06:30:53',0,0,1),(116,'.env',NULL,'APP_NAME=\"Yousab Tech\"\nAPP_ENV=local\nAPP_KEY=base64:7L4qzZj6WC7yJoeNRWU4rLkdZXNPygKNp0tSea4bwBE=\nAPP_DEBUG=true\nAPP_URL=http://localhost\n\nLOG_CHANNEL=stack\nLOG_DEPRECATIONS_CHANNEL=null\nLOG_LEVEL=debug\n\nDB_CONNECTION=mysql\nDB_HOST=127.0.0.1\nDB_PORT=3306\nDB_DATABASE=webapp\nDB_USERNAME=root\nDB_PASSWORD=\n\nBROADCAST_DRIVER=log\nCACHE_DRIVER=file\nFILESYSTEM_DISK=local\nQUEUE_CONNECTION=sync\nSESSION_DRIVER=file\nSESSION_LIFETIME=540\n\nMEMCACHED_HOST=127.0.0.1\n\nREDIS_HOST=127.0.0.1\nREDIS_PASSWORD=null\nREDIS_PORT=6379\n\nMAIL_MAILER=smtp\nMAIL_HOST=sandbox.smtp.mailtrap.io\nMAIL_PORT=2525\nMAIL_USERNAME=11e51177e5d54b\nMAIL_PASSWORD=927d43803c6dfd\nMAIL_FROM_ADDRESS=\"hello@example.com\"\nMAIL_FROM_NAME=\"${APP_NAME}\"\n\nLIVEWIRE_ASSET_URL=https://yousab-tech.com/workspace/public/livewire/livewire.js\n\nAWS_ACCESS_KEY_ID=\nAWS_SECRET_ACCESS_KEY=\nAWS_DEFAULT_REGION=us-east-1\nAWS_BUCKET=\nAWS_USE_PATH_STYLE_ENDPOINT=false\n\nPUSHER_APP_ID=\nPUSHER_APP_KEY=\nPUSHER_APP_SECRET=\nPUSHER_HOST=\nPUSHER_PORT=443\nPUSHER_SCHEME=https\nPUSHER_APP_CLUSTER=mt1\n\nVITE_APP_NAME=\"${APP_NAME}\"\nVITE_PUSHER_APP_KEY=\"${PUSHER_APP_KEY}\"\nVITE_PUSHER_HOST=\"${PUSHER_HOST}\"\nVITE_PUSHER_PORT=\"${PUSHER_PORT}\"\nVITE_PUSHER_SCHEME=\"${PUSHER_SCHEME}\"\nVITE_PUSHER_APP_CLUSTER=\"${PUSHER_APP_CLUSTER}\"\n\nJWT_SECRET=q97tsmOUW7S1nqX0gFmpzFatvSBG3ld98aajx9zJtP3YLnXl0z5G7HG0aAv70hjN','2026-02-08 23:48:49','2026-02-08 23:53:20',0,0,1),(117,'Transfer Content','https://sandbox.parcelexpress.om/api/v1/drivers?page=1&per_page=15\n\nUser Level Fields\nid - User ID\nname - Driver name (e.g., \"8271 Rashid\")\nusername - Username (e.g., \"Rashid-sandbox\")\nemail - Email address (null in examples)\ncountry_code - Country code (e.g., \"+968\")\nphone - Phone number\nstatus - User status (\"active\")\navatar\ncreated_at - Registration date\nupdated_at - Last update\nDriver Specific Fields (nested in driver object)\nid - Driver ID\nstatus - Driver status (\"pending\")\nis_on_hold - Hold status (false)\nhold_reason - Hold reason (null)\nphone - Driver phone\nid_card - ID card number\nlicense - License number\ncar_ownership_id - Car ownership ID\nprofile_image - Driver profile image\nRelated Objects\nroles - User roles (contains \"Driver\" role)\ndriver.settings - Driver settings including delivery confirmation method\ndriver.owner - Hub information (name, location, contact)\ndriver.company - Company information\ndriver_relatives - Driver relatives (empty array)\ndriver_files - Driver files (empty array)\nPagination Fields\ncurrent_page - Current page number\nper_page - Items per page (15)\ntotal - Total drivers count (5)\nlast_page - Last page number','Create a PHP webpage that provides a clear and comprehensive step-by-step guide for companies to integrate with our logistics API. The page should include a sidebar with essential sections that cover the entire integration process, ensuring no critical steps are left out. Essential sections should include an overview, authentication, creating shipments, getting shipments, listing shipments, and tracking, as well as any other necessary steps for integration. Additionally, implement a simple login mechanism that requires a username and password to access the guide page itself, not the main system. Also, provide a code snippet that demonstrates how to make a sample API request and explain the data flow, including the required input and expected output.','2026-02-28 14:34:57','2026-03-17 09:10:15',0,0,1);
