\n    };\\r\\n\\r\\n    const handleSubmit = async (e) => {\\r\\n        e.preventDefault();\\r\\n\\r\\n        try {\\r\\n            await axios.post(\\\'https://yousab-tech.com/academy/public/api/message\\\', formData);\\r\\n            toast.success(\\\'Message sent successfully!\\\');\\r\\n            setFormData({\\r\\n                demo: \\\'\\\',\\r\\n            });\\r\\n            setErrors({\\r\\n                demo: \\\'\\\',\\r\\n            });\\r\\n        } catch (error) {\\r\\n            if (error.response && error.response.data && error.response.data.data) {\\r\\n                const apiErrors = error.response.data.data;\\r\\n                setErrors({\\r\\n                    demo: apiErrors.demo ? apiErrors.demo.join(\\\'\\\\n\\\') : \\\'\\\',\\r\\n                });\\r\\n                toast.error(\\\'Error sending message. Please check your inputs.\\\');\\r\\n            } else {\\r\\n                toast.error(\\\'Error sending message. Please try again later.\\\');\\r\\n            }\\r\\n        }\\r\\n    };\\r\\n\\r\\n    return (\\r\\n        <div className=\\\"container-fluid py-5\\\">\\r\\n            <div className=\\\"container py-5\\\">\\r\\n                <div className=\\\"text-center mb-5\\\">\\r\\n                    <h5 className=\\\"text-primary text-uppercase mb-3\\\" style={{ letterSpacing: \\\'5px\\\' }}>اتصال</h5>\\r\\n                    <h1>الاتصال للحصول على أي استفسار</h1>\\r\\n                </div>\\r\\n                <div className=\\\"row justify-content-center\\\">\\r\\n                    <div className=\\\"col-lg-8\\\">\\r\\n                        <div className=\\\"contact-form bg-secondary rounded p-5\\\">\\r\\n                            <form id=\\\"contactForm\\\" onSubmit={handleSubmit}>\\r\\n                                <div className=\\\"control-group mb-3\\\">\\r\\n                                    <input \\r\\n                                        type=\\\"text\\\" \\r\\n                                        className=\\\"form-control border-0 p-4\\\" \\r\\n                                        id=\\\"demo\\\" \\r\\n                                        name=\\\"demo\\\"\\r\\n                                        placeholder=\\\"demo\\\" \\r\\n                                        value={formData.demo}\\r\\n                                        onChange={handleChange}\\r\\n                                    />\\r\\n                                    <p className=\\\"help-block text-danger\\\" style={{ whiteSpace: \\\'pre-line\\\' }}>{errors.demo}</p>\\r\\n                                </div>\\r\\n                                <div className=\\\"text-center\\\">\\r\\n                                    <button className=\\\"btn btn-primary py-3 px-5\\\" type=\\\"submit\\\">أرسل رسالة</button>\\r\\n                                </div>\\r\\n                            </form>\\r\\n                        </div>\\r\\n                    </div>\\r\\n                </div>\\r\\n            </div>\\r\\n\\r\\n            <ToastContainer\\r\\n                position=\\\"top-right\\\"\\r\\n                autoClose={5000}\\r\\n                hideProgressBar={false}\\r\\n                newestOnTop={false}\\r\\n                closeOnClick\\r\\n                rtl={false}\\r\\n                pauseOnFocusLoss\\r\\n                draggable\\r\\n                pauseOnHover\\r\\n            />\\r\\n        </div>\\r\\n    );\\r\\n};\\r\\n\\r\\nexport default ContactUs;\', `created_at` = \'2024-09-15 12:07:39\', `id` = \'15\', `isOverthinking` = \'0\', `script` = \'\', `title` = \'React Post\', `updated_at` = \'2025-07-13 05:58:06\'\r\n                WHERE id = 15;\r\n            \r\n','2025-07-13 19:05:39','2025-07-13 19:05:39',1,0),(805,NULL,'\r\n                UPDATE yousabte_workspace.issues\r\n                SET `codeLinks` = \'import React, { useEffect, useState } from \\\'react\\\';\\r\\nimport { Link } from \\\'react-router-