  </div>\r\n    </section>\r\n    <section class=\"contact-details py-5\" data-aos=\"fade-up\" data-aos-duration=\"500\" data-aos-delay=\"400\">\r\n        <div class=\"container\">\r\n            <div class=\"row\" data-aos=\"fade-up\" data-aos-duration=\"500\" data-aos-delay=\"300\">\r\n                <div class=\"col-md-12\">\r\n                    <h2 class=\"text-center\">Our Contact Information</h2>\r\n                    <ul class=\"list-unstyled d-flex flex-column flex-lg-row justify-content-center contact-ul\">\r\n                        <li class=\"px-2\">\r\n                            <a ><span  class=\"fa fa-map-marker px-1\"></span>@lang(\'site.address\') :\r\n                                {{ settings()->address }}</a>\r\n                        </li>\r\n                        <li class=\"px-2\">\r\n                            <a ><span  class=\"fa fa-envelope px-1\"></span>@lang(\'site.email\')\r\n                                : {{ settings()->email }}</a>\r\n                        </li>\r\n                        <li class=\"px-2\">\r\n                            <a ><span  class=\"fa fa-mobile px-1\"></span>@lang(\'site.phone\') :\r\n                                {{ settings()->phone }}</a>\r\n                        </li>\r\n                        <li class=\"px-2\">\r\n                            <a ><span class=\"fa-solid fa-house px-1\"></span>@lang(\'site.postal\') : {{ settings()->postal }}</a>\r\n                        </li>\r\n                    </ul>\r\n                </div>\r\n                <div class=\"col-md-12\">\r\n                    <ul class=\"list-unstyled social_media d-flex justify-content-center\">\r\n                        <li class=\"social_icons\">\r\n                            <a href=\"{{ settings()->facebook }}\" target=\"_blank\">\r\n                                <i class=\"fa fa-facebook\"></i>\r\n                            </a>\r\n                        </li>\r\n                        <li class=\"social_icons\">\r\n                            <a href=\"{{ settings()->twitter }}\" target=\"_blank\">\r\n                                <i class=\"fa fa-twitter\"></i>\r\n                            </a>\r\n                        </li>\r\n                        <li class=\"social_icons\">\r\n                            <a href=\"{{ settings()->email }}\" target=\"_blank\">\r\n                                <i class=\"fa fa-youtube\"></i>\r\n                            </a>\r\n                        </li>\r\n                        <li class=\"social_icons\">\r\n                            <a href=\"{{ settings()->instagram }}\" target=\"_blank\">\r\n                                <i class=\"fa fa-instagram\"></i>\r\n                            </a>\r\n                        </li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n            <div class=\"row\">\r\n                <div class=\"map-location\" data-aos=\"fade-up\" data-aos-duration=\"500\" data-aos-delay=\"500\">\r\n                    <iframe class=\"goole-maps\"\r\n                        src=\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d463880.04554274346!2d46.24820591719813!3d24.724722268098482!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3e2f03890d489399%3A0xba974d1c98e79fd5!2sRiyadh%20Saudi%20Arabia!5e0!3m2!1sen!2seg!4v1659529414423!5m2!1sen!2seg\"\r\n                        allowfullscreen=\"\" loading=\"lazy\" referrerpolicy=\"no-referrer-when-downgrade\"></iframe>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </section><!-- Contact form end -->\r\n \r\n \r\n    @push(\'scripts\')\r\n        <script>\r\n            $(\'#contact-us\').submit(function(e) {\r\n                e.preventDefault();\r\n                let formData = new FormData(this);\r\n                console.log(formData)\r\n                $.ajax({\r\n                    type: \'POST\',\r\n                    url: \"{{ route(\'direct_contact_post\') }}\",\r\n                    data: formData,\r\n                    contentType: false,\r\n                    processData: false,\r\n                    success: (response) => {\r\n                        if (response) {\r\n                            this.reset();\r\n                            // $(\'#message-success\').removeClass(\'hide\');\r\n                            // $(\'#message-success\').show();\r\n                            $(\'#message-success\').removeClass(\'message-hide\');\r\n                            $(\'#message-successalert\').text(response);\r\n                            setTimeout(() => {\r\n                                // $(\'#message-success\').fadeOut(\'fast\');\r\n                                $(\'#message-success\').addClass(\'message-hide\');\r\n                            }, 5000);\r\n                        }\r\n                    },\r\n                    error: function(response) {\r\n                        $.each(response.responseJSON.errors, function(key, value) {\r\n                            $(\"#\" + key).next().show();\r\n                            $(\"#\" + key).next().html(value[0]);\r\n                            $(\"#\" + key).next().removeClass(\'error-hide\');\r\n                            setTimeout(() => {\r\n                                $(\"#\" + key).next().fadeOut(\'fast\');\r\n                                $(\"#\" + key).next().addClass(\'error-hide\');\r\n \r\n                            }, 5000);\r\n                        });\r\n \r\n                    }\r\n                });\r\n            });\r\n        </script>\r\n    @endpush\r\n@endsection\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21',1),(171,'How to receive an error from request\r\n<div class=\"col-lg-6\">\r\n    <div class=\"form-group\">\r\n        <label for=\"\">الهاتف <label>\r\n        <input class=\"form-control @error(\'phone\') is-invalid @enderror\" type=\"text\" name=\"phone\" value=\"{{ old(\'phone\') }}\">\r\n        @error(\'phone\')\r\n            <span class=\"text-danger\">{{ $message }}</span>\r\n        @enderror\r\n    </div>\r\n</div>\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21',1),(172,'How to get all the routes\r\nRoute::get(\'routes\', function () {\r\n    $routeCollection = Route::getRoutes();\r\n    echo \"<table style=\'width:100%\'>\";\r\n    echo \"<tr>\";\r\n    echo \"<td width=\'10%\'><h4>HTTP Method</h4></td>\";\r\n    echo \"<td width=\'10%\'><h4>Route</h4></td>\";\r\n    echo \"<td width=\'10%\'><h4>Name</h4></td>\";\r\n    echo \"<td width=\'70%\'><h4>Corresponding Action</h4></td>\";\r\n    echo \"</tr>\";\r\n    foreach ($routeCollection as $value) {\r\n        echo \"<tr>\";\r\n        echo \"<td>\" . $value->methods()[0] . \"</td>\";\r\n        echo \"<td>\" . $value->uri() . \"</td>\";\r\n        echo \"<td>\" . $value->getName() . \"</td>\";\r\n        echo \"<td>\" . $value->getActionName() . \"</td>\";\r\n        echo \"</tr>\";\r\n    }\r\n    echo \"</table>\";\r\n});\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21',1),(173,'socket .io laravel part\r\n<!DOCTYPE html>\r\n<html lang=\"{{ str_replace(\'_\', \'-\', app()->getLocale()) }}\">\r\n\r\n<head>\r\n    <meta charset=\"utf-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n    <title>Chat App Socket.io | CodeChef</title>\r\n</head>\r\n\r\n<body>\r\n\r\n    <div class=\"container\">\r\n        <div class=\"row chat-row\">\r\n            <div class=\"chat-content\">\r\n                <ul></ul>\r\n            </div>\r\n\r\n            <div class=\"chat-section\">\r\n                <div class=\"chat-box\">\r\n                    <div class=\"chat-input bg-primary\"  contenteditable=\"\">\r\n                        <form id=\'form\'>\r\n                            <input  id=\"chatInput\" type=\"text\">\r\n                            <button >Send</button>\r\n                        </form>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <script src=\"https://code.jquery.com/jquery-3.6.0.js\" integrity=\"sha256-H+K7U5CnXl1h5ywQfKtSj8PCmoN9aaq30gDh27Xc0jk=\"\r\n        crossorigin=\"anonymous\"></script>\r\n    <script src=\"https://cdn.socket.io/4.0.1/socket.io.min.js\"\r\n        integrity=\"sha384-LzhRnpGmQP+lOvWruF/lgkcqD+WDVt9fU3H4BWmwP5u5LTmkUGafMcpZKNObVMLU\" crossorigin=\"anonymous\">\r\n    </script>\r\n\r\n    <script>\r\n        $(function() {\r\n            let ip_address = \'127.0.0.1\';\r\n            let socket_port = \'3000\';\r\n            let socket = io(ip_address + \':\' + socket_port);\r\n            const input = document.getElementById(\'chatInput\');\r\n            const form = document.getElementById(\'form\');\r\n\r\n            const value = input.value;\r\n            console.log(value)\r\n            const message = \'asdfdasf\'\r\n            // let chatInput = $(\'#chatInput\');\r\n            form.addEventListener(\'submit\', (e) => {\r\n                e.preventDefault();\r\n                console.log(\'fired\', message)\r\n               \r\n                socket.emit(\'add_message\', message);\r\n            })\r\n\r\n            // chatInput.keypress(function(e) {\r\n            //     let message = $(this).html();\r\n            //     console.log(message);\r\n            //     if (e.which === 13 && !e.shiftKey) {\r\n            //         socket.emit(\'sendChatToServer\', message);\r\n            //         chatInput.html(\'\');\r\n            //         return false;\r\n            //     }\r\n            // });\r\n\r\n            socket.on(\'send_message\', (message) => {\r\n                console.log(\'message came: \', message)\r\n                $(\'.chat-content ul\').append(`<li>${message}</li>`);\r\n            });\r\n        });\r\n    </script>\r\n</body>\r\n\r\n</html>\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21',1),(174,'socket .io laravel part\r\nconst express = require(\'express\');\r\n\r\nconst app = express();\r\n\r\nconst server = require(\'http\').createServer(app);\r\n\r\nconst io = require(\'socket.io\')(server, {\r\n    cors: { origin: \"*\"}\r\n});\r\n\r\nio.on(\'connection\', (socket) => {\r\n    console.log(\'connection\');\r\n    // socket.on(\'joined_room\', (user) => {\r\n\r\n    // })\r\n    socket.on(\'add_message\', (message) => {\r\n        console.log(message);\r\n\r\n        // io.sockets.emit(\'sendChatToClient\', message);\r\n       io.emit(\'send_message\', message);\r\n    });\r\n\r\n    socket.on(\'disconnect\', (socket) => {\r\n        console.log(\'Disconnect\');\r\n    });\r\n});\r\n\r\nserver.listen(3000, () => {\r\n    console.log(\'Server is running\');\r\n});\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21',1),(175,'How to give code to guest\r\n @guest\r\n    Code goes here\r\n  @endguest\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21',1),(176,'How to validate a youtube link and required_if\r\n        $rx = \'~\r\n        ^(?:https?://)?                           # Optional protocol\r\n        (?:www[.])?                              # Optional sub-domain\r\n        (?:youtube[.]com/watch[?]v=|youtu[.]be/) # Mandatory domain name (w/ query string in .com)\r\n        ([^&]{11})                               # Video id of 11 characters as capture group 1\r\n        ~x\';\r\n        $code = request()->isMethod(\'put\') ? \'required\' : \'required|unique:courses,code\';\r\n\r\n        $image = request()->isMethod(\'put\') ? \'nullable|image|max:900\' : \'required|image|max:900\';\r\n        $link = request()->isMethod(\'put\') ? [\'required_if:use_media,=,1\', request()->video_link!=null ?\"regex:$rx\":\"\"] :[\'required_if:use_media,=,1\',request()->video_link !=null ?\"regex:$rx\":\"\"];\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21',1),(177,'Event delegation\r\n    <script>\r\n        $(document).ready(function() {\r\n            let i = 0;\r\n            $(\"#addchild\").on(\'click\', function() {\r\n                console.log(\'tet\');\r\n                i++;\r\n $(\"#childform\").append(\r\n \"<div class=\'form-group\' id=\'item\"+i+\"\'><label>@lang(\'site.child_age\') <i class=\'fas fa-user-times remove\'      inputid=\'item\"+i+\"\' style=\'color:red;\'></i> </label><select class=\'form-control selectpicker @error(\'child_age\') is-invalid @enderror\'name=\'child_age[]\'><option value=\'\' selected>@lang(\'site.select_age\')</option><option value=\'0\'>0</option><option value=\'1\'>1</option><option value=\'2\'>2</option><option value=\'3\'>3</option><option value=\'4\'>4</option><option value=\'5\'>5</option><option value=\'6\'>6</option><option value=\'7\'>7</option><option value=\'8\'>8</option><option value=\'9\'>9</option><option value=\'10\'>10</option><option value=\'11\'>11</option></select><div class=\'invalid-feedback d-none\'></div></div>\"\r\n                );\r\n            });\r\n\r\n            $(document).on(\'click\', \".remove\",function(){\r\n                let id = $(this).attr(\'inputid\');\r\n                $(\"#\"+id).remove();\r\n            });\r\n\r\n\r\n        });\r\n    </script>\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21',1),(178,'How to handle active property in navbar\r\n<li class=\"nav-item\" \r\n<a class=\"nav-link {{ Route::is(\'home\') ? \'active\' : \'\' }}\" aria-current=\"page\" href=\"{{ route(\'home\') }}\">@lang(\'site.home\')</a>\r\n</li>\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21',1),(179,'How to handle whatsapp and calls\r\n<p><a href=\"https://wa.me/966500774150\"><i style=\"font-size:200%\" class=\"fab fa-whatsapp\"></i></a> <a href=\"tel:00966500774150\"><i style=\"font-size:200%\" class=\"fas fa-phone-square\"></i></a></p>\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21',1),(180,'Important jQuery reference\r\n    <script>\r\n        $(document).ready(function() {\r\n            let i = 0;\r\n            let adultPrice = 0;\r\n            let childPrice = 0;\r\n            let totalPrice = 0;\r\n            $(\"#adult\").on(\'change\', function() {\r\n                let adultNum = $(this).val();\r\n                adultPrice = adultNum * {{ $tour->price }};\r\n                totalPrice = adultPrice + childPrice;\r\n                $(\"#adultprice\").html(adultPrice);\r\n                $(\"#totalprice\").html(totalPrice);\r\n            });\r\n\r\n            $(document).on(\'change\', \'.child_age\', function() {\r\n\r\n                let ages = $(\'.child_age\').map(function() {\r\n                    return Number($(this).val());\r\n                }).get();\r\n\r\n                childPrice = 0;\r\n                ages.forEach(function(age) {\r\n                    if (age < 7) {\r\n                        childPrice += {{ $tour->price_infant }};\r\n                    } else {\r\n                        childPrice += {{ $tour->price_child }};\r\n                    }\r\n                });\r\n                totalPrice = adultPrice + childPrice;\r\n                $(\"#childprice\").html(childPrice);\r\n                $(\"#totalprice\").html(totalPrice);\r\n                console.log(totalPrice);\r\n\r\n            });\r\n\r\n            $(document).on(\'click\', \"#addchild\", function() {\r\n                console.log(\'tet\');\r\n                $(\"#childform\").append(\r\n                    `<div class=\'form-group\' id=\'item${i}\'>\r\n                        <label>\r\n                            @lang(\'site.child_age\') <i class=\'fas fa-user-times remove\' style=\'color:red;\' inputid=\'item${i}\'></i>\r\n                        </label>\r\n                        <select class=\'form-control selectpicker child_age ${i}\' name=\'child_age[]\' id=\"child_item${i}\">\r\n                            <option value=\'\' selected>@lang(\'site.select_age\')</option><option value=\'0\'>0</option><option value=\'1\'>1</option>\r\n                            <option value=\'2\'>2</option><option value=\'3\'>3</option><option value=\'4\'>4</option><option value=\'5\'>5</option>\r\n                            <option value=\'6\'>6</option><option value=\'7\'>7</option><option value=\'8\'>8</option><option value=\'9\'>9</option>\r\n                            <option value=\'10\'>10</option><option value=\'11\'>11</option>\r\n                        </select>\r\n                        <div class=\'invalid-feedback d-none\'></div>\r\n                    </div>`\r\n                );\r\n                i++;\r\n        });\r\n\r\n        $(document).on(\'click\', \".remove\", function() {\r\n            let id = $(this).attr(\'inputid\');\r\n\r\n            let value = $(\"#child_\" + id).val();\r\n            // console.log(value);\r\n            // console.log(childPrice);\r\n            if (value < 7) {\r\n                childPrice -= {{ $tour->price_infant }};\r\n            } else {\r\n                childPrice -= {{ $tour->price_child }};\r\n            }\r\n            totalPrice = adultPrice + childPrice;\r\n            $(\"#childprice\").html(childPrice);\r\n            $(\"#totalprice\").html(totalPrice);\r\n            $(\"#\" + id).remove();\r\n        });\r\n\r\n\r\n        });\r\n    </script>\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21',1),(181,'Multiple file receiving\r\n<input type=\"file\" name=\"images[]\" multiple  accept=\".png, .jpg, .jpeg, .svg\" />\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21',1),(182,'Request has file method\r\nif($request->hasFile(\'images\'))\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21',1),(183,'Scope search and hasMany functions\r\n    public function scopeSearch($query)\r\n    {\r\n        $query->when(request()->title, function ($q) {\r\n            return $q->whereHas(\'translations\', function ($q2) {\r\n                $q2->where(\'title\', \'like\', \'%\' . request()->title . \'%\');\r\n            });\r\n        })->when(request()->month, function ($q) {\r\n            return $q->whereMonth(\'start_date\', request()->month);\r\n        })->when(request()->year, function ($q) {\r\n            return $q->whereYear(\'start_date\', request()->year);\r\n        })->when(request()->city_id, function ($q) {\r\n            return $q->where(\'city_id\', request()->city_id);\r\n        })->when(request()->section_id, function ($q) {\r\n            return $q->where(\'section_id\', request()->section_id);\r\n        })->when(request()->category_id, function ($q) {\r\n            return $q->where(\'category_id\', request()->category_id);\r\n        });\r\n    }\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21',1),(184,'Json response \r\nfunction successResponse($data = [],$message=\'Success\')\r\n{\r\n    return response()->json([\'status\' => 200, \'msg\' => $message, \'data\' => $data], 200);\r\n}\r\n\r\nfunction failedResponse($data = [])\r\n{\r\n    return response()->json([\'status\' => 400, \'msg\' => \'Error\', \'data\' => $data], 400);\r\n}\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21',1),(185,'try catch example\r\n        try{\r\n            $courses = $this->course->search()->latest(\'id\')->paginate(PAGINATION_COUNT);\r\n            $data[\'courses\'] = CourseResource::collection($courses)->response()->getData(true);\r\n   \r\n            return successResponse($data[\'courses\']);\r\n        }catch(Exception $e){\r\n            return failedResponse($e->getMessage());\r\n        }\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21',1),(186,'model constructor\r\n    private $course;\r\n    public function __construct(Course $course)\r\n    {\r\n        $this->course = $course;\r\n    }\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21',1),(187,'request route\r\nrequest()->routeIs(\'how_we_are.*\',\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21',1),(188,'Eloquent whereHas and query builder\r\nuse Illuminate\\Database\\Eloquent\\Builder;\r\n$data[\'category\'] = CategoryResource::collection(Category::where(\'section_id\',\'!=\',null)->whereHas(\'courses\',function(Bu