tItem(\"products\"));\r\n        } else {\r\n            cartArr = [];\r\n        }\r\n\r\n        function toogle(product, cat, index) {\r\n\r\n            if (!cartArr.length || findProduct(cartArr, product).index === -1) {\r\n                product[\'qty\'] = 1;\r\n                product[\'category\'] = cat.title;\r\n                cartArr.push(product);\r\n                localStorage.setItem(\"products\", JSON.stringify(cartArr));\r\n                localStorage.setItem(\"itemsCount\", ++count);\r\n                console.log(\'count of items\',\r\n                    localStorage.getItem(\"itemsCount\")\r\n                );\r\n\r\n                $(\'#cart\').remove();\r\n                $(\'#flag\').append(`\r\n                        <a href=\"{{ route(\'cart\') }}\" id=\"cart\">\r\n                            <i class=\"fas fa-shopping-cart fa-lg text-success\"></i>${localStorage.getItem(\"itemsCount\")}\r\n                        </a>\r\n                        `);\r\n            }\r\n\r\n            $(\'#toggle\' + index).empty();\r\n            $(\'#toggle\' + index).append(`\r\n            <a class=\"d-flex\">\r\n                <button class=\"btn btn-link\" id=\"btnRemove${index}\">\r\n                    <i class=\"fas fa-minus\"></i>\r\n                </button>\r\n\r\n                <input id=\"form${index}\" min=\"1\" max=\"${product.stock}\" name=\"quantity\"\r\n                    value=\"1\" type=\"number\"\r\n                    class=\"form-control form-control-sm\" />\r\n\r\n                <button class=\"btn btn-link\" id=\"btn${index}\"\r\n                    >\r\n                    <i class=\"fas fa-plus\"></i>\r\n                </button>\r\n            </a>\r\n           \r\n            `);\r\n\r\n            var btnAdd = document.querySelector(`#btn${index}`);\r\n            btnAdd.addEventListener(\'click\', function() {\r\n                this.parentNode.querySelector(\'input[type=number]\').stepUp();\r\n                addToCart(index, product);\r\n            });\r\n\r\n            var btnRemove = document.querySelector(`#btnRemove${index}`);\r\n\r\n            btnRemove.addEventListener(\'click\', function() {\r\n                this.parentNode.querySelector(\'input[type=number]\').stepDown();\r\n                deletFromCart(index, product)\r\n            });\r\n\r\n            const input = document.querySelector(`#form${index}`);\r\n            input.value = findProduct(JSON.parse(localStorage.getItem(\"products\")), product).product.qty;\r\n        }\r\n\r\n        function addToCart(index, product) {\r\n\r\n            if (!cartArr.length || findProduct(cartArr, product).index === -1) {\r\n                product[\'qty\'] = 2;\r\n                cartArr.push(product);\r\n                localStorage.setItem(\"products\", JSON.stringify(cartArr));\r\n                localStorage.setItem(\"itemsCount\", ++count);\r\n            } else {\r\n                let newArr = cartArr.map(item => {\r\n                    if (item.id === product.id && item[\'qty\'] <= product.stock) {\r\n                        item[\'qty\']++;\r\n                        localStorage.setItem(\"itemsCount\", ++count);\r\n                    }\r\n                    return item;\r\n                })\r\n                cartArr = newArr;\r\n                localStorage.setItem(\"products\", JSON.stringify(cartArr));\r\n            }\r\n\r\n\r\n\r\n            $(\'#cart\').remove();\r\n            $(\'#flag\').append(`\r\n                        <a href=\"{{ route(\'cart\') }}\" id=\"cart\">\r\n                            <i class=\"fas fa-shopping-cart fa-lg text-success\"></i>${localStorage.getItem(\"itemsCount\")}\r\n                        </a>`);\r\n        }\r\n\r\n        function deletFromCart(index, product) {\r\n            if (findProduct(JSON.parse(localStorage.getItem(\"products\")), product).product.qty > 1) {\r\n                localStorage.setItem(\"itemsCount\", --count);\r\n\r\n                let newArr = cartArr.map(item => {\r\n                    if (item.id === product.id) {\r\n                        item[\'qty\']--;\r\n                    }\r\n                    return item;\r\n                })\r\n                cartArr = newArr;\r\n                localStorage.setItem(\"products\", JSON.stringify(cartArr));\r\n\r\n                $(\'#cart\').remove();\r\n                $(\'#flag\').append(`\r\n                                    <a href=\"{{ route(\'cart\') }}\" id=\"cart\">\r\n                                    <i class=\"fas fa-shopping-cart fa-lg text-success\"></i>${localStorage.getItem(\"itemsCount\")}\r\n                                    </a>`);\r\n\r\n            }\r\n        }\r\n\r\n        function findProduct(arr, product) {\r\n            let index = -1;\r\n            for (let i = 0; i < arr.length; i++) {\r\n                if (arr[i].id === product.id) {\r\n                    index = i\r\n                }\r\n            }\r\n            let modProduct = arr.find(item => item.id === product.id);\r\n            return {\r\n                index,\r\n                product: modProduct\r\n            };\r\n        }\r\n    </script>\r\n@endpush\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21',1),(218,'cart.balde.php\r\n@extends(\'frontend.layouts.master\')\r\n@section(\'content\')\r\n    <main id=\"main\">\r\n        <!-- Intro Single-->\r\n        <section class=\"intro-single\">\r\n            <div class=\"container\">\r\n                @if (session(\'success\'))\r\n                    <div class=\"alert alert-success alert-dismissible fade show\" role=\"alert\">{{ session(\'success\') }}\r\n                        <button class=\"btn-close\" type=\"button\" data-bs-dismiss=\"alert\" aria-label=\"Close\"></button>\r\n                    </div>\r\n                @endif\r\n                <div class=\"row\">\r\n                    <div class=\"col-md-12 col-lg-8\">\r\n                        <div class=\"title-single-box\">