for (let i = 0; i < arr.length; i++) {\r\n                if (arr[i].id === product.id) {\r\n                    index = i\r\n                }\r\n            }\r\n            let modProduct = arr.find(item => item.id === product.id);\r\n            return {\r\n                index,\r\n                product: modProduct\r\n            };\r\n        }\r\n    </script>\r\n@endpush\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21',1),(219,'Using ajax to get data\r\n @push(\'scripts\')\r\n        <script>\r\n            $(document).ready(function() {\r\n                // $(\'#categories\').append(\'<option value=\"\">{{ trans(\'general.category_name\') }}</option>\');\r\n                let old = $(\'#categories\').attr(\'old\');\r\n                if (old != null) {\r\n                    $(\'#categories\').find(\'option\').remove().end();\r\n                    var section_id = $(\'#section\').val();\r\n                    console.log(\'section_id\', section_id);\r\n\r\n                    let url = \"{{ route(\'section.categories\', [\'id=:id\']) }}\"\r\n                    url = url.replace(\':id\', section_id);\r\n                    $.ajax({\r\n                        type: \"Get\",\r\n                        url: url,\r\n                        datatype: \'JSON\',\r\n                        success: function(data) {\r\n                            console.log(data);\r\n\r\n                            if (data.status == 200) {\r\n                                let equal;\r\n                                data.data.categories.forEach(element => {\r\n                                    // equal = {{ old(\'category_id\') }};\r\n                                    // console.log(element.id);\r\n                                    let equal = \'\';\r\n                                    if (element.id == old)\r\n                                        equal = \'selected\';\r\n                                    var option =\r\n                                   