ularText}>Login to continue </Text>\r\n      <TextInput\r\n        style={styles.inputBox}\r\n        value={email}\r\n        onChangeText={onChangeEmail}\r\n        placeholder={\'email\'}\r\n        keyboardType={\'email-address\'}\r\n      />\r\n      <TextInput\r\n        style={styles.inputBox}\r\n        value={password}\r\n        onChangeText={onChangePassword}\r\n        placeholder={\'password\'}\r\n        keyboardType={\'default\'}\r\n        secureTextEntry={true}\r\n      />\r\n      <Pressable\r\n        onPress={() => navigation.navigate(\'Welcome\')}\r\n        style={styles.button}>\r\n        <Text style={styles.buttonText}>Log in</Text>\r\n      </Pressable>\r\n    </ScrollView>\r\n  );\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n  container: {\r\n    flex: 1,\r\n    backgroundColor: \'#333333\',\r\n  },\r\n  headerText: {\r\n    padding: 40,\r\n    fontSize: 30,\r\n    color: \'#EDEFEE\',\r\n    textAlign: \'center\',\r\n  },\r\n  regularText: {\r\n    fontSize: 24,\r\n    padding: 20,\r\n    marginVertical: 8,\r\n    color: \'#EDEFEE\',\r\n    textAlign: \'center\',\r\n  },\r\n  inputBox: {\r\n    height: 40,\r\n    margin: 12,\r\n    borderWidth: 1,\r\n    padding: 10,\r\n    fontSize: 16,\r\n    borderColor: \'EDEFEE\',\r\n    backgroundColor: \'#EDEFEE\',\r\n  },\r\n  button: {\r\n    fontSize: 22,\r\n    padding: 10,\r\n    marginVertical: 8,\r\n    margin: 100,\r\n    backgroundColor: \'#EE9972\',\r\n    borderColor: \'#EE9972\',\r\n    borderWidth: 2,\r\n    borderRadius: 50,\r\n  },\r\n  buttonText: {\r\n    color: \'black\',\r\n    textAlign: \'center\',\r\n    fontSize: 25,\r\n  },\r\n});\r\n\r\nSolution: Configure Tab Navigation\r\n','2024-02-09 02:18:35','2024-02-09 02:18:35',1),(334,'App.js\r\nimport * as React from \'react\';\r\nimport { View, StyleSheet } from \'react-native\';\r\n\r\nimport LittleLemonHeader from \'./components/LittleLemonHeader\';\r\nimport LittleLemonFooter from \'./components/LittleLemonFooter\';\r\nimp