  public function up()\r\n        {\r\n            Schema::create(\'posts\', function (Blueprint $table) {\r\n                $table->id();\r\n                $table->string(\'title\');\r\n                $table->text(\'body\');\r\n                $table->timestamps();\r\n            });\r\n        }\r\n    \r\n        /**\r\n         * Reverse the migrations.\r\n         *\r\n         * @return void\r\n         */\r\n        public function down()\r\n        {\r\n            Schema::dropIfExists(\'posts\');\r\n        }\r\n    };\r\n\r\nlivewire\\app\\Models\\Post.php\r\n\r\n<?php\r\n  \r\nnamespace App\\Models;\r\n  \r\nuse Illuminate\\Database\\Eloquent\\Factories\\HasFactory;\r\nuse Illuminate\\Database\\Eloquent\\Model;\r\n  \r\nclass Post extends Model\r\n{\r\n    use HasFactory;\r\n  \r\n    /**\r\n     * The attributes that are mass assignable.\r\n     *\r\n     * @var array\r\n     */\r\n    protected $fillable = [\r\n        \'title\', \'body\'\r\n    ];\r\n}\r\n\r\nlivewire\\app\\Livewire\\Posts.php\r\n<?php\r\n\r\nnamespace App\\Livewire;\r\n\r\nuse Livewire\\Component;\r\nuse App\\Models\\Post;\r\n\r\nclass Posts extends Component\r\n{\r\n    public $posts, $title, $body, $post_id;\r\n    public $updateMode = false;\r\n   \r\n    /**\r\n     * The attributes that are mass assignable.\r\n     *\r\n     * @var array\r\n     */\r\n    public function render()\r\n    {\r\n        $this->posts = Post::all();\r\n        return view(\'livewire.posts\');\r\n    }\r\n  \r\n    /**\r\n     * The attributes that are mass assignable.\r\n     *\r\n     * @var array\r\n     */\r\n    private function resetInputFields(){\r\n        $this->title = \'\';\r\n        $this->body = \'\';\r\n    }\r\n   \r\n    /**\r\n     * The attributes that are mass assignable.\r\n     *\r\n     * @var array\r\n     */\r\n    public function store()\r\n    {\r\n        $validatedDate = $this->validate([\r\n            \'title\' => \'required\',\r\n            \'body\' => \'required\',\r\n        ]);\r\n  \r\n        Post::create($validatedDate);\r\n  \r\n        session()->flash(\'message\', \'Post Created Successfully.\');\r\n  \r\n        $this->resetInputFields();\r\n    }\r\n  \r\n    /**\r\n     * The attributes that are mass assignable.\r\n     *\r\n     * @var array\r\n     */\r\n    public function edit($id)\r\n    {\r\n        $post = Post::findOrFail($id);\r\n        $this->post_id = $id;\r\n        $this->title = $post->title;\r\n        $this->body = $post->body;\r\n  \r\n        $this->updateMode = true;\r\n    }\r\n  \r\n    /**\r\n     * The attributes that are mass assignable.\r\n     *\r\n     * @var array\r\n     */\r\n    public function cancel()\r\n    {\r\n        $this->updateMode = false;\r\n        $this->resetInputFields();\r\n    }\r\n  \r\n    /**\r\n     * The attributes that are mass assignable.\r\n     *\r\n     * @var array\r\n     */\r\n    public function update()\r\n    {\r\n        $validatedDate = $this->validate([\r\n            \'title\' => \'required\',\r\n            \'body\' => \'required\',\r\n        ]);\r\n  \r\n        $post = Post::find($this->post_id);\r\n        $post->update([\r\n            \'title\' => $this->title,\r\n            \'body\' => $this->body,\r\n        ]);\r\n  \r\n        $this->updateMode = false;\r\n  \r\n        session()->flash(\'message\', \'Post Updated Successfully.\');\r\n        $this->resetInputFields();\r\n    }\r\n   \r\n    /**\r\n     * The attributes that are mass assignable.\r\n     *\r\n     * @var array\r\n     */\r\n    public function delete($id)\r\n    {\r\n        Post::find($id)->delete();\r\n        session()->flash(\'message\', \'Post Deleted Successfully.\');\r\n    }\r\n}\r\n\r\n\r\n\r\nlivewire\\resources\\views\\livewire\\posts.blade.php\r\n<div>\r\n  \r\n    @if (session()->has(\'message\'))\r\n        <div class=\"alert alert-success\">\r\n            {{ session(\'message\') }}\r\n        </div>\r\n    @endif\r\n  \r\n    @if($updateMode)\r\n        @include(\'livewire.update\')\r\n    @else\r\n        @include(\'livewire.create\')\r\n    @endif\r\n  \r\n    <table class=\"table table-bordered mt-5\">\r\n        <thead>\r\n            <tr>\r\n                <th>No.</th>\r\n                <th>Title</th>\r\n                <th>Body</th>\r\n                <th width=\"150px\">Action</th>\r\n            </tr>\r\n        </thead>\r\n        <tbody>\r\n            @foreach($posts as $post)\r\n            <tr>\r\n                <td>{{ $post->id }}</td>\r\n                <td>{{ $post->title }}</td>\r\n                <td>{{ $post->body }}</td>\r\n                <td>\r\n                <button wire:click=\"edit({{ $post->id }})\" class=\"btn btn-primary btn-sm\">Edit</button>\r\n                    <button wire:click=\"delete({{ $post->id }})\" class=\"btn btn-danger btn-sm\">Delete</button>\r\n                </td>\r\n            </tr>\r\n            @endforeach\r\n        </tbody>\r\n    </table>\r\n</div>\r\n\r\nC:\\Users\\User\\Desktop\\livewire\\resources\\views\\livewire\\create.blade.php\r\n<form>\r\n    <div class=\"form-group\">\r\n        <label for=\"exampleFormControlInput1\">Title:</label>\r\n        <input type=\"text\" class=\"form-control\" id=\"exampleFormControlInput1\" placeholder=\"Enter Title\" wire:model=\"title\">\r\n        @error(\'title\') <span class=\"text-danger\">{{ $message }}</span>@enderror\r\n    </div>\r\n    <div class=\"form-group\">\r\n        <label for=\"exampleFormControlInput2\">Body:</label>\r\n        <textarea type=\"email\" class=\"form-control\" id=\"exampleFormControlInput2\" wire:model=\"body\" placeholder=\"Enter Body\"></textarea>\r\n        @error(\'body\') <span class=\"text-danger\">{{ $message }}</span>@enderror\r\n    </div>\r\n    <button wire:click.prevent=\"store()\" class=\"btn btn-success\">Save</button>\r\n</form>\r\nlivewire\\resources\\views\\livewire\\update.blade.php\r\n<form>\r\n    <input type=\"hidden\" wire:model=\"post_id\">\r\n    <div class=\"fo