urn true;\r\n        } catch (Exception $e) {\r\n            return \"Mailer Error: {$mail->ErrorInfo}\";\r\n        }\r\n    }\r\n}\r\n3- Use it in your controller \r\n<?php\r\n\r\nnamespace App\\Http\\Controllers\\API;\r\n\r\nuse App\\Http\\Controllers\\Controller;\r\nuse App\\Http\\Requests\\API\\TripRequestRequest;\r\nuse App\\Http\\Resources\\TripResource;\r\nuse App\\Mail\\OrderUserMail;\r\nuse App\\Models\\TripRequestModel;\r\nuse Exception;\r\nuse Illuminate\\Http\\Request;\r\nuse Illuminate\\Support\\Facades\\Mail;\r\nuse App\\Services\\MailService;\r\n\r\nclass TripRequestController extends Controller\r\n{\r\n    private $tripRequest;\r\n    public function __construct(TripRequestModel $tripRequest)\r\n    {\r\n        $this->tripRequest = $tripRequest;\r\n    }\r\n\r\n    public function store(TripRequestRequest $request)\r\n    {\r\n        try {\r\n\r\n            // dd([env(\"MAIL_FROM_ADDRESS\"),$request->email]);\r\n            $data = $request->all();\r\n            $tripRequest = $this->tripRequest->create($data);\r\n            // dd( $tripRequest->email);\r\n            // Mail::to($tripRequest->email)->send(new OrderUserMail($tripRequest));\r\n\r\n             // Set the recipient, subject, and body\r\n            $to = $tripRequest->email;\r\n            $toName = $tripRequest->email;\r\n            $subject = \'Test Email from Laravel\';\r\n            $body = \'<b>This is a test email sent from Laravel using PHPMailer</b>\';\r\n\r\n            // Call the MailService to send the email\r\n            $result = MailService::sendMail($to, $toName, $subject, $body);\r\n            return successResponse($tripRequest);\r\n            // return response()->json([\'success\' => trans(\'general.sent_successfully\')]);\r\n        } catch (\\Exception $e) {\r\n            dd($e->getMessage());\r\n            return response()->json([\'error\' => __($e->getMessage())]);\r\n        }\r\n    }\r\n}','2024-10-16 17:39:35','2024-10-16 17:39:35',1),(452,'Usi